#: Au-delà, le périmètre n'est plus recalculé à chaque sélection (gros dessins).
PERIMETER_LIVE_LIMIT = 200_000
#: seul événement que regarde le filtre posé sur toute l'application
_CONTEXT_MENU = QEvent.Type.ContextMenu
_SHORTCUT_OVERRIDE = QEvent.Type.ShortcutOverride
_KEY_PRESS = QEvent.Type.KeyPress
#: touches virtuelles Windows de la rangée des chiffres (VK_0 … VK_9), quelle que soit la disposition
_VK_DIGITS = range(0x30, 0x3A)


class ReferenceGrid(QWidget):
    """Les 9 points de référence d'un cadre : on clique le point dont X et Y donnent la position, et autour duquel
    se font largeur, hauteur, rotation et échelle."""

    #: (fraction de la largeur, fraction de la hauteur), de haut en bas, y vers le haut comme le dessin
    POINTS = (((0.0, 1.0), 'Haut gauche'), ((0.5, 1.0), 'Haut centre'), ((1.0, 1.0), 'Haut droite'),
              ((0.0, 0.5), 'Milieu gauche'), ((0.5, 0.5), 'Centre'), ((1.0, 0.5), 'Milieu droite'),
              ((0.0, 0.0), 'Bas gauche'), ((0.5, 0.0), 'Bas centre'), ((1.0, 0.0), 'Bas droite'))
    #: touche du pavé numérique (avec Ctrl) de chaque point, dans l'ordre de POINTS : disposées comme le pavé
    KEYS = (7, 8, 9, 4, 5, 6, 1, 2, 3)
    SIZE = 15

    @classmethod
    def point_of_key(cls, digit: int):
        """Le point de référence de la touche `digit` du pavé numérique (None : pas une touche de 1 à 9)."""
        return cls.POINTS[cls.KEYS.index(digit)][0] if digit in cls.KEYS else None

    def __init__(self, changed, parent=None):
        from PySide6.QtWidgets import QButtonGroup, QGridLayout, QToolButton
        super().__init__(parent)
        grid = QGridLayout(self)
        grid.setContentsMargins(1, 1, 1, 1)
        grid.setSpacing(5)                                          # le cadre, tracé derrière, se voit entre les cases
        self.buttons = {}
        self._group = QButtonGroup(self)
        self._group.setExclusive(True)
        for i, (pt, label) in enumerate(self.POINTS):
            b = QToolButton()
            b.setCheckable(True)
            b.setFixedSize(self.SIZE, self.SIZE)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)                # le clavier reste dans le plan de travail
            b.setToolTip(tr('{0} (Ctrl + {1} du pavé numérique)').format(tr(label), self.KEYS[i]))
            b.setAccessibleName(tr(label))
            b.setStyleSheet('QToolButton{border:2px solid #495057;border-radius:3px;background:#ffffff;}'
                            'QToolButton:hover{border-color:#1971c2;background:#d0ebff;}'
                            'QToolButton:checked{border:2px solid #0b4f8a;background:#1971c2;}'
                            'QToolButton:disabled{border-color:#adb5bd;background:#f1f3f5;}')
            b.clicked.connect(lambda _=False, p=pt: changed(p))
            self._group.addButton(b)
            grid.addWidget(b, i // 3, i % 3)
            self.buttons[pt] = b
        grid.setColumnStretch(3, 1)
        self.set_point((0.5, 0.5))

    def paintEvent(self, ev) -> None:                              # noqa: N802 — API Qt
        """Le cadre de la sélection, tracé derrière les neuf cases : on lit d'un coup d'œil que c'est lui."""
        from PySide6.QtGui import QColor, QPainter, QPen
        a, b = self.buttons[(0.0, 1.0)].geometry().center(), self.buttons[(1.0, 0.0)].geometry().center()
        p = QPainter(self)
        p.setPen(QPen(QColor('#495057' if self.isEnabled() else '#adb5bd'), 2))
        p.drawRect(a.x(), a.y(), b.x() - a.x(), b.y() - a.y())
        p.end()

    def point(self) -> tuple[float, float]:
        return next((p for p, b in self.buttons.items() if b.isChecked()), (0.5, 0.5))

    def set_point(self, pt) -> None:
        self.buttons.get(tuple(pt), self.buttons[(0.5, 0.5)]).setChecked(True)


class DimSpinBox(QDoubleSpinBox):
    """Largeur et hauteur du panneau Dimensions (F2) : une cote en mm, ou un pourcentage de la cote affichée —
    « 120% » agrandit, « 80% » réduit, « +20% » et « -20% » ajoutent ou retirent."""

    @staticmethod
    def percent(text: str):
        """Le facteur d'un pourcentage écrit (« 120% » : 1,2 ; « +20 % » : 1,2 ; « -20% » : 0,8) ; None : pas un
        pourcentage valable."""
        import math
        t = str(text).replace('mm', '').replace(' ', '').replace(' ', '').replace(',', '.')
        if not t.endswith('%') or len(t) < 2:
            return None
        t = t[:-1]
        try:
            v = float(t)
        except ValueError:
            return None
        k = 1 + v / 100 if t[0] in '+-' else v / 100
        return k if math.isfinite(k) and k > 0 else None

    def validate(self, text, pos):                              # noqa: D401 — API Qt
        from PySide6.QtGui import QValidator
        if '%' in text:
            ok = self.percent(text) is not None
            return QValidator.State.Acceptable if ok else QValidator.State.Intermediate, text, pos
        return super().validate(text, pos)

    def valueFromText(self, text):                              # noqa: N802 — API Qt
        k = self.percent(text) if '%' in text else None
        if k is not None:
            return self.value() * k
        return super().valueFromText(text)


class DimensionsPanel(QWidget):
    """F2 : dimensions et positionnement de la sélection."""

    def __init__(self, win: 'MainWindow'):
        super().__init__()
        self.win = win
        form = QFormLayout(self)
        self.fields = {}
        #: « % » de la largeur et de la hauteur : agrandir ou réduire (revient à 100 % une fois appliqué)
        self.pct = {}
        from PySide6.QtWidgets import QHBoxLayout
        top, xy = QHBoxLayout(), QFormLayout()           # X et Y, la grille de référence à leur droite
        top.addLayout(xy, 1)
        form.addRow(top)
        for key, label in (('x', 'X'), ('y', 'Y'), ('w', tr('Largeur L')), ('h', tr('Hauteur H'))):
            sb = DimSpinBox() if key in 'wh' else QDoubleSpinBox()
            sb.setDecimals(3)
            sb.setRange(-1e6, 1e6)
            sb.setSuffix(' mm')
            sb.setButtonSymbols(QDoubleSpinBox.ButtonSymbols.NoButtons)
            sb.setKeyboardTracking(False)
            sb.editingFinished.connect(self.apply)
            self.fields[key] = sb
            if key not in 'wh':
                xy.addRow(label, sb)
                continue
            sb.setToolTip(tr('Une cote en mm, ou un pourcentage : « 120% » agrandit, « 80% » réduit, « +20% » et '
                             '« -20% » ajoutent ou retirent'))
            p = QDoubleSpinBox()
            p.setRange(0.01, 100000)
            p.setDecimals(2)
            p.setValue(100)
            p.setSuffix(' %')
            p.setButtonSymbols(QDoubleSpinBox.ButtonSymbols.NoButtons)
            p.setKeyboardTracking(False)
            p.setToolTip(tr('Agrandir ou réduire la largeur de ce pourcentage (avec Conserver les proportions : la '
                            'hauteur aussi)') if key == 'w' else
                         tr('Agrandir ou réduire la hauteur de ce pourcentage (avec Conserver les proportions : la '
                            'largeur aussi)'))
            p.editingFinished.connect(lambda k=key: self._percent(k))
            self.pct[key] = p
            row = QHBoxLayout()
            row.addWidget(sb, 3)
            row.addWidget(p, 2)
            form.addRow(label, row)
        #: épaisseur en Z et son « % » : grisés tant que la sélection n'a pas de hauteur (le dessin est en 2D)
        self.z_size, self.z_pct = QDoubleSpinBox(), QDoubleSpinBox()
        for z, suffix in ((self.z_size, ' mm'), (self.z_pct, ' %')):
            z.setDecimals(3 if z is self.z_size else 2)
            z.setRange(0, 1e6)
            z.setSuffix(suffix)
            z.setButtonSymbols(QDoubleSpinBox.ButtonSymbols.NoButtons)
            z.setEnabled(False)
            z.setToolTip(tr('Épaisseur en Z : pour un objet qui en a une (le dessin est en 2D)'))
        self.z_pct.setValue(100)
        row = QHBoxLayout()
        row.addWidget(self.z_size, 3)
        row.addWidget(self.z_pct, 2)
        form.addRow(tr('Épaisseur Z'), row)
        self.anchor = ReferenceGrid(self._set_reference)
        self.anchor.setToolTip(tr('Le point du cadre que donnent X et Y, et autour duquel se font largeur, hauteur, '
                                  'rotation et échelle (Ctrl + 1 à 9 du pavé numérique)'))
        self.anchor.set_point(self._saved_reference())
        top.addWidget(self.anchor, 0, Qt.AlignmentFlag.AlignVCenter)       # à droite de X et Y : le panneau ne grandit pas
        wide = max(self.fontMetrics().horizontalAdvance(t) for t in (
            tr('Largeur L'), tr('Hauteur H'), tr('Épaisseur Z'), tr('Périmètre'), tr('Rotation'), tr('Échelle')))
        for k in 'xy':                                   # X et Y alignés avec les lignes du dessous
            xy.labelForField(self.fields[k]).setMinimumWidth(wide)
        self.keep = QCheckBox(tr('Conserver les proportions (F2)'))
        self.keep.setToolTip(tr('F2 ouvre les dimensions ; chaque F2 suivant, dans les dimensions, coche ou décoche '
                                'cette case'))
        self.keep.setChecked(True)
        form.addRow(self.keep)
        self.perim = QLabel('—')
        form.addRow(tr('Périmètre'), self.perim)
        self.rot = QDoubleSpinBox()
        self.rot.setRange(-360, 360)
        self.rot.setDecimals(3)
        self.rot.setSuffix(' °')
        self.rot.setButtonSymbols(QDoubleSpinBox.ButtonSymbols.NoButtons)
        self.rot.setKeyboardTracking(False)
        self.rot.setToolTip(tr('Tourner la sélection de cet angle autour du point de référence (sens trigonométrique)'))
        self.rot.editingFinished.connect(self._rotate)
        form.addRow(tr('Rotation'), self.rot)
        self.scale = QDoubleSpinBox()
        self.scale.setRange(0.01, 100000)
        self.scale.setDecimals(3)
        self.scale.setValue(100)
        self.scale.setSuffix(' %')
        self.scale.setButtonSymbols(QDoubleSpinBox.ButtonSymbols.NoButtons)
        self.scale.setKeyboardTracking(False)
        self.scale.setToolTip(tr('Mettre la sélection à cette échelle autour du point de référence'))
        self.scale.editingFinished.connect(self._scale)
        form.addRow(tr('Échelle'), self.scale)
        # Tab : les cotes d'abord (largeur, hauteur, Z), puis leurs « % », puis rotation et échelle
        order = [self.fields['x'], self.fields['y'], self.fields['w'], self.fields['h'], self.z_size,
                 self.pct['w'], self.pct['h'], self.z_pct, self.rot, self.scale]
        for a, b in zip(order, order[1:]):
            QWidget.setTabOrder(a, b)
        self.tab_order = order
        self._loading = False
        # Entrée (valeur appliquée) ou Échap : retour au plan de travail, pour que
        # les flèches et Ctrl+C / Ctrl+V agissent de nouveau sur le dessin
        from PySide6.QtGui import QKeySequence, QShortcut
        for sb in list(self.fields.values()) + list(self.pct.values()) + [self.rot, self.scale]:
            sb.lineEdit().returnPressed.connect(win._back_to_canvas)
            esc = QShortcut(QKeySequence('Esc'), sb)
            esc.setContext(Qt.ShortcutContext.WidgetShortcut)
            esc.activated.connect(win._back_to_canvas)

    def _saved_reference(self):
        try:
            v = str(self.win.settings.value('f2/reference', '0.5,0.5')).split(',')
            return float(v[0]), float(v[1])
        except (TypeError, ValueError, IndexError):
            return 0.5, 0.5

    def _set_reference(self, pt) -> None:
        self.win.settings.setValue('f2/reference', f'{pt[0]},{pt[1]}')
        self.refresh()

    def set_reference_key(self, digit: int) -> bool:
        """Ctrl + `digit` du pavé numérique : le point de référence à la même place que la touche (7 : haut gauche,
        5 : centre, 3 : bas droite). Rend faux pour une autre touche."""
        pt = ReferenceGrid.point_of_key(digit)
        if pt is None:
            return False
        self.anchor.set_point(pt)
        self._set_reference(pt)
        label = next(lb for p, lb in ReferenceGrid.POINTS if p == pt)
        self.win.statusBar().showMessage(tr('Référence : {0}').format(tr(label)), 3000)
        return True

    def _ref_point(self, bb=None):
        """Le point de référence dans le cadre de la sélection."""
        bb = bb or self.win.canvas.selection_bbox()
        if not bb:
            return None
        fx, fy = self.anchor.point()
        return bb[0] + fx * (bb[2] - bb[0]), bb[1] + fy * (bb[3] - bb[1])

    def _rotate(self) -> None:
        a = self.rot.value()
        c = self._ref_point()
        self.rot.blockSignals(True)
        self.rot.setValue(0)
        self.rot.blockSignals(False)
        if c and abs(a) > 1e-12:
            self.win.canvas.transform_selection(Affine.rotation(a, c))

    def _percent(self, key: str) -> None:
        """« % » de la largeur (`key` 'w') ou de la hauteur ('h') : la sélection agrandie ou réduite autour du point de
        référence ; avec Conserver les proportions, l'autre cote suit. Le champ revient à 100 %."""
        sb = self.pct[key]
        k = sb.value() / 100
        sb.blockSignals(True)
        sb.setValue(100)
        sb.blockSignals(False)
        c = self._ref_point()
        if not c or abs(k - 1) < 1e-12:
            return
        kx = k if key == 'w' or self.keep.isChecked() else 1.0
        ky = k if key == 'h' or self.keep.isChecked() else 1.0
        self.win.canvas.transform_selection(
            Affine.translation(*c) @ Affine.scaling(kx, ky) @ Affine.translation(-c[0], -c[1]))

    def has_focus(self) -> bool:
        """Le focus clavier est-il dans le panneau (un de ses champs) ?"""
        from PySide6.QtWidgets import QApplication
        fw = QApplication.focusWidget()
        return fw is not None and (fw is self or self.isAncestorOf(fw))

    def _scale(self) -> None:
        k = self.scale.value() / 100
        c = self._ref_point()
        self.scale.blockSignals(True)
        self.scale.setValue(100)
        self.scale.blockSignals(False)
        if c and abs(k - 1) > 1e-12:
            self.win.canvas.transform_selection(
                Affine.translation(*c) @ Affine.scaling(k) @ Affine.translation(-c[0], -c[1]))

    def refresh(self) -> None:
        bb = self.win.canvas.selection_bbox()
        self._loading = True
        en = bb is not None
        for sb in list(self.fields.values()) + list(self.pct.values()) + [self.rot, self.scale]:
            sb.setEnabled(en)
        if bb:
            ox, oy = self.win.canvas.origin                # position lue depuis l'origine du dessin
            rx, ry = self._ref_point(bb)
            self.fields['x'].setValue(rx - ox)
            self.fields['y'].setValue(ry - oy)
            self.fields['w'].setValue(bb[2] - bb[0])
            self.fields['h'].setValue(bb[3] - bb[1])
            L = self.win.selection_length(limit=PERIMETER_LIVE_LIMIT)
            self.perim.setText(f'{L:.3f} mm' if L is not None else tr('— (Mesure → Périmètre)'))
        else:
            self.perim.setText('—')
        self._loading = False

    def apply(self) -> None:
        if self._loading:
            return
        c = self.win.canvas
        bb = c.selection_bbox()
        if not bb:
            return
        cx, cy = self._ref_point(bb)
        w, h = bb[2] - bb[0], bb[3] - bb[1]
        ox, oy = c.origin
        nx, ny = self.fields['x'].value() + ox, self.fields['y'].value() + oy
        nw, nh = self.fields['w'].value(), self.fields['h'].value()
        sx = nw / w if w > 1e-9 else 1.0
        sy = nh / h if h > 1e-9 else 1.0
        if self.keep.isChecked():
            # la valeur modifiée l'emporte
            if abs(nw - w) > 1e-9:
                sy = sx
            elif abs(nh - h) > 1e-9:
                sx = sy
        if abs(sx - 1) < 1e-12 and abs(sy - 1) < 1e-12 and abs(nx - cx) < 1e-9 and abs(ny - cy) < 1e-9:
            return
        m = Affine.translation(nx, ny) @ Affine.scaling(sx, sy) @ Affine.translation(-cx, -cy)
        c.transform_selection(m)


class PlateDialog(QDialog):
    """Plaque : dimensions, coins, épaisseur, matière ; plaques enregistrées
    (réglages de l'utilisateur) ; ajustement au dessin avec une marge."""

    def __init__(self, plate: Plate | None, parent=None, *, settings=None, drawing_bbox=None, part_note=None):
        super().__init__(parent)
        from .fit import no_hscroll
        no_hscroll(self)                                 # pas de défilement horizontal à l'ouverture
        self.setWindowTitle(tr('Plaque'))
        self.settings = settings
        self.drawing_bbox = drawing_bbox
        p = plate or Plate()
        self.visible = p.visible
        form = QFormLayout(self)
        from PySide6.QtWidgets import QComboBox, QHBoxLayout, QPushButton
        row = QHBoxLayout()
        self.presets = QComboBox()
        self.presets.setMinimumWidth(180)
        self._load_presets()
        self.presets.activated.connect(self._apply_preset)
        save = QPushButton(tr('Enregistrer'))
        save.clicked.connect(self._save_preset)
        rem = QPushButton(tr('Supprimer'))
        rem.clicked.connect(self._remove_preset)
        row.addWidget(self.presets, 1)
        row.addWidget(save)
        row.addWidget(rem)
        form.addRow(tr('Plaques enregistrées'), row)
        self.w = self._spin(p.width)
        self.h = self._spin(p.height)
        self.r = self._spin(p.corner_radius)
        self.t = self._spin(p.thickness or 0.0)
        self.x = self._spin(p.x, neg=True)
        self.y = self._spin(p.y, neg=True)
        self.mat = QLineEdit(p.material)
        self.old = p
        mg = list(p.margins or [0.0] * 4) + [0.0] * 4
        self.margins = [self._spin(float(v)) for v in mg[:4]]
        form.addRow(tr('Largeur'), self.w)
        form.addRow(tr('Hauteur'), self.h)
        form.addRow(tr('Rayon des coins'), self.r)
        form.addRow(tr('Épaisseur'), self.t)
        form.addRow(tr('Origine X'), self.x)
        form.addRow(tr('Origine Y'), self.y)
        form.addRow(tr('Matière'), self.mat)
        mrow = QHBoxLayout()
        for lab, sp in zip((tr('G'), tr('D'), tr('B'), tr('H')), self.margins):
            mrow.addWidget(QLabel(lab))
            mrow.addWidget(sp)
        form.addRow(tr('Marges (gauche, droite, bas, haut)'), mrow)
        from PySide6.QtWidgets import QCheckBox
        from PySide6.QtWidgets import QComboBox as _QCB
        self.zero = _QCB()
        for k, lab in Plate.ZEROS:
            self.zero.addItem(tr(lab), k)
        form.addRow(tr('Point zéro (origine des coordonnées)'), self.zero)
        self.adjust = QCheckBox(tr('Ajuster la composition à la nouvelle taille'))
        self.keep_ratio = QCheckBox(tr('Conserver les proportions'))
        self.keep_ratio.setChecked(True)
        self.adjust.setEnabled(plate is not None and bool(drawing_bbox))
        form.addRow(self.adjust)
        form.addRow(self.keep_ratio)
        self.part_note = None
        if part_note:                                    # pièce 3D : ce que l'ajustement fait au dessin posé dessus
            self.part_note = QLabel('⚠ ' + part_note)
            self.part_note.setWordWrap(True)
            self.part_note.setVisible(False)
            self.adjust.toggled.connect(self.part_note.setVisible)
            form.addRow(self.part_note)
        fit_row = QHBoxLayout()
        self.margin = self._spin(5.0)
        fit = QPushButton(tr('Ajuster au dessin'))
        fit.setEnabled(bool(drawing_bbox))
        fit.clicked.connect(self.fit_drawing)
        fit_row.addWidget(QLabel(tr('Marge')))
        fit_row.addWidget(self.margin)
        fit_row.addWidget(fit)
        form.addRow(fit_row)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        form.addRow(bb)

    @staticmethod
    def _spin(v, neg=False):
        s = QDoubleSpinBox()
        s.setDecimals(3)
        s.setRange(-1e5 if neg else 0, 1e5)
        s.setSuffix(' mm')
        s.setValue(v)
        return s

    def plate(self) -> Plate:
        return Plate(self.w.value(), self.h.value(), self.r.value(), self.mat.text(),
                     self.x.value(), self.y.value(), self.visible, self.t.value(),
                     [sp.value() for sp in self.margins])

    def adjust_matrix(self):
        """Ajuster la composition (TypeEdit) : la transformation qui porte
        l'ancienne plaque sur la nouvelle (proportions gardées au besoin,
        centrée), ou None."""
        from ..core.geom import Affine
        if not self.adjust.isChecked() or self.old is None or self.old.width <= 0 or self.old.height <= 0:
            return None
        new = self.plate()
        sx, sy = new.width / self.old.width, new.height / self.old.height
        if self.keep_ratio.isChecked():
            sx = sy = min(sx, sy)
        ocx, ocy = self.old.x + self.old.width / 2, self.old.y + self.old.height / 2
        ncx, ncy = new.x + new.width / 2, new.y + new.height / 2
        if abs(sx - 1) < 1e-12 and abs(sy - 1) < 1e-12 and abs(ncx - ocx) < 1e-12 and abs(ncy - ocy) < 1e-12:
            return None
        return Affine.translation(ncx, ncy) @ Affine(sx, 0, 0, sy, 0, 0) @ Affine.translation(-ocx, -ocy)

    def fit_drawing(self) -> None:
        """Plaque autour du dessin, à la marge indiquée."""
        if not self.drawing_bbox:
            return
        x0, y0, x1, y1 = self.drawing_bbox
        m = self.margin.value()
        self.x.setValue(x0 - m)
        self.y.setValue(y0 - m)
        self.w.setValue(x1 - x0 + 2 * m)
        self.h.setValue(y1 - y0 + 2 * m)

    # --- plaques enregistrées (réglages) ---------------------------------------
    def _presets(self) -> list[dict]:
        import json
        if self.settings is None:
            return []
        try:
            v = json.loads(self.settings.value('plaques/liste', '[]') or '[]')
            return [p for p in v if isinstance(p, dict) and p.get('nom')]
        except ValueError:
            return []

    def _store(self, lst) -> None:
        import json
        if self.settings is not None:
            self.settings.setValue('plaques/liste', json.dumps(lst, ensure_ascii=False))

    def _load_presets(self) -> None:
        self.presets.clear()
        self.presets.addItem(tr('—'), None)
        for p in self._presets():
            self.presets.addItem(p['nom'], p)

    def _apply_preset(self, i: int) -> None:
        p = self.presets.itemData(i)
        if not p:
            return
        self.w.setValue(float(p.get('largeur', self.w.value())))
        self.h.setValue(float(p.get('hauteur', self.h.value())))
        self.r.setValue(float(p.get('rayon', 0.0)))
        self.t.setValue(float(p.get('epaisseur', 0.0)))
        self.mat.setText(p.get('matiere', ''))

    def save_preset(self, name: str) -> None:
        lst = [p for p in self._presets() if p['nom'] != name]
        lst.append({'nom': name, 'largeur': self.w.value(), 'hauteur': self.h.value(), 'rayon': self.r.value(),
                    'epaisseur': self.t.value(), 'matiere': self.mat.text()})
        lst.sort(key=lambda p: p['nom'].lower())
        self._store(lst)
        self._load_presets()
        self.presets.setCurrentIndex(max(0, self.presets.findText(name)))

    def _save_preset(self) -> None:
        from PySide6.QtWidgets import QInputDialog
        default = f'{self.w.value():g} × {self.h.value():g}' + (f' {self.mat.text()}' if self.mat.text() else '')
        name, ok = QInputDialog.getText(self, tr('Plaques enregistrées'), tr('Nom'), text=default)
        if ok and name.strip():
            self.save_preset(name.strip())

    def _remove_preset(self) -> None:
        p = self.presets.currentData()
        if p:
            self._store([q for q in self._presets() if q['nom'] != p['nom']])
            self._load_presets()


class _UpdateSignals(QObject):
    """Relais entre le fil de vérification des mises à jour et l'interface."""
    found = Signal(object)
    failed = Signal(str)


def io_colors_keep() -> bool:
    """Couleurs des fichiers lus (et des SVG collés) gardées (F10 › Fichiers) ?"""
    from ..io import colors
    return bool(colors.KEEP)


class _ShowWatch(QObject):
    """Le temps d'une commande : une fenêtre, une question ou un menu s'est-il
    montré ? (une commande qui ouvre une fenêtre n'est pas muette, même
    annulée)"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.shown = False

    def eventFilter(self, obj, ev):                       # noqa: N802 (API Qt)
        if not self.shown and ev.type() == QEvent.Type.Show and isinstance(obj, QWidget) and obj.isWindow() \
                and type(obj).__name__ != 'QTipLabel':
            self.shown = True
        return False


def _align_box(it):
    """L'englobant qui sert à aligner. Une variable s'aligne sur sa ligne de base : son contenu change d'une ligne à
    l'autre, et ses jambages ne doivent pas la décaler. Texte tourné ou sur plusieurs lignes : son englobant."""
    from ..core.variables import uses_variables
    bb = it.bbox()
    if bb and isinstance(it, Text) and uses_variables([it]) and '\n' not in it.text:
        m = it.matrix
        if abs(m.b) < 1e-9 and abs(m.c) < 1e-9 and m.d > 0:
            y = m.apply((0.0, 0.0))[1]
            return (bb[0], y, bb[2], y + it.size * m.d)
    return bb


def _with_history(cls):
    """Les commandes de volumes notent de quoi se rejouer (core.history3d)."""
    import functools
    from ..core.history3d import RECORDED

    def recorded(name, fn):
        @functools.wraps(fn)
        def run(self, *args, **kwargs):
            return self._hist_run(name, fn, args, kwargs)
        return run
    for name in RECORDED:
        setattr(cls, name, recorded(name, getattr(cls, name)))
    return cls


