    # --- actions ------------------------------------------------------------
    def _act(self, key, text, slot, shortcut=None, icon_name=None, checkable=False, tip=None):
        a = QAction(text, self)
        a.setProperty('vd_key', key)
        if icon_name:
            a.setIcon(icon(icon_name))
            a.setProperty('vd_icon', icon_name)        # icône refaite au changement de thème
        if shortcut:
            seqs = shortcut if isinstance(shortcut, (list, tuple)) else [shortcut]
            a.setShortcuts([QKeySequence(s) for s in seqs])
            a.setShortcutContext(Qt.ShortcutContext.WindowShortcut)
        a.setCheckable(checkable)
        if tip or shortcut:
            sc = shortcut if isinstance(shortcut, str) else (shortcut[0] if shortcut else '')
            a.setToolTip(f'{tip or text}' + (f'  ({sc})' if sc else ''))
            a.setStatusTip(tip or text)
        # le nom de la commande d'abord : il nomme le pas d'annulation que la commande pose
        if checkable:
            a.toggled.connect(lambda _on, act=a: self._note_command(act))
            a.toggled.connect(slot)
        else:
            a.triggered.connect(lambda _=False, act=a: self._note_command(act))
            # « triggered » passe checked (False) : jamais dans le premier paramètre
            # de la commande (options_dialog(exec_dialog), center_on_plate(axis)…)
            a.triggered.connect(lambda _=False, s=slot, act=a: self._run_command(act, s))
        self.addAction(a)
        self.A[key] = a
        return a

    #: attributs du plan de travail qui bougent tout seuls (mesures d'affichage) : pas un effet
    _FX_NOISE = ('_last', '_render', '_view_t', '_work', '_paint', '_frame', '_fps', '_tick', '_hover', '_cursor')

    def _effect_probe(self) -> tuple:
        """Ce qu'une commande peut changer de visible : dessin et annulation,
        sélection, outil, vue, onglets, panneaux, cases cochées, messages,
        presse-papiers, parcours, plan de travail."""
        from PySide6.QtWidgets import QApplication
        c = self.canvas
        cp = getattr(self, 'cam_panel', None)
        stage = getattr(self, 'stage', None)
        p3 = getattr(self, 'panel3d', None)
        view3 = getattr(p3, 'view', None)
        simple = tuple((k, v) for k, v in vars(c).items()
                       if isinstance(v, (bool, int, float, str)) and not k.startswith(self._FX_NOISE))
        return (len(self._undo), getattr(self, '_undo_pushes', 0), len(self._redo), bool(self.modified), id(c.doc),
                tuple(map(id, c.selection)),
                getattr(c, 'tool', ''), self._fx_counts[0], self._fx_counts[1], id(self._clipboard),
                len(self._clipboard), self.ribbon.currentIndex() if hasattr(self, 'ribbon') else -1,
                tuple(a.isChecked() for a in self.A.values()),
                tuple(d.isVisible() for d in self.findChildren(QDockWidget)), self.isVisible(),
                self.full_screen_mode(),
                id(self.centralWidget()), len(getattr(cp, 'toolpaths', None) or []) if cp is not None else 0,
                len(c.doc.extra), simple, id(QApplication.focusWidget()),
                id(stage.currentWidget()) if stage is not None else 0,
                (getattr(view3, 'yaw', 0), getattr(view3, 'pitch', 0), getattr(view3, 'zoom', 0)))

    def _run_command(self, act, slot) -> None:
        """Commande lancée ; si rien de visible n'a changé (ni fenêtre ni
        message, rien au dessin, à la vue, à la sélection…), la barre d'état le
        dit avec la raison probable : jamais un bouton muet."""
        from PySide6.QtWidgets import QApplication
        if getattr(self, '_fx_depth', 0):                # commande lancée par une autre : sans contrôle
            return slot()
        if self._wants_copy(act):
            slot = lambda run=slot: self._on_copy_of_selection(run)
        if not hasattr(self, '_fx_counts'):
            self._fx_counts = [0, 0]                     # messages de la barre d'état, presse-papiers du système
            self.statusBar().messageChanged.connect(lambda _m: self._fx_counts.__setitem__(0, self._fx_counts[0] + 1))
            QApplication.clipboard().dataChanged.connect(
                lambda: self._fx_counts.__setitem__(1, self._fx_counts[1] + 1))
        before = self._effect_probe()
        watch = _ShowWatch(self)
        app = QApplication.instance()
        app.installEventFilter(watch)
        self._fx_depth = 1
        try:
            slot()
        finally:
            self._fx_depth = 0
            app.removeEventFilter(watch)
            watch.deleteLater()
        if watch.shown:
            return
        try:
            unchanged = self._effect_probe() == before
        except RuntimeError:                              # fenêtre fermée par la commande
            return
        if unchanged:
            self._silent_command(act)

    #: commandes que Maj applique à une copie de la sélection (TypeEdit : « Conserver la sélection ») : celles qui agissent
    #: d'un coup. Pas les outils à la souris ; pas En segment, En angle, Portion en arc, où Maj désigne l'autre portion.
    KEEP_ORIGINAL = frozenset(('combine', 'uncombine', 'to_curves', 'remove_loops', 'explode', 'punch', 'to_arcs', 'segment',
                               'reverse', 'approximate', 'chain', 'fillet', 'chamfer', 'join', 'node_refine', 'node_align_h',
                               'node_align_v', 'node_line', 'node_curve', 'align_left', 'align_right', 'align_top',
                               'align_bottom', 'align_hcenter', 'align_vcenter', 'align_center', 'align_left_out',
                               'align_right_out', 'align_top_out', 'align_bottom_out', 'align_plate_left', 'align_plate_right',
                               'align_plate_top', 'align_plate_bottom', 'center_plate', 'center_plate_h', 'center_plate_v',
                               'space_h', 'space_v', 'distribute_hc', 'distribute_vc', 'same_w', 'same_h', 'same_both',
                               'convert_curves', 'stroke', 'clip', 'mirror_h', 'mirror_v', 'rot90', 'rot-90'))

    @staticmethod
    def _shift_held() -> bool:
        from PySide6.QtWidgets import QApplication
        return bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)

    def _ctrl_on(self, key: str) -> bool:
        """Ctrl enfoncée sur cette commande ; celle de son propre raccourci ne compte pas."""
        act = self.A.get(key)
        return self._ctrl_held() and not (act is not None and any('Ctrl' in s.toString() for s in act.shortcuts()))

    def _held_on(self, key: str) -> bool:
        """Ctrl ou Maj enfoncée sur cette commande ; celles de son propre raccourci ne comptent pas."""
        act = self.A.get(key)
        own = ' '.join(s.toString() for s in act.shortcuts()) if act is not None else ''
        return (self._ctrl_held() and 'Ctrl' not in own) or (self._shift_held() and 'Shift' not in own)

    def _wants_copy(self, act) -> bool:
        """Maj enfoncée sur une de ces commandes, avec une sélection. Un raccourci qui contient lui-même Maj ne compte pas."""
        return (str(act.property('vd_key') or '') in self.KEEP_ORIGINAL and bool(self.canvas.selection) and self._shift_held()
                and not any('Shift' in s.toString() for s in act.shortcuts()))

    def _copy_selection_in_place(self) -> list:
        """Une copie de chaque objet sélectionné, juste au-dessus de lui ; les copies deviennent la sélection."""
        doc = self.canvas.doc
        self.push_undo()
        copies = []
        for it in list(self.canvas.selection):
            layer = doc.layer_of(it)
            c = it.clone()
            at = next((i for i, x in enumerate(layer.items) if x is it), len(layer.items) - 1) if layer is not None else 0
            (layer or doc.active_layer).items.insert(at + 1, c)
            copies.append(c)
        self.canvas.select(copies)
        return copies

    def _on_copy_of_selection(self, slot) -> None:
        """Lance la commande sur une copie de la sélection, annulable d'un coup. Si elle ne fait rien (fenêtre annulée,
        message), la copie est retirée : elle resterait invisible sur l'original et serait gravée deux fois."""
        originals = list(self.canvas.selection)
        copies = self._copy_selection_in_place()
        mark = self._undo[-1]
        try:
            slot()
        finally:
            at = next((i for i, s in enumerate(self._undo) if s is mark), None)
            if at is not None and at + 1 < len(self._undo):
                del self._undo[at + 1]                   # copie et commande : un seul pas
            elif at is not None:
                ids = {id(c) for c in copies}
                for L in self.canvas.doc.layers:
                    L.items[:] = [x for x in L.items if id(x) not in ids]
                del self._undo[at]
                self.canvas.select(originals)
                self.canvas.invalidate()

    def _silent_command(self, act) -> None:
        """« Commande » n'a rien changé : la raison probable (rien de
        sélectionné, aucun parcours calculé), sinon ce que fait la commande."""
        name = act.text().replace('&', '').rstrip('…').strip()
        key = str(act.property('vd_key') or '')
        if key.startswith(('zoom_', 'view_')) or key == 'refresh':
            return                                       # la vue montre déjà ce qu'il faut : rien à dire
        why = []
        if not self.canvas.selection:
            why.append(tr('rien n\'est sélectionné'))
        cp = getattr(self, 'cam_panel', None)
        if key.startswith('cam_') and cp is not None:
            if not cp.setup().operations:
                why.append(tr('aucune opération d\'usinage'))
            elif not getattr(cp, 'toolpaths', None):
                why.append(tr('aucun parcours calculé'))
        if key.startswith(('relief_', 'typeart_')) and self._typeart_selection()[0] is None:
            why.append(tr('aucun relief sélectionné'))
        if key.startswith('solid_') and not self._selected_solids():
            why.append(tr('aucun volume sélectionné'))
        tip = (act.statusTip() or '').strip()
        text = ', '.join(why) if why else (tip if tip and tip != act.text() else tr('rien à faire ici'))
        self.statusBar().showMessage(tr('« {0} » n\'a rien changé : {1}').format(name, text), 8000)

    def _note_command(self, act) -> None:
        """Dernière commande lancée : nomme le pas d'annulation qui suit."""
        import time
        self._last_cmd = (act.text().replace('&', '').rstrip('…'), time.monotonic())

    def _build_actions(self) -> None:
        self.A: dict[str, QAction] = {}
        a = self._act
        # Fichier (raccourcis TypeEdit)
        a('new', tr('Nouveau'), self.new_document, 'Ctrl+N', 'new',
          tip=tr('Nouveau dessin, dans un nouvel onglet'))
        a('open', tr('Ouvrir'), self.open_dialog, ['Ctrl+O', 'Ctrl+Shift+O'], 'open')
        a('doc_close', tr('Fermer l\'onglet'), lambda: self.close_tab(), 'Ctrl+F4', 'delete',
          tip=tr('Fermer le dessin de l\'onglet affiché'))
        a('doc_next', tr('Onglet de dessin suivant'), lambda: self.step_tab(1), 'Ctrl+F6', None)
        a('doc_prev', tr('Onglet de dessin précédent'), lambda: self.step_tab(-1), 'Ctrl+Shift+F6', None)
        a('save', tr('Enregistrer'), self.save, 'Ctrl+S', 'save')
        a('saveas', tr('Enregistrer sous'), self.save_as, 'Ctrl+Shift+S', 'save')
        a('doc_info', tr('Informations'), lambda _=False: self.doc_info_dialog(), None, 'variables',
          tip=tr('Titre, auteur, client et commentaires du document (gardés dans le fichier), et ses chiffres : '
                 'calques, objets, temps passé'))
        a('compare', tr('Comparer'), lambda _=False: self.compare_dialog(), None, 'compare',
          tip=tr('Comparer le dessin à un autre (onglet ouvert ou fichier) : ajouté en vert, enlevé en rouge, '
                 'modifié en orange'))
        a('compare_next', tr('Différence suivante'), lambda _=False: self.compare_step(1), None, 'compare_next',
          tip=tr('Montrer la zone suivante qui porte des différences'))
        a('compare_prev', tr('Différence précédente'), lambda _=False: self.compare_step(-1), None, 'compare_prev',
          tip=tr('Montrer la zone précédente qui porte des différences'))
        a('compare_close', tr('Fermer la comparaison'), lambda _=False: self.compare_close(), None, 'compare_close',
          tip=tr('Effacer les couleurs de la comparaison'))
        for k in ('compare_next', 'compare_prev', 'compare_close'):
            self.A[k].setEnabled(False)
        a('import', tr('Importer'), self.import_dialog, 'Ctrl+I', 'import')
        a('export', tr('Exporter'), self.export_dialog, 'Ctrl+E', 'export')
