    def _ribbon_tab_changed(self, i: int) -> None:
        """Mise en forme passe devant (à la main ou par l'outil Texte) : l'onglet d'où l'on vient est retenu, il
        revient quand elle s'en va."""
        r = self.ribbon
        prev = getattr(self, '_ribbon_cur', -1)
        title = getattr(self, 'text_tab_title', None)
        if title is not None and 0 <= i < r.count() and r.tabText(i) == title and prev != i:
            self._text_tab_back = prev
        self._ribbon_cur = i

    def _ribbon_tab_clicked(self, i: int) -> None:
        """Un onglet du ruban cliqué (pas un onglet qui change de lui-même) : CAD range les panneaux FAO, un onglet
        FAO les rétablit (`ui.columns`)."""
        cols = getattr(self, 'columns', None)
        pg = self.ribbon.page(i) if 0 <= i < self.ribbon.count() else None
        if cols is None or pg is None:
            return
        cols.tab_clicked('cad' if pg.property('vd_cad') in ('2d', '3d') else 'fao' if pg.property('vd_fao') else '')

    def column_panel(self, side: str, button=None):
        """La fenêtre de la colonne `side` (clic droit sur son bouton) : tout ce qu'elle peut accueillir, un œil par
        panneau."""
        cols = getattr(self, 'columns', None)
        return cols.show_panel(side, button) if cols is not None else None

    def _column(self, side: str, on: bool) -> None:
        """La colonne de panneaux `side` (« gauche », « droite ») montrée ou cachée."""
        cols = getattr(self, 'columns', None)
        if cols is not None:
            cols.set_shown(side, bool(on))

    def _dock_follows(self, dock, key: str) -> None:
        """La commande cochable `key` suit le panneau `dock` : ouvert ou fermé — pas seulement recouvert, ou
        découvert, par l'onglet d'un voisin de sa colonne (Qt le dit « invisible » alors), ni caché avec sa colonne."""
        def follow(v):
            cols = getattr(self, 'columns', None)
            if (cols is not None and cols.busy()) or bool(v) == dock.isHidden():
                return
            if self.A[key].isChecked() != bool(v):
                self.A[key].setChecked(bool(v))
        dock.visibilityChanged.connect(follow)

    def dock_actions_follow(self) -> None:
        """Après une colonne cachée ou montrée, des panneaux rangés par l'onglet CAD : « Panneau FAO » dit si la FAO
        est ouverte (ce qui est retenu), « Bibliothèque » si son panneau est montré — sans rien déclencher."""
        fao = self.settings.value('vue/panneau_fao', 'false') in (True, 'true')
        for key, on in (('cam_panel', fao), ('symbols', not self.dock_symbols.isHidden())):
            a = self.A.get(key)
            if a is not None and a.isChecked() != on:
                blocked = a.blockSignals(True)
                a.setChecked(on)
                a.blockSignals(blocked)
                a.changed.emit()

    def plugin_dock_allowed(self, dock) -> bool:
        """Le panneau d'un plugin est-il celui de la machine du dessin (ou de toutes) ?"""
        name = dock.objectName()
        return bool(getattr(self, '_plugin_docks_on', {}).get(name[len('plugin_'):], True))

    def _build_ribbon(self) -> None:
        r = self.ribbon = Ribbon()
        r.currentChanged.connect(self._ribbon_tab_changed)
        r.tabBarClicked.connect(self._ribbon_tab_clicked)
        A = self.A
        t = r.add_tab(tr('Fichier'))
        g = t.group(tr('Document'))
        for k in ('new', 'open', 'save', 'saveas'):
            g.add(A[k])
        from PySide6.QtWidgets import QMenu, QToolButton
        self.recent_menu = QMenu(self)
        self.recent_menu.aboutToShow.connect(self._fill_recent)
        rb = QToolButton()
        rb.setText(tr('Récents'))
        rb.setIcon(icon('open'))
        rb.setIconSize(rb.iconSize() * 1.6)
        rb.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextUnderIcon)
        rb.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        rb.setMenu(self.recent_menu)
        rb.setAutoRaise(True)
        rb.setProperty('ribbon_big', False)          # petit bouton, dans la colonne des modèles
        rb.setToolTip(tr('Fichiers ouverts récemment'))
        g.add_widget(rb)
        g.add(A['new_from_template'], big=False)
        g.add(A['save_as_template'], big=False)
        g.add(A['doc_info'], big=False)
        g.add(A['file_previews'], big=False)
        g.add(A['quit'], big=False)
