    def stepgen_dialog(self, category: str | None = None, exec_dialog: bool = True):
        """Fenêtre des générateurs STEP (ui.stepgen_dialog) ; rend la fenêtre sans l'ouvrir si
        `exec_dialog` est faux."""
        from .stepgen_dialog import StepGenDialog
        dlg = StepGenDialog(self, category)
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def stepgen_drawing(self, exec_dialog: bool = True, shape: str = 'extrudee'):
        """Fenêtre « Pièce du dessin » (ui.drawing_step_dialog) : les contours fermés des objets choisis
        (formes, textes par leur contour) en pièce STEP, extrudée ou tournée (`shape`) ; rend la fenêtre sans
        l'ouvrir si `exec_dialog` est faux, None si rien de fermé n'est choisi (dit dans la barre d'état)."""
        from ..core.geom import Path
        from .drawing_step_dialog import DrawingStepDialog
        contours = [c for leaf in _leaves(self.canvas.selection) for c in (getattr(item_path(leaf), 'contours', None)
                                                                          or []) if c]
        if not any(c.closed for c in contours):
            msg = tr('Choisir d\'abord dans le dessin des formes fermées (le bord de la pièce, ses trous)')
            self.statusBar().showMessage(msg, 8000)
            if exec_dialog and self.isVisible():
                QMessageBox.information(self, tr('Pièce du dessin'), msg)
            return None
        src = getattr(self.canvas.doc, 'source_path', '')
        name = pathlib.Path(src).stem if src else 'piece'
        dlg = DrawingStepDialog(self, Path(contours), name=name, shape=shape)
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def stepgen_edit(self, item=None, exec_dialog: bool = True):
        """La pièce générée `item` (sinon la seule choisie dans le dessin) rouverte dans la fenêtre des
        générateurs, « Remplacer dans le dessin » ; rend la fenêtre sans l'ouvrir si `exec_dialog` est faux,
        None si aucune pièce générée n'est choisie (dit dans la barre d'état)."""
        from .stepgen_dialog import StepGenDialog
        if item is None:
            sel = [it for it in self.canvas.selection if isinstance(getattr(it, 'extra', None), dict)
                   and 'stepgen' in it.extra]
            item = sel[0] if len(sel) == 1 and len(self.canvas.selection) == 1 else None
        dlg = StepGenDialog(self, None) if item is not None else None
        if dlg is None or not dlg.edit_item(item):
            if dlg is not None:
                dlg.deleteLater()
            msg = tr('Choisir d\'abord dans le dessin une seule pièce ajoutée par les générateurs STEP')
            self.statusBar().showMessage(msg, 8000)
            if exec_dialog and self.isVisible():
                QMessageBox.information(self, tr('Modifier la pièce générée'), msg)
            return None
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def step_bodies(self, path: str | None = None, exec_dialog: bool = True, picks=None):
        """Fenêtre « Corps d'un STEP » (ui.step_edit_dialog) sur `path`, sinon sur la pièce 3D du dessin
        (le corps des faces choisies coché seul), sinon sur un fichier demandé ; rend la fenêtre sans
        l'ouvrir si `exec_dialog` est faux."""
        from ..io import model3d
        from .step_edit_dialog import StepBodiesDialog
        name = None                                        # nom du corps choisi dans la vue 3D
        if path is None:
            src = model3d.source_of(self.canvas.doc)
            if src and pathlib.Path(src).suffix.lower() in ('.step', '.stp'):
                path = src
                p3 = getattr(self, 'panel3d', None)
                if picks is None and p3 is not None and p3.view.model is not None:
                    b = p3.selected_body()
                    names = list(getattr(p3.view.model, 'body_names', []) or [])
                    if b is not None and b < len(names):    # numéros des corps du fichier, pas des morceaux
                        picks, name = [b], names[b]
        dlg = StepBodiesDialog(self, None)
        ok = dlg.load(path, picks) if path else (dlg.load_file() if exec_dialog else False)
        if ok and name is not None and (picks[0] >= len(dlg.bodies) or dlg.bodies[picks[0]].name != name):
            dlg.check_all(True)                            # le corps de la vue 3D n'est pas celui du fichier
        if not ok and exec_dialog:
            if dlg.info.text():
                QMessageBox.warning(self, tr('Corps d\'un STEP'), dlg.info.text())
            dlg.deleteLater()
            return None
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def step_screw(self, path: str | None = None, face=None, exec_dialog: bool = True):
        """Fenêtre « Vis dans ce trou » (ui.screw_dialog) : la paroi `face` (numéro de face, ou plusieurs
        essayées dans l'ordre) d'un trou de la pièce STEP `path`, sinon les faces choisies dans la vue 3D de
        la pièce du dessin ; rend la fenêtre sans l'ouvrir si `exec_dialog` est faux, None si aucune face
        n'est choisie (dit dans la barre d'état)."""
        from .screw_dialog import ScrewDialog
        if path is None or face is None:
            got = self._step_hole_faces(tr('Vis dans ce trou'), exec_dialog)
            if got is None:
                return None
            path, face = got
        dlg = ScrewDialog(self, path, face)
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def step_part_hole(self, path: str | None = None, face=None, exec_dialog: bool = True):
        """Fenêtre « Pièce dans ce trou » (ui.part_hole_dialog) : la paroi `face` d'un alésage de la pièce STEP
        `path`, sinon les faces choisies dans la vue 3D de la pièce du dessin ; comme `step_screw`."""
        from .part_hole_dialog import PartHoleDialog
        if path is None or face is None:
            got = self._step_hole_faces(tr('Pièce dans ce trou'), exec_dialog)
            if got is None:
                return None
            path, face = got
        dlg = PartHoleDialog(self, path, face)
        if not exec_dialog:
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return None

    def _step_hole_faces(self, title: str, exec_dialog: bool):
        """(pièce STEP du dessin, faces choisies dans sa vue 3D) ; None si aucune, dit dans la barre d'état (et
        dans une fenêtre `title` si `exec_dialog`)."""
        from ..io import model3d
        src = model3d.source_of(self.canvas.doc)
        p3 = getattr(self, 'panel3d', None)
        sel = []
        if src and pathlib.Path(src).suffix.lower() in ('.step', '.stp') and p3 is not None \
                and p3.view.model is not None and not getattr(p3, 'volumes_shown', False) \
                and p3._model_source() is not None:
            sel = sorted(p3.view.sel_faces)            # numéros des faces du fichier (mêmes pour un corps seul)
        if not sel:
            msg = tr('Choisir d\'abord la paroi d\'un trou dans la vue 3D d\'une pièce STEP')
            self.statusBar().showMessage(msg, 8000)
            if exec_dialog and self.isVisible():
                QMessageBox.information(self, title, msg)
            return None
        return src, sel

    def _view3d_faces(self, need_selection: bool = True):
        """(vue 3D, modèle) de la pièce montrée dans la vue 3D, avec des faces choisies si `need_selection` ;
        sinon None, dit dans la barre d'état."""
        p3 = getattr(self, 'panel3d', None)
        view = p3.view if p3 is not None else None
        if view is None or view.model is None:
            msg = tr('Ouvrir d\'abord une pièce 3D (STEP, STL) dans la vue 3D')
        elif need_selection and not view.sel_faces:
            msg = tr('Choisir d\'abord une ou plusieurs faces dans la vue 3D')
        else:
            return view, view.model
        self.statusBar().showMessage(msg, 8000)
        return None

    def step_similar(self) -> list:
        """Les faces semblables à celles choisies dans la vue 3D (core.facesel) choisies à leur tour ; rend
        leurs numéros."""
        from ..core import facesel
        return self._step_grow(facesel.similar, tr('{0} face(s) semblable(s) choisie(s)'))

    def step_parallel(self) -> list:
        """Les faces parallèles à celles choisies dans la vue 3D (core.facesel) choisies ; rend leurs numéros."""
        from ..core import facesel
        return self._step_grow(facesel.parallel, tr('{0} face(s) parallèle(s) choisie(s)'))

    def step_coaxial(self) -> list:
        """Les faces du même axe que celles choisies dans la vue 3D (core.facesel) choisies ; rend leurs
        numéros."""
        from ..core import facesel
        return self._step_grow(facesel.coaxial, tr('{0} face(s) coaxiale(s) choisie(s)'))

    def step_tangent(self) -> list:
        """Les faces qui suivent celles choisies dans la vue 3D sans arête vive (core.facesel) choisies à leur
        tour ; rend leurs numéros."""
        from ..core import facesel
        return self._step_grow(facesel.tangent, tr('{0} face(s) tangente(s) choisie(s)'))

    def step_invert(self) -> list:
        """Les faces des corps des faces choisies dans la vue 3D qui ne sont pas choisies, choisies à leur place ;
        rend leurs numéros."""
        from ..core import facesel
        return self._step_grow(facesel.invert, tr('{0} face(s) choisie(s) : le reste du corps'))

    def step_body_faces(self) -> list:
        """Toutes les faces des corps des faces choisies dans la vue 3D choisies ; rend leurs numéros."""
        from ..core import facesel
        return self._step_grow(facesel.body_faces, tr('{0} face(s) du corps choisie(s)'))

    def _step_grow(self, grow, message: str) -> list:
        """Les faces choisies dans la vue 3D remplacées par `grow(modèle, faces)`, dit dans la barre d'état."""
        got = self._view3d_faces()
        if got is None:
            return []
        view, model = got
        faces = grow(model, sorted(view.sel_faces))
        view.set_selection(faces)
        self.statusBar().showMessage(message.format(len(faces)), 8000)
        return faces

    def step_measure(self, exec_dialog: bool = True) -> list:
        """Les faces choisies dans la vue 3D décrites et mesurées (ui.step_select) ; rend les lignes (aussi
        montrées dans une fenêtre si `exec_dialog`)."""
        from ..core import facesel
        from .step_select import measure_lines
        got = self._view3d_faces()
        if got is None:
            return []
        view, model = got
        lines = measure_lines(facesel.measure(model, sorted(view.sel_faces)))
        self.statusBar().showMessage(lines[-1] if lines else '', 8000)
        if exec_dialog and self.isVisible():
            box = QMessageBox(self)
            box.setWindowTitle(tr('Mesurer la sélection'))
            box.setText('\n'.join(lines))
            box.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            copy = box.addButton(tr('Copier'), QMessageBox.ButtonRole.ActionRole)
            box.addButton(QMessageBox.StandardButton.Close)
            box.exec()
            if box.clickedButton() is copy:
                from PySide6.QtWidgets import QApplication
                QApplication.clipboard().setText('\n'.join(lines))
            box.deleteLater()
        return lines

    def step_combine(self, paths: list | None = None, out: str | None = None) -> str | None:
        """Les fichiers STEP `paths` (demandés si None) réunis en une pièce `out` (demandée si None), chaque
        corps à sa place ; rend le fichier écrit."""
        from ..io import step_extract as X
        from .step_edit_dialog import STEP_FILTER
        from .stepgen_dialog import depot
        if paths is None:
            paths, _f = QFileDialog.getOpenFileNames(self, tr('Réunir des STEP'), depot(self.settings), STEP_FILTER)
        if not paths:
            return None
        if out is None:
            first = pathlib.Path(paths[0])
            out, _f = QFileDialog.getSaveFileName(self, tr('Pièce réunie'), str(first.parent / 'reunion.step'),
                                                  STEP_FILTER)
            if not out:
                return None
        from ..core.progress import Cancelled
        from . import progress
        from .step_edit_dialog import ERRORS
        try:
            done = progress.run(self, tr('Réunir des STEP'), X.combine, [(p, None, None) for p in paths], out,
                                name=pathlib.Path(out).stem)
        except Cancelled:
            return None
        except ERRORS as ex:
            msg = tr('Réunion impossible : {0}').format(ex)
            self.statusBar().showMessage(msg, 8000)
            if self.isVisible():
                QMessageBox.warning(self, tr('Réunir des STEP'), msg)
            return None
        self.statusBar().showMessage(tr('{0} fichiers réunis dans {1}').format(len(paths), done), 8000)
        return done

    def step_pattern(self, path: str | None = None, exec_dialog: bool = True, picks=None):
        """Fenêtre « Répéter des corps » (ui.step_pattern_dialog) sur `path`, sinon sur la pièce 3D du dessin
        (le corps des faces choisies seul), sinon sur un fichier demandé ; rend la fenêtre sans l'ouvrir si
        `exec_dialog` est faux, sinon le fichier écrit."""
        from ..io import model3d
        from .step_edit_dialog import STEP_FILTER
        from .step_pattern_dialog import StepPatternDialog
        from .stepgen_dialog import depot
        if path is None:
            src = model3d.source_of(self.canvas.doc)
            if src and pathlib.Path(src).suffix.lower() in ('.step', '.stp'):
                path = src
                p3 = getattr(self, 'panel3d', None)
                if picks is None and p3 is not None and p3.view.model is not None and p3.selected_body() is not None:
                    picks = [p3.selected_body()]
        if path is None and exec_dialog:
            path, _f = QFileDialog.getOpenFileName(self, tr('Répéter des corps'), depot(self.settings), STEP_FILTER)
        if not path:
            return None
        dlg = StepPatternDialog(self, path, picks)
        if not exec_dialog:
            return dlg
        ok, n = dlg.exec(), dlg.count.value()
        out = dlg.written if ok else None
        dlg.deleteLater()
        if out:
            self.statusBar().showMessage(tr('{0} copie(s) écrite(s) dans {1}').format(n, out), 8000)
        return out

    def step_depot(self, exec_dialog: bool = True):
        """Le dépôt STEP dans le navigateur à vignettes (créé s'il manque)."""
        from .stepgen_dialog import depot
        folder = pathlib.Path(depot(self.settings))
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError as ex:
            self.statusBar().showMessage(tr('Dépôt STEP inaccessible : {0}').format(ex), 6000)
            return None
        return self.file_browser(exec_dialog, folder=str(folder), exts=('.stp', '.step'), remember=False)

    def step_depot_folder(self, path: str | None = None) -> str | None:
        """Choisir le dossier du dépôt STEP."""
        from .stepgen_dialog import DEPOT_KEY, depot
        if path is None:
            path = QFileDialog.getExistingDirectory(self, tr('Dossier du dépôt STEP'), depot(self.settings))
            if not path:
                return None
        self.settings.setValue(DEPOT_KEY, str(path))
        self.statusBar().showMessage(tr('Dépôt STEP : {0}').format(path), 5000)
        return str(path)

