    def show_toolpaths(self, where: str) -> None:
        """Parcours calculés : '2d' (sur le dessin), '3d' (trajectoires en
        3D, matière intacte), 'sim2d' (simulation, image ombrée), 'sim3d'
        (simulation en 3D, matière enlevée)."""
        if where == 'sim2d':
            self.cam_panel.simulate()
            return
        if where == '2d':
            self.set_view_mode('2d')
            self.cam_panel._repaint_paths()
            return
        p = self._ensure_panel3d()
        key = 'simulation' if where == 'sim3d' else 'parcours'
        p.source.blockSignals(True)
        p.source.setCurrentIndex(max(0, p.source.findData(key)))
        p.source.blockSignals(False)
        if not p.paths.isChecked():
            p.paths.setChecked(True)
        p.stale = True
        self.set_view_mode('3d')

    def set_toolpaths_visible(self, on: bool) -> None:
        """Calque « Trajectoires » : montré ou caché, en 2.5D et en 3D."""
        on = bool(on)
        self.canvas.toolpaths_visible = on
        self.settings.setValue('vue/calque_trajectoires', on)
        self.canvas.invalidate()
        p3 = getattr(self, 'panel3d', None)
        if p3 is not None and p3.paths.isChecked() != on:
            p3.paths.setChecked(on)
        self.layers_panel.refresh()

    def place_model3d(self, *, exec_dialog: bool = True, placement=None, undo: bool = True):
        """Placer la pièce 3D du document comme sur la machine ; rend le
        placement appliqué (ou la fenêtre, sans l'ouvrir) ; `undo` : son pas
        d'annulation (sans : celui de l'appelant, la plaque)."""
        import pathlib
        from dataclasses import dataclass
        from ..core import placement3d as P3
        from ..io import model3d
        doc = self.canvas.doc
        src = model3d.source_of(doc)
        if src is None:
            self.statusBar().showMessage(tr('Ce dessin ne vient pas d\'un fichier 3D (STEP, STL, 3D XML)'), 5000)
            return None
        cur = P3.of(doc)
        if placement is None:
            from .dialogs import ParamsDialog

            @dataclass
            class P:
                face: str = cur.face
                rot: float = cur.rot
                mode: str = cur.mode
                dx: float = cur.dx
                dy: float = cur.dy
            labels = {'face': tr('Face tournée vers l\'outil'), 'rot': tr('Rotation autour de Z (°)'),
                      'mode': tr('Position'), 'dx': tr('Décalage X (mm, position libre)'),
                      'dy': tr('Décalage Y (mm, position libre)')}
            faces = [(k, tr(v)) for k, v in P3.FACE_LABELS.items()]
            try:                                           # faces d'appui stables (pièce posée dessus)
                from ..cam import mill3d
                for key, area, _f in P3.rest_faces(mill3d.raw_model(src)):
                    if key not in P3.FACES:
                        faces.append((key, tr('Posée sur une face plane de {0} mm²').format(f'{area:.0f}')))
            except Exception:                              # noqa: BLE001 — pièce illisible : les six faces
                pass
            if cur.face not in [k for k, _t in faces]:
                faces.append((cur.face, tr(P3.face_label(cur.face))))
            choices = {'face': faces, 'mode': [(k, tr(v)) for k, v in P3.MODES.items()]}
            dlg = ParamsDialog(self, tr('Placer la pièce 3D'), P(), labels, choices=choices)
            if not exec_dialog:
                return dlg
            if not dlg.exec():
                return None
            r = dlg.result_params()
            placement = P3.Placement(r.face, float(r.rot), r.mode, float(r.dx), float(r.dy))
        pl = placement
        if pl.mode != 'libre':                            # décalage d'après la plaque
            from .progress import Cancelled, run
            try:
                m = run(self, tr('Placer la pièce 3D'), model3d.load, src, P3.Placement(pl.face, pl.rot))
            except Cancelled:
                return None
            plate = doc.plate
            box = (plate.x, plate.y, plate.width, plate.height) if plate is not None else None
            P3.resolve(pl, m.bounds(), box)
        if undo:
            self.push_undo(tr('Placer la pièce 3D'), keys=('placement3d',))
        if pathlib.Path(src).suffix.lower() in ('.stp', '.step'):
            from ..io import step
            new = step.read(src, pl)                       # vue de dessus de la face choisie
            if not any(L.items for L in new.layers) and P3.normal_of(pl.face) is not None:
                new = self._placed_mesh_view(src, pl) or new   # posée en biais : aucune face horizontale lue
            for L in doc.layers:
                L.items = self._without_view(L.items)
            keep = [L for L in doc.layers if L.items or not L.name.startswith('STEP')]
            doc.layers = keep + [L for L in new.layers if L.items]
            if not doc.layers:
                doc.layers = new.layers
        doc.extra[P3.KEY] = P3.to_dict(pl)
        from ..core import surface2d
        surface2d.follow(doc)                              # surfaces posées : leur contenu suit la pièce
        self.canvas.selection = []
        self.canvas.invalidate()
        self.layers_panel.refresh()
        self._on_doc_changed()
        if self.panel3d is not None:
            self.panel3d.stale = True
            self._refresh_3d_if_visible()
        return pl

    def _placed_mesh_view(self, src, pl):
        """Vue de dessus du maillage de la pièce posée (niveaux des faces
        vers le haut et silhouette) — quand la lecture du STEP posé en biais
        n'en trouve aucune horizontale ; None si elle échoue."""
        import pathlib
        from ..cam import mill3d
        from ..io import mesh3d, model3d
        try:
            m = model3d.placed(mill3d.raw_model(src), pl)
            new = mesh3d.top_view(m.triangles, pathlib.Path(src).name)
        except Exception:                                  # noqa: BLE001 — pièce illisible : dessin inchangé
            return None
        for L in new.layers:
            L.name = 'STEP ' + L.name                      # remplacée au prochain placement, comme la vue du STEP
            for it in L.items:
                it.extra['step'] = 1
        return new

    def set_view_mode(self, mode: str) -> None:
        """Plan de travail en 2D (dessin, modification) ou en 3D (la pièce
        usinée, vue seule ; recalculée quand le dessin change)."""
        if mode == '3d':
            self._ensure_panel3d()
            self.stage.setCurrentWidget(self.panel3d)
            if self.panel3d.stale:
                self.panel3d.refresh()
            self.panel3d.view.setFocus()
        else:
            self.stage.setCurrentIndex(0)
            self.canvas.setFocus()
        for k in ('view_2d', 'view_3d'):
            self.A[k].setChecked(k == f'view_{mode}')
        go = '2d' if mode == '3d' else '3d'              # dans les menus, l'icône montre où il mène
        self.A['view_toggle'].setProperty('vd_mode', mode)
        self.A['view_toggle'].setIcon(icon(f'view_{go}'))
        self.A['view_toggle'].setProperty('vd_icon', f'view_{go}')
        self._fao_tabs(mode)

    def _fao_tabs(self, mode: str | None = None) -> None:
        """La FAO suit le plan de travail : seul l'onglet du mode (FAO 2D ou FAO 3D) paraît, et s'il
        était choisi l'autre le remplace. Un onglet masqué par l'utilisateur, ou absent de la disposition
        TypeEdit 13, le reste."""
        from .ribbon_editor import hidden
        r = getattr(self, 'ribbon', None)
        if r is None:
            return
        mode = mode or self.view_mode()
        self._cad_tabs(mode)
        want, other = (tr('FAO 3D'), tr('FAO 2D')) if mode == '3d' else (tr('FAO 2D'), tr('FAO 3D'))
        titles = [r.tabText(i) for i in range(r.count())]
        if want not in titles or other not in titles:
            return
        here, there = titles.index(want), titles.index(other)
        in_te = bool(r.widget(here).property('te_layout'))
        r.setTabVisible(here, in_te if getattr(self, 'layout_active', False)
                        else (not in_te and want not in set(hidden(self.settings))))
        if r.currentIndex() == there and r.isTabVisible(here):
            r.setCurrentIndex(here)
        r.setTabVisible(there, False)

    def _cad_tabs(self, mode: str | None = None) -> None:
        """L'onglet CAD suit le plan de travail : la page du dessin 2D en 2D, celle de la création 3D en 3D, sous le même
        titre (propriété `vd_cad` de la page). S'il était choisi, il le reste. Les pages de l'autre disposition
        (VectorDrive, TypeEdit 13), ou masquées par l'utilisateur, le restent."""
        from .ribbon_editor import hidden
        r = getattr(self, 'ribbon', None)
        if r is None:
            return
        mode = mode or self.view_mode()
        te = getattr(self, 'layout_active', False)
        hid = set(hidden(self.settings))
        show, hide = [], []
        for i in range(r.count()):
            pg = r.page(i)
            side = pg.property('vd_cad') if pg is not None else None
            if side not in ('2d', '3d'):
                continue
            in_te = bool(r.widget(i).property('te_layout'))
            ok = in_te if te else (not in_te and r.tabText(i) not in hid)
            (show if ok and side == mode else hide).append(i)
        for i in show:
            r.setTabVisible(i, True)
        if r.currentIndex() in hide and show:            # CAD choisi : il le reste, dans le nouveau mode
            r.setCurrentIndex(show[0])
        for i in hide:
            r.setTabVisible(i, False)

    def toggle_view_mode(self) -> None:
        """Le bouton va-et-vient : de la 2D à la 3D, et retour."""
        self.set_view_mode('2d' if self.view_mode() == '3d' else '3d')

    def animate_parts(self):
        """Le bouton Animation : la vue 3D et ses corps en mouvement. Rend la fenêtre, None si rien ne peut s'animer."""
        self.set_view_mode('3d')
        dlg = self.panel3d.animate()
        if dlg is None:
            self.statusBar().showMessage(tr('Animation : il faut une pièce 3D en plusieurs corps (assemblage STEP, volumes '
                                            'du dessin)'), 8000)
        return dlg

    def set_3d_view(self, name: str) -> None:
        """Plan de travail en 3D, vue prédéfinie (view3d.VIEWS)."""
        self.set_view_mode('3d')
        self.panel3d.view.set_view(name)

    def view_mode(self) -> str:
        return '3d' if self.panel3d is not None and self.stage.currentWidget() is self.panel3d else '2d'

    def _refresh_3d_if_visible(self) -> None:
        if self.view_mode() == '3d' and self.panel3d.stale:
            self.panel3d.refresh()

    # --- ruban personnalisé ---------------------------------------------------------------
    def _build_custom_tab(self, restyle: bool = True) -> None:
        """Onglets à soi (« Mon onglet » et les suivants : commandes choisies,
        libellés choisis, à leur place) et onglets masqués, d'après les
        réglages ; refait à chaque changement."""
        from .ribbon_editor import AFTER, RelayAction, free_title, hidden, load_all
        r = self.ribbon
        for w in r.custom_pages:
            i = r.indexOf(w)
            if i >= 0:
                r.removeTab(i)
            w.deleteLater()
        for a in self._custom_relays:
            a.detach()
            a.deleteLater()
        r.custom_pages, r.custom_titles, r.custom_rank, self._custom_relays = [], [], [], []
        r.custom_title = None
        taken = {r.tabText(i) for i in range(r.count())}
        placed: dict = {}                                # onglets à soi déjà posés à cette place
        for rank, conf in enumerate(load_all(self.settings)):
            groups = [(gi, g) for gi, g in enumerate(conf['groupes'])
                      if any(c['key'] in self.A for c in g['commandes'])]
            if not groups:
                continue                                 # onglet vide : pas affiché (rempli par clic droit)
            title = free_title(conf['titre'], taken)     # jamais le titre d'un autre onglet
            taken.add(title)
            pos = conf['position']
            anchor = self._tab_index(pos[len(AFTER):]) if pos.startswith(AFTER) else -1
            if pos == 'debut':
                index = placed.get(pos, 0)
            elif anchor >= 0:
                index = anchor + 1 + placed.get(pos, 0)
            else:
                end = r.indexOf(r.last_left) if r.last_left is not None else -1   # « fin » : avant FAO
                index = end if end >= 0 else r.count()
            placed[pos] = placed.get(pos, 0) + 1
            page = r.insert_tab(index, title)
            for gi, g in groups:
                grp = page.group(g['titre'])
                for ci, c in enumerate(g['commandes']):
                    act = self.A.get(c['key'])
                    if act is None:
                        continue                         # commande d'un plugin absent : gardée dans les réglages
                    if c.get('texte'):
                        act = RelayAction(act, c['texte'], self)
                        self._custom_relays.append(act)
                    b = grp.add(act, big=bool(c.get('big')))
                    b.setProperty('ribbon_custom_at', f'{rank}:{gi}:{ci}')
            sc = next(r.widget(i) for i in range(r.count()) if r.page(i) is page)
            sc.setProperty('ribbon_custom', True)
            r.custom_pages.append(sc)
            r.custom_titles.append(title)
            r.custom_rank.append(rank)
            if r.custom_title is None:
                r.custom_title = title
        hid = set(hidden(self.settings))
        te = getattr(self, 'layout_active', False)
        for i in range(r.count()):
            w = r.widget(i)
            if w.property('te_context'):
                continue                                 # onglet contextuel TypeEdit : selon le mode choisi
            in_te = bool(w.property('te_layout'))
            if not in_te and r.tabText(i) == getattr(self, 'text_tab_title', None):
                continue                                 # onglet contextuel : selon la sélection
            if w.property('ribbon_custom'):
                r.setTabVisible(i, True)                 # onglets à soi : dans les deux dispositions
                continue
            if w.property('ribbon_both'):                # Aide : dans les deux dispositions
                r.setTabVisible(i, r.tabText(i) not in hid)
                continue
            r.setTabVisible(i, in_te if te else (not in_te and r.tabText(i) not in hid))
        self._fao_tabs()
        if not r.isTabVisible(r.currentIndex()):
            vis = [i for i in range(r.count()) if r.isTabVisible(i)]
            if vis:
                r.setCurrentIndex(vis[0])
        if restyle:
            self._apply_ribbon_options()
        else:
            r.finalize()

    def _tab_index(self, title: str) -> int:
        """Onglet titré `title` (de la disposition affichée de préférence ; ni
        contextuel, ni à soi) ; -1 s'il n'y en a pas."""
        r = self.ribbon
        te = bool(getattr(self, 'layout_active', False))
        found = -1
        for i in range(r.count()):
            w = r.widget(i)
            if r.tabText(i) != title or w.property('te_context') or w.property('ribbon_custom'):
                continue
            if bool(w.property('te_layout')) == te:
                return i
            if found < 0:
                found = i
        return found

    def _custom_rank_at(self, index: int) -> int:
        """Rang dans les réglages de l'onglet à soi `index` du ruban ; -1 si ce
        n'est pas un onglet à soi."""
        r = self.ribbon
        w = r.widget(index) if index >= 0 else None
        return r.custom_rank[r.custom_pages.index(w)] if w is not None and w in r.custom_pages else -1

    def _action_key(self, act) -> str | None:
        from .ribbon_editor import RelayAction
        src = act.src if isinstance(act, RelayAction) else act
        return next((k for k, a in self.A.items() if a is src), None)

    def _save_custom(self, tabs: list, message: str) -> None:
        from .ribbon_editor import save_all
        save_all(self.settings, tabs)
        self._build_custom_tab()
        self.statusBar().showMessage(message, 5000)

    def add_to_custom_tab(self, key: str, rank: int, title: str | None = None) -> int:
        """Commande `key` au bout du dernier groupe de l'onglet à soi `rank`
        (-1 : nouvel onglet, nommé `title` ou demandé) ; rend le rang de
        l'onglet (-1 : rien fait)."""
        from .ribbon_editor import free_title, load_all
        tabs = load_all(self.settings)
        if rank < 0 or rank >= len(tabs):
            if title is None:
                from PySide6.QtWidgets import QInputDialog
                title, ok = QInputDialog.getText(self, tr('Nouvel onglet'), tr('Nom de l\'onglet'),
                                                 text=tr('Mon onglet {0}').format(len(tabs) + 1))
                if not ok:
                    return -1
            taken = {self.ribbon.tabText(i) for i in range(self.ribbon.count())
                     if not self.ribbon.widget(i).property('ribbon_custom')} | {t['titre'] for t in tabs}
            tabs.append({'titre': free_title(title.strip() or tr('Mon onglet'), taken), 'position': 'fin',
                         'groupes': []})
            rank = len(tabs) - 1
        tab = tabs[rank]
        if any(c['key'] == key for g in tab['groupes'] for c in g['commandes']):
            self.statusBar().showMessage(tr('Déjà dans « {0} »').format(tab['titre']), 5000)
            return rank
        if not tab['groupes']:
            tab['groupes'].append({'titre': tr('Mes commandes'), 'commandes': []})
        cmds = tab['groupes'][-1]['commandes']
        cmds.append({'key': key, 'big': len(cmds) < 3})
        self._save_custom(tabs, tr('« {0} » ajouté à « {1} »').format(
            self.A[key].text().replace('&', '') if key in self.A else key, tab['titre']))
        return rank

    def remove_from_custom_tab(self, at: str) -> bool:
        """Bouton d'un onglet à soi retiré (`at` : « rang:groupe:commande »)."""
        from .ribbon_editor import load_all
        try:
            rank, gi, ci = (int(v) for v in str(at).split(':'))
            tabs = load_all(self.settings)
            c = tabs[rank]['groupes'][gi]['commandes'].pop(ci)
        except (ValueError, IndexError):
            return False
        g = tabs[rank]['groupes'][gi]
        if not g['commandes']:
            del tabs[rank]['groupes'][gi]                # groupe vidé : retiré aussi
        act = self.A.get(c['key'])
        self._save_custom(tabs, tr('« {0} » retiré de « {1} »').format(
            c.get('texte') or (act.text().replace('&', '') if act else c['key']), tabs[rank]['titre']))
        return True

    def rename_custom_tab(self, rank: int, title: str | None = None) -> bool:
        from .ribbon_editor import free_title, load_all
        tabs = load_all(self.settings)
        if not 0 <= rank < len(tabs):
            return False
        old = tabs[rank]['titre']
        if title is None:
            from PySide6.QtWidgets import QInputDialog
            title, ok = QInputDialog.getText(self, tr('Renommer l\'onglet'), tr('Nom de l\'onglet'), text=old)
            if not ok:
                return False
        taken = {self.ribbon.tabText(i) for i in range(self.ribbon.count())
                 if not self.ribbon.widget(i).property('ribbon_custom')} | \
            {t['titre'] for k, t in enumerate(tabs) if k != rank}
        tabs[rank]['titre'] = free_title(title.strip() or old, taken)
        self._save_custom(tabs, tr('Onglet « {0} » renommé « {1} »').format(old, tabs[rank]['titre']))
        return True

    def remove_custom_tab(self, rank: int, ask: bool = True) -> bool:
        from .ribbon_editor import load_all
        tabs = load_all(self.settings)
        if not 0 <= rank < len(tabs):
            return False
        title = tabs[rank]['titre']
        if ask and QMessageBox.question(self, tr('Supprimer l\'onglet'),
                                        tr('Supprimer l\'onglet « {0} » et ses groupes ?').format(title)) \
                != QMessageBox.StandardButton.Yes:
            return False
        del tabs[rank]
        self._save_custom(tabs, tr('Onglet « {0} » supprimé').format(title))
        return True

    def new_custom_tab(self, exec_dialog: bool = True):
        """Personnaliser le ruban sur un nouvel onglet (nom demandé)."""
        from .ribbon_editor import RibbonEditor
        dlg = RibbonEditor(self)
        if exec_dialog:
            if dlg.new_tab() >= 0 and dlg.exec():
                self._build_custom_tab()
        return dlg

    def _ribbon_tab_menu(self, index: int, pos, exec_menu: bool = True):
        """Clic droit sur un onglet du ruban : renommer ou supprimer un onglet
        à soi, nouvel onglet, personnaliser le ruban."""
        m = QMenu(self)
        rank = self._custom_rank_at(index)
        if rank >= 0:
            title = self.ribbon.tabText(index)
            m.addAction(icon('text'), tr('Renommer « {0} »…').format(title),
                        lambda: self.rename_custom_tab(rank))
            m.addAction(icon('delete'), tr('Supprimer « {0} »').format(title), lambda: self.remove_custom_tab(rank))
            m.addSeparator()
        m.addAction(icon('new'), tr('Nouvel onglet…'), lambda: self.new_custom_tab())
        m.addAction(self.A['ribbon_editor'])
        if exec_menu:
            m.exec(pos)
            m.deleteLater()
        return m

    def _ribbon_button_menu(self, button, pos, exec_menu: bool = True):
        """Clic droit sur un bouton du ruban (ou des favoris) : la commande dans les favoris (barre du haut) ou
        retirée, ajoutée à un onglet à soi (ou à un nouveau), retirée de l'onglet à soi où elle est."""
        from .ribbon_editor import load_all
        m = QMenu(self)
        key = self._action_key(button.defaultAction())
        if key is not None and key not in ('ui_mode', 'view_toggle'):     # d'un mode à l'autre
            from . import modes
            simple = modes.in_simple(key, self.settings, self._plugin_action_keys())
            m.addAction(tr('Réserver au mode expert') if simple else tr('Montrer aussi en mode simple'),
                        lambda _=False, k=key, to=not simple: self.move_button_mode(k, to))
            m.addSeparator()
        if key is not None:
            fav = key in self.favorite_keys()
            m.addAction(tr('Retirer des favoris (barre du haut)') if fav else tr('Ajouter aux favoris (barre du haut)'),
                        lambda _=False, k=key, on=not fav: self.add_favorite(k) if on else self.remove_favorite(k))
            m.addSeparator()
            for rank, t in enumerate(load_all(self.settings)):
                m.addAction(icon('new'), tr('Ajouter à « {0} »').format(t['titre']),
                            lambda _=False, k=rank: self.add_to_custom_tab(key, k))
            m.addAction(tr('Ajouter à un nouvel onglet…'), lambda: self.add_to_custom_tab(key, -1))
            at = button.property('ribbon_custom_at')
            if at:
                rank = int(str(at).split(':')[0])
                tabs = load_all(self.settings)
                if rank < len(tabs):
                    m.addAction(icon('delete'), tr('Retirer de « {0} »').format(tabs[rank]['titre']),
                                lambda: self.remove_from_custom_tab(at))
            m.addSeparator()
        m.addAction(self.A['ribbon_editor'])
        if exec_menu:
            m.exec(pos)
            m.deleteLater()
        return m

    # --- disposition du ruban de TypeEdit 13 -----------------------------------------------
    #: icônes des boutons « Mode » et « Opérations » (clé de contexte TypeEdit)
    TE_MODE_ICONS = {'1000': 'node', '1001': 'rect', 'idContextText': 'text', '1002': 'offset', '1003': 'align_left',
                     '1004': 'rotate', '1005': 'shadow', '1006': 'duplicate', '1007': 'envelope', '1008': 'tools',
                     '1009': 'measure', 'idContextRapido': 'text_box',
                     'ID_COMPO_TEXTLIBRE': 'text_horizontal', 'ID_COMPO_TEXTVERTICAL': 'text_vertical'}
    #: onglets contextuels de TypeEdit renommés (clé de contexte → titre) ; leurs boutons Mode portent le nom de la
    #: commande de VectorDrive (« Texte », « Texte vertical »), pas celui de l'onglet (« Rapido »)
    TE_CONTEXT_TITLES = {'idContextRapido': 'Mise en forme'}
    #: onglets contextuels de TypeEdit qui reçoivent les champs de mise en forme et les préréglages
    TE_TEXT_CONTEXTS = ('idContextRapido',)
    #: commandes de la barre d'accès rapide qui ouvrent un onglet contextuel
    TE_QUICK_CONTEXTS = {'ID_MANIPULER_ZONE_ALIGNER': '1003'}

    def ribbon_layout_name(self) -> str:
        """« vectordrive » ou « typeedit13 » (option, ou selon le thème)."""
        from .options import value
        from .theme import current
        v = value(self.settings, 'vue/disposition')
        if v == 'theme':
            return 'typeedit13' if current().seed.get('typeedit13') else 'vectordrive'
        return v

    def apply_ribbon_layout(self, restyle: bool = True) -> bool:
        """Ruban de VectorDrive, ou celui de TypeEdit 13 (onglets, groupes et
        commandes dans l'ordre de TypeEdit, lus dans le TypeEdit 13 du poste ;
        les onglets de VectorDrive restent dans l'onglet « VectorDrive »)."""
        from ..i18n import language
        from . import typeedit_layout as TL
        name = self.ribbon_layout_name()
        lay = TL.installed(13, language()) if name == 'typeedit13' else None
        if name == 'typeedit13' and lay is None:
            self.statusBar().showMessage(tr('TypeEdit 13 introuvable sur ce poste : ruban de VectorDrive'), 8000)
        if lay is self._te_layout and self.layout_active == (lay is not None):
            return self.layout_active
        self._clear_te_tabs()
        self.layout_active = lay is not None
        self._te_layout = lay
        if lay is not None:
            self._build_te_tabs(lay)
        self._build_custom_tab(restyle=restyle)
        self.refresh_favorites()                         # dans la barre d'accès rapide de TypeEdit 13, ou la leur
        if self.layout_active:
            self.ribbon.setCurrentIndex(self._te_main_index())
        return self.layout_active

    def _te_context_title(self, key, title: str) -> str:
        """Titre d'un onglet contextuel de TypeEdit (« Rapido » : « Mise en forme »)."""
        return tr(self.TE_CONTEXT_TITLES[str(key)]) if str(key) in self.TE_CONTEXT_TITLES else title

    def _clear_te_tabs(self) -> None:
        r = self.ribbon
        self.textbar_te = None                           # ses champs partent avec l'onglet
        for i in range(r.count() - 1, -1, -1):
            w = r.widget(i)
            if w.property('te_layout'):
                r.removeTab(i)
                w.deleteLater()
        r.last_left = getattr(self, '_vd_last_left', None)
        for a in self._te_actions:
            a.deleteLater()
        self._te_actions = []
        for g in getattr(self, '_te_file_groups', []):
            r.page(r.indexOf(self.file_page)).remove_group(g)
        self._te_file_groups = []
        bar = getattr(self, 'te_quickbar', None)
        if bar is not None:
            bar.setParent(None)
            bar.deleteLater()
            self.te_quickbar = None

    def _te_main_index(self) -> int:
        """Onglet TypeEdit (celui des boutons Mode), sinon le premier."""
        r = self.ribbon
        for i in range(r.count()):
            if r.widget(i).property('te_main'):
                return i
        return next((i for i in range(r.count()) if r.isTabVisible(i)), 0)

    def _vd_tab_menus(self) -> list:
        """[(titre, [(groupe, [actions])])] des onglets de VectorDrive."""
        from PySide6.QtWidgets import QToolButton
        from .ribbon import RibbonGroup
        r = self.ribbon
        out = []
        for i in range(r.count()):
            w = r.widget(i)
            title = r.tabText(i)
            if w.property('te_layout') or w.property('ribbon_both') or w.property('ribbon_custom') \
                    or title == getattr(self, 'text_tab_title', None):
                continue                                 # Fichier, Aide : déjà affichés tels quels
            page = w.widget() if hasattr(w, 'widget') else w
            groups = []
            for g in page.findChildren(RibbonGroup):
                acts = [b.defaultAction() for b in g.buttons()]
                if acts:
                    groups.append((g.title.text(), acts))
            if groups:
                out.append((title, groups))
        return out

    def _build_te_tabs(self, lay) -> None:
        from PySide6.QtWidgets import QMenu
        from .shortcuts import TE_ACTIONS
        r = self.ribbon
        A = self.A
        vd_menus = self._vd_tab_menus()
        back = QAction(icon('undo'), tr('Retour'), self)
        back.setToolTip(tr('Fermer cet onglet et revenir à l\'onglet TypeEdit'))
        back.triggered.connect(self.close_te_contexts)
        self._te_actions.append(back)
        modes: dict = {}

        def mode(cmd):
            key = lay.modes[cmd]
            if cmd not in modes:
                t = lay.contexts.get(key)
                title = self._te_context_title(key, t.title if t else cmd)
                base = A.get(TE_ACTIONS.get(cmd, ''))
                own = str(key) in self.TE_CONTEXT_TITLES and base is not None    # Texte, Texte vertical
                a = QAction(icon(self.TE_MODE_ICONS.get(cmd, self.TE_MODE_ICONS.get(str(key), 'tools'))),
                            base.text() if own else title, self)
                a.setToolTip(title + (' — ' + base.text() if base is not None else ''))
                a.triggered.connect(lambda _=False, k=key, b=base: self.show_te_context(k, b))
                self._te_actions.append(a)
                modes[cmd] = a
            return modes[cmd]

        def fill(page, tab, skip=frozenset()) -> int:
            n = 0
            for p in tab.panels:
                items, seen = [], set(skip)
                for c, big in p.commands:
                    if c == tab.exit_command:
                        a, big = back, True
                    elif c in lay.modes and str(lay.modes[c]) in {str(k) for k in lay.contexts}:
                        a, big = mode(c), True
                    else:
                        a = A.get(TE_ACTIONS.get(c, ''))
                        if a is A['view_3d'] or a is A['view_2d'] or a is A['view_toggle']:
                            a = None                         # 2D / 3D : le va-et-vient de la rangée des onglets
                    if a is not None and id(a) not in seen:
                        seen.add(id(a))
                        items.append((a, big))
                    if c == 'ID_FILE_COST' and 'proof' in A and id(A['proof']) not in seen:
                        seen.add(id(A['proof']))             # BAT à côté du devis (le Coût de TypeEdit)
                        items.append((A['proof'], True))
                if not items:
                    continue
                renamed = tab.context is not None and p.title == tab.title     # « Rapido » : « Mise en forme »
                g = page.group(self._te_context_title(tab.context, p.title) if renamed else p.title)
                for a, big in items:
                    g.add(a, big=big)
                n += 1
            return n

        pos = 0
        te_fao = te_opt = None
        file_title = r.tabText(r.indexOf(self.file_page))
        for tab in lay.tabs:
            cmds = [c for p in tab.panels for c, _b in p.commands]
            if tab.title == file_title or 'ID_FILE_COST' in cmds:   # Fichier de TypeEdit : à la suite du bandeau complet
                fp = r.page(r.indexOf(self.file_page))
                from PySide6.QtWidgets import QToolButton
                before = fp.groups()
                have = {id(b.defaultAction()) for b in fp.findChildren(QToolButton) if b.defaultAction()}
                fill(fp, tab, skip=have - {id(A['proof'])})   # rien en double ; le BAT reste près du devis
                self._te_file_groups = [g for g in fp.groups() if g not in before]
                continue
            known = sum(1 for c in cmds if c in lay.modes or TE_ACTIONS.get(c, '') in A)
            art = 'ID_GALBE_NEWGALBE' in cmds              # onglet TypeArt : la 3D de VectorDrive
            main = any(c in lay.modes for c in cmds) and not art   # onglet TypeEdit (boutons Mode) : le 2.5D
            if len(cmds) > 4 and known < len(cmds) / 4 and not art:
                continue                                 # module sans équivalent : pas d'onglet
            title = tr('CAD') if main or art else tab.title  # 2.5D et 3D : CAD, selon le mode du plan de travail
            page = r.insert_tab(pos, title)
            if main or art:
                page.setProperty('vd_cad', '3d' if art else '2d')
            if art:                                      # commandes 3D de VectorDrive, d'abord
                g = page.group(tr('Vues 3D'))
                for k in ('view_engraver', 'view_iso', 'view_yz', 'view_zx', 'place_model3d'):
                    g.add(A[k], big=False)
                g = page.group(tr('Usinage 3D'))
                for k in ('cam_paths_3d', 'cam_sim_3d', 'cam_new_relief', 'cam_new_finition', 'cam_simulate'):
                    if k in A:
                        g.add(A[k], big=k in ('cam_paths_3d', 'cam_sim_3d'))
            if not fill(page, tab) and not art:
                w = r.widget(pos)
                r.removeTab(pos)
                w.deleteLater()
                continue
            w = r.widget(pos)
            w.setProperty('te_layout', True)
            if main:
                w.setProperty('te_main', True)
            if 'ID_EDIT_OPTIONS' in cmds:                # onglet « Modifier » de TypeEdit : devient Options
                te_opt = (w, page)
            if {'ID_CREATEPATH', 'ID_LISTPATH'} & set(cmds):
                te_fao = w
                page.setProperty('vd_fao', True)         # l'onglet FAO de la disposition TypeEdit aussi
            pos += 1
        # les onglets de VectorDrive, chacun en menu
        page = r.insert_tab(pos, 'VectorDrive')
        g = page.group(tr('Onglets de VectorDrive'))
        for title, groups in vd_menus:
            m = QMenu(self)
            for gt, acts in groups:
                m.addSection(gt)
                for a in acts:
                    m.addAction(a)
            a = QAction(icon('ribbon'), title, self)
            a.setMenu(m)
            self._te_actions.append(a)
            g.add(a)
        vd_tab = r.widget(pos)
        vd_tab.setProperty('te_layout', True)
        if te_fao is not None:                           # FAO le dernier des onglets de gauche
            r.tabBar().moveTab(r.indexOf(vd_tab), r.indexOf(te_fao))
            r.last_left = te_fao
            self._te_machines(te_fao.widget())           # les machines et leurs commandes, comme dans les rubans FAO
        if te_opt is not None:                           # Modifier → Options, tout à droite
            from .options import PAGES
            w, page = te_opt
            g = page.group(tr('Options'), at_start=True)
            for slug, _icon in PAGES.values():
                g.add(A[f'options_{slug}'], big=slug in ('general', 'apparence', 'fao'))
            r.setTabText(r.indexOf(w), tr('Options'))
            r.set_right(r.indexOf(w), rank=0)
        r.tabBar().moveTab(r.indexOf(self.file_page), 0)  # Fichier de VectorDrive, le premier
        self._build_te_quickbar(lay, mode)
        # onglets contextuels (cachés : ouverts par les boutons Mode / Opérations)
        for key, tab in lay.contexts.items():
            idx = r.count()
            page = r.insert_tab(idx, self._te_context_title(key, tab.title))
            w = r.widget(idx)
            w.setProperty('te_layout', True)
            w.setProperty('te_context', str(key))
            if not fill(page, tab):
                r.removeTab(idx)
                w.deleteLater()
                continue
            if str(key) in self.TE_TEXT_CONTEXTS and getattr(self, 'textbar_te', None) is None:
                from .textbar import TextFormat
                self.textbar_te = TextFormat(self, page, compact=True)     # police, hauteur, …, préréglages
            r.setTabVisible(idx, False)
        r.finalize()

    def _build_te_quickbar(self, lay, mode) -> None:
        """Barre d'accès rapide de TypeEdit 13 (celle de l'utilisateur, lue
        dans CONFIG/QATSettings_TE.INI), au-dessus ou au-dessous du ruban."""
        from PySide6.QtCore import QSize
        from PySide6.QtWidgets import QToolBar
        from .shortcuts import TE_ACTIONS
        self.te_quickbar = None
        if not lay.quick:
            return
        bar = QToolBar(tr('Accès rapide'))
        bar.setObjectName('teQuickBar')
        bar.setIconSize(QSize(20, 20))
        bar.setMovable(False)
        seen = set()
        for c in lay.quick:
            a = None
            if c in lay.modes and str(lay.modes[c]) in {str(k) for k in lay.contexts}:
                a = mode(c)
            elif c in self.TE_QUICK_CONTEXTS and self.TE_QUICK_CONTEXTS[c] in {str(k) for k in lay.contexts}:
                src = next((m for m, k in lay.modes.items() if str(k) == self.TE_QUICK_CONTEXTS[c]), None)
                a = mode(src) if src else None
            else:
                a = self.A.get(TE_ACTIONS.get(c, ''))
            if a is None or id(a) in seen:
                continue
            seen.add(id(a))
            bar.addAction(a)
        if not bar.actions():
            bar.deleteLater()
            return
        holder = self.menuWidget()
        box = holder.layout() if holder is not None else None
        if box is None:
            bar.deleteLater()
            return
        top = max(0, box.indexOf(self.doc_bar) + 1) if getattr(self, 'doc_bar', None) is not None else 0
        box.insertWidget(top if lay.quick_on_top else box.count(), bar)       # au-dessus du ruban
        self.te_quickbar = bar

    def show_te_context(self, key, action=None) -> None:
        """Bouton Mode / Opérations de TypeEdit : son onglet contextuel paraît
        (les autres se ferment) ; la commande liée, s'il y en a une, part."""
        r = self.ribbon
        target = -1
        for i in range(r.count()):
            k = r.widget(i).property('te_context')
            if k:
                r.setTabVisible(i, k == str(key))
                if k == str(key):
                    target = i
        if target >= 0:
            r.setCurrentIndex(target)
        if str(key) in self.TE_TEXT_CONTEXTS and getattr(self, 'textbar_te', None) is not None:
            self.textbar_te.refresh()                    # sans sélection : les valeurs des nouveaux textes
        if action is not None:
            action.trigger()

    def close_te_contexts(self) -> None:
        r = self.ribbon
        for i in range(r.count()):
            if r.widget(i).property('te_context'):
                r.setTabVisible(i, False)
        r.setCurrentIndex(self._te_main_index())
        if 'tool_select' in self.A:
            self.A['tool_select'].trigger()

    def ribbon_editor(self, exec_dialog: bool = True):
        from .ribbon_editor import RibbonEditor
        dlg = RibbonEditor(self)
        if exec_dialog and dlg.exec():
            self._build_custom_tab()
        return dlg

    # --- modèles de dessin ---------------------------------------------------------------------
    def new_from_template(self, path: str) -> bool:
        """Nouveau dessin, copie sans nom du modèle `path`."""
        from .progress import Cancelled, run
        try:
            doc = run(self, tr('Ouverture de {0}').format(pathlib.Path(path).name), registry.open_document, path)
        except Cancelled:
            return False
        except Exception as ex:
            QMessageBox.critical(self, tr('Modèle de dessin'), f'{pathlib.Path(path).name}\n\n{ex}')
            return False
        doc.source_path = ''
        from ..core import surface2d
        from ..io import model3d
        doc.extra.pop(model3d.SOURCE_KEY, None)          # modèle de 0.527.2-0.527.3 : sans sa pièce 3D
        for L in doc.layers:                             # ni ses surfaces posées
            L.extra = {k: v for k, v in L.extra.items() if k != surface2d.KEY}
        self._open_in_tab(doc, None)                     # nouvel onglet
        self._cam_document_changed()
        self.canvas.fit()
        self.statusBar().showMessage(tr('Nouveau dessin d\'après le modèle {0}').format(pathlib.Path(path).stem), 6000)
        return True

    def new_from_template_dialog(self) -> None:
        from PySide6.QtWidgets import QInputDialog
        from ..io import doc_templates as DT
        tpls = DT.templates()
        if not tpls:
            QMessageBox.information(self, tr('Modèle de dessin'),
                                    tr('Aucun modèle : « Enregistrer comme modèle… » en crée un à partir du dessin.'))
            return
        labels = {(n if origin == 'utilisateur' else f'{n}  ({tr(origin)})'): path
                  for n, (origin, path) in sorted(tpls.items())}
        name, ok = QInputDialog.getItem(self, tr('Nouveau d\'après un modèle'), tr('Modèle'), list(labels), 0, False)
        if ok and name:
            self.new_from_template(labels[name])

    def save_as_template(self, name: str) -> pathlib.Path:
        from ..io import doc_templates as DT
        return DT.save(self.canvas.doc, name)

    def save_as_template_dialog(self) -> None:
        from PySide6.QtWidgets import QInputDialog
        name, ok = QInputDialog.getText(self, tr('Enregistrer comme modèle'), tr('Nom du modèle'))
        if ok and name.strip():
            f = self.save_as_template(name.strip())
            self.statusBar().showMessage(tr('Modèle enregistré : {0}').format(f.name), 6000)

    # --- réglages d'un poste à l'autre ---------------------------------------------------------------
    #: réglages propres au poste, jamais exportés ni importés
    LOCAL_KEYS = ('fichiers/recents', 'fichiers/onglets_fermes', 'fichiers/dossier_', 'session/', 'fenetre/')

    def batch_dialog(self, exec_dialog: bool = True):
        from .batch_dialog import BatchDialog
        dlg = BatchDialog(self)
        if exec_dialog:
            dlg.exec()
        return dlg

    def batch_add(self, paths) -> 'QDialog':
        """Traitement par lots ouvert (ou repris) avec ces fichiers ou dossiers :
        clic droit de l'explorateur « Traitement par lots… », plusieurs
        fichiers à la suite dans la même fenêtre."""
        from .batch_dialog import BatchDialog
        dlg = getattr(self, '_batch_dlg', None)
        try:
            alive = dlg is not None and dlg.isVisible()
        except RuntimeError:                              # fenêtre déjà détruite
            alive = False
        if not alive:
            dlg = BatchDialog(self)
            self._batch_dlg = dlg
            dlg.show()
        dlg.add_paths([str(p) for p in paths])
        dlg.raise_()
        dlg.activateWindow()
        if self.isMinimized():
            self.showNormal()
        return dlg

    # --- paramètres : réglages + outils + modèles + thèmes (.vdparam) ----------------------
    def export_params(self, path: str, cats=None) -> dict:
        from ..io import params
        return params.export(path, self.settings, cats, local_keys=self.LOCAL_KEYS)

    def import_params(self, path: str, cats=None, backup_dir=None) -> tuple[dict, object]:
        """Reprend les paramètres choisis ; ce qui est remplacé part d'abord dans
        un dossier de sauvegarde (rendu avec le compte de chaque catégorie)."""
        from ..io import params
        counts, backup = params.import_(path, self.settings, cats, local_keys=self.LOCAL_KEYS,
                                        backup_dir=backup_dir)
        if counts.get('reglages'):
            self._apply_imported_settings()
        if counts.get('outils') or counts.get('modeles_fao'):
            try:
                self.cam_panel.refresh()
            except Exception:                            # noqa: BLE001 - panneau FAO absent
                pass
        return counts, backup

    def _params_choice(self, title: str, available: dict, intro: str) -> list | None:
        from PySide6.QtWidgets import QCheckBox
        from ..io import params
        from .dialogs import _buttons
        dlg = QDialog(self)
        dlg.setWindowTitle(title)
        form = QFormLayout(dlg)
        form.addRow(QLabel(intro))
        boxes = {}
        for key, label in params.CATEGORIES:
            if key not in available:
                continue
            n = available[key]
            cb = QCheckBox(f'{tr(label)} ({n})' if n is not None else tr(label))
            cb.setChecked(bool(n) or n is None)
            cb.setEnabled(n != 0)
            form.addRow(cb)
            boxes[key] = cb
        _buttons(dlg, form)
        if not dlg.exec():
            return None
        return [k for k, cb in boxes.items() if cb.isChecked()]

    def export_params_dialog(self) -> None:
        from ..io import params
        cats = self._params_choice(tr('Exporter les paramètres'), params.available(self.settings, self.LOCAL_KEYS),
                                   tr('À mettre dans le fichier :'))
        if not cats:
            return
        start = str(pathlib.Path(self._last_dir('parametres')) / ('VectorDrive_parametres' + params.EXT))
        path, _ = QFileDialog.getSaveFileName(self, tr('Exporter les paramètres'), start,
                                              tr('Paramètres VectorDrive (*.vdparam)'))
        if not path:
            return
        self._remember_dir('parametres', path)
        try:
            counts = self.export_params(path, cats)
        except OSError as ex:
            QMessageBox.warning(self, tr('Exporter les paramètres'), str(ex))
            return
        self.statusBar().showMessage(tr('Paramètres exportés : {0}').format(params.summary(counts)), 8000)

    def import_params_dialog(self) -> None:
        from ..io import params
        path, _ = QFileDialog.getOpenFileName(self, tr('Importer des paramètres'), self._last_dir('parametres'),
                                              tr('Paramètres VectorDrive (*.vdparam *.ini)'))
        if not path:
            return
        self._remember_dir('parametres', path)
        try:
            found = params.contents(path)
        except (OSError, ValueError) as ex:
            QMessageBox.warning(self, tr('Importer des paramètres'), str(ex))
            return
        cats = self._params_choice(tr('Importer des paramètres'), found,
                                   tr('À reprendre (les outils sont ajoutés à « Mes outils », sans doublon ; '
                                      'ce qui est remplacé est d\'abord sauvegardé) :'))
        if not cats:
            return
        try:
            counts, backup = self.import_params(path, cats)
        except (OSError, ValueError) as ex:
            QMessageBox.warning(self, tr('Importer des paramètres'), str(ex))
            return
        msg = tr('Paramètres importés : {0}').format(params.summary(counts))
        if backup:
            msg += '\n\n' + tr('Sauvegarde de ce qui a été remplacé : {0}').format(backup)
        QMessageBox.information(self, tr('Importer des paramètres'), msg)

    def export_settings(self, path: str) -> int:
        from PySide6.QtCore import QSettings
        out = QSettings(str(path), QSettings.Format.IniFormat)
        out.clear()
        n = 0
        for k in self.settings.allKeys():
            if not k.startswith(self.LOCAL_KEYS):
                out.setValue(k, self.settings.value(k))
                n += 1
        out.sync()
        return n

    def import_settings(self, path: str) -> int:
        """Reprend les réglages d'un fichier exporté et les applique."""
        from PySide6.QtCore import QSettings
        src = QSettings(str(path), QSettings.Format.IniFormat)
        n = 0
        for k in src.allKeys():
            if not k.startswith(self.LOCAL_KEYS):
                self.settings.setValue(k, src.value(k))
                n += 1
        self._apply_imported_settings()
        return n

    def _apply_imported_settings(self) -> None:
        """Réglages relus : options, raccourcis, ruban personnel, thème."""
        self.apply_options()
        self._apply_shortcuts()
        self._build_custom_tab()
        from .themes import DEFAULT_KEY
        self.set_theme(str(self.settings.value('vue/theme', DEFAULT_KEY) or DEFAULT_KEY))

    def export_settings_dialog(self) -> None:
        path, _ = QFileDialog.getSaveFileName(self, tr('Exporter les réglages'), 'VectorDrive_reglages.ini',
                                              tr('Réglages (*.ini)'))
        if path:
            n = self.export_settings(path)
            self.statusBar().showMessage(tr('{0} réglage(s) exporté(s)').format(n), 6000)

    def import_settings_dialog(self) -> None:
        path, _ = QFileDialog.getOpenFileName(self, tr('Importer des réglages'), '', tr('Réglages (*.ini)'))
        if path:
            n = self.import_settings(path)
            self.statusBar().showMessage(tr('{0} réglage(s) importé(s)').format(n), 6000)

    DRAG_TOOLS = ('rect', 'ellipse', 'line')

    def point_by_coordinates(self, values: dict | None = None) -> bool:
        """Point(s) de l'outil de dessin par coordonnées : deux points pour un
        rectangle, une ellipse ou un trait ; sinon le point suivant
        (absolu, ou relatif au précédent)."""
        from PySide6.QtWidgets import QCheckBox, QDoubleSpinBox
        from .dialogs import _buttons
        c = self.canvas
        tool = c.tool
        if tool == 'select' or (c.tool_obj is None and tool not in self.DRAG_TOOLS):
            QMessageBox.information(self, tr('Point par coordonnées'),
                                    tr('Choisissez d\'abord un outil de dessin (rectangle, polyligne, arc…).'))
            return False
        drag = c.tool_obj is None and tool in self.DRAG_TOOLS
        last = getattr(self, '_last_xy', (0.0, 0.0))
        if values is None:
            dlg = QDialog(self)
            dlg.setWindowTitle(tr('Point par coordonnées'))
            form = QFormLayout(dlg)
            spins = {}
            keys = ('x1', 'y1', 'x2', 'y2') if drag else ('x', 'y')
            labels = {'x1': tr('Premier point X'), 'y1': tr('Premier point Y'), 'x2': tr('Second point X'),
                      'y2': tr('Second point Y'), 'x': 'X', 'y': 'Y'}
            for k in keys:
                sb = QDoubleSpinBox()
                sb.setRange(-1e6, 1e6)
                sb.setDecimals(3)
                sb.setSuffix(' mm')
                o = c.origin
                sb.setValue(last[0] - o[0] if k.startswith('x') else last[1] - o[1])
                form.addRow(labels[k], sb)
                spins[k] = sb
            rel = QCheckBox(tr('Relatif au point précédent ({0:.3f} ; {1:.3f})').format(*last))
            form.addRow(rel)
            _buttons(dlg, form)
            if not dlg.exec():
                return False
            values = {k: sb.value() for k, sb in spins.items()}
            values['relatif'] = rel.isChecked()
        ox, oy = last if values.get('relatif') else c.origin      # absolu : depuis l'origine du dessin
        if drag:
            a = (ox + values['x1'], oy + values['y1'])
            b = (ox + values['x2'], oy + values['y2'])
            c.draw_between(a, b)
            self._last_xy = b
        else:
            p = (ox + values['x'], oy + values['y'])
            c.click_at(*p)
            self._last_xy = p
        return True

    def move_by(self, dx: float, dy: float, copy_: bool = False) -> list:
        """Déplace la sélection (ou en pose une copie) de (dx, dy)."""
        sel = list(self.canvas.selection)
        if not sel:
            return []
        m = Affine.translation(dx, dy)
        if not copy_:
            self.canvas.transform_selection(m)
            return sel
        new = [it.clone().transformed(m) for it in sel]          # copies : nouveaux objets
        self._add_items(new)
        return new

    def move_by_dialog(self) -> None:
        from dataclasses import make_dataclass
        from .dialogs import ParamsDialog
        if not self.canvas.selection:
            QMessageBox.information(self, tr('Déplacer'), tr('Sélectionnez les objets à déplacer.'))
            return
        st = self.settings
        Spec = make_dataclass('Deplacer', [('dx', float, float(st.value('deplacer/dx', 10.0))),
                                           ('dy', float, float(st.value('deplacer/dy', 0.0))),
                                           ('copy', bool, False)])
        dlg = ParamsDialog(self, tr('Déplacer'), Spec(), {'dx': tr('Vers la droite (mm)'), 'dy': tr('Vers le haut (mm)'),
                                                           'copy': tr('Poser une copie (l\'original reste)')})
        if not dlg.exec():
            return
        v = dlg.result_params()
        st.setValue('deplacer/dx', v.dx)
        st.setValue('deplacer/dy', v.dy)
        self.move_by(v.dx, v.dy, v.copy)

    def _popup_theme_menu(self) -> None:
        from PySide6.QtGui import QCursor
        self.theme_menu.popup(QCursor.pos())

    def theme_editor(self, exec_dialog: bool = True):
        from .theme_editor import ThemeEditor
        dlg = ThemeEditor(self)
        if exec_dialog:
            dlg.exec()
        return dlg
        for w in (self.ruler_h, self.ruler_v):
            w.update()

    def _toggle_engrave_preview(self, on: bool) -> None:
        self.canvas.engrave_preview = on
        if on and not any(getattr(t, 'width', 0) > 0 for t in self.canvas.doc.tools):
            self.statusBar().showMessage(tr('Aucune largeur d\'outil : la renseigner dans la table des outils'), 6000)
        self.canvas.invalidate()

    def select_similar(self, how: str) -> list:
        """Sélectionne les objets semblables à la sélection : même outil, ou
        même nature et même taille (à 0,01 mm près), dans les calques
        visibles et non verrouillés."""
        sel = list(self.canvas.selection)
        if not sel:
            return []
        tol = 0.01

        def size(it):
            bb = it.bbox()
            return (round((bb[2] - bb[0]) / tol), round((bb[3] - bb[1]) / tol)) if bb else None

        if how == 'tool':
            keys = {it.tool for it in sel}
            match = lambda it: it.tool in keys
        else:
            keys = {(type(it).__name__, size(it)) for it in sel}
            match = lambda it: (type(it).__name__, size(it)) in keys
        out = [it for L in self.canvas.doc.layers if L.visible and not L.locked
               for it in L.items if it.visible and match(it)]
        self.canvas.select(out)
        self.statusBar().showMessage(tr('{0} objet(s) sélectionné(s)').format(len(out)), 4000)
        return out

    # --- FAO -----------------------------------------------------------------
    def _toggle_cam_panel(self, on: bool) -> None:
        if on and not self.dock_paths.isVisible() and getattr(self, '_docks_before_cam', None) is None:
            self._docks_before_cam = self.saveState()    # rendue à la fermeture du panneau FAO
        if not on and getattr(self, '_docks_before_cam', None) is not None:
            state, self._docks_before_cam = self._docks_before_cam, None
            if self.dock_paths.isVisible() and not self.dock_paths.isFloating():
                self.restoreState(state)                 # la disposition d'avant revient (Dimensions compris)
        self.dock_cam.setVisible(on)
        self.dock_paths.setVisible(on)
        if self.isVisible() and not getattr(self, '_closing', False):
            self.settings.setValue('vue/panneau_fao', bool(on))
        if on:
            self.dock_cam.raise_()
            self.dock_paths.raise_()
            self.cam_full_height()                       # toute la hauteur de la fenêtre pour les opérations
            self.cam_panel.refresh()
            self.cam_palette.refresh()

    def set_full_screen(self, on: bool) -> bool:
        """Plein écran (F12, ou Maj+F11) ou retour à la fenêtre agrandie ; retenu. Barre des tâches gardée
        (option) : la fenêtre sans cadre sur la zone de travail de l'écran."""
        if on:
            self.remember_window()                       # la fenêtre d'avant : rendue en quittant le plein écran
            self._enter_full_screen()
        else:
            self._leave_full_screen()
            if self.restore_last_window():
                self.show()                              # à sa place et sa taille d'avant (agrandie si elle l'était)
            else:
                self.showMaximized()
            self.raise_()
            self.activateWindow()
        self.settings.setValue('fenetre/plein_ecran', bool(on))
        self._check_quietly('full_screen', bool(on))
        return bool(on)

    def _window_actions(self) -> tuple:
        """(Réduire, Fenêtre, Fermer) : les boutons que la barre de titre ne porte plus en plein écran. Leur texte est
        leur signe ; ce qu'ils font est dans leur bulle."""
        got = self.__dict__.get('_window_acts')
        if got is None:
            from PySide6.QtGui import QAction
            got = []
            for sign, tip, slot in (('—', tr('Réduire VectorDrive dans la barre des tâches'),
                                     lambda: self.showMinimized()),
                                    ('❐', tr('Quitter le plein écran : la fenêtre (F12 passe à l\'état suivant)'),
                                     lambda: self.set_full_screen(False)),
                                    ('✕', tr('Fermer VectorDrive'), lambda: self.close())):
                act = QAction(sign, self)
                act.setToolTip(tip)
                act.triggered.connect(lambda _on=False, f=slot: f())
                got.append(act)
            self._window_acts = got = tuple(got)
        return got

    def _sync_window_buttons(self) -> None:
        r = getattr(self, 'ribbon', None)
        if r is not None:
            r.show_window_buttons(self.is_full_screen())

    def cycle_full_screen(self) -> str:
        """F12 (ou Maj+F11), appuis successifs : plein écran, puis plein écran avec la barre des tâches de Windows,
        puis la fenêtre ; rend l'état obtenu : 'full', 'taskbar' ou 'window'."""
        if not self.is_full_screen():
            self.set_keep_taskbar(False)
            self.set_full_screen(True)
            return 'full'
        if not self.keeps_taskbar():
            self.set_keep_taskbar(True)                  # repris aussitôt, la barre gardée
            self._check_quietly('full_screen', True)
            return 'taskbar'
        self.set_full_screen(False)
        return 'window'

    #: plein écran en gardant la barre des tâches de Windows
    TASKBAR_KEY = 'fenetre/plein_ecran_barre'
    #: taille minimale de la fenêtre (px) : petite, pour qu'elle tienne dans tout écran
    MIN_WINDOW = (640, 480)

    def keeps_taskbar(self) -> bool:
        return self.settings.value(self.TASKBAR_KEY, 'false') in (True, 'true')

    def set_keep_taskbar(self, on: bool) -> bool:
        """Plein écran en gardant la barre des tâches (ou non) ; retenu, et repris aussitôt en plein écran."""
        self.settings.setValue(self.TASKBAR_KEY, bool(on))
        self._check_quietly('full_screen_taskbar', bool(on))
        if self.is_full_screen():
            self._enter_full_screen()                    # déjà sans cadre : seule sa place change
        return bool(on)

    def is_full_screen(self) -> bool:
        """En plein écran, la barre des tâches gardée ou non."""
        return bool(self.full_screen_mode())

    def full_screen_mode(self) -> str:
        """'' (la fenêtre), 'full' (tout l'écran) ou 'taskbar' (la barre des tâches de Windows gardée). Tenu ici,
        pas déduit de Qt : les deux pleins écrans sont la fenêtre sans cadre, posée par nous."""
        return getattr(self, '_full_mode', '')

    def _full_screen_rect(self):
        """Où poser la fenêtre : tout l'écran, ou sa zone de travail quand la barre des tâches est gardée."""
        from PySide6.QtWidgets import QApplication
        screen = self.screen() or QApplication.primaryScreen()
        return screen.availableGeometry() if self.keeps_taskbar() else screen.geometry()

    def _enter_full_screen(self) -> None:
        """Plein écran, ou changement de plein écran : la fenêtre sans cadre sur tout l'écran (Windows passe alors
        sa barre des tâches dessous) ou sur la zone de travail. Pas `showFullScreen` : avec le liseré qu'on lui
        posait pour la vue 3D, Qt ne se croyait plus en plein écran et F12 ne bouclait pas."""
        if not self.is_full_screen():
            if self.isFullScreen():
                self.showNormal()
            self.setWindowState(Qt.WindowState.WindowNoState)
            self.setWindowFlag(Qt.WindowType.FramelessWindowHint, True)   # la fenêtre est cachée : montrée plus bas
        self._full_mode = 'taskbar' if self.keeps_taskbar() else 'full'
        self.setGeometry(self._full_screen_rect())
        self.show()
        self._frame_full_screen()                        # une fois la fenêtre montrée : son style natif est posé
        self.raise_()
        self.activateWindow()                            # l'appui suivant sur F12 doit lui arriver
        self._watch_screen()
        self._sync_window_buttons()

    def _leave_full_screen(self) -> None:
        if self.is_full_screen():
            self._full_mode = ''
            self._frame_full_screen()
            self.setWindowFlag(Qt.WindowType.FramelessWindowHint, False)
        elif self.isFullScreen():
            self.showNormal()
        self._sync_window_buttons()

    def _watch_screen(self) -> None:
        """L'écran change de taille (résolution, barre des tâches déplacée) : le plein écran le suit."""
        screen = self.screen()
        seen = self.__dict__.setdefault('_watched_screens', [])
        if screen is None or any(s is screen for s in seen):
            return
        seen.append(screen)
        screen.geometryChanged.connect(self._refit_full_screen)
        screen.availableGeometryChanged.connect(self._refit_full_screen)

    def _refit_full_screen(self, *_a) -> None:
        if self.is_full_screen() and not self.isMinimized():
            self.setGeometry(self._full_screen_rect())

    def full_screen_holds(self) -> bool:
        """En plein écran, la fenêtre est bien là où elle doit être (tout l'écran, ou sa zone de travail)."""
        return not self.is_full_screen() or self.isMinimized() or self.geometry() == self._full_screen_rect()

    def resizeEvent(self, ev) -> None:                    # noqa: N802 (API Qt)
        super().resizeEvent(ev)
        self._hold_full_screen()

    def moveEvent(self, ev) -> None:                      # noqa: N802 (API Qt)
        super().moveEvent(ev)
        self._hold_full_screen()

    def _hold_full_screen(self) -> None:
        """Quelque chose a déplacé ou retaillé la fenêtre en plein écran (un panneau trop haut, une mise en page) :
        elle reprend sa place au prochain tour de la boucle d'événements — une fois, pas en boucle."""
        if self.full_screen_holds() or getattr(self, '_holding', False):
            return
        self._holding = True

        def back():
            self._holding = False
            if not self.full_screen_holds():
                self.setGeometry(self._full_screen_rect())
        from PySide6.QtCore import QTimer
        QTimer.singleShot(0, back)

    def _frame_full_screen(self) -> None:
        """Le liseré d'un pixel quand la fenêtre couvre tout l'écran ; retiré dans les autres états."""
        if self.full_screen_mode() == 'full':
            done = self._border_in_full_screen()
        else:
            from . import winborder
            winborder.set_border(self, False)
            done = False
        # le liseré prend un pixel de chaque côté à la surface, que Qt croit toujours entière : deux pixels de marge
        # à droite et en bas, pour que rien ne soit coupé
        self.setContentsMargins(0, 0, 2 if done else 0, 2 if done else 0)

    def _border_in_full_screen(self) -> bool:
        """Windows : un liseré d'un pixel autour de la fenêtre qui couvre tout l'écran — sa surface, vue 3D OpenGL
        comprise, fait alors un pixel de moins que l'écran de chaque côté. Sans lui elle passerait en plein écran
        exclusif : l'image clignote, menus et bulles paraissent mal. Qt retire toute bordure d'une fenêtre sans
        cadre : `ui.winborder` la lui rend. Rend vrai si c'est fait (faux hors de Windows)."""
        from . import winborder
        return winborder.set_border(self, True)

    def wants_full_screen(self) -> bool:
        """Plein écran au lancement : comme la dernière fois ; d'office tant que rien n'est retenu."""
        return self.settings.value('fenetre/plein_ecran', 'true') in (True, 'true')

    #: place et taille de la dernière fenêtre (hors plein écran), pour tout nouveau lancement
    GEOMETRY_KEY = 'fenetre/geometrie'

    def remember_window(self) -> bool:
        """Retient la fenêtre telle qu'elle est — sa place, sa taille, agrandie ou non. Pas en plein écran (c'est la
        fenêtre d'avant qui compte), ni réduite, ni avant d'avoir été montrée."""
        if self.is_full_screen() or self.isMinimized() or not self.isVisible():
            return False
        self.settings.setValue(self.GEOMETRY_KEY, bytes(self.saveGeometry().toBase64()).decode('ascii'))
        return True

    def restore_last_window(self) -> bool:
        """Remet la fenêtre à sa place et sa taille retenues (à faire avant de la montrer) ; faux : rien de retenu."""
        from PySide6.QtCore import QByteArray
        raw = str(self.settings.value(self.GEOMETRY_KEY, '') or '')
        try:
            return bool(raw) and bool(self.restoreGeometry(QByteArray.fromBase64(raw.encode('ascii'))))
        except (ValueError, TypeError):
            return False

    def show_at_start(self, session: bool = False) -> str:
        """Montre la fenêtre au lancement : en plein écran s'il l'était la dernière fois — ou si rien n'est retenu,
        c'est l'état d'office, avec la barre des tâches visible —, sinon à sa place et sa taille de la dernière fois
        (celles de la session, sinon celles retenues à la fermeture), sinon agrandie. Rend 'full', 'taskbar',
        'window' ou 'maximized'."""
        if not self.settings.contains('fenetre/plein_ecran') and not self.settings.contains(self.TASKBAR_KEY):
            self.set_keep_taskbar(True)                  # tout premier démarrage : la barre des tâches reste visible
        if self.wants_full_screen():
            if session:
                self.restore_panels()                    # les panneaux de la session (le plein écran prend la place)
            self.set_full_screen(True)
            return self.full_screen_mode()
        if (session and self.restore_window()) or self.restore_last_window():
            self.show()
            return 'window'
        self.showMaximized()
        return 'maximized'

    def toggle_overlay(self, which: str, on: bool | None = None) -> bool:
        """Fenêtre FAO (« paths » : outils, opérations et parcours ;
        « palette » : créer un parcours) en plein écran translucide, ou de
        retour à sa place ; rend l'état obtenu."""
        ov = self.overlays[which]
        return ov.set_active(not ov.active if on is None else on)

    def show_program(self) -> None:
        """Le programme machine dans sa fenêtre (`ui.program_window`) : montrée, devant, à jour. La première fois,
        détachée et sans place à elle (pas remise par la session, ou hors de l'écran) : posée sur la moitié droite du
        dessin."""
        d = self.dock_program
        first, self._program_shown = not getattr(self, '_program_shown', False), True
        d.setVisible(True)
        scr = self.screen().availableGeometry() if self.screen() is not None else None
        kept = getattr(self, '_panels_restored', False) and scr is not None and scr.contains(d.frameGeometry())
        if first and d.isFloating() and not kept:
            st = self.stage
            tl = st.mapToGlobal(st.rect().topLeft())
            w = max(420, min(760, st.width() // 2))
            d.setGeometry(tl.x() + st.width() - w, tl.y(), w, max(360, st.height()))
        d.raise_()
        self.program_panel.refresh()

    def program_changed(self) -> None:
        """Le panneau FAO ou le dessin a changé : la fenêtre du programme suit, si elle est montrée et « en direct »."""
        p = getattr(self, 'program_panel', None)
        if p is not None:
            p.notify()

    def cam_full_height(self) -> None:
        """Panneau des opérations FAO sur toute la hauteur de la fenêtre : le
        panneau Dimensions, s'il est au-dessus de lui, passe en onglet à côté."""
        d = getattr(self, 'dock_paths', None)
        if d is None or d.isFloating() or not d.isVisible():
            return
        self.dock_full_height(d)

    def dock_full_height(self, d) -> None:
        """Un panneau ancré mis devant, sur toute la hauteur de sa colonne : le panneau Dimensions, s'il est
        au-dessus de lui, passe en onglet à côté (un grand panneau sous Dimensions dépasserait l'écran)."""
        if d is None or d.isFloating() or d.isHidden():
            return
        from PySide6.QtWidgets import QDockWidget
        dims = self.findChild(QDockWidget, 'dims')
        cols = getattr(self, 'columns', None)
        if dims is not None and dims is not d and not dims.isHidden() and not dims.isFloating() \
                and self.dockWidgetArea(dims) == self.dockWidgetArea(d) and dims not in self.tabifiedDockWidgets(d) \
                and not (cols is not None and 'dims' in cols.split_names()):   # partagé en hauteur : laissé
            self.tabifyDockWidget(d, dims)
        d.raise_()

    def dock_as_window(self, dock, key: str = ''):
        """Un panneau ancrable (celui d'un plugin, par exemple) qui peut aller dans sa propre fenêtre — réduire,
        agrandir, fermer, plein écran — et en revenir : rend son `DockAsWindow` (`ui.panel_window`), le même à
        chaque appel. `key` : réglage sous lequel sa place et son plein écran sont retenus (d'office
        « panneaux/<nom du panneau> »)."""
        from .panel_window import DockAsWindow
        host = getattr(dock, '_as_window', None)
        if host is None:
            host = dock._as_window = DockAsWindow(dock, self, self.settings,
                                                  key or f'panneaux/{dock.objectName() or "panneau"}')
        return host

    def toggle_paths_window(self, floating: bool | None = None) -> bool:
        """Liste des opérations et parcours : dans le panneau de droite, ou
        en fenêtre détachée (au choix, retenu) ; rend l'état obtenu."""
        d = self.dock_paths
        floating = not d.isFloating() if floating is None else bool(floating)
        d.setVisible(True)
        d.setFloating(floating)
        if floating:
            scr = self.screen().availableGeometry() if self.screen() is not None else None
            w, h = 460, 760
            if scr is not None:
                h = min(h, scr.height() - 80)
                d.setGeometry(scr.right() - w - 30, scr.top() + 60, w, h)
            else:
                d.resize(w, h)
        else:
            d.raise_()
        self.settings.setValue('fao/liste_detachee', floating)
        return floating

    def _cam_new(self, key: str):
        """Nouveau parcours depuis la palette FAO (ou son raccourci)."""
        if not self.dock_cam.isVisible():
            self.A['cam_panel'].setChecked(True)
        return self.cam_panel.new_operation(key)

    # --- raccourcis clavier ---------------------------------------------------
    def _apply_shortcuts(self) -> None:
        from PySide6.QtGui import QKeySequence
        from . import shortcuts as SC
        if not hasattr(self, '_default_shortcuts'):
            self._default_shortcuts = {k: [s.toString(QKeySequence.SequenceFormat.PortableText)
                                           for s in a.shortcuts()] for k, a in self.A.items()}
        scheme, te, custom = SC.load(self.settings)
        SC.apply(self.A, SC.effective(self._default_shortcuts, scheme, te, custom))

    def shortcuts_dialog(self, exec_dialog: bool = True):
        from . import shortcuts as SC
        scheme, te, custom = SC.load(self.settings)
        dlg = SC.dialog_class()(self, self.A, self._default_shortcuts, scheme, te, custom)
        if not exec_dialog:
            return dlg
        if dlg.exec():
            SC.save(self.settings, dlg.scheme, dlg.te_entries, dlg.custom)
            self._apply_shortcuts()
        return dlg

    def _cam_wrap(self, kind: str):
        if not self.dock_cam.isVisible():
            self.A['cam_panel'].setChecked(True)
        return self.cam_panel.wrap_op(kind)

    def _cam(self, what: str):
        if not self.dock_cam.isVisible():
            self.A['cam_panel'].setChecked(True)
        return getattr(self.cam_panel, what)()

    # --- modes simple et expert ----------------------------------------------------------------
    def ui_mode(self) -> str:
        """'simple' ou 'expert' : le mode retenu."""
        from . import modes
        return modes.current(self.settings)

    def _plugin_action_keys(self) -> tuple:
        from ..plugins import REGISTRY
        return tuple(spec.key for spec in REGISTRY.actions)

    def _mode_filter(self):
        """Le filtre du mode simple : fonction(commande) → son bouton est-il montré ? La répartition d'office
        (`ui.modes.SIMPLE`, machines, plugins), puis les choix de l'utilisateur."""
        from . import modes
        from .ribbon_editor import RelayAction
        keys = {id(a): k for k, a in self.A.items()}
        plugin = set(self._plugin_action_keys())
        plus, minus = modes._keys(self.settings, modes.PLUS), modes._keys(self.settings, modes.MINUS)

        def allowed(action) -> bool:
            src = action.src if isinstance(action, RelayAction) else action
            key = keys.get(id(src))
            if key is None:                              # pas une commande de la fenêtre : toujours montrée
                return True
            if key in minus:
                return False
            return modes.default_simple(key, plugin) or key in plus
        return allowed

    def set_ui_mode(self, mode: str, announce: bool = True) -> str:
        """Passe en mode simple (l'essentiel du ruban) ou expert (tout) ; le mode est retenu. Rend le mode."""
        from . import modes
        mode = mode if mode in modes.MODES else 'expert'
        self.settings.setValue(modes.KEY, mode)
        self.A['ui_mode'].setProperty('vd_mode', mode)
        r = self.ribbon
        r.set_mode_filter(self._mode_filter() if mode == 'simple' else None)
        cp = getattr(self, 'cam_panel', None)
        if cp is not None and hasattr(cp, 'apply_mode'):
            cp.apply_mode(mode)                          # panneau FAO : « Réglage… » en mode expert
        b = getattr(r, 'mode_button', None)
        if b is not None:
            b.update()
        if announce:
            self.statusBar().showMessage(
                tr('Mode simple : l\'essentiel du ruban ; clic droit sur un bouton pour le réserver au mode expert')
                if mode == 'simple' else tr('Mode expert : toutes les commandes'), 6000)
        return mode

    def toggle_ui_mode(self) -> str:
        return self.set_ui_mode('expert' if self.ui_mode() == 'simple' else 'simple')

    def move_button_mode(self, key: str, to_simple: bool) -> None:
        """Le bouton de la commande `key` montré aussi en mode simple, ou réservé au mode expert (clic droit)."""
        from . import modes
        modes.move(self.settings, key, to_simple, self._plugin_action_keys())
        self.set_ui_mode(self.ui_mode(), announce=False)
        name = self.A[key].text().replace('&', '') if key in self.A else key
        self.statusBar().showMessage((tr('« {0} » : montré aussi en mode simple') if to_simple
                                      else tr('« {0} » : réservé au mode expert')).format(name), 6000)

    #: réglage : les commandes des favoris (barre du haut), dans l'ordre
    FAV_KEY = 'ruban/favoris'

    def _stored_favorites(self) -> list:
        """Les clés retenues, celles d'une commande absente aujourd'hui comprises (un plugin pas chargé)."""
        v = self.settings.value(self.FAV_KEY, [])
        if isinstance(v, str):                           # une seule : QSettings la rend seule
            v = [v] if v else []
        out = []
        for k in v or []:
            if str(k) and str(k) not in out:
                out.append(str(k))
        return out

    def favorite_keys(self) -> list:
        """Les commandes des favoris (clés de `self.A`), dans l'ordre où elles ont été ajoutées."""
        return [k for k in self._stored_favorites() if k in self.A]

    def _save_favorites(self, keys: list) -> None:
        if keys:
            self.settings.setValue(self.FAV_KEY, list(keys))
        else:
            self.settings.remove(self.FAV_KEY)
        self.refresh_favorites()

    def add_favorite(self, key: str) -> bool:
        """La commande `key` au bout des favoris (barre du haut) ; False si elle y est déjà ou n'existe pas."""
        keys = self._stored_favorites()
        if key not in self.A or key in keys:
            return False
        self._save_favorites(keys + [key])
        self.statusBar().showMessage(tr('« {0} » : ajouté aux favoris (barre du haut)').format(
            self.A[key].text().replace('&', '')), 6000)
        return True

    def remove_favorite(self, key: str) -> bool:
        keys = self._stored_favorites()
        if key not in keys:
            return False
        self._save_favorites([k for k in keys if k != key])
        self.statusBar().showMessage(tr('« {0} » : retiré des favoris').format(
            self.A[key].text().replace('&', '')), 6000)
        return True

    def _is_favorite_button(self, button) -> bool:
        """Un bouton des favoris : de leur barre, ou ajouté par eux à la barre d'accès rapide de TypeEdit 13."""
        bar = button.parentWidget()
        if bar is None:
            return False
        if bar is getattr(self, 'fav_bar', None):
            return True
        return bar is getattr(self, 'te_quickbar', None) and (
            any(a is button.defaultAction() for a in getattr(self, '_fav_added', ()))
            or self._action_key(button.defaultAction()) in self.favorite_keys())   # déjà là de TypeEdit

    def refresh_favorites(self):
        """Les favoris : à la suite de la barre d'accès rapide de TypeEdit 13 si elle est là, sinon dans leur barre,
        tout en haut (au-dessus du ruban, la première rangée en plein écran) ; sans favoris, pas de barre. Rend la
        barre qui les porte (ou None)."""
        from PySide6.QtCore import QSize
        from PySide6.QtWidgets import QToolBar
        from shiboken6 import isValid
        keys = self.favorite_keys()
        te = getattr(self, 'te_quickbar', None)
        old = getattr(self, '_fav_host', None)
        if old is not None and isValid(old):
            for a in getattr(self, '_fav_added', ()):
                if isValid(a):
                    old.removeAction(a)
                    if a.isSeparator():                  # le leur : défait
                        a.deleteLater()
        self._fav_added = []
        self._fav_host = None
        bar = getattr(self, 'fav_bar', None)
        if bar is not None and (te is not None or not keys or not isValid(bar)):
            if isValid(bar):
                bar.setParent(None)
                bar.deleteLater()
            self.fav_bar = bar = None
        if not keys:
            return None
        if te is not None:                               # à la suite de celle de TypeEdit 13 (rien en double)
            have = {id(a) for a in te.actions()}
            new = [self.A[k] for k in keys if id(self.A[k]) not in have]
            if new:                                      # un séparateur seulement s'il y a quelque chose après
                self._fav_added.append(te.addSeparator())
            for a in new:
                te.addAction(a)
                self._fav_added.append(a)
            self._fav_host = te
            return te
        if bar is None:
            holder = self.menuWidget()
            box = holder.layout() if holder is not None else None
            if box is None:
                return None
            bar = QToolBar(tr('Favoris'))
            bar.setObjectName('favBar')
            bar.setIconSize(QSize(20, 20))
            bar.setMovable(False)
            bar.setToolTip(tr('Favoris : clic droit sur un bouton du ruban pour l\'y ajouter ou l\'en retirer'))
            box.insertWidget(0, bar)                     # tout en haut, au-dessus du ruban
            self.fav_bar = bar
        else:
            bar.clear()
        for k in keys:
            bar.addAction(self.A[k])
        return bar

    def _machine_tip(self, m) -> str:
        kind = tr('Laser') if m.kind == 'laser' else tr('Fraiseuse')
        tip = f'{kind} : {tr(m.label)}'
        if m.tip:
            tip += '\n' + tr(m.tip)
        if m.plugin:
            tip += '\n' + tr('Machine déclarée par le plugin « {0} »').format(m.plugin)
        return tip

    def _te_machines(self, page) -> None:
        """Disposition TypeEdit 13 : l'onglet FAO de TypeEdit reçoit le groupe « Machine » (fraiseuses et lasers :
        il n'y a là qu'un onglet FAO) et les commandes que les plugins réservent à une machine, dans leurs groupes."""
        from ..plugins import REGISTRY
        self._machine_group(page, None, at_start=True)
        groups: dict = {}
        fao = (tr('FAO'), tr('FAO 2D'), tr('FAO 3D'), tr('FAO laser'))
        for spec in REGISTRY.actions:
            if not spec.posts or spec.key not in self.A or tr(spec.tab) not in fao:
                continue
            title = tr(spec.group or spec.plugin or 'Plugin')
            if title not in groups:
                groups[title] = page.group(title)
            groups[title].add(self.A[spec.key], big=spec.big)

    def _machine_group(self, page, kind: str | None, *, at_start: bool = False) -> None:
        """Le groupe « Machine » d'un ruban FAO : un bouton par machine de ce genre (déclarées par les plugins) ;
        celui de la machine du dessin est enfoncé. Sans machine déclarée : pas de groupe. Les boutons portent le nom de
        la machine, en texte seul : un petit bouton du ruban se réduit à son icône quand la place manque, et toutes
        les machines auraient la même."""
        from PySide6.QtWidgets import QSizePolicy, QToolButton
        from ..cam import machines as MC
        ms = MC.all_machines(kind)                       # None : toutes, fraiseuses puis lasers
        if not ms:
            return
        if kind is None:
            ms = sorted(ms, key=lambda m: m.kind == 'laser')
        g = page.group(tr('Machine'), at_start=at_start)
        for m in ms:
            b = QToolButton()
            b.setDefaultAction(self.A[f'machine_{m.key}'])
            b.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextOnly)
            b.setAutoRaise(True)
            b.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            b.setProperty('ribbon_machine', m.key)
            g.add_widget(b)                              # empilés par trois, jamais réduits à l'icône

    def _sync_machine_buttons(self, key: str | None = None) -> None:
        """Le bouton de la machine du dessin enfoncé, les autres relevés."""
        from ..cam import machines as MC
        if key is None:
            key = getattr(self, '_machine_key', '') or ''
        for m in MC.all_machines():
            act = self.A.get(f'machine_{m.key}')
            if act is not None and act.isChecked() != (m.key == key):
                act.blockSignals(True)
                act.setChecked(m.key == key)
                act.blockSignals(False)

    def set_machine(self, key: str) -> bool:
        """La machine choisie dans un ruban FAO : son meilleur post-processeur devient celui du dessin. Rend False si
        elle n'en a pas encore (machine à configurer) : le dessin garde le sien."""
        from ..cam import machines as MC
        from ..cam import post
        m = MC.by_key(key)
        cp = self.cam_panel
        best = MC.resolve(m, post.posts(cp.machines_dir())) if m is not None else ''
        if not best:
            self._sync_machine_buttons()
            self.statusBar().showMessage(tr('{0} : pas encore de post-processeur pour cette machine').format(
                tr(m.label) if m is not None else key), 8000)
            return False
        cp.set_post(best)
        cp.refresh()
        self._sync_machine_buttons()
        self.statusBar().showMessage(tr('Machine : {0}').format(tr(m.label)), 4000)
        return True

    def machine_changed(self, key: str) -> str:
        """Machine du dessin (clé de post-processeur) : actions et panneaux
        des plugins montrés pour elle seule, son bouton enfoncé dans le ruban FAO, la palette réduite à son genre
        (fraiseuse ou laser), plugins prévenus quand elle
        change. Rend la machine (famille de la clé)."""
        from ..cam import machines as MC
        from ..cam import post
        from ..plugins import REGISTRY
        fam = post.family(key or '')
        m = MC.of_post(key or '')
        mkey = m.key if m is not None else ''
        self._sync_machine_buttons(mkey)
        if fam == getattr(self, '_machine', None) and mkey == getattr(self, '_machine_key', None):
            return fam
        self._machine, self._machine_key = fam, mkey

        def shown(posts) -> bool:
            return fam in posts or key in posts or (bool(mkey) and mkey in posts)
        for spec in REGISTRY.actions:
            if spec.posts and spec.key in self.A:
                self.A[spec.key].setVisible(shown(spec.posts))
        for spec in REGISTRY.panels:
            dock = self.plugin_docks.get(spec.key) if hasattr(self, 'plugin_docks') else None
            if dock is not None and spec.posts:
                on = shown(spec.posts)
                was = not dock.isHidden()
                self._plugin_docks_on = {**getattr(self, '_plugin_docks_on', {}), spec.key: on}
                dock.setVisible(on)
                if on and not was:
                    self.dock_full_height(dock)           # le panneau de la machine choisie : devant, sur la colonne
        kind = m.kind if m is not None else ''
        if kind != getattr(self, '_machine_kind', ''):   # fraiseuse ↔ laser : la palette ne montre que ses parcours
            self._machine_kind = kind
            palette = getattr(self, 'cam_palette', None)
            if palette is not None:
                palette.refresh()
        for fn in REGISTRY.post_hooks:
            try:
                fn(self, fam)
            except Exception as ex:                       # un plugin ne casse jamais la fenêtre
                self.statusBar().showMessage(tr('Plugin : {0}').format(ex), 10000)
        return fam

    def _plugin_docks(self) -> None:
        """Panneaux ancrés des plugins (cachés tant que la machine ne leur va pas)."""
        from ..plugins import REGISTRY
        self.plugin_docks = {}
        for spec in REGISTRY.panels:
            try:
                w = spec.factory(self)
            except Exception as ex:                       # un plugin ne casse jamais la fenêtre
                self.statusBar().showMessage(tr('Plugin : {0}').format(ex), 10000)
                continue
            d = QDockWidget(tr(spec.title), self)
            d.setObjectName(f'plugin_{spec.key}')
            d.setWidget(w)
            area = Qt.DockWidgetArea.LeftDockWidgetArea if spec.area == 'gauche' else Qt.DockWidgetArea.RightDockWidgetArea
            self.addDockWidget(area, d)
            layers = self.findChild(QDockWidget, 'layers')
            if area == Qt.DockWidgetArea.RightDockWidgetArea and layers is not None:
                self.tabifyDockWidget(layers, d)          # en onglet à côté des Calques : empilé, il ferait une
                layers.raise_()                           # colonne plus haute que l'écran
            if spec.posts:
                d.setVisible(False)
            self.plugin_docks[spec.key] = d

    def _plugin_ribbon(self, r) -> None:
        """Actions des plugins dans le ruban : onglet existant (ou nouveau), un groupe par nom."""
        from ..plugins import REGISTRY
        from .ribbon import RibbonGroup
        groups = {}
        for spec in REGISTRY.actions:
            if spec.key not in self.A:
                continue
            ref = self.A.get(spec.after) if getattr(spec, 'after', '') else None
            if ref is not None and any(g.insert_after(ref, self.A[spec.key], big=spec.big) is not None
                                       for g in r.findChildren(RibbonGroup)):
                continue                                 # à côté du bouton demandé
            if not spec.tab:
                continue
            title = tr(spec.tab)
            if title == tr('FAO') and not any(r.tabText(i) == title for i in range(r.count())):
                title = tr('FAO 2D')                     # l'onglet FAO d'avant
            page = next((r.widget(i).widget() for i in range(r.count()) if r.tabText(i) == title), None) \
                or r.add_tab(title)
            key = (title, tr(spec.group or spec.plugin or 'Plugin'))
            if key not in groups:
                groups[key] = page.group(key[1])
            groups[key].add(self.A[spec.key], big=spec.big)

    def _cam_document_changed(self) -> None:
        """Nouveau document : réglage FAO relu, parcours effacés ; parcours
        TypeEdit à côté d'un VND signalés."""
        self.cam_panel.refresh()
        self.cam_panel.display([])
        src = self.canvas.doc.source_path
        if src and src.lower().endswith('.vnd'):
            from ..cam import typeedit
            n = len(typeedit.companions(src))
            if n:
                self.statusBar().showMessage(
                    tr('{0} parcours TypeEdit à côté de ce VND : FAO > Parcours TypeEdit pour les voir').format(n),
                    10000)

    def ask_arrow_step(self, horizontal: bool = True, value: float | None = None,
                       start: float | None = None) -> float | None:
        """Ctrl+flèche : « pas de déplacement ? ». Proposé : le pas en cours,
        sinon `start` (mode point : étendue des points choisis), sinon la
        largeur (ou hauteur) de la sélection plus l'écart des options.
        Entrée : les flèches avancent de cette valeur (0 : retour au pas des
        options). `value` : réponse donnée d'avance (essais)."""
        c = self.canvas
        if value is None:
            if getattr(self, 'step_answer', None) is not None:    # essais : réponse posée d'avance
                value = self.step_answer
        if value is None:
            from PySide6.QtWidgets import QInputDialog
            start = c.arrow_step or start or c.extent_step(horizontal) or c.nudge_mm
            value, ok = QInputDialog.getDouble(self, tr('Pas de déplacement'), tr('Pas des flèches (mm) :'),
                                               float(start), 0.0, 100000.0, 3)
            if not ok:
                return None
        c.arrow_step = value if value > 0 else None
        c.arrowStepChanged.emit(float(value) if value > 0 else 0.0)
        c.setFocus()
        return c.arrow_step

    def arrow_step_move(self, dx: int, dy: int, value: float | None = None) -> bool:
        """Ctrl+flèche : demande le pas, puis déplace aussitôt la sélection
        d'un pas dans le sens de la flèche (TypeEdit). 0 : retour au pas des
        options, sans déplacer."""
        step = self.ask_arrow_step(dx != 0, value)
        if not step or not self.canvas.selection:
            return False
        self.canvas.transform_selection(Affine.translation(dx * step, dy * step))
        return True

    def _arrow_step_changed(self, step: float) -> None:
        if step > 0:
            msg = tr('Pas des flèches : {0} mm (Ctrl+flèche pour le changer)').format(f'{step:g}')
        else:
            msg = tr('Pas des flèches : {0} mm').format(f'{self.canvas.nudge_mm:g}')
        self.statusBar().showMessage(msg, 8000)

    def _toggle_rulers(self, on: bool) -> None:
        for w in (self.ruler_h, self.ruler_v, self.ruler_corner):
            w.setVisible(on)
        self.settings.setValue('vue/regles', on)

    def edit_guide(self, i: int) -> None:
        from PySide6.QtWidgets import QInputDialog
        axis, v = self.canvas.guides[i]
        label = tr('Position Y du guide (mm)') if axis == 'h' else tr('Position X du guide (mm)')
        val, ok = QInputDialog.getDouble(self, tr('Guide'), label, v, -1e6, 1e6, 4)
        if ok:
            self.push_undo()
            self.canvas.guides[i][1] = val
            self._on_doc_changed()
            self.canvas.update()

    def object_to_guides(self) -> int:
        """Les côtés droits des objets sélectionnés en repères, les objets restent ; rend le nombre de repères créés."""
        from ..core import guides as GD
        c = self.canvas
        if not c.selection:
            self.statusBar().showMessage(tr('Sélectionnez des objets.'), 4000)
            return 0
        guides, obliques = GD.split(GD.lines_of(c.selection))
        guides, obliques = GD.new_only(guides, obliques, c.guides, c.oblique_guides)
        n = len(guides) + len(obliques)
        if n == 0:
            self.statusBar().showMessage(tr('Ces repères existent déjà.'), 5000)
            return 0
        if n > GD.MAX_GUIDES:
            self.statusBar().showMessage(tr('Trop de côtés droits ({0}) : sélectionnez moins d’objets.').format(n), 8000)
            return 0
        self.push_undo(keys=(c.OBLIQUES,))
        c.guides.extend(guides)
        if obliques:
            c.doc.extra.setdefault(c.OBLIQUES, []).extend(obliques)
        self._on_doc_changed()
        c.update()
        self.statusBar().showMessage(tr('{0} repère(s) créé(s).').format(n), 6000)
        return n

    def guides_dialog(self, values: tuple | None = None) -> bool:
        """Repères… : `values` (repères, lignes de construction) donnés d'avance (essais)."""
        c = self.canvas
        if values is None:
            from .guides_dialog import GuidesDialog
            p = c.doc.plate
            dlg = GuidesDialog(self, c.guides, c.oblique_guides, (p.x, p.y, p.x + p.width, p.y + p.height))
            if not dlg.exec():
                return False
            values = dlg.values()
        guides, obliques = values
        if list(guides) == list(c.guides) and list(obliques) == list(c.oblique_guides):
            return False
        self.push_undo(keys=(c.OBLIQUES,))
        c.guides[:] = [list(g) for g in guides]
        if obliques:
            c.doc.extra[c.OBLIQUES] = [list(o) for o in obliques]
        else:
            c.doc.extra.pop(c.OBLIQUES, None)
        self._on_doc_changed()
        c.update()
        return True

    def clear_guides(self) -> None:
        if self.canvas.guides or self.canvas.oblique_guides:
            self.push_undo(keys=(self.canvas.OBLIQUES,))
            self.canvas.guides.clear()
            self.canvas.doc.extra.pop(self.canvas.OBLIQUES, None)
            self._on_doc_changed()
            self.canvas.update()

    def edit_oblique_guide(self, i: int, params: dict | None = None) -> bool:
        """Ligne de construction (double-clic) : point de passage, angle, ou
        suppression ; à 0° ou 90°, elle devient un guide ordinaire."""
        from dataclasses import asdict, field, make_dataclass
        c = self.canvas
        g = c.oblique_guides
        if not 0 <= i < len(g):
            return False
        x, y, a = g[i]
        if params is None:
            from .dialogs import ParamsDialog
            P = make_dataclass('P', [('x', float, field(default=x)), ('y', float, field(default=y)),
                                     ('angle', float, field(default=a)), ('delete', bool, field(default=False))])
            dlg = ParamsDialog(self, tr('Ligne de construction'), P(), {
                'x': tr('Passe par X (mm)'), 'y': tr('Passe par Y (mm)'), 'angle': tr('Angle (°)'),
                'delete': tr('Supprimer la ligne')})
            if not dlg.exec():
                return False
            params = asdict(dlg.result_params())
        if params.get('delete'):
            c.remove_oblique(i)
            return True
        x2, y2 = float(params.get('x', x)), float(params.get('y', y))
        a2 = float(params.get('angle', a)) % 180.0
        if [x2, y2, a2] == [x, y, a]:
            return False
        self.push_undo(keys=(c.OBLIQUES,))
        lst = c.doc.extra[c.OBLIQUES]
        del lst[i]
        if min(a2, 180.0 - a2) < 1e-6:
            c.guides.append(['h', y2])
        elif abs(a2 - 90.0) < 1e-6:
            c.guides.append(['v', x2])
        else:
            lst.insert(i, [x2, y2, round(a2, 9)])
        if not lst:
            c.doc.extra.pop(c.OBLIQUES)
        self._on_doc_changed()
        c.update()
        return True

    def _snap_status(self) -> None:
        if not hasattr(self, 'lbl_snap'):          # pendant la construction des actions
            return
        sn = self.canvas.snap
        if not sn.enabled:
            self.lbl_snap.setText(tr('Accrochage : non'))
            return
        from ..core.snap import LABELS
        names = [tr(LABELS[k]) for k in ('node', 'intersection', 'middle', 'center', 'centroid', 'quadrant',
                                         'perpendicular', 'tangent', 'extension', 'parallel', 'guide', 'nearest',
                                         'grid') if k in sn.modes]
        if sn.tracking:
            names.append(tr(LABELS['tracking']))
        if sn.polar:
            names.append(tr('polaire {0}°').format(f'{sn.polar_step:g}'))
        self.lbl_snap.setText(tr('Accrochage : ') + (', '.join(names) or tr('aucun mode')))

    def snap_window(self, show: bool = True):
        """Fenêtre des accrochages (F3) : ouverte, ou refermée si elle l'est."""
        from .snap_window import SnapWindow
        w = getattr(self, '_snap_window', None)
        if w is None:
            w = self._snap_window = SnapWindow(self)
        if show and w.isVisible():
            w.close()
        elif show:
            w.sync()
            w.show()
            w.raise_()
        return w

    def _toggle_snap(self, on: bool) -> None:
        self.canvas.snap.enabled = on
        if not on:
            self.canvas._snap_hit = None
        self._snap_status()
        self.canvas.update()

    def _center_line_tool(self):
        """Outil Ligne d'axe, avec ses réglages (F10 › Dessin)."""
        from . import tools as T
        from .options import value
        self.canvas.measured.emit(tr('Ligne d\'axe : cliquez le premier trait droit'))
        return T.CenterLineTool(self.canvas, value(self.settings, 'axe/debord'), value(self.settings, 'axe/tirets'),
                                value(self.settings, 'axe/echelle'))

    def _tan_circle_tool(self):
        """Outil cercle tangent, après son rayon (None : abandon)."""
        from PySide6.QtWidgets import QInputDialog
        from . import tools as T
        r, ok = QInputDialog.getDouble(self, tr('Cercle tangent'),
                                       tr('Rayon (mm) — 0 : cercle tangent à trois objets'),
                                       float(self.settings.value('dessin/cercle_tangent', 5.0) or 0.0),
                                       0.0, 100000.0, 3)
        if not ok:
            return None
        self.settings.setValue('dessin/cercle_tangent', r)
        self.canvas.tan_circle_radius = r
        self.canvas.measured.emit(tr('Cercle tangent : cliquez le premier objet, près du point de contact'))
        return T.TanCircleTool(self.canvas)

    def _dline_tool(self):
        """Outil ligne double : avec les derniers réglages ; la première fois ou Ctrl+clic, après sa fenêtre (None : abandon)."""
        import json

        from . import tools as T
        o = getattr(self.canvas, 'dline', None)
        if not o:
            try:
                o = json.loads(str(self.settings.value('ligne_double/reglages', '') or ''))
            except ValueError:
                o = None
        if not isinstance(o, dict) or not o or self._ctrl_held():
            o = self.dline_dialog(o if isinstance(o, dict) else {})
            if o is None:
                return None
            self.settings.setValue('ligne_double/reglages', json.dumps(o))
        self.canvas.dline = o
        return T.DoubleLineTool(self.canvas)

    def dline_dialog(self, cur: dict):
        """Réglages de la ligne double : {'left', 'right', 'corners', 'ends'} ou None."""
        from .dline_dialog import DoubleLineDialog
        d = DoubleLineDialog(self, cur)
        return d.values() if d.exec() == QDialog.DialogCode.Accepted else None

    def set_intuitive_snap(self, on: bool) -> None:
        """Accrochage intuitif de la cotation (gardé dans les réglages)."""
        self.canvas.intuitive_snap = bool(on)
        self.settings.setValue('accrochage/intuitif', bool(on))

    def _point_mode(self, kind: str) -> bool:
        if not self.canvas.start_point_mode(kind):
            self.statusBar().showMessage(tr('Choisissez d\'abord un outil (trait, cote, déplacement…).'), 5000)
            return False
        self.statusBar().showMessage(tr('Milieu : premier point') if kind == 'm2p' else tr('Depuis : point de base'),
                                     5000)
        return True

    def _ask_offset(self):
        """Décalage (X, Y) depuis le point de base ; None : abandon."""
        from PySide6.QtWidgets import QInputDialog
        text, ok = QInputDialog.getText(self, tr('Depuis un point'), tr('Décalage X ; Y (mm)'), text='0 ; 0')
        if not ok:
            return None
        try:
            parts = [float(v.strip().replace(',', '.')) for v in text.replace(';', ' ').split()]
        except ValueError:
            return None
        return (parts[0], parts[1]) if len(parts) == 2 else None

    def _snap_polar(self, on: bool) -> None:
        """Repérage polaire (Maj+F12) ; l'activer allume aussi l'accrochage."""
        sn = self.canvas.snap
        sn.polar = bool(on)
        try:
            sn.polar_step = float(self.settings.value('accrochage/pas_polaire', 15.0))
        except (TypeError, ValueError):
            sn.polar_step = 15.0
        if on and not self.A['snap'].isChecked():
            self.A['snap'].setChecked(True)
        self._snap_status()
        self.canvas.overlay_update()

    def boundary_gap_dialog(self, value: float | None = None) -> float | None:
        """Écart toléré du contour de zone (mm)."""
        if value is None:
            from PySide6.QtWidgets import QInputDialog
            v, ok = QInputDialog.getDouble(self, tr('Contour de zone'),
                                           tr('Écart toléré entre les traits (mm, 0 : zones fermées seulement)'),
                                           float(self.canvas.boundary_gap), 0.0, 1000.0, 3)
            if not ok:
                return None
            value = v
        self.settings.setValue('dessin/ecart_contour', float(value))
        self.canvas.boundary_gap = float(value)
        return float(value)

    def polar_step_dialog(self, value: float | None = None) -> float | None:
        """Pas du repérage polaire (degrés)."""
        if value is None:
            from PySide6.QtWidgets import QInputDialog
            v, ok = QInputDialog.getDouble(self, tr('Repérage polaire'), tr('Pas des angles (°)'),
                                           self.canvas.snap.polar_step, 1.0, 90.0, 1)
            if not ok:
                return None
            value = v
        self.settings.setValue('accrochage/pas_polaire', float(value))
