    def _snap_tracking(self, on: bool) -> None:
        """Repérage d'accrochage (F11) ; l'activer allume aussi l'accrochage."""
        sn = self.canvas.snap
        sn.tracking = bool(on)
        sn.clear_tracking()
        if on and not self.A['snap'].isChecked():
            self.A['snap'].setChecked(True)
        self._snap_status()
        self.canvas.overlay_update()

    def _snap_mode(self, kind: str, on: bool) -> None:
        (self.canvas.snap.modes.add if on else self.canvas.snap.modes.discard)(kind)
        self._snap_status()

    def _cycle_snap(self, d: int) -> None:
        modes = self.canvas.snap.modes
        names = [m for _, m in self.SNAP_PRESETS]
        i = next((j for j, m in enumerate(names) if m == modes), -1)
        name, new = self.SNAP_PRESETS[(i + d) % len(self.SNAP_PRESETS)]
        for k in ('node', 'intersection', 'middle', 'center', 'centroid', 'quadrant', 'perpendicular', 'tangent',
                  'extension', 'parallel', 'guide', 'nearest', 'grid'):
            self.A[f'snap_{k}'].setChecked(k in new)
        if not self.A['snap'].isChecked():
            self.A['snap'].setChecked(True)
        self.statusBar().showMessage(tr('Accrochage : {0}').format(name), 2000)

    def apply_options(self) -> None:
        from ..core import fonts
        from .options import value as option
        st = self.settings
        for d in str(st.value('polices/dossiers', '') or '').split(';'):
            if d.strip() and pathlib.Path(d.strip()).is_dir():
                fonts.add_font_dir(d.strip())
        from ..io import colors as io_colors
        io_colors.KEEP = bool(option(st, 'import/couleurs'))    # couleurs des DXF, SVG… en outils
        io_colors.DXF_BLACK_TRUE = bool(option(st, 'export/dxf_noir'))   # le noir d'un DXF aussi en couleur vraie
        io_colors.DXF_ARCS = option(st, 'export/dxf_courbes') == 'arcs'  # les courbes d'un DXF en arcs raccordés
        from ..io import smb as io_smb
        io_smb.KEEP_COLORS = bool(option(st, 'symboles/couleurs'))
        io_smb.LIVE_TEXTS = bool(option(st, 'symboles/textes_vivants'))   # l'export en SMB aussi
        from . import symbols as ui_symbols
        ui_symbols.SHOW_HIDDEN = bool(option(st, 'navigateur/caches'))
        self.canvas.nudge_mm = option(st, 'options/deplacement')
        self.canvas.step_gap_mm = option(st, 'options/ecart_pas')
        if str(st.value('options/delai_deplacement_929', '') or '') != '1':   # l'ancien défaut (600 ms) : 250 ms, une fois
            if str(st.value('options/delai_deplacement', '') or '').strip() == '600':
                st.setValue('options/delai_deplacement', 250)
            st.setValue('options/delai_deplacement_929', '1')
        self.canvas.move_delay_ms = int(option(st, 'options/delai_deplacement'))
        if self.canvas.highlight_px != int(option(st, 'options/surbrillance')):
            self.canvas.highlight_px = int(option(st, 'options/surbrillance'))
            self.canvas.update()
        self.canvas.snap.grid_step = option(st, 'options/grille')
        self.canvas.snap_px = int(option(st, 'options/tolerance'))
        self.canvas.dim_text = option(st, 'options/cote_texte')
        self.undo_limit = int(option(st, 'options/annulations'))
        self.zoom_step = option(st, 'vue/zoom_pas')
        self.canvas.handle_px = option(st, 'vue/poignees')
        self.RECENT_MAX = option(st, 'fichiers/max_recents')
        self.dims.keep.setChecked(option(st, 'options/proportions'))
        dec = option(st, 'options/decimales')
        for sb in self.dims.fields.values():
            sb.setDecimals(dec)
        if not getattr(self, '_snap_started', False):  # au lancement seulement : F10 › OK ne le rallume pas
            self._snap_started = True
            if str(st.value('options/accrochage_986', '') or '') != '1':   # actif d'office : une fois, même laissé éteint
                st.setValue('options/accrochage', True)
                st.setValue('options/accrochage_986', '1')
            if str(st.value('vnd/textes_vivants_988', '') or '') != '1':   # textes modifiables dans TypeEdit : une fois
                st.setValue('vnd/textes_vivants', True)
                st.setValue('vnd/textes_vivants_988', '1')
            if str(st.value('symboles/textes_vivants_1000', '') or '') != '1':   # … ceux des symboles aussi
                st.setValue('symboles/textes_vivants', True)
                st.setValue('symboles/textes_vivants_1000', '1')
            if option(st, 'options/accrochage') and not self.A['snap'].isChecked():
                self.A['snap'].setChecked(True)
        tabs = bool(option(st, 'vue/onglets_calques'))     # F10 › Affichage : ouverts ou fermés tout de suite
        if self.A['layer_tabs'].isChecked() != tabs:
            self.A['layer_tabs'].setChecked(tabs)
        from ..cam import toollib
        toollib.CHOSEN_PATH = option(st, 'fao/bibliotheque')
        from ..core import workers
        from . import progress as _progress
        workers.set_count(option(st, 'perf/fils'))         # fils de calcul (0 : cœurs − 1)
        workers.set_processes(option(st, 'perf/processus'))  # processus des longs travaux (0 : automatique)
        _progress.LOW_PRIORITY = bool(option(st, 'perf/priorite_basse'))
        from .symbols import _PREVIEWS
        _PREVIEWS.set_budget(option(st, 'perf/cache_vignettes'))     # mémoire des vignettes (Mo)
        from ..cam import simulate as _sim
        _sim.SIM_CACHE_BYTES = int(option(st, 'perf/cache_simulations')) * 1024 * 1024
        while _sim._SIM_CACHE and sum(x.H.nbytes for x in _sim._SIM_CACHE.values()) > _sim.SIM_CACHE_BYTES:
            _sim._SIM_CACHE.pop(next(iter(_sim._SIM_CACHE)))
        cp = getattr(self, 'cam_panel', None)
        if cp is not None:                               # post-processeur choisi dans les Options
            cp._fill_posts()
            cp.set_post(option(st, 'fao/post'))
            cp.refresh()
        self.apply_cam_opacity()
        self._snap_status()
        self._apply_ribbon_options()

    def apply_cam_opacity(self) -> float:
        """Panneaux FAO détachés : opacité des Options (le plein écran
        translucide garde la sienne) ; rend l'opacité appliquée."""
        from .options import value
        v = max(0.4, min(1.0, value(self.settings, 'fao/opacite') / 100.0))
        ovs = getattr(self, 'overlays', {}) or {}
        for d in (getattr(self, 'dock_cam', None), getattr(self, 'dock_paths', None)):
            if d is None or any(o.dock is d and o.active for o in ovs.values()):
                continue
            d.setWindowOpacity(v if d.isFloating() else 1.0)
        return v

    def options_dialog(self, exec_dialog: bool = True, page: str | None = None):
        """F10 ; `page` : onglet ouvert (bouton de l'onglet Options du ruban)."""
        from .options import OptionsDialog, value
        dlg = OptionsDialog(self.settings, self, page=page)
        if not exec_dialog:
            return dlg
        from .options import APPEARANCE
        before = {k: value(self.settings, k) for k in APPEARANCE}
        gpu_before = value(self.settings, 'affichage/gpu')
        if dlg.exec():
            self.apply_options()
            if value(self.settings, 'affichage/gpu') != gpu_before:
                self.apply_gpu(value(self.settings, 'affichage/gpu'))
            if {k: value(self.settings, k) for k in APPEARANCE} != before:
                self.set_theme(value(self.settings, 'vue/theme'))
            self.canvas.update()
        return dlg

    def apply_gpu(self, choice: str) -> bool:
        """Carte graphique de la vue 3D (gpu) posée dans le réglage Graphismes
        de Windows ; effet au prochain démarrage."""
        from .. import gpu
        try:
            gpu.apply(choice)
        except OSError as ex:
            QMessageBox.warning(self, tr('Carte graphique de la vue 3D'), str(ex))
            return False
        self.statusBar().showMessage(tr('Carte graphique de la vue 3D : choix pris en compte au prochain démarrage.'),
                                     8000)
        return True

    def _startup_view(self) -> None:
        """État d'affichage au démarrage (options F10)."""
        from .options import value
        st = self.settings
        for key, act in (('vue/grille_visible', 'grid'), ('vue/sens', 'direction'), ('vue/remplissage', 'fill')):
            if value(st, key) and not self.A[act].isChecked():
                self.A[act].setChecked(True)
        self.A['origin_visible'].setChecked(st.value('vue/origine', True) not in (False, 'false'))
        self._typeart_sync()
        if value(st, 'options/ouvrir_dernier'):
            recent = [p for p in self._recent() if pathlib.Path(p).exists()]
            if recent:
                QTimer.singleShot(0, lambda: self.session_dir is None and self.open_path(recent[0]))

    def duplicate_dialog(self) -> None:
        from .dialogs import DuplicateDialog
        sel = self.canvas.selection
        bb = self.canvas.selection_bbox()
        if not sel or not bb:
            QMessageBox.information(self, tr('Dupliquer'), tr('Sélectionnez au moins un objet.'))
            return
        pl = self.canvas.doc.plate
        pc = (pl.x + pl.width / 2, pl.y + pl.height / 2) if pl else None
        dlg = DuplicateDialog(self, center=((bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2),
                              plate_center=pc, settings=self.settings)
        if dlg.exec():
            self.duplicate(dlg.values())

    def duplicate_scaled_dialog(self, exec_dialog: bool = True, count: int | None = None, rotate: bool = True,
                                equidistant: bool = False) -> list:
        """Duplication homothétique sur une courbe (TypeEdit) : sélection =
        objet de départ, objet de fin, puis la courbe ; rend les copies."""
        from dataclasses import dataclass

        from ..core import duplicate as D
        sel = list(self.canvas.selection)
        curve = sel[-1] if sel else None
        if len(sel) != 3 or not isinstance(curve, Shape) or not curve.path.contours:
            QMessageBox.information(self, tr('Duplication homothétique'),
                                    tr('Sélectionnez l\'objet de départ, l\'objet de fin, puis la courbe.'))
            return []

        @dataclass
        class P:
            count: int = 5
            rotate: bool = True
            equidistant: bool = False
        p = P(int(self.settings.value('dup_homot/n', 5)) if count is None else count, rotate, equidistant)
        if exec_dialog:
            from .dialogs import ParamsDialog
            p.rotate = self.settings.value('dup_homot/rotation', 'true') in (True, 'true')
            p.equidistant = self.settings.value('dup_homot/equidistant', 'false') in (True, 'true')
            dlg = ParamsDialog(self, tr('Duplication homothétique'), p, {
                'count': tr('Nombre de copies'), 'rotate': tr('Orienter selon la courbe'),
                'equidistant': tr('Copies équidistantes (écart constant entre les copies)')})
            if not dlg.exec():
                return []
            p = dlg.result_params()
            self.settings.setValue('dup_homot/n', p.count)
            self.settings.setValue('dup_homot/rotation', p.rotate)
            self.settings.setValue('dup_homot/equidistant', p.equidistant)
        doc = self.canvas.doc
        new = D.scaled_along(sel[0], sel[1], curve.path.contours[0], max(1, int(p.count)), rotate=p.rotate,
                             equidistant=p.equidistant)
        if not new:
            return []
        home = doc.layer_of(sel[0])
        self.push_undo()
        for c in new:
            doc.add(c, home)
        self.canvas.invalidate()
        self.canvas.select(new)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} copie(s) créée(s)').format(len(new)), 3000)
        return new

    def _array_tool(self, mode: str, cols: int, rows: int = 1, rotate: bool = True):
        from . import tools as T
        self.canvas.tool = 'pick_point'
        self.canvas.snap.clear_tracking()
        self.canvas.tool_obj = T.ArrayDragTool(self.canvas, mode, cols, rows, rotate)
        self.canvas.setCursor(self.canvas.tool_obj.cursor)
        return self.canvas.tool_obj

    def _has_selection_to_copy(self, title: str) -> bool:
        if self.canvas.selection:
            return True
        QMessageBox.information(self, title, tr('Sélectionnez d\'abord les objets à dupliquer'))
        return False

    def dup_linear(self, params: dict | None = None):
        """Duplication linéaire (TypeEdit) : colonnes et rangées, original compris, puis le geste. Rend l'outil."""
        if not self._has_selection_to_copy(tr('Duplication linéaire')):
            return None
        p = self._ask('dup_lineaire', tr('Duplication linéaire'),
                      [('cols', int, 3, tr('Colonnes')), ('rows', int, 1, tr('Rangées'))], params=params)
        if p is None:
            return None
        return self._array_tool('linear', int(p['cols']), int(p['rows']))

    def dup_circular(self, params: dict | None = None):
        """Duplication circulaire (TypeEdit) : le nombre d'exemplaires, original compris, puis le geste. Rend l'outil."""
        if not self._has_selection_to_copy(tr('Duplication circulaire')):
            return None
        p = self._ask('dup_circulaire', tr('Duplication circulaire'),
                      [('count', int, 6, tr('Exemplaires (original compris)')), ('rotate', bool, True, tr('Rotation'))],
                      params=params)
        if p is None:
            return None
        return self._array_tool('circular', max(2, int(p['count'])), 1, bool(p['rotate']))

    def array_dialog(self, tool, params: dict | None = None) -> list:
        """F2 pendant une duplication linéaire ou circulaire : les réglages en chiffres ; rend les copies."""
        a, b = tool.down, tool.hover
        if tool.mode == 'circular':
            cx, cy = b if b is not None else tool.center
            if params is None:
                self.settings.setValue('cad/dup_circulaire_f2', {'count': tool.cols, 'rotate': tool.rotate, 'angle': 360.0,
                                                                 'x': cx, 'y': cy})
            p = self._ask('dup_circulaire_f2', tr('Duplication circulaire'),
                          [('count', int, tool.cols, tr('Exemplaires (original compris)')),
                           ('angle', float, 360.0, tr('Angle total (°)')),
                           ('x', float, cx, tr('Centre X (mm)')), ('y', float, cy, tr('Centre Y (mm)')),
                           ('rotate', bool, tool.rotate, tr('Rotation'))], params=params)
            if p is None:
                return []
            v = {'mode': 'circular', 'ci_n': int(p['count']), 'center': (float(p['x']), float(p['y'])),
                 'ci_angle': float(p['angle']), 'rotate': bool(p['rotate'])}
        else:
            sx, sy = tool.steps(a, b) if a is not None and b is not None else (10.0, 10.0)
            if params is None:
                self.settings.setValue('cad/dup_lineaire_f2', {'cols': tool.cols, 'rows': tool.rows, 'dx': sx, 'dy': sy,
                                                               'ox': 0.0, 'oy': 0.0})
            p = self._ask('dup_lineaire_f2', tr('Duplication linéaire'),
                          [('cols', int, tool.cols, tr('Colonnes')), ('rows', int, tool.rows, tr('Rangées')),
                           ('dx', float, sx, tr('Delta X, entre deux colonnes (mm)')),
                           ('dy', float, sy, tr('Delta Y, entre deux rangées (mm)')),
                           ('ox', float, 0.0, tr('Offset X de chaque rangée (mm)')),
                           ('oy', float, 0.0, tr('Offset Y de chaque colonne (mm)'))], params=params)
            if p is None:
                return []
            v = {'mode': 'grid', 'gr_cols': max(1, int(p['cols'])), 'gr_rows': max(1, int(p['rows'])),
                 'gr_dx': float(p['dx']), 'gr_dy': float(p['dy']), 'gr_ox': float(p['ox']), 'gr_oy': float(p['oy'])}
        tool.cancel()
        new = self.duplicate(v)
        self.canvas.toolFinished.emit()
        return new

    def free_copy_dialog(self, tool, params: dict | None = None) -> None:
        """F2 en Duplication libre : où va le point saisi, ou le centre de la sélection, en chiffres."""
        grip = tool.grip()
        if grip is None:
            return
        at = tool.hover if tool.hover is not None else grip
        if params is None:
            self.settings.setValue('cad/dup_libre_f2', {'x': at[0], 'y': at[1]})
        p = self._ask('dup_libre_f2', tr('Duplication libre'),
                      [('x', float, at[0], tr('Position X (mm)')), ('y', float, at[1], tr('Position Y (mm)'))], params=params)
        tool.cancel()
        if p is not None:
            tool.place((float(p['x']), float(p['y'])), grip)

    def interpolate_dialog(self, params: dict | None = None) -> list:
        """Interpoler entre deux objets (Inkscape) : les formes de passage, placées entre les deux ; rend les objets créés."""
        from ..core.morph import interpolate
        sel = list(self.canvas.selection)
        if len(sel) != 2 or not all(isinstance(x, Shape) for x in sel) \
                or len(sel[0].path.contours) != len(sel[1].path.contours):
            QMessageBox.information(self, tr('Interpoler entre deux objets'),
                                    tr('Sélectionnez deux formes de même nombre de contours.'))
            return []
        p = self._ask('interpoler', tr('Interpoler entre deux objets'), [('steps', int, 5, tr('Formes de passage'))], params=params)
        if p is None:
            return []
        n = max(1, int(p['steps']))
        a, b = sel
        new = []
        for k in range(n):
            c = a.clone()
            c.path = interpolate(a.path, b.path, (k + 1) / (n + 1))
            new.append(c)
        self.push_undo()
        layer = self.canvas.doc.layer_of(a) or self.canvas.doc.active_layer
        at = next((i for i, it in enumerate(layer.items) if it is a), len(layer.items) - 1) + 1
        layer.items[at:at] = new
        self.canvas.invalidate()
        self.canvas.select(new)
        self._on_doc_changed()
        return new

    def duplicate(self, v: dict) -> list:
        """Duplique la sélection ; chaque copie va dans le calque de son original."""
        from ..core import duplicate as D
        sel = list(self.canvas.selection)
        doc = self.canvas.doc
        if v['mode'] == 'along':
            curve = sel[-1] if sel else None
            if len(sel) < 2 or not isinstance(curve, Shape) or not curve.path.contours:
                QMessageBox.information(self, tr('Dupliquer'),
                                        tr('Sélectionnez les objets puis, en dernier, la courbe.'))
                return []
            objs = sel[:-1]
            kind = v.get('al_kind', 'along')
            if kind == 'morph' and not (len(objs) == 2 and all(isinstance(x, Shape) for x in objs)
                                        and len(objs[0].path.contours) == len(objs[1].path.contours)):
                QMessageBox.information(self, tr('Dupliquer'), tr('Par déformation : sélectionnez deux formes de même nombre de '
                                                                  'contours, puis la courbe.'))
                return []
            origin = None
            if kind == 'follow':
                from ..core import forms
                marks = [x for x in objs if isinstance(x, Shape) and getattr(forms.spec_of(x), 'kind', '') == 'marker']
                rest = [x for x in objs if not any(x is k for k in marks)]
                if marks and rest:
                    bb = marks[0].bbox()
                    origin, objs = ((bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2), rest
            try:
                new_all = []
                for contour in curve.path.contours:             # plusieurs courbes combinées : sur chacune
                    if kind == 'morph':
                        new_all += D.morph_along(objs[0], objs[1], contour, v['al_n'], rotate=v['al_rot'])
                    elif kind == 'follow':
                        new_all += D.following(objs, contour, v['al_n'], rotate=v['al_rot'], spacing=v.get('al_sp', 0.0),
                                               origin=origin)
                    else:
                        new_all += D.along(objs, contour, v['al_n'], rotate=v['al_rot'], spacing=v.get('al_sp', 0.0))
            except ValueError:
                QMessageBox.information(self, tr('Dupliquer'), tr('Écart trop petit pour la longueur de la courbe '
                                                                  '(plus de {0} copies).').format(D.ALONG_MAX))
                return []
            if not new_all:
                return []
            home = doc.layer_of(objs[0])
            self.push_undo()
            for c in new_all:
                doc.add(c, home)
            self.canvas.invalidate()
            self.canvas.select(new_all)
            self._on_doc_changed()
            self.statusBar().showMessage(tr('{0} copie(s) créée(s)').format(len(new_all)), 3000)
            return new_all
        homes = [doc.layer_of(it) for it in sel]
        new_all = []
        self.push_undo()
        for it, home in zip(sel, homes):
            if v['mode'] == 'linear':
                new = D.linear([it], v['lin_n'], v['lin_dx'], v['lin_dy'])
            elif v['mode'] == 'grid':
                new = D.grid([it], v['gr_cols'], v['gr_rows'], v['gr_dx'], v['gr_dy'], v.get('gr_ox', 0.0), v.get('gr_oy', 0.0))
            else:
                new = D.circular([it], v['ci_n'], v['center'], v['ci_angle'], rotate=v['rotate'])
            for c in new:
                doc.add(c, home)
            new_all.extend(new)
        if not new_all:
            self._undo.pop()
            return []
        self.canvas.invalidate()
        self.canvas.select(sel + new_all)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} copie(s) créée(s)').format(len(new_all)), 3000)
        return new_all

    def selection_area(self) -> tuple[int, float]:
        """(nombre de contours fermés, surface en mm²) de la sélection ; les
        trous sont déduits à l'intérieur de chaque objet (pair-impair)."""
        from ..core import pathops
        n, total = 0, 0.0
        for leaf in _leaves(self.canvas.selection):
            p = item_path(leaf)
            if not p:
                continue
            closed = geom.Path([c for c in p.contours if c.closed])
            if closed.contours:
                n += len(closed.contours)
                total += abs(pathops.area(closed))
        return n, total

    def show_area(self) -> None:
        n, total = self.selection_area()
        if not n:
            QMessageBox.information(self, tr('Surface'), tr('Sélectionnez au moins un contour fermé.'))
            return
        QMessageBox.information(self, tr('Surface'), tr('{0} contour(s) fermé(s)\nSurface : {1:.3f} mm²').format(n, total))

    def selection_filter(self, show: bool | None = None):
        """Ouvre ou ferme la fenêtre du filtre de sélection (F9) ; rend la fenêtre."""
        dlg = getattr(self, '_selfilter', None)
        if dlg is None:
            from .selfilter_dialog import SelectionFilterDialog
            dlg = self._selfilter = SelectionFilterDialog(self)
            dlg.closed.connect(lambda: self._check_quietly('select_filter', False))
        want = (not dlg.isVisible()) if show is None else show
        if want:
            dlg.show()
            dlg.raise_()
        else:
            dlg.hide()
        self._check_quietly('select_filter', want)
        return dlg

    def selection_modes(self, show: bool | None = None):
        """Ouvre ou ferme la fenêtre des modes de sélection ; rend la fenêtre."""
        dlg = getattr(self, '_selmodes', None)
        if dlg is None:
            from .selmodes_dialog import SelectionModesDialog
            dlg = self._selmodes = SelectionModesDialog(self)
        want = (not dlg.isVisible()) if show is None else show
        if want:
            dlg.show()
            dlg.raise_()
        else:
            dlg.hide()
        self._check_quietly('selection_modes', want)
        return dlg

    def group_reverse(self) -> int:
        """Inverse l'ordre des objets dans les groupes sélectionnés, sous-groupes compris, et des contours dans les objets
        combinés ; rend le nombre de groupes et d'objets inversés."""
        groups = [it for it in self.canvas.selection if isinstance(it, Group)]
        combined = [it for it in self.canvas.selection if isinstance(it, Shape) and len(it.path.contours) > 1]
        if not groups and not combined:
            self.statusBar().showMessage(tr('Sélectionnez un ou plusieurs groupes ou objets combinés.'), 4000)
            return 0
        self.push_undo(tr('Inverser l’ordre dans les groupes'))
        count = 0

        def walk(g: Group) -> None:
            nonlocal count
            g.children.reverse()
            count += 1
            for ch in g.children:
                if isinstance(ch, Group):
                    walk(ch)
        for g in groups:
            walk(g)
        for s in combined:
            s.path = geom.Path(list(reversed(s.path.contours)))
            count += 1
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} groupe(s) inversé(s).').format(count), 5000)
        return count

    def view_light(self, params: dict | None = None):
        """Direction de la lumière de la vue 3D, gardée d'une session à l'autre ; rend les valeurs retenues."""
        from . import view3d as V3
        params = self._ask('view_light', tr('Éclairage'), [
            ('azimuth', float, V3.LIGHT['azimuth'], tr('Direction, depuis l’axe de la vue (°)')),
            ('elevation', float, V3.LIGHT['elevation'], tr('Hauteur au-dessus du plan (°, jusqu’à 85)'))], params=params)
        if params is None:
            return None
        V3.LIGHT.update(azimuth=float(params['azimuth']) % 360.0, elevation=min(85.0, max(0.0, float(params['elevation']))))
        self.settings.setValue('vue3d/lumiere', [V3.LIGHT['azimuth'], V3.LIGHT['elevation']])
        for view in self.findChildren(V3.View3D):
            view.update()
        return dict(V3.LIGHT)

    def _restore_light(self) -> None:
        from . import view3d as V3
        got = self.settings.value('vue3d/lumiere', None)
        try:
            V3.LIGHT.update(azimuth=float(got[0]) % 360.0, elevation=min(85.0, max(0.0, float(got[1]))))
        except (TypeError, ValueError, IndexError):      # jamais réglé, ou valeur abîmée : la lumière d'origine
            V3.LIGHT.update(V3.LIGHT_DEFAULT)

    def sort_selection(self, mode: str, *, from_right: bool = False, from_bottom: bool = False) -> int:
        """Classe les objets sélectionnés (ordre du dessin, donc de l'usinage) ; rend le nombre d'objets déplacés. Sans
        sélection, le classement attend le rectangle suivant, dont le premier point donne le coin de départ."""
        from ..core import selsort as SS
        sel = list(self.canvas.selection)
        if not sel and mode != 'inverse':
            self.canvas.sort_armed = mode
            self.statusBar().showMessage(tr('Tracez le rectangle de sélection : son premier point est le départ du classement'),
                                         6000)
            return 0
        if len(sel) < 2:
            self.statusBar().showMessage(tr('Sélectionnez au moins deux objets à classer.'), 4000)
            return 0
        ordered = SS.sort(sel, mode, from_right=from_right, from_bottom=from_bottom)
        self.push_undo(tr('Classement de la sélection'))
        moved = SS.apply_order(self.canvas.doc, ordered)
        self.canvas.selection = ordered
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} objet(s) classé(s) : {1}').format(len(ordered), tr(SS.SORTS[mode])), 4000)
        return moved

    def _check_quietly(self, key: str, on: bool) -> None:
        """Coche une action cochable sans relancer sa commande."""
        a = self.A[key]
        a.blockSignals(True)
        a.setChecked(on)
        a.blockSignals(False)

    def _node_entered(self, on: bool) -> None:
        """Le Mode Point vient d'être pris : le « triggered » qui suit (même
        appui) ne doit pas l'enlever. Marque effacée au tour suivant (une
        entrée par programme n'est pas suivie d'un « triggered »)."""
        if on:
            self._node_just_entered = True
            QTimer.singleShot(0, lambda: setattr(self, '_node_just_entered', False))

    def _toggle_node_mode(self, _checked: bool = False) -> None:
        if getattr(self, '_node_just_entered', False):
            self._node_just_entered = False
            return
        if self.canvas.tool == 'node':
            self.set_tool('select')

