    def texture_shapes(self, kind: str = 'hilbert', iterations: int = 4, border: bool = False) -> list:
        """Texture (TypeEdit) sur chaque objet sélectionné à contours fermés ;
        rend les nouvelles formes (une par objet, couleur de l'objet)."""
        from ..core.texture import texture
        new = []
        for it in self.canvas.selection:
            leaves = [x for x in _leaves([it]) if isinstance(x, (Shape, Text))]
            contours = [c for x in leaves for c in ((x.path if isinstance(x, Shape) else x.outline).contours
                                                     if (x.path if isinstance(x, Shape) else x.outline) else [])]
            p = texture(geom.Path(contours), kind, iterations, border)
            if p.contours:
                new.append(Shape(path=p, tool=it.tool, name=tr('Texture')))
        if not new:
            QMessageBox.information(self, tr('Texture'), tr('Sélectionnez des contours fermés ou des textes.'))
            return []
        self._add_items(new)
        return new

    def texture_create(self, pattern: str | None = None, width: float = 3.0, symmetry: str = 'auto',
                       angle: float = 0.0, border: bool = False) -> list:
        """Création de texture (TypeEdit) : un motif (modèle, ou les traits
        ouverts sélectionnés) répété par symétrie dans chaque objet à contours
        fermés de la sélection, coupé à lui ; rend les nouvelles formes."""
        from ..core import pathops
        from ..core import patterns as PT
        if pattern is None:
            from dataclasses import dataclass
            from .dialogs import ParamsDialog

            @dataclass
            class P:
                pattern: str = str(self.settings.value('texture2/motif', 'chevrons'))
                width: float = float(self.settings.value('texture2/case', 3.0))
                symmetry: str = 'auto'
                angle: float = 0.0
                border: bool = False
            choices = {'pattern': [('selection', tr('Traits sélectionnés'))] +
                       [(k, tr(v[0])) for k, v in PT.PRESETS.items()],
                       'symmetry': [('auto', tr('Celle du modèle'))] + [(k, tr(v)) for k, v in PT.SYMMETRIES]}
            dlg = ParamsDialog(self, tr('Création de texture'), P(), {
                'pattern': tr('Motif'), 'width': tr('Largeur de la case (mm)'), 'symmetry': tr('Symétrie'),
                'angle': tr('Angle (°)'), 'border': tr('Avec les bords (garder les contours)')}, choices=choices)
            if not dlg.exec():
                return []
            p = dlg.result_params()
            self.settings.setValue('texture2/motif', p.pattern)
            self.settings.setValue('texture2/case', p.width)
            pattern, width, symmetry, angle, border = p.pattern, p.width, p.symmetry, p.angle, p.border
        leaves = [x for x in _leaves(self.canvas.selection) if isinstance(x, (Shape, Text))]

        def contours(x):
            path = x.path if isinstance(x, Shape) else x.outline
            return path.contours if path else []
        if pattern == 'selection':
            opened = [c.flatten(0.01) for x in leaves for c in contours(x) if not c.closed and c.segments]
            opened = [pl for pl in opened if len(pl) >= 2]
            if not opened:
                QMessageBox.information(self, tr('Création de texture'),
                                        tr('Dessinez le motif en traits ouverts et sélectionnez-le avec les contours.'))
                return []
            motif, cell = PT.motif_of(opened)
            sym = 'translation' if symmetry == 'auto' else symmetry
        else:
            motif, cell, advised = PT.preset_motif(pattern, max(0.05, width))
            sym = advised if symmetry == 'auto' else symmetry
        new = []
        try:
            for x in leaves:
                closed = geom.Path([c for c in contours(x) if c.closed and c.segments])
                if not closed.contours:
                    continue
                region = pathops._to_shapely(pathops.normalize(closed))
                p = PT.tile(region, motif, cell, sym, angle)
                if border:
                    p = geom.Path(p.contours + closed.contours)
                if p.contours:
                    new.append(Shape(path=p, tool=x.tool, name=tr('Texture')))
        except ValueError:
            QMessageBox.warning(self, tr('Création de texture'), tr('Case trop petite pour cette surface.'))
            return []
        if not new:
            QMessageBox.information(self, tr('Création de texture'), tr('Sélectionnez des contours fermés ou des textes.'))
            return []
        self._add_items(new)
        return new

    def texture_dialog(self) -> list:
        from dataclasses import dataclass

        from ..core.texture import CURVES
        from .dialogs import ParamsDialog

        @dataclass
        class P:
            kind: str = 'hilbert'
            iterations: int = 4
            border: bool = False
        p = P(str(self.settings.value('texture/courbe', 'hilbert')), int(self.settings.value('texture/iterations', 4)))
        dlg = ParamsDialog(self, tr('Texture'), p, {'kind': tr('Courbe'), 'iterations': tr('Itérations (finesse)'),
                                                    'border': tr('Avec les bords (garder les contours)')},
                           choices={'kind': [(k, tr(v[0])) for k, v in CURVES.items()]})
        if not dlg.exec():
            return []
        p = dlg.result_params()
        self.settings.setValue('texture/courbe', p.kind)
        self.settings.setValue('texture/iterations', p.iterations)
        return self.texture_shapes(p.kind, p.iterations, p.border)

    def revolution_dialog(self) -> list:
        from dataclasses import dataclass

        from .dialogs import ParamsDialog

        @dataclass
        class P:
            count: int = 6
            clockwise: bool = True
        p = P(int(self.settings.value('symetrie/copies', 6)))
        dlg = ParamsDialog(self, tr('Courbe de révolution'), p, {'count': tr('Nombre de répétitions'),
                                                                  'clockwise': tr('Dans le sens horaire')})
        if not dlg.exec():
            return []
        p = dlg.result_params()
        return self.revolution(max(1, p.count), p.clockwise)

    def _retext(self, changes: list) -> None:
        """Applique [(texte, nouvelle chaîne)] : remis en page à la même place."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        if not changes:
            return
        self.push_undo()
        for t, s in changes:
            t.text = s
            t.outline = TX.outline_for(t)
            drop_source_object(t)
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()

    def toggle_vertical_text(self) -> int:
        """Texte vertical (lettres les unes sous les autres, centrées) ou
        retour au texte d'origine."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        texts = [t for t in _leaves(self.canvas.selection) if isinstance(t, Text)]
        if not texts:
            QMessageBox.information(self, tr('Texte vertical'), tr('Sélectionnez des textes.'))
            return 0
        self.push_undo()
        for t in texts:
            v = t.extra.get('vertical')
            if v:
                t.text, t.align = v['text'], v['align']
                t.extra.pop('vertical')
            else:
                t.extra['vertical'] = {'text': t.text, 'align': t.align}
                t.text = '\n'.join(ch for ch in t.text.replace('\n', ' '))
                t.align = 'center'
            t.outline = TX.outline_for(t)
            drop_source_object(t)
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()
        return len(texts)

    def tangents(self, kind: str = 'externes') -> list:
        """Tangentes (ou enveloppe) aux deux cercles de la sélection."""
        from ..core.shapes import belt, circle_tangents, fit_circle
        circles = []
        for s in _leaves(self.canvas.selection):
            if isinstance(s, Shape):
                for c in s.path.contours:
                    f = fit_circle(c, 0.02)
                    if f:
                        circles.append((f[0], f[1]))
        if len(circles) != 2:
            QMessageBox.information(self, tr('Tangentes'), tr('Sélectionnez exactement deux cercles.'))
            return []
        (c1, r1), (c2, r2) = circles
        if kind == 'enveloppe':
            b = belt(c1, r1, c2, r2)
            contours = [b] if b is not None else []
        else:
            contours = circle_tangents(c1, r1, c2, r2, kind)
        if not contours:
            QMessageBox.information(self, tr('Tangentes'), tr('Aucune tangente possible pour ces cercles.'))
            return []
        tool = self.canvas.selection[0].tool
        new = [Shape(path=geom.Path([c]), tool=tool) for c in contours]
        self._add_items(new)
        return new

    def _two_circles(self) -> list:
        from ..core.shapes import fit_circle
        circles = []
        for s in _leaves(self.canvas.selection):
            if isinstance(s, Shape):
                for c in s.path.contours:
                    f = fit_circle(c, 0.02)
                    if f:
                        circles.append((f[0], f[1]))
        return circles

    def tangent_arc(self, radius: float, enclosing: bool = False) -> list:
        """Arcs de rayon `radius` tangents aux deux cercles de la sélection."""
        from ..core.shapes import tangent_arcs
        circles = self._two_circles()
        if len(circles) != 2:
            QMessageBox.information(self, tr('Arc tangent'), tr('Sélectionnez exactement deux cercles.'))
            return []
        (c1, r1), (c2, r2) = circles
        contours = tangent_arcs(c1, r1, c2, r2, radius, enclosing)
        if not contours:
            QMessageBox.information(self, tr('Arc tangent'),
                                    tr('Aucun arc de ce rayon ne touche les deux cercles.'))
            return []
        tool = self.canvas.selection[0].tool
        new = [Shape(path=geom.Path([c]), tool=tool) for c in contours]
        self._add_items(new)
        return new

    def tangent_arc_dialog(self) -> list:
        from PySide6.QtWidgets import QInputDialog
        r, ok = QInputDialog.getDouble(self, tr('Arc tangent'), tr('Rayon de l\'arc (mm)'),
                                       float(self.settings.value('arc_tangent/rayon', 5.0)), 0.001, 100000.0, 3)
        if not ok:
            return []
        kinds = [tr('À l\'extérieur des deux cercles (congé)'), tr('Englobant les deux cercles')]
        kind, ok = QInputDialog.getItem(self, tr('Arc tangent'), tr('Raccord'), kinds, 0, False)
        if not ok:
            return []
        self.settings.setValue('arc_tangent/rayon', r)
        return self.tangent_arc(r, enclosing=kinds.index(kind) == 1)

    def tangents_dialog(self) -> None:
        from PySide6.QtWidgets import QInputDialog
        kinds = [('externes', tr('Tangentes externes')), ('internes', tr('Tangentes internes (croisées)')),
                 ('toutes', tr('Toutes les tangentes')), ('enveloppe', tr('Enveloppe (courroie, oblong)'))]
        label, ok = QInputDialog.getItem(self, tr('Tangentes'), tr('Tracer'), [k[1] for k in kinds], 0, False)
        if ok:
            self.tangents(next(k for k, lab in kinds if lab == label))

    def change_text_case(self, mode: str) -> int:
        from ..core.textops import change_case
        m = {'upper': 'majuscules', 'lower': 'minuscules', 'words': 'mots'}[mode]
        changes = [(t, change_case(t.text, m)) for t in self._texts()]
        changes = [(t, s) for t, s in changes if s != t.text]
        for t, _s in changes:                            # pour la casse initiale ; retouché depuis, le texte repart de là
            src = t.extra.get('case_source')
            if not (isinstance(src, str) and src.lower() == t.text.lower()):
                t.extra['case_source'] = t.text
        self._retext(changes)
        self.statusBar().showMessage(tr('{0} texte(s) modifié(s)').format(len(changes)), 5000)
        return len(changes)

    def restore_text_case(self) -> int:
        """La casse d'avant les changements de casse, petites majuscules comprises. Un texte retouché depuis garde ses lettres."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        todo = []
        for t in self._texts():
            src = t.extra.get('case_source')
            back = isinstance(src, str) and src != t.text and src.lower() == t.text.lower()
            if back or t.extra.get('small_caps'):
                todo.append((t, src if back else t.text))
        if todo:
            self.push_undo(tr('Casse initiale'))
            for t, s in todo:
                t.text = s
                t.extra.pop('case_source', None)
                t.extra.pop('small_caps', None)
                t.outline = TX.outline_for(t)
                drop_source_object(t)
            self.canvas.invalidate()
            self._on_selection()
            self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} texte(s) modifié(s)').format(len(todo)), 5000)
        return len(todo)

    def merge_texts(self):
        """Textes choisis (du premier niveau) réunis en un texte de plusieurs
        lignes (`core.textmerge`), au rang du premier d'entre eux ; annulable."""
        from ..core import text as TX
        from ..core import textmerge as TM
        sel = [t for t in self.canvas.selection if TM.mergeable(t)]
        out = TM.merge(sel)
        if out is None:
            QMessageBox.information(self, tr('Réunir les textes'), tr(
                'Sélectionnez au moins deux textes (ni sur courbe, ni en arc, ni dans un cadre).'))
            return None
        out.outline = TX.outline_for(out)
        self.push_undo()
        ids = {id(t) for t in sel}
        target, index = None, None
        for L in self.canvas.doc.layers:
            for i, it in enumerate(L.items):
                if id(it) in ids and target is None:
                    target, index = L, i
            L.items = [it for it in L.items if id(it) not in ids]
        target = target or self.canvas.doc.active_layer
        target.items.insert(min(index or 0, len(target.items)), out)
        self.canvas.invalidate()
        self.canvas.select([out])
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} textes réunis : {1} ligne(s)').format(
            len(sel), out.text.count('\n') + 1), 6000)
        return out

    def text_typographic(self) -> int:
        """Ponctuation typographique des textes choisis (sinon de tous) ;
        rend le nombre de textes changés."""
        from ..core.textops import typographic
        changes = [(t, typographic(t.text)) for t in self._texts()]
        changes = [(t, s) for t, s in changes if s != t.text]
        self._retext(changes)
        self.statusBar().showMessage(tr('{0} texte(s) modifié(s)').format(len(changes)), 5000)
        return len(changes)

    def find_replace(self, find: str, repl: str, *, case: bool = False, whole: bool = False) -> int:
        """Remplace dans les textes de la sélection (sinon de tout le dessin) ;
        rend le nombre de remplacements."""
        from ..core.textops import find_replace
        changes, total = [], 0
        for t in self._texts():
            s, n = find_replace(t.text, find, repl, case=case, whole=whole)
            if n:
                changes.append((t, s))
                total += n
        self._retext(changes)
        self.statusBar().showMessage(tr('{0} remplacement(s) dans {1} texte(s)').format(total, len(changes)), 6000)
        return total

    def spell_language(self) -> str:
        """Langue du correcteur : le réglage F10, sinon celle du poste."""
        from PySide6.QtCore import QLocale
        return str(self.settings.value('texte/langue_orthographe', '') or '').strip() or QLocale.system().bcp47Name()

    def spell_check(self, exec_dialog: bool = True):
        """Orthographe des textes de la sélection, sinon de tout le dessin. Rend la fenêtre, None s'il n'y a rien à revoir."""
        from ..core import spell as SP
        from .spell_dialog import SpellDialog, SpellSession
        texts = self._texts()
        if not texts:
            self.statusBar().showMessage(tr('Aucun texte à relire.'), 6000)
            return None
        lang = self.spell_language()
        checker = SP.open_checker(lang) or (None if lang == 'fr-FR' else SP.open_checker('fr-FR'))
        if checker is None:
            QMessageBox.information(self, tr('Orthographe'),
                                    tr('Pas de correcteur pour « {0} » sur ce poste : ajouter la langue dans les paramètres '
                                       'de Windows, ou la choisir dans F10 › Texte.').format(lang))
            return None

        def show(t):
            self.canvas.select([t])
        session = SpellSession(texts, checker, lambda t, s: self._retext([(t, s)]), self._spell_words(),
                               self._spell_add_word)
        if session.finished():
            checker.close()
            self.statusBar().showMessage(tr('Aucune faute dans {0} texte(s).').format(len(texts)), 6000)
            return None
        dlg = SpellDialog(self, session, show)
        self.last_spell_dialog = dlg
        if not exec_dialog:
            return dlg
        dlg.exec()
        checker.close()
        self.statusBar().showMessage(tr('{0} correction(s).').format(session.replacements), 6000)
        return dlg

    def texts_in(self, scope: str) -> list:
        """Les textes de 'selection', 'layer' (le plan actif) ou 'all' (tous les plans)."""
        doc = self.canvas.doc
        pool = {'selection': self.canvas.selection, 'layer': doc.active_layer.items}.get(
            scope, [it for L in doc.layers for it in L.items])
        return [t for t in _leaves(pool) if isinstance(t, Text)]

    def find_replace_dialog(self, exec_dialog: bool = True):
        """La fenêtre Rechercher / remplacer. Rend ce qui a été changé (voir `replace_in_texts`) ; None : rien."""
        from .find_replace_dialog import FindReplaceDialog
        title = tr('Rechercher / remplacer')
        if not self._texts():
            QMessageBox.information(self, title, tr('Aucun texte.'))
            return None
        dlg = FindReplaceDialog(self, self.texts_in, bool(self.texts_in('selection')),
                                self.settings.value('texte/rechercher', '') or '')
        self.last_find_dialog = dlg
        if not exec_dialog or not dlg.exec():
            return None
        v = dlg.values()
        if v['text'] and v['find']:
            self.settings.setValue('texte/rechercher', v['find'])
        got = self.replace_in_texts(v)
        if not any(got.values()):
            if v['text'] and v['find'] and not (v['size'] or v['font'] or v['comp']):
                QMessageBox.information(self, title, tr('« {0} » introuvable.').format(v['find']))
            else:
                QMessageBox.information(self, title, tr('Rien à changer.'))
        return got

    def replace_in_texts(self, p: dict) -> dict:
        """Ce que demande `p` (voir `FindReplaceDialog.values`), annulable d'un coup. Rend les nombres de changements :
        'text' (remplacements), 'size', 'font', 'comp' (textes)."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        from ..core.textops import find_replace
        got = {'text': 0, 'size': 0, 'font': 0, 'comp': 0}
        plan = []
        for t in self.texts_in(p.get('scope', 'all')):
            new = {}
            if p.get('text') and p.get('find'):
                s, n = find_replace(t.text, p['find'], p.get('repl', ''), case=bool(p.get('case')), whole=bool(p.get('whole')))
                if n:
                    new['text'] = s
                    got['text'] += n
            if p.get('size') and float(p.get('new_size', 0.0)) > 0.0:
                size = float(p['new_size'])
                wanted = p.get('all_sizes') or (p.get('old_size') is not None and abs(t.size - float(p['old_size'])) < 5e-4)
                if wanted and abs(t.size - size) >= 5e-4:
                    new['size'] = size
                    got['size'] += 1
            if p.get('font') and p.get('new_font'):
                fx = TX.char_fx(t)
                inner = any(f.get('font') == p.get('old_font') or (p.get('all_fonts') and 'font' in f) for f in fx.values())
                if (t.font != p['new_font'] and (p.get('all_fonts') or t.font == p.get('old_font'))) or inner:
                    new['font'] = p['new_font']
                    got['font'] += 1
            if p.get('comp') and float(p.get('ratio', 0.0)) > 0.0:
                ratio = float(p['ratio']) / 100.0
                if abs(t.width_ratio - ratio) >= 5e-4 or 'fit' in t.extra:
                    new['comp'] = ratio
                    got['comp'] += 1
            if new:
                plan.append((t, new))
        if not plan:
            return got
        self.push_undo(tr('Rechercher / remplacer'))
        for t, new in plan:
            if 'text' in new:
                t.text = new['text']
            if 'size' in new:
                t.size = new['size']
            if 'font' in new:
                fx = TX.char_fx(t)
                if p.get('all_fonts') or t.font == p.get('old_font'):
                    if 'vnd_obj' in t.extra:
                        t.spacing = 0.0                  # interlettrage calé sur l'ancienne police
                    if not p.get('all_fonts') or t.font != new['font']:
                        t.font = new['font']
                keep = {}
                for i, f in fx.items():
                    f = dict(f)
                    if 'font' in f and (p.get('all_fonts') or f['font'] == p.get('old_font')):
                        del f['font']
                        if not p.get('all_fonts') and t.font != new['font']:
                            f['font'] = new['font']
                    keep[i] = f
                TX.set_char_fx(t, keep)
            if 'comp' in new:
                t.extra.pop('fit', None)                 # une largeur imposée reprendrait la main
                t.width_ratio = new['comp']
            t.outline = TX.outline_for(t)
            drop_source_object(t)
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} remplacement(s), {1} taille(s), {2} police(s), {3} compression(s)').format(
            got['text'], got['size'], got['font'], got['comp']), 6000)
        return got

    def zoom_selection(self) -> None:
        bb = self.canvas.selection_bbox()
        if bb:
            self.canvas.fit(bb)

    def _toggle_origin(self, on) -> None:
        self.canvas.show_origin = bool(on)
        self.settings.setValue('vue/origine', bool(on))
        self.canvas.overlay_update()

    def _origin_changed(self) -> None:
        for r in (self.ruler_h, self.ruler_v):
            r.update()
        if getattr(self, '_pos_raw', None):              # la barre d'état : par rapport à la nouvelle origine
            self._on_snap(*self._pos_raw)
        if hasattr(self, 'dims'):
            self._selection_info()
        ox, oy = self.canvas.origin
        self.statusBar().showMessage(tr('Origine du dessin : X {0:g} ; Y {1:g} mm').format(round(ox, 3), round(oy, 3)),
                                     6000)

    def origin_to(self, where: str) -> tuple[float, float] | None:
        """Origine posée sur : 'zero' (zéro du dessin), 'plate_bl' / 'plate_tl'
        / 'plate_center' (plaque), 'selection_bl' / 'selection_center'."""
        pt = self.origin_point(where)
        if pt is not None:
            self.canvas.set_origin(*pt)
        return pt

    def origin_point(self, where: str) -> tuple[float, float] | None:
        c = self.canvas
        pt = None
        if where == 'zero':
            pt = (0.0, 0.0)
        elif where.startswith('plate') and c.doc.plate is not None:
            pl = c.doc.plate
            pt = {'plate_bl': (pl.x, pl.y), 'plate_tl': (pl.x, pl.y + pl.height),
                  'plate_center': (pl.x + pl.width / 2, pl.y + pl.height / 2)}.get(where)
        elif where.startswith('selection'):
            bb = c.selection_bbox()
            if bb:
                pt = {'selection_bl': (bb[0], bb[1]),
                      'selection_center': ((bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2)}.get(where)
        return pt

    def origin_dialog(self, values: tuple[float, float] | None = None) -> bool:
        """Placer l'origine : valeurs (mm, depuis le zéro du dessin) ou raccourcis."""
        from PySide6.QtWidgets import QDoubleSpinBox, QGridLayout, QPushButton
        from .dialogs import _buttons
        c = self.canvas
        if values is None:
            dlg = QDialog(self)
            dlg.setWindowTitle(tr('Origine du dessin'))
            form = QFormLayout(dlg)
            form.addRow(QLabel(tr('Position de l\'origine depuis le zéro du dessin (les fichiers écrits '
                                  'gardent le zéro du dessin, sauf le VND et les programmes machine : '
                                  'l\'origine y devient le zéro, comme dans TypeEdit) :')))
            spins = []
            for lab, v in (('X', c.origin[0]), ('Y', c.origin[1])):
                sb = QDoubleSpinBox()
                sb.setRange(-1e6, 1e6)
                sb.setDecimals(3)
                sb.setSuffix(' mm')
                sb.setValue(v)
                form.addRow(lab, sb)
                spins.append(sb)
            grid = QGridLayout()
            presets = [('zero', tr('Zéro du dessin'))]
            if c.doc.plate is not None:
                presets += [('plate_bl', tr('Plaque : bas gauche')), ('plate_tl', tr('Plaque : haut gauche')),
                            ('plate_center', tr('Plaque : centre'))]
            if c.selection:
                presets += [('selection_bl', tr('Sélection : bas gauche')),
                            ('selection_center', tr('Sélection : centre'))]
            for i, (key, lab) in enumerate(presets):
                b = QPushButton(lab)

                def put(k):
                    pt = self.origin_point(k)
                    if pt is not None:
                        spins[0].setValue(pt[0])
                        spins[1].setValue(pt[1])
                b.clicked.connect(lambda _=False, k=key: put(k))
                grid.addWidget(b, i // 2, i % 2)
            form.addRow(grid)
            _buttons(dlg, form)
            if not dlg.exec():
                return False
            values = (spins[0].value(), spins[1].value())
        c.set_origin(float(values[0]), float(values[1]))
        return True

    def _toggle_grid(self, on) -> None:
        self.canvas.show_grid = on
        self.canvas.update()

    def _toggle_direction(self, on) -> None:
        self.canvas.show_direction = on
        self.canvas.update()

    def _toggle_points(self, which: str, on: bool) -> None:
        """Points de départ / de contrôle affichés (gardé dans les réglages)."""
        setattr(self.canvas, 'show_starts' if which == 'starts' else 'show_nodes', bool(on))
        self.settings.setValue(f'vue/points_{which}', bool(on))
        self.canvas.update()

    def _toggle_fill(self, on) -> None:
        self.canvas.show_fill = on
        self.canvas.update()

    def _toggle_tool_colors(self, on) -> None:
        self.canvas.tool_colors = bool(on)
        self.canvas.update()

    def set_selection_color(self, color: str | None = None, ask: bool = True) -> int:
        """Édition › Couleur… : une couleur propre aux objets sélectionnés (trait et remplissage), indépendante de leur
        outil ; `ask` : la demander. `color` None sans demander : la retirer (couleur de l'outil). Rend le nombre
        d'objets changés ; un pas d'annulation."""
        from ..core.document import own_color, set_own_color
        items = list(self.canvas.selection)
        if not items:
            self.statusBar().showMessage(tr('Sélectionnez d’abord les objets à colorer'), 5000)
            return 0
        if ask:
            from PySide6.QtGui import QColor
            from PySide6.QtWidgets import QColorDialog
            first = next((lf for lf in _leaves(items)), None)
            start = QColor(own_color(first) or self.canvas.doc.item_color(first)) if first is not None \
                else QColor('#000000')
            got = QColorDialog.getColor(start, self, tr('Couleur des objets sélectionnés'))
            if not got.isValid():
                return 0
            color = got.name()
        changed = sum(1 for lf in _leaves(items) if own_color(lf) != (str(color).lower() if color else None))
        if not changed:
            return 0
        self.push_undo()
        set_own_color(items, color)
        self._on_doc_changed()
        self.canvas.invalidate()
        msg = tr('{0} objet(s) à la couleur {1}').format(changed, color) if color else \
            tr('{0} objet(s) à la couleur de leur outil').format(changed)
        if not self.canvas.tool_colors:
            msg += tr(' — couleurs cachées : Ctrl+8 les montre')
        self.statusBar().showMessage(msg, 6000)
        return changed

    # --- CAD ----------------------------------------------------------------
    def mirror(self, horizontal: bool) -> None:
        bb = self.canvas.selection_bbox()
        if not bb:
            return
        cx, cy = (bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2
        if self._ctrl_on('mirror_h' if horizontal else 'mirror_v'):
            cx, cy = bb[2], bb[1]                        # TypeEdit : l'axe sur le côté droit, ou à la base
        m = Affine.mirror_y(cx) if horizontal else Affine.mirror_x(cy)
        self.canvas.transform_selection(m)

    def _toggle_cyclic(self, on: bool) -> None:
        self.canvas.cyclic = self.cyclic_n.value() if on else 0
        if on and self.A['sym_draw'].isChecked():
            self.A['sym_draw'].setChecked(False)
        self.canvas.update()
        if on:
            cx, cy = self.canvas.symmetry_center()
            self.statusBar().showMessage(tr('Symétrie cyclique : {0} copies autour de ({1:.3f} ; {2:.3f})').format(
                self.canvas.cyclic, cx, cy), 6000)

    def _set_cyclic(self, n: int) -> None:
        self.cyclic_n.setValue(n)
        self.A['sym_cyclic'].setChecked(True)

    def _cyclic_count(self, n: int) -> None:
        self.settings.setValue('symetrie/copies', n)
        if self.canvas.cyclic:
            self.canvas.cyclic = n
            self.canvas.update()

    def _toggle_notes(self, on: bool) -> None:
        self.canvas.show_notes = bool(on)
        self.canvas.update()

    def add_note(self, text: str | None = None, at=None) -> int | None:
        """Note (post-it) au centre de la vue ; rend son indice."""
        from PySide6.QtWidgets import QInputDialog
        if text is None:
            text, ok = QInputDialog.getMultiLineText(self, tr('Note'), tr('Texte de la note'))
            if not ok or not text.strip():
                return None
        x, y = at if at is not None else self._view_center()
        self.push_undo(tr('Note'))
        notes = list(self.canvas.notes())
        notes.append({'x': float(x), 'y': float(y), 'text': text.strip()})
        self.canvas.doc.extra['notes'] = notes
        if not self.A['notes_visible'].isChecked():
            self.A['notes_visible'].setChecked(True)
        self.canvas.update()
        self._on_doc_changed()
        return len(notes) - 1

    def edit_note(self, i: int, text: str | None = None) -> None:
        """Modifier une note ; un texte vide la supprime."""
        from PySide6.QtWidgets import QInputDialog
        notes = list(self.canvas.notes())
        if not 0 <= i < len(notes):
            return
        if text is None:
            text, ok = QInputDialog.getMultiLineText(self, tr('Note'), tr('Texte de la note (vide : supprimer)'),
                                                     notes[i].get('text', ''))
            if not ok:
                return
        self.push_undo(tr('Note'))
        if text.strip():
            notes[i] = dict(notes[i], text=text.strip())
        else:
            del notes[i]
        if notes:
            self.canvas.doc.extra['notes'] = notes
        else:
            self.canvas.doc.extra.pop('notes', None)
        self.canvas.update()
        self._on_doc_changed()

    def _toggle_symmetric(self, on: bool) -> None:
        if on and self.A['sym_cyclic'].isChecked():
            self.A['sym_cyclic'].setChecked(False)
        self.canvas.symmetric = bool(on)
        self.canvas.update()
        if on:
            self.statusBar().showMessage(tr('Dessin symétrique : axe x = {0:.3f} mm').format(self.canvas.symmetry_axis()), 6000)

    def bbox_frame_quick(self):
        """[E] Cadre englobant : le rectangle de l'encombrement de la
        sélection (ou de tout le dessin), marge 0, sans fenêtre ; rend la
        forme ajoutée."""
        bb = self.canvas.selection_bbox() if self.canvas.selection else self.canvas.doc.bbox()
        if not bb:
            self.statusBar().showMessage(tr('Le dessin est vide.'), 4000)
            return None
        sh = Shape(path=geom.Path([geom.rect(bb[0], bb[1], bb[2] - bb[0], bb[3] - bb[1])]),
                   tool=self.canvas.current_tool_index)
        self._add_items([sh])
        return sh

    def bbox_frame(self) -> None:
        """Cadre englobant : rectangle à coins arrondis ou ellipse autour de
        la sélection (ou de tout le dessin), marge réglable."""
        from dataclasses import dataclass
        from .dialogs import ParamsDialog
        bb = self.canvas.selection_bbox() if self.canvas.selection else self.canvas.doc.bbox()
        if not bb:
            QMessageBox.information(self, tr('Cadre englobant'), tr('Le dessin est vide.'))
            return
        s = self.settings

        @dataclass
        class Spec:
            margin: float = float(s.value('cadre/marge', 2.0))
            radius: float = float(s.value('cadre/rayon', 0.0))
            shape: str = str(s.value('cadre/forme', 'rect'))
        spec = Spec()
        if spec.shape not in ('rect', 'ellipse'):
            spec.shape = 'rect'
        dlg = ParamsDialog(self, tr('Cadre englobant'), spec,
                           {'margin': tr('Marge (mm)'), 'radius': tr('Rayon des coins (mm)'), 'shape': tr('Forme')},
                           choices={'shape': [('rect', tr('Rectangle')), ('ellipse', tr('Ellipse'))]})
        if not dlg.exec():
            return
        v = dlg.result_params()
        for k, val in (('marge', v.margin), ('rayon', v.radius), ('forme', v.shape)):
            s.setValue(f'cadre/{k}', val)
        x0, y0, x1, y1 = bb[0] - v.margin, bb[1] - v.margin, bb[2] + v.margin, bb[3] + v.margin
        if v.shape == 'ellipse':
            # ellipse passant par les coins du cadre : demi-axes × √2
            c = geom.ellipse(((x0 + x1) / 2, (y0 + y1) / 2), (x1 - x0) / 2 * 2 ** 0.5, (y1 - y0) / 2 * 2 ** 0.5)
        else:
            c = geom.rect(x0, y0, x1 - x0, y1 - y0, max(0.0, v.radius))
        self._add_items([Shape(path=geom.Path([c]), tool=self.canvas.current_tool_index)])

    @staticmethod
    def _axis_of(item):
        """Extrémités d'un trait droit (forme d'un seul segment de droite,
        ou d'une polyligne alignée), sinon None."""
        if not isinstance(item, Shape) or len(item.path.contours) != 1:
            return None
        c = item.path.contours[0]
        if c.closed or not c.segments or not all(isinstance(s, geom.Line) for s in c.segments):
            return None
        a, b = c.start, c.end
        L = geom.dist(a, b)
        if L < 1e-9:
            return None
        for s in c.segments:
            for q in (s.p0, s.p1):
                if abs((b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0])) / L > 1e-6:
                    return None
        return a, b

    #: palettes de TypeEdit : action → (titre, commandes de VectorDrive qui y répondent)
    PALETTES = {
        'palette_shapes': ('Formes géométriques', (
            'tool_rect', 'tool_ellipse', 'tool_polygon', 'tool_star', 'tool_spiral', 'tool_line', 'tool_polyline',
            'tool_polycurve', 'tool_bezier', 'tool_arc', 'tool_circle3', 'tool_tan_circle', 'tool_marker', 'tool_axis_h', 'tool_axis_v',
            'tangent_arc')),
        'palette_effects': ('Effets spéciaux', (
            'texture', 'texture_create', 'envelope', 'envelope_curves', 'bend_path', 'shadow', 'stamp', 'hatch', 'halftone', 'double_line',
            'dash_convert', 'stroke',
            'offset', 'reverse', 'clip', 'fit_frame', 'punch', 'knife', 'revolution', 'sym_cyclic',
            'wrap_drawing_cyl', 'wrap_drawing_cone')),
        'palette_align': ('Alignement', (
            'align_left', 'align_hcenter', 'align_right', 'align_top', 'align_vcenter', 'align_bottom', 'align_center',
            'distribute_h', 'distribute_v', 'space_h', 'space_v', 'same_w', 'same_h', 'same_both', 'center_plate')),
        'palette_transform': ('Transformation', (
            'mirror_h', 'mirror_v', 'mirror_axis', 'rot90', 'rot-90', 'rot_free', 'move_by', 'duplicate',
            'duplicate_scaled', 'sym_point')),
        'palette_typeart': ('3D', ('galbe', 'typeart_sweep', 'typeart_dome', 'typeart_extrude', 'typeart_revolution',
                                        'typeart_plane', 'galbe_smooth', 'cam_new_relief', 'cam_new_finition')),
        'palette_trades': ('Métiers', (
            'stamp', 'braille', 'barcode', 'code_plate', 'dial', 'graduation', 'leds', 'shape_script', 'marquetry', 'halftone',
            'galbe', 'texture_create', 'nest', 'fill_plate')),
    }

    def show_palette(self, key: str):
        """Palette de TypeEdit : menu des commandes équivalentes, sous la
        souris (sans bloquer) ; rend le menu."""
        from PySide6.QtGui import QCursor
        from PySide6.QtWidgets import QMenu
        title, keys = self.PALETTES[key]
        old = getattr(self, '_last_palette', None)
        if old is not None:                               # la palette d'avant : libérée (une seule gardée)
            try:
                old.deleteLater()
            except RuntimeError:
                pass
        m = QMenu(tr(title), self)
        for k in keys:
            if k in self.A:
                m.addAction(self.A[k])
        self._last_palette = m
        m.popup(QCursor.pos())
        return m

    def wrap_drawing(self, kind: str = 'cylindre', spec=None) -> list:
        """Enrouler le dessin (TypeEdit, onglet CAO) : copies des objets
        sélectionnés telles qu'on les verra de dessus sur une pièce cylindrique
        ou conique couchée ; les originaux sont gardés. Rend les copies."""
        from dataclasses import dataclass
        from ..cam import wrap as WR
        shapes = [it for it in _leaves(self.canvas.selection) if isinstance(it, (Shape, Text))]
        if not shapes:
            self.statusBar().showMessage(tr('Sélectionnez le dessin à enrouler.'), 4000)
            return []
        if spec is None:
            from .dialogs import ParamsDialog

            @dataclass
            class P:
                mode: str = f'{kind}_y'
                radius: float = float(self.settings.value('enroulement/rayon', 20.0))
                origin: float = 0.0
                radius2: float = 0.0
                length: float = 0.0
            labels = {'mode': tr('Pièce'), 'radius': tr('Rayon de la pièce (mm)'),
                      'origin': tr('Génératrice du dessus, en travers de l\'axe (mm)')}
            if kind == 'cone':
                labels.update(radius2=tr('Cône : second rayon (mm)'),
                              length=tr('Cône : écart entre les rayons, le long de l\'axe (mm)'))
            modes = [(k, tr(v)) for k, v in WR.MODES.items() if k.startswith(kind)]
            dlg = ParamsDialog(self, tr('Enroulement'), P(), labels, choices={'mode': modes})
            if not dlg.exec():
                return []
            p = dlg.result_params()
            self.settings.setValue('enroulement/rayon', p.radius)
            spec = WR.Wrap(p.mode, p.radius, p.origin, p.radius2, p.length)
        new = []
        for it in shapes:
            path = it.path if isinstance(it, Shape) else it.outline
            res = WR.wrap_path(path, spec) if path else None
            if res is None:
                self.statusBar().showMessage(tr('Enroulement impossible : réglage incomplet, ou dessin au-delà du '
                                                'quart de tour.'), 6000)
                return []
            new.append(Shape(path=res, tool=it.tool, filled=getattr(it, 'filled', False), name=tr('Enroulé')))
        self._add_items(new)
        return new

    def fit_into_frame(self, margin: float | None = None, stretch: bool | None = None) -> list:
        """Ajuster dans le cadre : les objets sélectionnés, mis à l'échelle
        (proportions gardées, ou étirés) et centrés dans la boîte du cadre,
        moins une marge ; rend les objets ajustés."""
        sel = list(self.canvas.selection)
        frame, targets = self._frame_in(sel)
        if frame is None and len(sel) >= 2:              # un cadre ouvert : sa boîte suffit ici
            frame, targets = sel[-1], sel[:-1]
        if frame is None or not frame.bbox():
            self.statusBar().showMessage(tr('Sélectionnez le cadre, puis les objets à y placer.'), 5000)
            return []
        if margin is None or stretch is None:
            from dataclasses import dataclass
            from .dialogs import ParamsDialog

            @dataclass
            class P:
                margin: float = float(self.settings.value('cadre_ajuste/marge', 1.0))
                stretch: bool = False
            dlg = ParamsDialog(self, tr('Ajuster dans le cadre'), P(), {
                'margin': tr('Marge (mm)'), 'stretch': tr('Remplir le cadre (proportions non gardées)')})
            if not dlg.exec():
                return []
            p = dlg.result_params()
            margin, stretch = p.margin, p.stretch
            self.settings.setValue('cadre_ajuste/marge', margin)
        from ..core.geom import bbox_union
        box = bbox_union(it.bbox() for it in targets)
        try:
            m = Affine.fit(box, frame.bbox(), max(0.0, margin), bool(stretch))
        except ValueError:
            self.statusBar().showMessage(tr('La marge est plus grande que le cadre.'), 5000)
            return []
        self.canvas.selection = targets
        self.canvas.transform_selection(m)
        self._on_selection()
        return list(self.canvas.selection)

    def mirror_axis(self) -> None:
        """Symétrie de la sélection par rapport au trait droit, ou aux deux
        marqueurs, sélectionnés en dernier (l'axe reste en place). Ctrl ou Maj :
        les originaux restent, comme dans TypeEdit."""
        sel = list(self.canvas.selection)
        axis, used = self._axis_for_mirror(sel)
        if axis is None:
            QMessageBox.information(self, tr('Miroir sur axe'),
                                    tr('Sélectionnez les objets puis, en dernier, le trait droit ou les deux marqueurs qui '
                                       'servent d\'axe.'))
            return
        from ..core.document import drop_source_object
        m = Affine.reflection(*axis)
        objects = sel[:-used]
        if not self._held_on('mirror_axis'):
            self.canvas.select(objects)
            self.canvas.transform_selection(m)
            return
        copies = []
        for it in objects:
            c = it.transformed(m)
            drop_source_object(c)
            copies.append(c)
        self._add_items(copies)

    def _axis_for_mirror(self, sel: list) -> tuple:
        """L'axe d'un miroir et le nombre d'objets qui le donnent : les deux derniers s'ils sont des marqueurs, sinon le dernier
        s'il est un trait droit ; (None, 0) sinon."""
        from ..core import forms
        last = [forms.spec_of(it) if isinstance(it, Shape) else None for it in sel[-2:]]
        if len(sel) >= 3 and all(getattr(s, 'kind', '') == 'marker' for s in last):
            centres = []
            for it in sel[-2:]:
                b = it.bbox()
                centres.append(((b[0] + b[2]) / 2, (b[1] + b[3]) / 2))
            if geom.dist(*centres) > 1e-9:
                return tuple(centres), 2
        axis = self._axis_of(sel[-1]) if len(sel) >= 2 else None
        return (axis, 1) if axis is not None else (None, 0)

    def _marker_tool(self):
        """Ctrl ou Maj sur l'outil Marqueur (TypeEdit) : choisir d'abord son aspect."""
        from . import tools as T
        if self._held_on('tool_marker'):
            self.tool_form_dialog('marker')
        return T.MarkerTool(self.canvas)

    def rotate(self, deg: float) -> None:
        bb = self.canvas.selection_bbox()
        if bb:
            self.canvas.transform_selection(Affine.rotation(deg, ((bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2)))

    def _reference_box(self):
        """Référence d'alignement : le premier objet sélectionné quand il y en
        a plusieurs (comme TypeEdit : il ne bouge pas, les autres viennent à
        lui), sinon la plaque si elle existe, sinon l'objet seul."""
        sel = self.canvas.selection
        if len(sel) >= 2:
            return sel[0].bbox()
        d = self.canvas.doc
        if d.plate and d.plate.visible:
            p = d.plate
            return (p.x, p.y, p.x + p.width, p.y + p.height)
        return sel[0].bbox() if sel else None

    def align(self, kind: str) -> None:
        sel = self.canvas.selection
        if kind.endswith('_out') or len(sel) >= 2:
            # contre (ou sur) le premier objet sélectionné, qui ne bouge pas
            if len(sel) < 2:
                self.statusBar().showMessage(tr('Sélectionnez d\'abord l\'objet de référence, puis les autres'), 5000)
                return
            ref, keep = sel[0].bbox(), sel[0]
            sel = sel[1:]
        else:
            ref, keep = self._reference_box(), None
        if not ref or not sel:
            return
        self.push_undo()
        for it in list(sel):
            bb = it.bbox()
            if not bb:
                continue
            dx = dy = 0.0
            if kind == 'left':
                dx = ref[0] - bb[0]
            elif kind == 'right':
                dx = ref[2] - bb[2]
            elif kind == 'hcenter':
                dx = (ref[0] + ref[2]) / 2 - (bb[0] + bb[2]) / 2
            elif kind == 'top':
                dy = ref[3] - bb[3]
            elif kind == 'bottom':
                dy = ref[1] - bb[1]
            elif kind == 'vcenter':
                dy = (ref[1] + ref[3]) / 2 - (bb[1] + bb[3]) / 2
            elif kind == 'center':                       # aligner et centrer (TypeEdit) : les deux
                dx = (ref[0] + ref[2]) / 2 - (bb[0] + bb[2]) / 2
                dy = (ref[1] + ref[3]) / 2 - (bb[1] + bb[3]) / 2
            elif kind == 'left_out':
                dx = ref[0] - bb[2]
            elif kind == 'right_out':
                dx = ref[2] - bb[0]
            elif kind == 'top_out':
                dy = ref[3] - bb[1]
            elif kind == 'bottom_out':
                dy = ref[1] - bb[3]
            self.canvas.selection = [it]
            self.canvas.transform_selection(Affine.translation(dx, dy), record=False)
        # resélectionner tout ce qui a bougé (et la référence), dans le même ordre
        self._reselect(([keep.id] if keep is not None else []) + [s.id for s in sel])

    def center_on_plate(self, axis: str = 'hv') -> None:
        """Centrer la sélection sur la plaque : dans les deux sens, ou
        seulement horizontalement ('h') ou verticalement ('v')."""
        d = self.canvas.doc
        bb = self.canvas.selection_bbox()
        if not d.plate or not bb:
            return
        p = d.plate
        dx = p.x + p.width / 2 - (bb[0] + bb[2]) / 2 if 'h' in axis else 0.0
        dy = p.y + p.height / 2 - (bb[1] + bb[3]) / 2 if 'v' in axis else 0.0
        self.canvas.transform_selection(Affine.translation(dx, dy))

    def center_on_origin(self) -> bool:
        """Alt+W : le centre de la sélection posé sur l'origine (celle de
        « Placer l'origine », le zéro du dessin sinon). Rend vrai si déplacée."""
        bb = self.canvas.selection_bbox()
        if not bb:
            self.statusBar().showMessage(tr('Sélectionnez les objets à centrer.'), 4000)
            return False
        ox, oy = getattr(self.canvas, 'origin', (0.0, 0.0)) or (0.0, 0.0)
        dx, dy = ox - (bb[0] + bb[2]) / 2, oy - (bb[1] + bb[3]) / 2
        if abs(dx) < 1e-9 and abs(dy) < 1e-9:
            return False
        self.canvas.transform_selection(Affine.translation(dx, dy))
        return True

    def remove_duplicate_points(self) -> int:
        """Points confondus des contours sélectionnés (segments de longueur
        nulle) : supprimés. Renvoie leur nombre."""
        from ..core.cleanup import drop_null_segments
        shapes = [l for l in _leaves(self.canvas.selection) if isinstance(l, Shape)]
        if not shapes:
            QMessageBox.information(self, tr('Points doubles'), tr('Sélectionnez au moins un objet.'))
            return 0
        self.push_undo()
        n = 0
        for sh in shapes:
            sh.path, k = drop_null_segments(sh.path)
            n += k
        self.canvas.invalidate(shapes)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} point(s) double(s) supprimé(s)').format(n), 5000)
        return n

    def show_perimeter(self) -> None:
        sel = self.canvas.selection
        if not sel:
            QMessageBox.information(self, tr('Périmètre'), tr('Sélectionnez au moins un objet.'))
            return
        n = sum(len(item_path(l).contours) for l in _leaves(sel) if item_path(l))
        QMessageBox.information(self, tr('Périmètre'),
                                tr('{0} contour(s)\nPérimètre total : {1:.3f} mm').format(n, self.selection_length()))

    def _map_contours(self, fn) -> None:
        sel = self.canvas.selection
        if not sel:
            return
        self.push_undo()
        for leaf in _leaves(sel):
            if isinstance(leaf, Shape):
                leaf.path = geom.Path([fn(c) for c in leaf.path.contours])
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()

    def close_contours(self) -> None:
        self._map_contours(lambda c: c if c.closed else c.close())

    def open_contours(self) -> None:
        self._map_contours(lambda c: c.opened())

    def _toggle_symbols(self, on: bool) -> None:
        """B (TypeEdit) : la bibliothèque — panneau montré, sur la bibliothèque
        de l'atelier dépliée (ou sur le dossier où l'on en était)."""
        self.dock_symbols.setVisible(on)
        if on:
            self.dock_symbols.raise_()
            if self.symbols.tree.currentItem() is None or not self.symbols.list.count():
                self.symbols.open_library()
            self.symbols.list.setFocus()

    def toggle_library_window(self) -> bool:
        """B (TypeEdit) : la bibliothèque dans sa fenêtre, agrandie à tout
        l'écran (F11 : plein écran) ; ouverte et devant : refermée. Rend vrai
        si elle est ouverte."""
        w = getattr(self, '_library_window', None)
        if w is not None and w.isVisible() and w.isActiveWindow():
            w.close()
            return False
        w = self.library_window(show=False)
        if not w.isVisible() and not (w.windowState() & Qt.WindowState.WindowFullScreen):
            w.setWindowState(w.windowState() | Qt.WindowState.WindowMaximized)
        w.show()
        w.raise_()
        w.activateWindow()
        w.panel.list.setFocus()
        return True

    def _library_shown(self, global_pos=None) -> bool:
        """Le point écran `global_pos` est-il sur une Bibliothèque montrée (panneau ou grande fenêtre, pas réduite) ?
        Alors un déplacement de la sélection qui y arrive devient un glisser-déposer vers elle ; ailleurs (règle,
        hors de la fenêtre…) il continue comme avant."""
        from PySide6.QtWidgets import QApplication
        under = QApplication.widgetAt(global_pos) if global_pos is not None else None
        if under is None:
            return False
        panels = [self.symbols]
        w = getattr(self, '_library_window', None)
        if w is not None:
            panels.append(w.panel)
        return any(p.isVisible() and not p.window().isMinimized() and (under is p or p.isAncestorOf(under))
                   for p in panels)

    def library_window(self, show: bool = True):
        """La bibliothèque en grande fenêtre (une seule, gardée) ; elle s'ouvre
        sur le dossier du panneau."""
        from .symbols import LibraryWindow
        w = getattr(self, '_library_window', None)
        if w is None:
            w = self._library_window = LibraryWindow(self.settings, self)
            w.panel.insertRequested.connect(lambda p: self._library_activated(p, w))
            w.panel.printRequested.connect(lambda p: self.print_file(p))
            w.panel.saveRequested.connect(self.save_as_symbol)
            w.panel.addSelectionRequested.connect(lambda f: self.add_selection_to_library(f, fallback=False))
        folder = getattr(self.symbols, '_folder', None)
        if folder is not None:
            w.panel.show_folder(folder)
        elif w.panel.list.count() == 0:
            w.panel.open_library()
        if show:
            w.show()
            w.raise_()
            w.activateWindow()
        return w

    def _view_center(self) -> tuple[float, float]:
        return self.canvas.to_doc(self._center())

    def insert_symbol(self, path: str, at: tuple[float, float] | None = None) -> None:
        """Pose un symbole (.smb) ou un dessin de la bibliothèque (DXF,
        VDZ…) : centré sur `at`, ou au centre de la vue."""
        g = self._read_symbol(path)
        if g is not None:
            self._put_symbol(g, path, at or self._view_center())

    def _read_symbol(self, path: str):
        """Le fichier de la bibliothèque en un objet (None : illisible ou annulé)."""
        from .progress import Cancelled, run
        from .symbols import file_as_group
        try:                                             # un gros DXF : lu dans le fil de calcul, fenêtre vivante
            return run(self, tr('Lecture de {0}').format(pathlib.Path(path).name), file_as_group, path)
        except Cancelled:
            return None
        except Exception as ex:
            QMessageBox.critical(self, tr('Symbole illisible'), f'{pathlib.Path(path).name}\n\n{ex}')
            return None

    def place_symbol_by_click(self, path: str) -> bool:
        """Poser un dessin de la bibliothèque d'un clic : son contour suit le pointeur,
        le clic le pose (centré), Échap : rien. Rend vrai si l'outil attend le clic."""
        g = self._read_symbol(path)
        if g is None:
            return False
        from . import tools as T
        self.canvas.tool = 'place_symbol'
        self.canvas.snap.clear_tracking()
        def put(p, angle=0.0):
            bb = g.bbox()
            c = ((bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2) if bb else (0.0, 0.0)
            turn = Affine.translation(*c) @ Affine.rotation(angle) @ Affine.translation(-c[0], -c[1])
            turned = g.transformed(turn) if angle else g
            self._put_symbol(turned, path, (p[0] - c[0], p[1] - c[1]) if c != (0.0, 0.0) else p)
        self.canvas.tool_obj = T.PlaceGroupTool(
            self.canvas, g, put,
            tr('Cliquez où poser « {0} » — R : tourner de 90°, Échap : annuler').format(pathlib.Path(path).stem))
        self.canvas.setCursor(self.canvas.tool_obj.cursor)
        self.activateWindow()
        self.raise_()
        self.canvas.setFocus()
        return True

    def _panel_activated(self, path: str) -> None:
        """Double-clic dans le panneau Bibliothèque : le dessin se pose d'un clic (réglage
        symboles/poser_au_clic), sinon au centre de la vue."""
        if self.settings.value('symboles/poser_au_clic', 'true') in (True, 'true'):
            self.place_symbol_by_click(path)
        else:
            self.insert_symbol(path)

    def _library_activated(self, path: str, w) -> None:
        """Double-clic dans la grande fenêtre de la bibliothèque : fermée, puis le dessin
        se pose d'un clic (réglage de la fenêtre) ; sinon posé au centre de la vue."""
        if w.click_place.isChecked():
            w.close()
            self.place_symbol_by_click(path)
        else:
            self.insert_symbol(path)
            w.placed()

    def _put_symbol(self, g, path: str, at) -> None:
        x, y = at
        g = g.transformed(Affine.translation(x, y))
        self.push_undo()
        colors = g.extra.pop('tool_colors', None)
        if colors:                                       # ses couleurs gardées dans ce dessin
            self.canvas.doc.adopt_tool_colors([g], colors)
        self.canvas.doc.add(g)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()
        self.statusBar().showMessage(tr('Symbole posé : {0}').format(pathlib.Path(path).stem), 4000)
        from .symbols import remember_recent
        remember_recent(self.settings, path)             # « Récents » de la bibliothèque
        for panel in (self.symbols, getattr(getattr(self, '_library_window', None), 'panel', None)):
            if panel is not None and getattr(panel, '_recents_shown', False):
                panel.show_recents()

    def _from_library(self, path: str) -> bool:
        """Le fichier vient-il de la bibliothèque (dans un de ses dossiers) ?"""
        from .symbols import LIBRARY_EXT
        p = pathlib.Path(path)
        if p.suffix.lower() not in LIBRARY_EXT:
            return False
        for r in getattr(getattr(self, 'symbols', None), 'roots', []) or []:
            try:
                p.resolve().relative_to(pathlib.Path(r).resolve())
                return True
            except (ValueError, OSError):
                continue
        return False

    def _file_dropped(self, path: str, x: float, y: float) -> None:
        if path.lower().endswith('.smb') or self._from_library(path):
            self.insert_symbol(path, (x, y))             # de la bibliothèque : posé là où on le lâche
            return
        from .progress import Cancelled, run
        try:
            other = run(self, tr('Import de {0}').format(pathlib.Path(path).name), registry.open_document, path)
            self._after_read(other, path)
            if pathlib.Path(path).suffix.lower() != '.vdz':
                from ..io import companion
                companion.apply(other, path)
        except Cancelled:
            return
        except Exception as ex:
            QMessageBox.critical(self, tr('Import impossible'), str(ex))
            return
        self._import_undo_step()
        added = self._adopt_layers(other)
        self.canvas.invalidate()
        self.canvas.select(added)
        self._on_doc_changed()

    # --- opérations (round 3) ----------------------------------------------
    def _selected_shapes(self, *, convert_text: bool = True) -> list:
        """Formes de la sélection (groupes dépliés, textes en contours)."""
        out = []
        for leaf in _leaves(self.canvas.selection):
            if isinstance(leaf, Shape):
                out.append(leaf)
            elif isinstance(leaf, Text) and convert_text and leaf.outline:
                out.append(Shape(path=leaf.outline, tool=leaf.tool))
        return out

    def _replace_selection(self, new_items: list, *, keep: bool = False) -> None:
        """Remplace les objets sélectionnés par `new_items` (au calque et à la
        place du premier), annulable."""
        sel = list(self.canvas.selection)
        if not sel:
            return
        self.push_undo()
        ids = {id(s) for s in sel}
        target, index = self.canvas.doc.active_layer, None
        for L in self.canvas.doc.layers:
            for i, it in enumerate(L.items):
                if id(it) in ids and index is None:
                    target, index = L, i
            if not keep:
                L.items = [it for it in L.items if id(it) not in ids]
        if index is None or index > len(target.items):
            index = len(target.items)
        target.items[index:index] = new_items
        self.canvas.invalidate()
        self.canvas.select(new_items)
        self._on_doc_changed()

    def shape_build(self, stroke, delete: bool = False) -> int:
        """Concepteur de formes sur les formes choisies (core.pathfinder.build) ;
        les pièces remplacent la sélection. Rend le nombre de pièces touchées."""
        from ..core import pathfinder as PF
        sel = list(_leaves(self.canvas.selection))
        order = {id(it): i for i, it in enumerate(self.canvas.doc.iter_leaves())}
        sel.sort(key=lambda it: order.get(id(it), 0))
        items = [(it.path, it.tool) for it in sel if isinstance(it, Shape) and it.path.contours]
        items += [(it.outline, it.tool) for it in sel if isinstance(it, Text) and it.outline]
        if not items:
            return 0
        res, n = PF.build(items, stroke, delete)
        if not n:
            return 0
        self._replace_selection([Shape(path=p, tool=t) for p, t in res])
        return n

    def pathfinder(self, op: str) -> list:
        """Pathfinder sur les formes choisies, empilées dans l'ordre du dessin
        (du bas vers le haut) ; les nouvelles formes remplacent la sélection."""
        from ..core import pathfinder as PF
        sel = list(_leaves(self.canvas.selection))
        order = {id(it): i for i, it in enumerate(self.canvas.doc.iter_leaves())}
        sel.sort(key=lambda it: order.get(id(it), 0))
        items = []
        for it in sel:
            if isinstance(it, Shape) and it.path.contours:
                items.append((it.path, it.tool))
            elif isinstance(it, Text) and it.outline:
                items.append((it.outline, it.tool))
        if len(items) < 2:
            QMessageBox.information(self, tr('Pathfinder'), tr('Sélectionnez au moins deux formes.'))
            return []
        from .progress import Cancelled, run
        try:
            res = run(self, tr('Pathfinder'), PF.apply, op, items)
        except Cancelled:
            return []
        new = [Shape(path=p, tool=t) for p, t in res]
        self._replace_selection(new)
        self.statusBar().showMessage(tr('{0} forme(s)').format(len(new)), 4000)
        return new

    def boolean(self, op: str) -> None:
        from ..core import pathops
        keep = self._held_on(f'bool_{op}')               # TypeEdit : Ctrl ou Maj garde les contours originaux
        shapes = self._selected_shapes()
        if len(shapes) < 2:
            QMessageBox.information(self, tr('Booléens'), tr('Sélectionnez au moins deux objets.'))
            return
        from ..core import progress as P
        from .progress import Cancelled, run

        def work():
            if op == 'union':
                return pathops.union_all([s.path for s in shapes])
            out = shapes[0].path
            for i, s in enumerate(shapes[1:]):
                P.step(i, len(shapes) - 1, 'Objet {0} sur {1}')
                out = pathops.boolean(out, s.path, op)
            return out
        try:
            res = run(self, tr('Booléens'), work)
        except Cancelled:
            return
        except Exception as ex:
            QMessageBox.critical(self, tr('Booléens'), str(ex))
            return
        self._replace_selection([Shape(path=res, tool=shapes[0].tool)] if res else [], keep=keep)

    def _spell_words(self) -> set:
        """Le dictionnaire personnel : les mots ajoutés depuis la fenêtre d'orthographe."""
        import json
        try:
            words = json.loads(str(self.settings.value('orthographe/dictionnaire', '') or '[]'))
        except ValueError:
            return set()
        return {str(w).casefold() for w in words} if isinstance(words, list) else set()

    def _spell_add_word(self, word: str) -> None:
        import json
        self.settings.setValue('orthographe/dictionnaire', json.dumps(sorted(self._spell_words() | {word.casefold()}),
                                                                      ensure_ascii=False))

    def compress_global(self, percent: float | None = None) -> int:
        """Compression globale (TypeEdit) : le pourcentage de la longueur de la plus longue ligne ; rend le nombre de textes."""
        from PySide6.QtWidgets import QInputDialog

        from .textbar import selected_texts
        if not selected_texts(self):
            self.statusBar().showMessage(tr('Sélectionnez un texte.'), 4000)
            return 0
        if percent is None:
            last = float(self.settings.value('texte/compression_globale', 90.0))
            percent, ok = QInputDialog.getDouble(self, tr('Compression globale'), tr('Pourcentage de la longueur de la ligne'),
                                                 last, 1.0, 100.0, 1)
            if not ok:
                return 0
            self.settings.setValue('texte/compression_globale', percent)
        return self.textbar.set_global_compression(percent)

    def offset_dialog(self) -> None:
        from .dialogs import OffsetDialog
        shapes = self._selected_shapes()
        if not shapes:
            return
        s = self.settings
        dlg = OffsetDialog(self, float(s.value('decalage/distance', 1.0)), str(s.value('decalage/jonction', 'round')),
                           s.value('decalage/garder', 'true') in (True, 'true') or self._held_on('offset'),
                           s.value('decalage/dernier', 'false') in (True, 'true'),
                           union=s.value('decalage/reunir', 'true') in (True, 'true'))
        if not dlg.exec():
            return
        self.offset_selection(dlg.values())

    def offset_selection(self, v: dict) -> None:
        """Décaler la sélection. Une forme sans résultat (décalage trop grand) reste telle quelle : elle ne disparaît pas.
        `union` (d'office) : les décalages qui se croisent sont réunis, à chaque distance et pour un même outil
        (`pathops.crossing_groups` ; l'un dans l'autre, ils restent séparés)."""
        shapes = self._selected_shapes()
        s = self.settings
        s.setValue('decalage/distance', v['distance'])
        s.setValue('decalage/jonction', v['join'])
        s.setValue('decalage/garder', bool(v['keep']))
        s.setValue('decalage/dernier', bool(v.get('last_only')))
        union = bool(v.get('union', True))
        s.setValue('decalage/reunir', union)
        from ..core import parallel
        from .progress import Cancelled, run

        def work():
            # un tracé à la fois ; un long travail (milliers d'objets) passe sur plusieurs processus
            from ..core import workers
            dists = [v['distance'] * k for k in range(1, v['count'] + 1)]
            if v.get('last_only'):
                dists = dists[-1:]
            res = workers.adaptive_map(parallel.offset_job, [(s.path, dists, v['join']) for s in shapes])
            # rang du décalage (les distances croissent : un retrait vide laisse vides les suivants), outil, tracé
            out = [(k, s.tool, p) for s, (paths, _e, _a) in zip(shapes, res) for k, p in enumerate(paths)]
            joined = into = 0
            if union:
                # morceau par morceau (une lettre d'un texte, une forme) : seuls ceux qui se croisent sont réunis, à
                # la place du premier tracé d'où ils viennent ; le reste de chaque tracé reste tel quel
                from ..core import pathops
                by: dict = {}
                for i, (k, tool, _p) in enumerate(out):
                    by.setdefault((k, tool), []).append(i)
                rest: dict = {}
                adds: dict = {}
                for idx in by.values():
                    pieces, owner = [], []
                    for i in idx:
                        for r in pathops.regions(out[i][2]):
                            pieces.append(r)
                            owner.append(i)
                    groups = pathops.crossing_groups(pieces, owner)
                    used = {m for g in groups for m in g}
                    for g in groups:
                        adds.setdefault(min(owner[m] for m in g), []).append(
                            pathops.union_all([pieces[m] for m in g]))
                        joined, into = joined + len(g), into + 1
                    for i in {owner[m] for m in used}:
                        rest[i] = [c for m, r in enumerate(pieces) if owner[m] == i and m not in used
                                   for c in r.contours]
                kept = []
                for i, (k, tool, p) in enumerate(out):
                    if i not in rest:
                        kept.append((k, tool, p))
                    elif rest[i]:
                        kept.append((k, tool, geom.Path(rest[i])))
                    kept += [(k, tool, q) for q in adds.get(i, [])]
                out = kept
            return ([Shape(path=p, tool=tool) for _k, tool, p in out], sum(r[1] for r in res), sum(r[2] for r in res),
                    [s for s, r in zip(shapes, res) if not r[0]], (joined, into))
        try:
            new, exact, approx, failed, (joined, into) = run(self, tr('Décaler'), work)
        except Cancelled:
            return
        if not new:
            QMessageBox.warning(self, tr('Décaler'), tr('Aucun contour n\'a pu être créé : le décalage est trop grand pour '
                                                        'cette forme, ou elle est trop fine.'))
            return
        if failed and all(any(x is y for y in shapes) for x in self.canvas.selection):
            self.canvas.select([x for x in self.canvas.selection if not any(x is y for y in failed)])
        from ..core import cleanup
        doubled = sum(cleanup.dedupe([x], 0.01)[1] for x in shapes)     # avant : `shapes` peut quitter le dessin
        self._replace_selection(new, keep=v['keep'])
        if failed:
            self.statusBar().showMessage(tr('{0} forme(s) sans décalage possible, laissées telles quelles')
                                         .format(len(failed)), 8000)
        elif doubled:
            self.statusBar().showMessage(tr('Décalage : {0} contour(s) tracé(s) deux fois, comptés en pair-impair (pas de '
                                            'matière entre eux) ; « Superposés » (à) supprime les doublons')
                                         .format(doubled), 10000)
        elif joined:
            self.statusBar().showMessage(tr('Décalage : {0} contours qui se croisaient, réunis en {1}').format(joined, into),
                                         8000)
        elif approx:
            self.statusBar().showMessage(tr('Décalage : {0} exact(s), {1} approché(s) à 0,01 mm (formes dégénérées)')
                                         .format(exact, approx), 8000)

    def mark_open_contours(self, items: list | None = None) -> int:
        """Ctrl sur Détection des intersections (TypeEdit) : un repère à chaque bout de chaque contour ouvert ; rend leur nombre."""
        items = list(self.canvas.selection) or [it for L in self.canvas.doc.layers if L.visible
                                                 for it in L.items if it.visible] if items is None else items
        found = [c for leaf in _leaves(items) if (p := item_path(leaf)) for c in p.contours if not c.closed and c.segments]
        self.canvas.cross_marks = [(x, y, 'self') for c in found for x, y in (c.start, c.end)]
        self.canvas.update()
        self.statusBar().showMessage(tr('{0} contour(s) ouvert(s)').format(len(found)) if found else tr('Aucun contour ouvert'), 6000)
        return len(found)

    def intersections(self, exec_dialog: bool = True, method: str | None = None):
        """Points d'intersection de la sélection (sinon du dessin visible),
        repérés sur le plan de travail ; la fenêtre propose la méthode pour
        les supprimer, appliquée aux objets concernés. Rend la fenêtre
        (sans l'ouvrir si `exec_dialog` est faux) ou None. Ctrl : les contours ouverts."""
        if self._ctrl_held():
            self.mark_open_contours()
            return None
        from ..core import intersect as I
        from .intersections_dialog import IntersectionsDialog
        from .progress import Cancelled, run
        items = list(self.canvas.selection) or [it for L in self.canvas.doc.layers if L.visible
                                                 for it in L.items if it.visible]
        if not items:
            self.statusBar().showMessage(tr('Rien à examiner'), 4000)
            return None
        try:
            rep = run(self, tr('Points d\'intersection'), I.find, items)
        except Cancelled:
            return None
        self.canvas.cross_marks = [(c.x, c.y, c.kind) for c in rep.crossings]
        self.canvas.update()
        if not rep.count():
            self.statusBar().showMessage(tr('Aucun point d\'intersection'), 5000)
            return None
        dlg = IntersectionsDialog(self, rep, self.canvas, self.settings)
        if method is not None:
            dlg.set_method(method)
        if not exec_dialog:
            return dlg
        if dlg.exec():
            self.apply_intersections(rep, dlg.method(), dlg.limit.value())
        dlg.deleteLater()
        return None

    def apply_intersections(self, rep, method: str, limit: float) -> int:
        """Méthode `method` (core.intersect.METHODS) sur les formes des
        objets où il y a des intersections ; rend le nombre de points restants."""
        from ..core import intersect as I
        kinds = {'loops': ('self',), 'union': ('objets',), 'outer': ('objets', 'contours'),
                 'dedupe': ('doublon',)}.get(method, ('self', 'contours', 'objets'))
        targets = []
        for c in rep.crossings:                            # les objets que la méthode concerne
            if c.kind in kinds:
                for it in (c.a, c.b):
                    if isinstance(it, (Shape, Group, Text)) and all(it is not t for t in targets):
                        targets.append(it)
        if not targets:
            return rep.count()
        self.canvas.select(targets)
        shapes = self._selected_shapes()
        if not shapes:
            return rep.count()
        new = I.apply(method, shapes, limit=limit)
        self._replace_selection(new)
        left = sum(1 for c in I.find(new).crossings if c.kind in kinds)
        self.canvas.cross_marks = []
        self.canvas.update()
        self.statusBar().showMessage(tr('{0} : {1} point(s) d\'intersection restant(s)').format(
            tr(I.METHODS[method]), left), 6000)
        return left

    def remove_intersections(self) -> None:
        from ..core import pathops
        shapes = self._selected_shapes()
        if shapes:
            self._replace_selection([Shape(path=pathops.normalize(s.path), tool=s.tool) for s in shapes])

    def var_stroke(self, params: dict | None = None) -> list:
        """Traits choisis remplacés par des bandes de largeur variable."""
        from ..core import varstroke as VS
        shapes = self._selected_shapes()
        if not shapes:
            self.statusBar().showMessage(tr('Sélectionnez des traits.'), 5000)
            return []
        p = self._ask('var_stroke', tr('Largeur variable'),
                      [('profile', str, 'effile', tr('Profil')), ('w_start', float, 0.0, tr('Largeur au départ (mm)')),
                       ('w_end', float, 2.0, tr('Largeur à l\'arrivée (profils tout faits : la plus grande) (mm)')),
                       ('waves', int, 4, tr('Ondulé : nombre d\'ondes'))],
                      choices={'profile': [('lineaire', tr('De la largeur de départ à celle d\'arrivée')),
                                           ('effile', tr('Effilé aux deux bouts')), ('ondule', tr('Ondulé')),
                                           ('pointe_debut', tr('Pointe au départ')), ('pointe_fin', tr('Pointe à l’arrivée')),
                                           ('pincement', tr('Pincé au milieu')), ('goutte', tr('Goutte')),
                                           ('vague', tr('Vague'))]}, params=params)
        if p is None:
            return []
        spec = VS.VarStrokeSpec(profile=p['profile'], w_start=float(p['w_start']), w_end=float(p['w_end']),
                                waves=int(p['waves']))
        new = [Shape(path=VS.var_stroke(s.path, spec), tool=s.tool) for s in shapes]
        new = [s for s in new if s.path.contours]
        if new:
            self._replace_selection(new)
        return new

    def nib_stroke(self, params: dict | None = None) -> list:
        """Traits choisis remplacés par ce que trace une plume plate ou elliptique."""
        from ..core import varstroke as VS
        shapes = self._selected_shapes()
        if not shapes:
            self.statusBar().showMessage(tr('Sélectionnez des traits.'), 5000)
            return []
        p = self._ask('nib_stroke', tr('Plume calligraphique'),
                      [('width', float, 3.0, tr('Largeur de la plume (mm)')),
                       ('angle', float, 30.0, tr('Angle de la plume (°)')),
                       ('ratio', float, 0.1, tr('Épaisseur de la plume (part de sa largeur, 0 : plate, 1 : ronde)'))], params=params)
        if p is None:
            return []
        new = [Shape(path=VS.nib_stroke(s.path, float(p['width']), float(p['angle']), float(p['ratio'])), tool=s.tool) for s in shapes]
        new = [s for s in new if s.path.contours]
        if new:
            self._replace_selection(new)
        return new

    def stroke_dialog(self, params: dict | None = None) -> list:
        """Contour du trait (TypeEdit : Couteaux) : du filaire, un contour fermé. Le rayon est la moitié de l'épaisseur.
        Coins et bouts arrondis : exact (arcs concentriques, Bézier à 0,1 µm), contrôlé contre le calcul natif. Rend les
        objets créés."""
        from ..core import strokehull as EN
        shapes = self._selected_shapes()
        if not shapes:
            return []
        p = self._ask('couteaux', tr('Contour du trait'),
                      [('radius', float, 0.5, tr('Rayon (la moitié de l\'épaisseur, mm)')),
                       ('corner', str, 'arrondi', tr('Coins')),
                       ('end', str, 'arrondi', tr('Début et fin')),
                       ('keep', bool, False, tr('Conserver les courbes d\'origine')),
                       ('envelope', str, 'aucune', tr('Créer une enveloppe')),
                       ('margin', float, 1.0, tr('Marge de l\'enveloppe (mm)'))],
                      choices={'corner': [('aigu', tr('Aigus')), ('chanfrein', tr('Chanfreinés')), ('arrondi', tr('Arrondis'))],
                               'end': [('plat', tr('Plats')), ('arrondi', tr('Arrondis'))],
                               'envelope': [('aucune', tr('Aucune')), ('rectangle', tr('Rectangulaire')),
                                            ('cercle', tr('Circulaire')), ('convexe', tr('Convexe')),
                                            ('concave', tr('Concave'))]},
                      params=params)
        if p is None:
            return []
        if abs(float(p['radius'])) < 1e-9:
            self.statusBar().showMessage(tr('Rayon nul : rien à faire.'), 5000)
            return []
        new = [Shape(path=EN.stroke(s.path, float(p['radius']), p['corner'], p['end']), tool=s.tool) for s in shapes]
        new = [s for s in new if s.path.contours]
        if not new:
            self.statusBar().showMessage(tr('Le contour du trait est vide.'), 5000)
            return []
        hull = []
        if p['envelope'] != 'aucune':
            ink = geom.Path([c for s in new for c in s.path.contours])
            hull = [Shape(path=EN.envelope(ink, p['envelope'], float(p['margin'])), tool=new[0].tool)]
        if p['keep']:
            self.push_undo()
            layer = self.canvas.doc.active_layer
            for s in new + hull:
                layer.items.append(s)
            self.canvas.invalidate()
            self.canvas.select(new + hull)
            self._on_doc_changed()
        else:
            self._replace_selection(new + hull)
        return new + hull

    def corner_dialog(self, kind: str) -> None:
        from ..core import geom as G
        from .dialogs import CornerDialog
        tool = self.canvas.tool_obj
        dlg = CornerDialog(self, kind, float(self.settings.value(f'coins/{kind}', 2.0)))
        if not dlg.exec():
            return
        size = dlg.value()
        self.settings.setValue(f'coins/{kind}', size)
        if abs(size) < 1e-9:
            return
        if kind == 'fillet':
            self.canvas.fillet_radius = abs(size)            # aussi le rayon du raccord entre deux traits
        elif kind == 'chamfer':
            self.canvas.chamfer_size = size
        if type(tool).__name__ == 'NodeTool' and tool.shape() is not None and tool.sel:
            sh = tool.shape()
            self.push_undo()
            cs = list(sh.path.contours)
            for ci in {c for c, _ in tool.sel}:
                only = set()
                c = cs[ci]
                for _, k in (x for x in tool.sel if x[0] == ci):
                    only.add(k if c.closed else k - 1)
                cs[ci] = G.corner_contour(c, size, kind, only)
            sh.path = G.Path(cs)
            tool.sel.clear()
            self.canvas.invalidate([sh])
            self._on_doc_changed()
            return
        shapes = self._selected_shapes(convert_text=False)
        if shapes:
            self._replace_selection([Shape(path=G.Path([G.corner_contour(c, size, kind) for c in s.path.contours]),
                                           tool=s.tool) for s in shapes])

    def select_all(self) -> None:
        """Tout sélectionner ; en Mode Point, tous les points de la forme active."""
        tool = self.canvas.tool_obj
        if type(tool).__name__ == 'NodeTool' and tool.shape() is not None:
            n = tool.select_all_nodes()
            self.statusBar().showMessage(tr('{0} point(s) sélectionné(s)').format(n), 3000)
            return
        self.canvas.select_all()

    def node_delete(self) -> None:
        tool = self.canvas.tool_obj
        if type(tool).__name__ == 'NodeTool':
            tool.delete_selected()

    def node_add(self) -> bool:
        """« Ajouter un point » de TypeEdit : là où l'on a cliqué sur le contour, en Mode Point."""
        tool = self.canvas.tool_obj
        if type(tool).__name__ == 'NodeTool' and tool.add_marked():
            self._on_doc_changed()
            return True
        self.statusBar().showMessage(tr('Mode Point : cliquez d\'abord sur le contour, là où ajouter le point'), 6000)
        return False

    def simplify_curves(self, params: dict | None = None) -> bool:
        """« Simplifier la courbe » de TypeEdit : moins de points à la précision notée ; Ctrl ou Maj la demande. En Mode Point,
        l'objet en cours ; sinon les objets sélectionnés. Rend vrai si la commande a été exécutée."""
        from ..core import fitcurve
        from ..core.geom import Path as P
        s = self.settings
        tool = self.canvas.tool_obj
        one = tool.shape() if type(tool).__name__ == 'NodeTool' else None
        if one is None and not self._selected_shapes():
            QMessageBox.information(self, tr('Simplifier'), tr('Sélectionnez au moins un objet.'))
            return False
        precision = float(s.value('simplifier/precision', 0.05))
        if params is not None or self._ctrl_held() or self._shift_held():
            p = self._ask('simplifier', tr('Simplifier'), [('precision', float, precision, tr('Précision (mm)'))], params=params)
            if p is None:
                return False
            precision = max(1e-4, float(p['precision']))
            s.setValue('simplifier/precision', precision)
        corner = float(s.value('approximation/angle', 35.0))
        if one is None:
            self._fit_selection(tr('Simplifier'), lambda path: fitcurve.approximate(path, precision, corner, True))
            return True
        before = one.path.segment_count()
        self.push_undo()
        one.path = P(list(fitcurve.approximate(one.path, precision, corner, True).contours))
        tool.sel.clear()
        tool.hsel.clear()
        tool.mark = None
        self.canvas.invalidate([one])
        self.canvas.update()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} : {1} segment(s) → {2}').format(tr('Simplifier'), before, one.path.segment_count()), 6000)
        return True

    def refine_curves(self) -> None:
        """« Affiner la courbe » de TypeEdit : en Mode Point, l'objet en
        cours ; sinon les objets sélectionnés."""
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        if type(tool).__name__ == 'NodeTool' and tool.shape() is not None:
            sh = tool.shape()
            self.push_undo()
            sh.path = P([N.refine(c) for c in sh.path.contours])
            tool.sel.clear()
            self.canvas.invalidate([sh])
            self.canvas.update()
            self._on_doc_changed()
            return
        self._fit_selection(tr('Affiner'), lambda p: P([N.refine(c) for c in p.contours]))

    def node_portion(self, kind: str) -> None:
        """« Transformer en segment » / « en angle » de TypeEdit : deux
        points d'un même contour sélectionnés en Mode Point ; la portion la
        plus courte entre eux (Maj : l'autre)."""
        from PySide6.QtWidgets import QApplication
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        if (type(tool).__name__ != 'NodeTool' or tool.shape() is None or len(tool.sel) != 2
                or len({ci for ci, _k in tool.sel}) != 1):
            QMessageBox.information(self, tr('Mode Point'), tr('En Mode Point, sélectionnez deux points d\'un même contour.'))
            return
        (ci, a), (_ci, b) = sorted(tool.sel)
        other = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        sh = tool.shape()
        cs = list(sh.path.contours)
        c = {'segment': N.to_segment, 'arc': N.to_arc}.get(kind, N.to_angle)(cs[ci], a, b, other)
        if c == cs[ci]:
            return
        self.push_undo()
        cs[ci] = c
        sh.path = P(cs)
        tool.sel.clear()
        self.canvas.invalidate([sh])
        self.canvas.update()
        self._on_doc_changed()

    def node_project(self, kind: str) -> None:
        """Projections de TypeEdit : les points sélectionnés en Mode Point
        iront sur le repère (guide ou contour) cliqué ensuite."""
        tool = self.canvas.tool_obj
        if type(tool).__name__ != 'NodeTool' or tool.shape() is None or not tool.sel:
            QMessageBox.information(self, tr('Mode Point'), tr('En Mode Point, sélectionnez des points.'))
            return
        tool.pending = kind
        self.statusBar().showMessage(tr('Cliquez sur le repère : un guide ou un contour'), 10000)

    def node_break(self) -> None:
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        if type(tool).__name__ != 'NodeTool' or tool.shape() is None or not tool.sel:
            QMessageBox.information(self, tr('Couper'), tr('En Mode Point, sélectionnez un ou plusieurs points.'))
            return
        sh = tool.shape()
        self.push_undo()
        cs = list(sh.path.contours)
        for ci in sorted({ci for ci, _k in tool.sel}, reverse=True):      # du dernier au premier : les indices restent bons
            cs[ci:ci + 1] = N.break_many(cs[ci], [k for i, k in tool.sel if i == ci])
        sh.path = P(cs)
        tool.sel.clear()
        self.canvas.invalidate([sh])
        self._on_doc_changed()

    def node_start(self) -> None:
        """Mode Point : le point sélectionné devient le départ de son
        contour (fermé), et celui de l'usinage (TE, page 693)."""
        import math
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        if type(tool).__name__ != 'NodeTool' or tool.shape() is None or len(tool.sel) != 1:
            QMessageBox.information(self, tr('Point de départ'), tr('En Mode Point, sélectionnez un seul point.'))
            return
        sh = tool.shape()
        (ci, k), = tool.sel
        if not sh.path.contours[ci].closed:
            QMessageBox.information(self, tr('Point de départ'),
                                    tr('Le contour est ouvert : son départ est à l\'une de ses extrémités '
                                       '(Inverser le sens pour en changer).'))
            return
        self.push_undo()
        cs = list(sh.path.contours)
        cs[ci] = N.set_start(cs[ci], k)
        sh.path = P(cs)
        nodes = [s.start for s in cs[ci].segments]       # un seul point choisi par contour : le dernier
        kept = [p for p in (sh.extra or {}).get('start_xy', []) if not any(math.dist(p[:2], q[:2]) < 1e-6 for q in nodes)]
        sh.extra = dict(sh.extra or {}, start_xy=kept + [list(nodes[0][:2])])
        tool.sel.clear()
        tool.sel.add((ci, N.node_count(cs[ci]) - 1))
        self.canvas.invalidate([sh])
        self._on_doc_changed()

    def node_edit(self, kind: str) -> None:
        """Mode Point : droite / courbe, lisse / symétrique, alignements, sur
        les points sélectionnés."""
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        hsel = getattr(tool, 'hsel', set())
        if type(tool).__name__ == 'NodeTool' and tool.shape() is not None and kind == 'node_line' and hsel:
            # points hors courbe sélectionnés : leur segment devient droite
            sh = tool.shape()
            cs = list(sh.path.contours)
            for ci in {ci for ci, _s, _w in hsel}:
                cs[ci] = N.to_lines(cs[ci], sorted({s for c2, s, _w in hsel if c2 == ci} |
                                                   set(N.segments_between(cs[ci], {k for c2, k in tool.sel
                                                                                   if c2 == ci}))))
            tool.hsel.clear()
            if P(cs) != sh.path:
                self.push_undo()
                sh.path = P(cs)
                self.canvas.invalidate([sh])
                self.canvas.update()
                self._on_doc_changed()
            return
        if type(tool).__name__ != 'NodeTool' or tool.shape() is None or not tool.sel:
            QMessageBox.information(self, tr('Mode Point'), tr('En Mode Point, sélectionnez des points.'))
            return
        sh = tool.shape()
        cs = list(sh.path.contours)
        by_contour: dict[int, set[int]] = {}
        for ci, k in tool.sel:
            by_contour.setdefault(ci, set()).add(k)
        if kind in ('node_align_h', 'node_align_v', 'node_average'):
            if len(tool.sel) < 2:
                QMessageBox.information(self, tr('Mode Point'), tr('Sélectionnez au moins deux points.'))
                return
            cs = N.align_nodes(cs, set(tool.sel), {'node_align_h': 'h', 'node_align_v': 'v'}.get(kind, 'both'), tool.first_node)
        else:
            for ci, ks in by_contour.items():
                c = cs[ci]
                if kind == 'node_line':
                    c = N.to_lines(c, N.segments_between(c, ks))
                elif kind == 'node_curve':
                    c = N.to_curves(c, N.segments_between(c, ks))
                else:
                    for k in sorted(ks):
                        c = N.smooth_node(c, k, symmetric=kind == 'node_symmetric')
                cs[ci] = c
        if P(cs) == sh.path:
            return
        self.push_undo()
        sh.path = P(cs)
        self.canvas.invalidate([sh])
        self.canvas.update()
        self._on_doc_changed()

    def node_attr(self, kind: str) -> int:
        """Mode Point : points sélectionnés en courbe ('on' : les points hors
        courbe) ou hors courbe ('off' : les points en courbe). Rend le
        nombre de points changés."""
        from ..core import nodes as N
        from ..core.geom import Path as P
        tool = self.canvas.tool_obj
        if type(tool).__name__ != 'NodeTool' or tool.shape() is None:
            QMessageBox.information(self, tr('Mode Point'), tr('En Mode Point, sélectionnez des points.'))
            return 0
        sh = tool.shape()
        cs = list(sh.path.contours)
        n = 0
        if kind == 'on':
            for ci in {ci for ci, _s, _w in tool.hsel}:
                # de la fin vers le début : couper un segment décale les suivants
                for si, w in sorted({(s, w) for c2, s, w in tool.hsel if c2 == ci}, reverse=True):
                    c = N.handle_to_on(cs[ci], si, w)
                    n += c != cs[ci]
                    cs[ci] = c
        else:
            for ci in {ci for ci, _k in tool.sel}:
                for k in sorted({k for c2, k in tool.sel if c2 == ci}, reverse=True):
                    c = N.node_to_off(cs[ci], k)
                    n += c != cs[ci]
                    cs[ci] = c
        if not n:
            self.statusBar().showMessage(tr('Sélectionnez des points hors courbe (petits ronds).') if kind == 'on'
                                         else tr('Sélectionnez des points en courbe (pas les bouts d\'un contour '
                                                 'ouvert).'), 6000)
            return 0
        self.push_undo()
        sh.path = P(cs)
        tool.sel.clear()
        tool.hsel.clear()
        self.canvas.invalidate([sh])
        self.canvas.update()
        self._on_doc_changed()
        return n

    def point_attrs(self, hit, x: float, y: float, on_curve: bool, w: float | None = None) -> bool:
        """Attributs d'un point du Mode Point (TypeEdit) : position X, Y (depuis
        l'origine du dessin), en courbe / hors courbe, poids W d'un contrôle
        de conique (arc : W < 1)."""
        from ..core import nodes as N
        from ..core.geom import Conic, Path as P
        tool = self.canvas.tool_obj
        sh = tool.shape() if type(tool).__name__ == 'NodeTool' else None
        if sh is None:
            return False
        ox, oy = self.canvas.origin
        pt = (x + ox, y + oy)
        cs = list(sh.path.contours)
        ci = hit[1]
        c = cs[ci]
        if hit[0] == 'node':
            k = hit[2]
            c = N.move_node(c, k, pt)
            if not on_curve:
                c = N.node_to_off(c, k)
        else:
            si, which = hit[2], hit[3]
            c = N.move_handle(c, si, which, pt)
            s = c.segments[si]
            if w is not None and isinstance(s, Conic) and w > 0 and abs(w - s.w) > 1e-12:
                segs = list(c.segments)
                segs[si] = Conic(s.p0, s.p1, s.p2, float(w))
                c = type(c)(segs, c.closed)
            if on_curve:
                c = N.handle_to_on(c, si, which)
        if c == cs[ci]:
            return False
        self.push_undo()
        cs[ci] = c
        sh.path = P(cs)
        tool.sel.clear()
        tool.hsel.clear()
        self.canvas.invalidate([sh])
        self.canvas.update()
        self._on_doc_changed()
        return True

    def point_dialog(self, hit) -> bool:
        """Double-clic sur un point en Mode Point : « Attributs du point »."""
        from PySide6.QtWidgets import QDoubleSpinBox, QRadioButton
        from ..core import nodes as N
        from ..core.geom import Conic
        from .dialogs import _buttons
        tool = self.canvas.tool_obj
        sh = tool.shape() if type(tool).__name__ == 'NodeTool' else None
        if sh is None:
            return False
        c = sh.path.contours[hit[1]]
        if hit[0] == 'node':
            pt, seg = N.node_point(c, hit[2]), None
        else:
            pt, seg = N.handle_point(c, hit[2], hit[3]), c.segments[hit[2]]
        ox, oy = self.canvas.origin
        dlg = QDialog(self)
        dlg.setWindowTitle(tr('Attributs du point'))
        form = QFormLayout(dlg)
        spins = []
        for lab, v in (('X', pt[0] - ox), ('Y', pt[1] - oy)):
            sb = QDoubleSpinBox()
            sb.setRange(-1e6, 1e6)
            sb.setDecimals(3)
            sb.setSuffix(' mm')
            sb.setValue(v)
            form.addRow(lab, sb)
            spins.append(sb)
        wsb = None
        if isinstance(seg, Conic):
            wsb = QDoubleSpinBox()
            wsb.setRange(0.01, 100)
            wsb.setDecimals(4)
            wsb.setValue(seg.w)
            wsb.setToolTip(tr('Poids du point de contrôle : 1 = courbe ordinaire, moins de 1 = arc'))
            form.addRow(tr('Poids W'), wsb)
        on = QRadioButton(tr('En courbe'))
        off = QRadioButton(tr('Hors courbe'))
        (on if hit[0] == 'node' else off).setChecked(True)
        form.addRow(on)
        form.addRow(off)
        _buttons(dlg, form)
        if not dlg.exec():
            return False
        return self.point_attrs(hit, spins[0].value(), spins[1].value(), on.isChecked(),
                                wsb.value() if wsb is not None else None)

    def join_contours(self) -> None:
        from ..core import nodes as N
        from ..core.geom import Path as P
        shapes = self._selected_shapes(convert_text=False)
        opens = [(s, c) for s in shapes for c in s.path.contours if not c.closed]
        if len(opens) != 2:
            QMessageBox.information(self, tr('Joindre'), tr('Sélectionnez exactement deux contours ouverts.'))
            return
        j = N.join(opens[0][1], opens[1][1])
        if j is None:
            return
        rest = [c for s in shapes for c in s.path.contours if c is not opens[0][1] and c is not opens[1][1]]
        self._replace_selection([Shape(path=P(rest + [j]), tool=shapes[0].tool)])

    def text_to_curves(self) -> None:
        from ..core import fonts
        from ..core import text as TX
        texts = [t for t in _leaves(self.canvas.selection) if isinstance(t, Text)]
        for t in texts:
            if not t.outline and fonts.is_available(t.font):     # contour pas encore calculé (police présente :
                try:                                             # pas d'Arial de remplacement)
                    t.outline = TX.outline_for(t)
                except Exception:                        # noqa: BLE001 — police illisible
                    pass
        texts = [t for t in texts if t.outline]
        if not texts:
            self.statusBar().showMessage(tr('En courbes : aucun texte sélectionné (ou sa police manque)'), 6000)
            return
        new = [Shape(path=t.outline, tool=t.tool, name=t.text[:30]) for t in texts]
        others = [s for s in self.canvas.selection if not isinstance(s, Text)]
        self._replace_selection(others + new)

    # --- texte -------------------------------------------------------------
    def new_text(self, x: float, y: float) -> None:
        """Un nouveau texte à écrire en (x, y) : l'outil Texte, le curseur posé là — la frappe écrit dans le dessin,
        avec la mise en forme de l'onglet Mise en forme."""
        if self.canvas.tool != 'text':
            self.set_tool('text')
        self.canvas.tool_obj.start((x, y))
        self.canvas.setFocus()

    # --- saisie dans le dessin (outil Texte) ----------------------------------------------------------------------
    def typing_tool(self):
        """L'outil Texte, s'il a une saisie en cours."""
        from . import tools as T
        tool = self.canvas.tool_obj
        return tool if isinstance(tool, T.TextTool) and tool.active() else None

    def finish_typing(self) -> None:
        tool = self.typing_tool()
        if tool is not None:
            tool.finish()

    def typing_focus(self, src=None) -> None:
        """Après un champ de Mise en forme validé pendant la saisie : la frappe revient au dessin — sauf quand on l'a
        validé en prenant un autre champ (clic, Tab) : celui-ci garde la main (`src` : le champ validé)."""
        if self.typing_tool() is None:
            return
        if src is not None:
            from PySide6.QtWidgets import (QAbstractSpinBox, QApplication, QComboBox, QLineEdit, QPlainTextEdit,
                                           QTextEdit)
            f = QApplication.focusWidget()
            if f is not None and f is not self.canvas and f is not src and not src.isAncestorOf(f) \
                    and isinstance(f, (QLineEdit, QAbstractSpinBox, QComboBox, QTextEdit, QPlainTextEdit)):
                return
        self.canvas.setFocus()

    def typable(self, item) -> bool:
        """Un texte qui se reprend dans le dessin : droit (ni courbe, ni en arc, ni de droite à gauche), de premier
        niveau, hors cadre, pas gelé."""
        from ..core import text as TX
        return isinstance(item, Text) and TX.straight(item) and not item.extra.get('box') and not item.locked \
            and self.canvas.doc.layer_of(item) is not None

    def new_text_height(self) -> float:
        from . import text_presets as TP
        try:
            return max(float(TP.new_text_format(self.settings)['attrs'].get('size', 5.0)), 0.05)
        except (TypeError, ValueError):
            return 5.0

    def typed_text_new(self, at, text: str) -> Text:
        """Première lettre d'un texte écrit dans le dessin : le texte, avec la mise en forme des nouveaux textes
        (préréglage choisi, champs de Mise en forme sans sélection, largeur imposée donnée avant), est ajouté — un
        pas d'annulation pour toute sa saisie — et sélectionné."""
        import copy
        from ..core import text as TX
        from . import text_presets as TP
        fmt = TP.new_text_format(self.settings)
        a = fmt['attrs']
        t = Text(text=text, font=str(a.get('font', 'Arial')), size=float(a.get('size', 5.0)),
                 matrix=Affine.translation(float(at[0]), float(at[1])), align=str(a.get('align', 'left')),
                 spacing=float(a.get('spacing', 0.0)), line_spacing=float(a.get('line_spacing', 1.2)),
                 width_ratio=float(a.get('width_ratio', 1.0)), tool=self.canvas.current_tool_index)
        for k, val in fmt['extra'].items():
            if k in TX.FORMAT_EXTRA:
                t.extra[k] = copy.deepcopy(val)
        fit = getattr(self, 'next_text_fit', None)
        if fit:
            t.extra['fit'] = dict(fit)
            self.next_text_fit = None
        t.outline = TX.outline_for(t)
        was, redo = self.modified, list(self._redo)
        self.push_undo(tr('Texte'))
        self._typed_new = (t, getattr(self, '_undo_pushes', 0), was, redo)    # effacé avant la fin : pas retiré
        self.canvas.doc.add(t)
        self.canvas.invalidate()
        self.canvas.select([t])
        self._on_doc_changed()
        return t

    def typed_text_begin(self, t: Text) -> None:
        """Première frappe dans un texte repris : un pas d'annulation pour toute la saisie ; le paragraphe TypeEdit
        d'origine n'est plus valable."""
        from ..core.document import drop_source_object
        self.push_undo(tr('Texte'))
        drop_source_object(t)

    def typed_text_changed(self, t: Text) -> None:
        """Une frappe : le texte remis en page, à sa place (le reste du dessin à jour à la fin de la saisie)."""
        from ..core import text as TX
        t.outline = TX.outline_for(t)
        self.canvas.invalidate([t])
        self.work_activity()
        if not self.modified:
            self.modified = True
            self._title()

    def typed_text_done(self, t: Text, begun: bool) -> None:
        """Fin de la saisie : un texte qu'elle a vidé s'en va (un texte neuf écrit puis effacé : son pas d'annulation
        aussi, rien n'a changé) ; sinon calques, liens, sélection à jour."""
        new, self._typed_new = getattr(self, '_typed_new', None), None
        if not begun:
            return
        v = t.extra.get('vertical')
        src = v['text'] if isinstance(v, dict) and isinstance(v.get('text'), str) else t.text
        was = None
        if not src.strip():
            layer = self.canvas.doc.layer_of(t)
            if layer is not None:
                layer.items = [x for x in layer.items if x is not t]
            self.canvas.select([x for x in self.canvas.selection if x is not t])
            self.canvas.invalidate()
            if new is not None and new[0] is t and new[1] == getattr(self, '_undo_pushes', 0) and self._undo:
                self._undo.pop()
                self._redo[:] = new[3]
                was = new[2]
        self._on_selection()
        self._on_doc_changed()
        if was is not None and self.modified != was:    # le dessin redevient tel qu'avant le texte
            self.modified = was
            self._title()

    def type_in_text(self, t: Text, at=None, double: bool = False, sp=None) -> None:
        """Le texte `t` repris dans le dessin : l'outil Texte, le curseur au plus près du point `at` (sinon à la
        fin) — la frappe le modifie là où il est. `double` : repris par un double clic en `at` (`sp` : ce point à
        l'écran), son mot est sélectionné (le clic suivant : la ligne ; puis tout le texte)."""
        if self.canvas.tool != 'text':
            self.set_tool('text')
        self.canvas.tool_obj.edit(t, at=at)
        if double and at is not None:
            from PySide6.QtCore import QPointF
            self.canvas.tool_obj.double_clicked(
                sp if sp is not None else self.canvas.view().map(QPointF(float(at[0]), float(at[1]))))
        self.canvas.setFocus()

    def font_recognize_dialog(self, exec_dialog: bool = True, start: str | None = None):
        """« Reconnaître une police… » : les polices du poste les plus proches de lettres en courbes sélectionnées ou
        d'une image (`ui.font_recognize`) ; `start` : la source d'emblée ('selection', 'image', 'presse-papiers').
        Rend la fenêtre."""
        from .font_recognize import FontRecognizeDialog
        dlg = FontRecognizeDialog(self, start)
        if exec_dialog:
            dlg.exec()
            dlg.deleteLater()
        return dlg

    def font_panel(self):
        """Le contenu du panneau « Reconnaître une police » (`ui.font_recognize`), fait la première fois."""
        from .font_recognize import FontRecognizeDialog
        d = self.dock_fonts
        w = d.widget()
        if not isinstance(w, FontRecognizeDialog):
            w = FontRecognizeDialog(self, docked=d)
            d.setWidget(w)
        return w

    def show_font_panel(self, start: str | None = None):
        """« Reconnaître une police… » : son panneau, dans la colonne choisie (clic droit sur sa barre : colonne de
        gauche ou de droite), mis devant ; l'image pointe de nouveau sur la dernière capture. Rend son contenu."""
        d = self.dock_fonts
        had = d.widget() is not None
        p = self.font_panel()
        if had or start:                                 # déjà faite : de nouveau sur la dernière capture
            p.renew(start)
        cols = getattr(self, 'columns', None)
        if cols is not None and not d.isFloating() \
                and not self.settings.value('panneaux_colonnes/place/polices', ''):
            cols.move(d, cols.side(d) or 'droite')       # la première fois : en onglet dans sa colonne, retenu
        else:
            d.setVisible(True)
            d.raise_()
        p.go.setFocus()                                  # Entrée : reconnaître ; Échap : arrêter
        return p

    def apply_recognized_font(self, name: str) -> int:
        """La police `name` mise aux textes sélectionnés (un pas d'annulation) ; rend le nombre de textes changés.
        Sans texte sélectionné : elle devient celle des prochains textes, et la barre de texte la montre — comme un
        choix dans la liste des polices (`TextBar.apply`)."""
        return int(self.textbar.apply('font', name) or 0)

    def _cursor_doc(self):
        """Le point du dessin sous la souris."""
        from PySide6.QtCore import QPointF
        from PySide6.QtGui import QCursor
        return self.canvas.to_doc(QPointF(self.canvas.mapFromGlobal(QCursor.pos())))

    def insert_spring(self) -> bool:
        """Ressort (TypeEdit) au curseur du texte qui s'écrit : l'espace libre de la ligne se partage entre ses
        ressorts. Sans saisie : dit comment faire."""
        from ..core.text import SPRING
        tool = self.typing_tool()
        if tool is None:
            self.statusBar().showMessage(tr('Ressort : avec l\'outil Texte, cliquez dans le texte à l\'endroit voulu, '
                                            'puis Ressort (ou la touche Tab)'), 8000)
            return False
        tool.insert(SPRING)
        tool.wake()
        self.canvas.setFocus()
        return True

    def leave_text_mode(self) -> None:
        """Retour : le texte en cours fini, l'outil Sélection, plus de sélection — l'onglet d'avant revient."""
        self.finish_typing()
        self.A['tool_select'].trigger()
        self.canvas.select([])
        self._on_selection()

    def _te_script_folder(self):
        """Le dossier ShapeScript de TypeEdit s'il est installé."""
        import os
        import pathlib
        if os.environ.get('VECTORDRIVE_NO_TYPEEDIT') == '1':
            return None
        from .themes import ribbon_script_files
        for f in ribbon_script_files():
            for parent in pathlib.Path(f).parents:
                if (parent / 'ShapeScript').is_dir():
                    return parent / 'ShapeScript'
        return None

    def script_slot_text(self, n: int) -> str:
        """Le libellé d'un bouton de script : son numéro, et le nom du script qu'il lance."""
        import pathlib
        path = str(self.settings.value(f'scripts/bouton_{n}', '') or '')
        return f'{tr("Script {0}").format(n)} : {pathlib.Path(path).stem}' if path else tr('Script {0}').format(n)

    def set_script_slot(self, n: int, path) -> None:
        self.settings.setValue(f'scripts/bouton_{n}', str(path))
        self.A[f'script_{n}'].setText(self.script_slot_text(n))

    def script_slot(self, n: int):
        """Lance le script du bouton `n` ; s'il n'en a pas ou que le fichier a disparu, la fenêtre des scripts s'ouvre."""
        import pathlib
        path = str(self.settings.value(f'scripts/bouton_{n}', '') or '')
        if not path or not pathlib.Path(path).is_file():
            return self.shape_script()
        return self.run_script_file(path)

    def run_script_file(self, name, params=()):
        """Lance un script d'après son nom (bouton, ligne de commande) et dit ce qui ne va pas."""
        from ..core import shapescript as SS
        from .script_dialog import why
        title = tr('Script')
        path = SS.find_script(name, self._te_script_folder())
        if path is None:
            QMessageBox.warning(self, title, tr('Script introuvable : {0}').format(name))
            return None
        try:
            return self.run_shape_script(SS.read_text(path), path, params)
        except SS.ScriptError as ex:
            QMessageBox.warning(self, title, f'{path.name}\n{why(ex)}')
            return None

    def sketch_edit(self):
        """Esquisse contrainte : la reprendre, partir des traits et arcs sélectionnés, ou d'une page blanche."""
        from ..core import sketch as SK
        from ..core.geom import Path
        from .sketch_editor import MAX_ENTITIES, SketchEditor
        title = tr('Esquisse contrainte')
        sel = [it for it in self.canvas.selection if isinstance(it, Shape) and it.path.contours]
        if len(sel) == 1 and 'sketch' in sel[0].extra:
            return self.edit_sketch(sel[0])
        sk, ignored = SK.from_path(Path([c for it in sel for c in it.path.contours]))
        if len(sk.lines) + len(sk.circles) > MAX_ENTITIES:
            QMessageBox.information(self, title, tr('Trop de morceaux pour une esquisse : {0} au plus.').format(MAX_ENTITIES))
            return None
        if sel and not sk.lines and not sk.circles:
            QMessageBox.information(self, title, tr('Rien à reprendre : une esquisse garde les traits et les arcs, pas les courbes.'))
            return None
        dlg = SketchEditor(self, sk, ignored)
        self.sketch_box = dlg
        if not dlg.exec():
            return None
        return self.sketch_done(dlg.sketch, sel)

    def sketch_done(self, sk, replaced=()):
        """L'objet d'une esquisse validée, à la place de ce dont elle est partie."""
        path = sk.to_path()
        shape = Shape(path=path, name=tr('Esquisse'), tool=replaced[0].tool if replaced else self.canvas.current_tool_index)
        shape.extra['sketch'] = sk.to_dict()
        shape.extra['sketch_box'] = list(path.bbox())
        if replaced:
            L = self.canvas.doc.layer_of(replaced[0])
            self.push_undo(tr('Esquisse contrainte'))
            for old in replaced:
                layer = self.canvas.doc.layer_of(old)
                if layer is not None:
                    layer.items[:] = [it for it in layer.items if it is not old]
            L.items.append(shape)
            self.canvas.invalidate()
            self.canvas.select([shape])
            self._on_doc_changed()
        else:
            self._add_items([shape])
        return shape

    def edit_sketch(self, item):
        """Reprendre l'esquisse d'un objet ; il garde sa place si on l'a déplacé depuis. Tourné ou mis à l'échelle depuis,
        il repart de l'esquisse telle qu'elle a été validée, et on le dit."""
        from ..core import sketch as SK
        from .sketch_editor import SketchEditor
        was = item.extra.get('sketch_box') or item.bbox()
        now = item.bbox()
        same = abs((now[2] - now[0]) - (was[2] - was[0])) < 1e-3 and abs((now[3] - now[1]) - (was[3] - was[1])) < 1e-3
        dlg = SketchEditor(self, SK.Sketch.from_dict(item.extra['sketch']))
        if not same:
            dlg.message = tr('Objet tourné ou mis à l’échelle depuis : on repart de l’esquisse validée.')
            dlg.refresh(keep_message=True)
        self.sketch_box = dlg
        if not dlg.exec():
            return None
        new = self._sketch_shape(item, dlg.sketch)
        self._replace_item(item, new, tr('Esquisse contrainte'))
        return new

    def _sketch_shape(self, item, sketch):
        """La forme d'une esquisse reprise, à la place où `item` a été déplacé depuis."""
        from ..core import sketch as SK
        from ..core.geom import Affine
        was = item.extra.get('sketch_box') or item.bbox()
        now = item.bbox()
        path = sketch.to_path()
        box = path.bbox()
        new = Shape(path=path, name=item.name, tool=item.tool)
        new.extra['sketch'] = sketch.to_dict()
        new.extra['sketch_box'] = list(box)
        dx = (now[0] + now[2] - was[0] - was[2]) / 2
        dy = (now[1] + now[3] - was[1] - was[3]) / 2
        if dx or dy:
            new.path = new.path.transformed(Affine.translation(dx, dy))
            new.extra['sketch_box'] = list(new.path.bbox())
            sk = SK.Sketch.from_dict(new.extra['sketch'])
            for v in sk.points.values():
                v[0] += dx
                v[1] += dy
            for c in sk.constraints:
                if c.kind == 'fix':
                    c.value = (float(c.value[0]) + dx, float(c.value[1]) + dy)
            new.extra['sketch'] = sk.to_dict()
        return new

    def shape_script(self):
        """La fenêtre des scripts de forme."""
        from .script_dialog import ScriptDialog
        dlg = ScriptDialog(self, self._te_script_folder())
        dlg.exec()
        return dlg

    def _script_shape(self, got, text: str, path, name: str):
        from ..core.document import Shape
        from ..core.geom import Path
        shape = Shape(path=Path(got.contours), name=name or tr('Script'), tool=self.canvas.current_tool_index)
        if got.reedit is not None:
            shape.extra['script'] = {'name': name, 'text': text, 'params': got.reedit,
                                     'path': str(path) if path is not None else '',
                                     'box': list(Path(got.contours).bbox())}
        return shape

    def run_shape_script(self, text: str, path=None, params=()):
        """Lance le script et ajoute ce qu'il dessine à la page ; None s'il ne dessine rien ou si on annule.
        Une erreur remonte en `ScriptError`. Les valeurs que le script garde ne sont écrites que s'il a abouti."""
        from ..core import shapescript as SS
        from .script_dialog import make_host
        host = make_host(self, path, params)
        got = SS.run(text, host)
        if path is not None:
            SS.save_values(path, host.profile)
        if not got.contours:
            return None
        shape = self._script_shape(got, text, path, path.stem if path is not None else '')
        self._add_items([shape])
        return shape

    def edit_script_object(self, item):
        """Relance le script d'un objet qui en vient, avec ses paramètres ; le résultat le remplace là où il a été déplacé."""
        import pathlib
        from ..core import shapescript as SS
        from ..core.geom import Affine
        from .script_dialog import make_host, why
        title = tr('Script')
        data = item.extra['script']
        path = pathlib.Path(data['path']) if data.get('path') else None
        host = make_host(self, path, reedit=dict(data.get('params') or {}))
        try:
            got = SS.run(data.get('text', ''), host)
        except SS.ScriptError as ex:
            QMessageBox.warning(self, title, why(ex))
            return None
        if not got.contours or got.reedit is None:
            return None                                  # annulé dans sa boîte : l'objet reste tel quel
        if path is not None:
            SS.save_values(path, host.profile)
        new = self._script_shape(got, data.get('text', ''), path, data.get('name', ''))
        new.tool, new.name = item.tool, item.name
        was = data.get('box') or item.bbox()
        now = item.bbox()
        dx = (now[0] + now[2] - was[0] - was[2]) / 2
        dy = (now[1] + now[3] - was[1] - was[3]) / 2
        if dx or dy:
            new.path = new.path.transformed(Affine.translation(dx, dy))
        self._replace_item(item, new, title)
        return new

    def _add_items(self, items: list) -> None:
        self.push_undo()
        for it in items:
            self.canvas.doc.add(it)
        self.canvas.invalidate()
        self.canvas.select(items)
        self._on_doc_changed()

    def _put_on_curve(self, t: Text, curve: Shape) -> None:
        """Le texte `t` sur la courbe, qui disparaît sauf si Maj est enfoncée (TypeEdit)."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        if '\n' in t.text:
            QMessageBox.information(self, tr('Texte sur courbe'), tr('Un texte sur courbe tient sur une seule ligne.'))
            return
        self.push_undo(tr('Texte sur courbe'))
        for k in ('box', 'fit', 'arc', 'arc_warp', 'path_offset'):
            t.extra.pop(k, None)
        t.extra['on_path'] = curve.path.contours[0]
        t.outline = TX.outline_for(t)
        drop_source_object(t)
        if not self._shift_held():
            layer = self.canvas.doc.layer_of(curve)
            if layer is not None:
                layer.items = [x for x in layer.items if x is not curve]
        self.canvas.select([t])
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()

    def text_on_path(self) -> None:
        from ..core import text as TX
        from .dialogs import TextDialog
        shapes = [s for s in self.canvas.selection if isinstance(s, Shape) and s.path.contours]
        texts = [t for t in self.canvas.selection if isinstance(t, Text)]
        if len(shapes) != 1 or len(texts) > 1:
            QMessageBox.information(self, tr('Texte sur courbe'), tr('Sélectionnez une seule courbe, et le texte à y poser.'))
            return
        if texts:
            self._put_on_curve(texts[0], shapes[0])
            return
        contour = shapes[0].path.contours[0]
        dlg = TextDialog(self, font=self.settings.value('texte/police', 'Arial'),
                         height=float(self.settings.value('texte/hauteur', 5.0)), align='center')
        if not dlg.exec():
            return
        v = dlg.values()
        t = Text(text=v['text'], font=v['font'], size=v['height'], align=v['align'],
                 spacing=v['spacing'], tool=shapes[0].tool)
        t.extra['on_path'] = contour
        t.outline = TX.outline_for(t)
        self._add_items([t])

    def _circle_of_selection(self):
        """(centre, rayon) si la sélection est un seul cercle."""
        sel = self.canvas.selection
        return self._circle_of(sel[0]) if len(sel) == 1 else None

    @staticmethod
    def _circle_of(item):
        if not isinstance(item, Shape) or len(item.path.contours) != 1:
            return None
        c = item.path.contours[0]
        params = [s.circle_params() for s in c.segments if hasattr(s, 'circle_params')]
        if not c.closed or not params or len(params) != len(c.segments) or None in params:
            return None
        (cx, cy), r = params[0][0], params[0][1]
        if any(abs(p[1] - r) > 1e-6 or abs(p[0][0] - cx) > 1e-6 or abs(p[0][1] - cy) > 1e-6 for p in params):
            return None
        return (cx, cy), r

    def text_on_arc(self, params: dict | None = None, target: Text | None = None):
        """Texte en arc : le texte `target` ou le texte sélectionné, sinon un nouveau. Distance cordale : l'arc passe
        par le milieu du texte et garde sa longueur pour corde. Rend le texte."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        from .dialogs import ArcTextDialog
        sel = self.canvas.selection
        if target is None and len(sel) == 1 and isinstance(sel[0], Text):
            target = sel[0]
        if target is not None and '\n' in target.text:
            QMessageBox.information(self, tr('Texte en arc'), tr('Un texte en arc tient sur une seule ligne.'))
            return None
        old = dict(target.extra.get('arc') or {}) if target is not None else {}
        circ = None if target is not None else self._circle_of_selection()
        center, radius = circ if circ else (tuple(old.get('center') or self._view_center()), float(old.get('radius', 30.0)))
        if params is None:
            method = old.get('method') or ('angles' if self._ctrl_held() else 'circle' if circ or target is None or old
                                           else 'chord')
            dlg = ArcTextDialog(self, text=target.text if target is not None else '',
                                font=target.font if target is not None else self.settings.value('texte/police', 'Arial'),
                                height=target.size if target is not None else float(self.settings.value('texte/hauteur', 5.0)),
                                spacing=target.spacing if target is not None else 0.0, radius=radius, center=center,
                                method=method, position=old.get('position', 'top'), side=old.get('side', 'outside'),
                                chord=float(old.get('chord', 1.0)), start=float(old.get('start', 135.0)),
                                end=float(old.get('end', 45.0)))
            if not dlg.exec():
                return None
            params = dlg.values()
        v = params
        if not v['text'].strip():
            return None
        method = v.get('method', 'circle')
        arc = {'center': list(v.get('center') or center), 'radius': float(v['radius']), 'position': v['position'],
               'side': v['side'], 'method': method}
        if method == 'angles':
            arc.update(start=float(v['start']), end=float(v['end']))
        elif method == 'chord':
            length = TX.advance(v['text'], v['font'], v['height'], v['spacing'])
            if length <= 0.0:
                QMessageBox.information(self, tr('Texte en arc'), tr('Police introuvable ou texte vide.'))
                return None
            f = max(float(v['chord']), 1e-3)
            ux, uy = TX.arc_direction(v['position'])
            mx, my = self._arc_middle(target, old)
            arc['radius'] = TX.radius_from_chord(length, f)
            arc['center'] = [mx + ux * (f - arc['radius']), my + uy * (f - arc['radius'])]
            arc['chord'] = f
        if target is None:
            tool = self.canvas.selection[0].tool if circ else self.canvas.current_tool_index
            t = Text(text=v['text'], font=v['font'], size=v['height'], align='center', spacing=v['spacing'], tool=tool)
            t.extra['arc'] = arc
            t.outline = TX.outline_for(t)
            self._add_items([t])
            self._arc_tight(t)
            return t
        self.push_undo(tr('Texte en arc'))
        t = target
        t.text, t.font, t.size, t.spacing, t.align = v['text'], v['font'], v['height'], v['spacing'], 'center'
        for k in ('fit', 'box', 'arc_warp'):
            t.extra.pop(k, None)
        t.extra['arc'] = arc
        t.outline = TX.outline_for(t)
        drop_source_object(t)
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()
        self._arc_tight(t)
        return t

    def _arc_tight(self, t) -> None:
        """Entre deux angles trop proches, les lettres se serrent, jusqu'à se chevaucher : on le dit."""
        if 'start' in t.extra['arc'] and t.spacing < 0.0:
            self.statusBar().showMessage(tr('Le texte est plus long que l\'arc : ses lettres se serrent.'), 8000)

    def _arc_middle(self, t, old: dict) -> tuple[float, float]:
        """Le milieu de la ligne de base : celui de la corde d'un arc déjà posé, celui du texte droit, sinon la vue."""
        from ..core import text as TX
        if t is None:
            return self._view_center()
        if old:
            ux, uy = TX.arc_direction(old.get('position', 'top'))
            d = float(old['radius']) - float(old.get('chord', 0.0))
            return old['center'][0] + ux * d, old['center'][1] + uy * d
        bb = t.bbox()
        if not bb:
            return t.matrix.apply((0.0, 0.0))
        m = t.matrix
        rotated = abs(m.b) > 1e-9 or abs(m.c) > 1e-9
        return (bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2 if rotated else m.apply((0.0, 0.0))[1]

    def edit_texts(self, texts: list) -> int:
        """Formulaire commun des textes sélectionnés (double-clic sur l'un d'eux) : les champs modifiés vont à tous, comme
        depuis l'onglet Mise en forme, en un pas d'annulation. Rend le nombre de réglages changés."""
        from ..core import text as TX
        from . import text_presets as TP
        from .dialogs import TextsDialog
        from .textbar import selected_texts
        rows = []
        for t in texts:
            v = TP.values(TX.text_format(t))
            fit = t.extra.get('fit') or {}
            v['fit_width'] = float(fit.get('width', 0.0) or 0.0)
            v['fit_mode'] = fit.get('mode') or 'spacing'
            rows.append(v)
        dlg = TextsDialog(self, rows)
        if not dlg.exec():
            return 0
        ch = dlg.changes()
        if not ch:
            return 0
        keep = list(self.canvas.selection)
        if {id(t) for t in selected_texts(self)} != {id(t) for t in texts}:
            self.canvas.select(texts)                    # l'onglet Mise en forme va aux textes sélectionnés
        bar = self.textbar
        n = 0
        with self.one_undo(tr('Mise en forme des textes')) as step:
            for f in ('font', 'size', 'width', 'italic', 'spacing', 'line_spacing', 'spacing_mode', 'align'):
                if f in ch:
                    n += bool(bar.apply(f, ch[f]))
            if 'fit_width' in ch or 'fit_mode' in ch:    # après l'interlettrage et la largeur, qui la retirent
                n += bool(bar.set_fit(ch.get('fit_width'), ch.get('fit_mode')))
            step['used'] = n > 0
        if [id(x) for x in self.canvas.selection] != [id(x) for x in keep]:
            self.canvas.select(keep)
        self.refresh_text_bars()
        self.statusBar().showMessage(tr('{0} textes : {1} réglage(s) changé(s)').format(len(texts), n), 5000)
        return n

    def edit_text(self, t: Text) -> None:
        from ..core import text as TX
        from ..core.document import drop_source_object
        from .dialogs import TextDialog
        fit = t.extra.get('fit') or {}
        dlg = TextDialog(self, text=t.text, font=t.font, height=t.size, align=t.align,
                         spacing=t.spacing, line_spacing=t.line_spacing,
                         fit_width=fit.get('width', 0.0), fit_mode=fit.get('mode', 'spacing'))
        if not dlg.exec():
            return
        v = dlg.values()
        self.push_undo()
        t.text, t.font, t.size = v['text'], v['font'], v['height']
        if v['line_spacing'] != t.line_spacing:
            t.extra.pop('line_mode', None)               # la valeur donnée remplace le mode d'interligne
        t.align, t.line_spacing = v['align'], v['line_spacing']
        if v['fit']['width'] > 0:
            t.extra['fit'] = v['fit']
        else:
            t.extra.pop('fit', None)
            t.spacing, t.width_ratio = v['spacing'], 1.0
        t.outline = TX.outline_for(t)
        drop_source_object(t)                 # le paragraphe TypeEdit d'origine n'est plus valable
        self.canvas.invalidate([t])
        self._on_selection()
        self._on_doc_changed()

    def replace_font_dialog(self) -> None:
        from .dialogs import FontBox, _buttons
        texts = [t for t in _leaves(self.canvas.selection) if isinstance(t, Text)] or \
            [t for t in self.canvas.doc.iter_leaves() if isinstance(t, Text)]
        if not texts:
            QMessageBox.information(self, tr('Changer la police'), tr('Aucun texte.'))
            return
        dlg = QDialog(self)
        dlg.setWindowTitle(tr('Changer la police'))
        form = QFormLayout(dlg)
        form.addRow(QLabel(tr('{0} texte(s)').format(len(texts))))
        box = FontBox()
        box.setCurrentFont(texts[0].font)
        form.addRow(tr('Police'), box)
        _buttons(dlg, form)
        if dlg.exec():
            self.replace_font(texts, box.currentText())

    def replace_font(self, texts: list, font: str) -> int:
        """Change la police des textes (mis en page à nouveau, à la même
        place) ; un texte TypeEdit devient un texte VectorDrive."""
        from ..core import text as TX
        from ..core.document import drop_source_object
        self.push_undo()
        n = 0
        for t in texts:
            fx = TX.char_fx(t)
            mixed = any('font' in f for f in fx.values())
            if t.font == font and not mixed:
                continue
            if 'vnd_obj' in t.extra:
                t.spacing = 0.0                # interlettrage calé sur l'ancienne police
            t.font = font
            if mixed:                          # tout le texte change : les lettres aussi
                TX.set_char_fx(t, {i: {k: v for k, v in f.items() if k != 'font'} for i, f in fx.items()})
            t.outline = TX.outline_for(t)
            drop_source_object(t)
            n += 1
        self.canvas.invalidate()
        self._on_selection()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} texte(s) changé(s) de police').format(n), 5000)
        return n

    def liquify_params(self):
        """Les réglages retenus du pinceau de Liquéfier."""
        from ..core import liquify as LQ
        last = self.settings.value('cad/liquefier', None)
        return LQ.params_from(last if isinstance(last, dict) else None)

    def liquify_options(self, params: dict | None = None):
        """Les réglages du pinceau ; ils valent aussi pour l'outil en cours et prennent la main sur lui."""
        from dataclasses import asdict
        from ..core import liquify as LQ
        kinds = [('warp', tr('Déformer')), ('twirl', tr('Tordre')), ('pucker', tr('Contracter')), ('bloat', tr('Dilater')),
                 ('scallop', tr('Festonner')), ('crystallize', tr('Cristalliser')), ('wrinkle', tr('Froisser'))]
        cur = asdict(self.liquify_params())
        spec = [('kind', str, cur['kind'], tr('Ce que fait le pinceau')),
                ('width', float, cur['width'], tr('Largeur du pinceau (mm)')),
                ('height', float, cur['height'], tr('Hauteur du pinceau (mm)')),
                ('angle', float, cur['angle'], tr('Angle du pinceau (°)')),
                ('intensity', float, cur['intensity'], tr('Force (0 à 1)')),
                ('detail', float, cur['detail'], tr('Détail ajouté (1 à 10)')),
                ('simplify_on', bool, cur['simplify_on'], tr('Retirer ensuite les points inutiles')),
                ('simplify', float, cur['simplify'], tr('Force du retrait (0 à 100)')),
                ('rate', float, cur['rate'], tr('Tordre : vitesse (°, négatif : l’autre sens)')),
                ('complexity', float, cur['complexity'], tr('Festonner, cristalliser, froisser : complexité (0 à 15)')),
                ('horizontal', float, cur['horizontal'], tr('Froisser : à l’horizontale (0 à 1)')),
                ('vertical', float, cur['vertical'], tr('Froisser : à la verticale (0 à 1)'))]
        p = self._ask('liquefier', tr('Liquéfier'), spec, choices={'kind': kinds}, params=params)
        if p is None:
            return None
        got = LQ.params_from(p)
        self.settings.setValue('cad/liquefier', asdict(got))
        if self.canvas.tool == 'liquify':
            self.canvas.tool_obj.params = got
        else:
            self.set_tool('liquify')
        return got

    def _item_double_clicked(self, item) -> None:
        if isinstance(item, Text) and any(s is item for s in self.canvas.selection):
            from .textbar import selected_texts
            texts = [item] + [t for t in selected_texts(self) if t is not item]   # celui double-cliqué montré
            if len(texts) > 1:                           # plusieurs textes sélectionnés : le formulaire commun
                self.edit_texts(texts)
                return
        if isinstance(item, Shape) and 'script' in item.extra:
            self.edit_script_object(item)
        elif isinstance(item, Shape) and 'sketch' in item.extra:
            self.edit_sketch(item)
        elif isinstance(item, Shape) and self._has_history(item):
            self.solid_history(item)
        elif isinstance(item, Group) and 'codeplate' in item.extra:
            self.edit_code_plate(item)
        elif isinstance(item, Group) and 'barcode' in item.extra:
            self.edit_barcode(item)
        elif isinstance(item, Text) and 'box' in item.extra:
            self.edit_text_box(item)
        elif isinstance(item, Group) and 'text_flow' in item.extra:
            self.text_flow_edit(item)
        elif isinstance(item, Group) and 'braille' in item.extra:
            self.edit_braille(item)
        elif isinstance(item, Group) and 'halftone' in item.extra:
            self.edit_halftone(item)
        elif isinstance(item, Group) and 'graduation' in item.extra:
            self.edit_graduation(item)
        elif isinstance(item, Group) and 'dial' in item.extra:
            self.edit_dial(item)
        elif isinstance(item, Shape) and 'trou' in item.extra:
            self.edit_holes([item])
        elif isinstance(item, Group) and 'hatch' in item.extra:
            self.edit_hatch(item)
        elif isinstance(item, Group) and 'shadow' in item.extra:
            self.edit_shadow(item)
        elif isinstance(item, Group) and 'envelope' in item.extra:
            self.edit_envelope(item)
        elif isinstance(item, Group) and 'path_bend' in item.extra:
            self.bend_edit(item)
        elif isinstance(item, Group) and 'stamp' in item.extra:
            self.edit_stamp(item)
        elif isinstance(item, Group) and 'columns' in item.extra:
            self.edit_columns(item)
        elif isinstance(item, Group) and 'text_columns' in item.extra:
            self.text_table(target=item)
        elif isinstance(item, Group) and 'tolerance' in item.extra and self._is_gdt(item):
            self.canvas.select([item])
            self.gdt_frame(item)
        elif isinstance(item, Text) and item.extra.get('arc'):
            self.text_on_arc(target=item)
        elif isinstance(item, Text) and self.typable(item):
            sp, self.canvas.last_double = getattr(self.canvas, 'last_double', None), None
            at = self.canvas.to_doc(sp) if sp is not None else self._cursor_doc()
            self.type_in_text(item, at, double=True, sp=sp)   # repris dans le dessin, là où il est double-cliqué
        elif isinstance(item, Text):
            self.edit_text(item)
        elif isinstance(item, Group) and 'cote' in item.extra and self._is_dim(item):
            self.canvas.select([item])
            self.edit_dim(item)
        elif isinstance(item, Shape) and self._is_form(item):
            self.canvas.select([item])
            self.edit_form(item)
        elif isinstance(item, Shape):
            self.canvas.select([item])
            self.set_tool('node')

    # --- texte dans un cadre, combiner, répartir ----------------------------------
    def _rect_of_selection(self):
        sel = self.canvas.selection
        if len(sel) == 1 and isinstance(sel[0], Shape) and len(sel[0].path.contours) == 1 \
                and sel[0].path.contours[0].closed:
            return sel[0].bbox()
        return None

    def text_in_box(self, box=None, params: dict | None = None):
        """Texte dans un rectangle : `box`, la forme fermée sélectionnée, sinon glissé à la souris (F2 : en chiffres).
        Rend le texte."""
        from ..core import text as TX
        from .dialogs import BoxTextDialog
        chosen = self._rect_of_selection()
        bb = box or chosen
        if bb is None:
            from . import tools as T
            self.canvas.tool = 'pick_point'
            self.canvas.snap.clear_tracking()
            self.canvas.tool_obj = T.DragRectTool(self.canvas, lambda b: self.text_in_box(b), self._text_box_numeric,
                                                  tr('Glissez le rectangle du texte ; F2 : ses dimensions en chiffres'))
            self.canvas.setCursor(self.canvas.tool_obj.cursor)
            return None
        if params is None:
            dlg = BoxTextDialog(self, font=self.settings.value('texte/police', 'Arial'))
            if not dlg.exec():
                return None
            params = dlg.values()
        v = params
        if not v['text'].strip():
            return None
        tool = self.canvas.selection[0].tool if chosen and box is None else self.canvas.current_tool_index
        t = Text(text=v['text'], font=v['font'], align=v['align'], line_spacing=v['line_spacing'], tool=tool)
        t.extra['box'] = {'x0': bb[0], 'y0': bb[1], 'x1': bb[2], 'y1': bb[3], 'stretch': bool(v.get('stretch')),
                          'compress': bool(v.get('compress')), 'middle': True}
        t.outline = TX.outline_for(t)
        if not t.outline:
            QMessageBox.information(self, tr('Texte dans un rectangle'), tr('Police introuvable ou cadre vide.'))
            return None
        self._add_items([t])
        return t

    def _text_box_numeric(self):
        """F2 pendant le tracé : largeur, hauteur, un des 9 points du cadre et ses coordonnées. Rend le rectangle."""
        from .dialogs import _buttons, _spin
        s = self.settings
        cx, cy = self._view_center()
        dlg = QDialog(self)
        dlg.setWindowTitle(tr('Rectangle'))
        form = QFormLayout(dlg)
        w = _spin(float(s.value('texte/cadre_l', 60.0)), 0.01, 100000)
        h = _spin(float(s.value('texte/cadre_h', 20.0)), 0.01, 100000)
        grid = ReferenceGrid(lambda _p: None)
        x, y = _spin(cx, -1000000, 1000000), _spin(cy, -1000000, 1000000)
        form.addRow(tr('Largeur'), w)
        form.addRow(tr('Hauteur'), h)
        form.addRow(tr('Référence'), grid)
        form.addRow('X', x)
        form.addRow('Y', y)
        _buttons(dlg, form)
        self.last_box_numeric = (w, h, grid, x, y)
        if not dlg.exec():
            return None
        s.setValue('texte/cadre_l', w.value())
        s.setValue('texte/cadre_h', h.value())
        fx, fy = grid.point()
        x0, y0 = x.value() - fx * w.value(), y.value() - fy * h.value()
        return (x0, y0, x0 + w.value(), y0 + h.value())

    def _flow_spec(self, v: dict):
        from ..core.textflow import FlowSpec
        return FlowSpec(size=float(v['size']), fit=bool(v['fit']), line_spacing=float(v['line_spacing']),
                        margin=float(v['margin']), align=str(v['align']), middle=bool(v['middle']))

    def _flow_report(self, got) -> None:
        msg = tr('{0} ligne(s), hauteur {1:.2f} mm').format(len(got.lines), got.size)
        if got.rest:
            msg += ' — ' + tr('{0} mot(s) sans place').format(len(got.rest.split()))
        self.statusBar().showMessage(msg, 10000)

    def _flow_refused(self, got=None) -> None:
        title = tr('Texte dans une forme')
        if got is None:
            QMessageBox.information(self, title, tr('Cette forme est trop petite pour la marge demandée.'))
        else:
            QMessageBox.information(self, title, tr('Rien ne tient dans la forme : réduisez la taille ou la marge.'))

    def text_in_shape(self, params: dict | None = None):
        """Le texte, repris d'un texte sélectionné ou saisi, coule dans la plus grande forme fermée sélectionnée, en
        contournant les autres. Rend le groupe."""
        from ..core import textflow as TF
        from ..core.hatch import closed_path
        from .textflow_dialog import TextFlowDialog
        title = tr('Texte dans une forme')
        sel = list(self.canvas.selection)
        shapes = [it for it in sel if isinstance(it, (Shape, Group))]
        sources = [it for it in sel if isinstance(it, Text)]
        closed = [(it, closed_path([it])) for it in shapes]
        closed = [(it, path) for it, path in closed if path is not None and path.contours and path.bbox()]

        def extent(pair) -> float:
            box = pair[1].bbox()
            return (box[2] - box[0]) * (box[3] - box[1])
        target, region = max(closed, key=extent) if closed else (None, None)
        obstacles = [path for it, path in closed if it is not target]
        if region is None or not region.contours:
            QMessageBox.information(self, title, tr('Sélectionnez une forme fermée, et le texte à y mettre s’il existe déjà.'))
            return None
        text = '\n'.join(t.text for t in sources)
        font = sources[0].font if sources else self.settings.value('texte/police', 'Arial')
        size = sources[0].size if sources else 5.0
        if params is None:
            dlg = TextFlowDialog(self, text=text, font=font, spec=TF.FlowSpec(size=size),
                                 gap=float(self.settings.value('cad/flow_gap', 2.0)) if obstacles else None)
            if not dlg.exec():
                return None
            params = dlg.values()
            if 'gap' in params:
                self.settings.setValue('cad/flow_gap', params['gap'])
        text, font = params.get('text', text), params.get('font', font)
        if not text.strip():
            return None
        spec = self._flow_spec({'size': size, 'fit': False, 'line_spacing': 1.2, 'margin': 1.0, 'align': 'center',
                                'middle': True, **params})
        try:
            if obstacles:
                region = TF.carve(region, obstacles, float(params.get('gap', 2.0)))
            g, got = TF.build(text, font, region, spec, tool=target.tool)
        except ValueError:
            self._flow_refused()
            return None
        if g is None:
            self._flow_refused(got)
            return None
        g.name = title
        doc = self.canvas.doc
        self.push_undo()
        layer = doc.layer_of(target) or doc.active_layer
        layer.items.append(g)
        for t in sources:
            owner = doc.layer_of(t)
            if owner is not None:
                owner.items.remove(t)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()
        self._flow_report(got)
        return g

    def text_flow_edit(self, g: Group, params: dict | None = None):
        """Double-clic : reprend le texte et les réglages ; la forme reste celle du groupe."""
        from ..core import textflow as TF
        from .textflow_dialog import TextFlowDialog
        d = g.extra['text_flow']
        if params is None:
            dlg = TextFlowDialog(self, text=d.get('text', ''), font=d.get('font', 'Arial'), spec=TF.FlowSpec.from_dict(d))
            if not dlg.exec():
                return None
            params = dlg.values()
        text, font = params.get('text', d.get('text', '')), params.get('font', d.get('font', 'Arial'))
        if not text.strip():
            return None
        spec = self._flow_spec({**TF.FlowSpec.from_dict(d).to_dict(), **params})
        try:
            new, got = TF.rebuild(g, text, font, spec)
        except ValueError:
            self._flow_refused()
            return None
        if new is None:
            self._flow_refused(got)
            return None
        new.name = g.name
        self.push_undo()
        out = self._replace_in_layers([g], {id(g): [new]})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        self._flow_report(got)
        return new

    def _columns_dialog(self, n: int, gutter: float):
        from dataclasses import dataclass
        from .dialogs import ParamsDialog

        @dataclass
        class Spec:
            columns: int = n
            gutter: float = gutter
        dlg = ParamsDialog(self, tr('En colonnes'), Spec(), {'columns': tr('Nombre de colonnes'),
                                                             'gutter': tr('Écart entre colonnes (mm)')})
        if not dlg.exec():
            return None
        v = dlg.result_params()
        return max(1, v.columns), max(0.0, v.gutter)

    def _columns_group(self, t: Text, n: int, gutter: float) -> Group:
        from ..core import text as TX
        g = Group(children=TX.columns(t, n, gutter), tool=t.tool, name=tr('Colonnes'))
        g.extra['columns'] = {'n': n, 'gutter': gutter}
        return g

    def text_columns(self) -> None:
        sel = self.canvas.selection
        if len(sel) != 1 or not isinstance(sel[0], Text) or '\n' not in sel[0].text:
            QMessageBox.information(self, tr('En colonnes'), tr('Sélectionnez un texte de plusieurs lignes.'))
            return
        r = self._columns_dialog(int(self.settings.value('colonnes/nombre', 2)),
                                 float(self.settings.value('colonnes/ecart', 5.0)))
        if r is None:
            return
        self.settings.setValue('colonnes/nombre', r[0])
        self.settings.setValue('colonnes/ecart', r[1])
        self._replace_selection([self._columns_group(sel[0], *r)])

    def edit_columns(self, g: Group) -> None:
        texts = [c for c in g.children if isinstance(c, Text)]
        if not texts:
            return
        r = self._columns_dialog(int(g.extra['columns'].get('n', 2)), float(g.extra['columns'].get('gutter', 5.0)))
        if r is None:
            return
        import copy as _copy
        t = _copy.copy(texts[0])
        t.text = '\n'.join(c.text for c in texts)
        new = self._columns_group(t, *r)
        self.push_undo()
        out = self._replace_in_layers([g], {id(g): [new]})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def text_table(self, spec=None, target: Group | None = None):
        """Texte en colonnes : un nouveau, à partir du texte sélectionné s'il y en a un (ses lignes dans la première colonne),
        ou le groupe `target` à refaire. Rend le groupe."""
        from ..core import textcolumns as TC
        from .text_columns_dialog import TextColumnsDialog
        doc = self.canvas.doc
        sel = self.canvas.selection
        source = sel[0] if target is None and len(sel) == 1 and isinstance(sel[0], Text) else None
        moved = (0.0, 0.0)
        if target is not None:
            old = TC.TextColumns.from_dict(target.extra['text_columns'])
            a, b = TC.build(old).bbox(), target.bbox()
            if a and b:                                  # le groupe a pu être déplacé depuis
                moved = (b[0] - a[0], b[1] - a[1])
                old.x += moved[0]
                old.y += moved[1]
        else:
            old = TC.TextColumns(border_tool=self.canvas.current_tool_index)
            cx, cy = self._view_center()
            old.x, old.y = cx, cy
            if source is not None:
                old.font, old.height = source.font, source.size
                old.x, old.y = source.matrix.apply((0.0, 0.0))
                TC.seed_from_lines(old, source.text.split('\n'))
        if spec is None:
            tools = [(i, f'{i + 1} — {t.name}') for i, t in enumerate(doc.tools)]
            dlg = TextColumnsDialog(self, old, tools, ReferenceGrid)
            self.last_text_table = dlg
            if not dlg.exec():
                return None
            spec = dlg.spec()
        g = TC.build(spec, tool=target.tool if target is not None else self.canvas.current_tool_index, name=tr('Texte en colonnes'))
        if not g.children:
            QMessageBox.information(self, tr('Texte en colonnes'), tr('Il n’y a ni texte ni bordure à poser.'))
            return None
        replaced = target if target is not None else source
        if replaced is None:
            self._add_items([g])
            return g
        self.push_undo(tr('Texte en colonnes'))
        out = self._replace_in_layers([replaced], {id(replaced): [g]})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        return g

    def edit_text_box(self, t: Text) -> None:
        from ..core import text as TX
        from ..core.document import drop_source_object
        from .dialogs import BoxTextDialog
        b = t.extra['box']
        dlg = BoxTextDialog(self, text=t.text, font=t.font, align=t.align, line_spacing=t.line_spacing,
                            stretch=b.get('stretch', False), width=b['x1'] - b['x0'], height=b['y1'] - b['y0'],
                            compress=b.get('compress', False))
        if not dlg.exec():
            return
        v = dlg.values()
        self.push_undo()
        t.text, t.font, t.align, t.line_spacing = v['text'], v['font'], v['align'], v['line_spacing']
        cx, cy = (b['x0'] + b['x1']) / 2, (b['y0'] + b['y1']) / 2
        t.extra['box'] = {'x0': cx - v['width'] / 2, 'y0': cy - v['height'] / 2,
                          'x1': cx + v['width'] / 2, 'y1': cy + v['height'] / 2, 'stretch': v['stretch'],
                          'compress': v['compress'], 'middle': b.get('middle', False)}
        t.outline = TX.outline_for(t)
        drop_source_object(t)
        self.canvas.invalidate([t])
        self._on_selection()
        self._on_doc_changed()

    def _replace_in_layers(self, old: list, new_by_old: dict) -> list:
        """Remplace des objets de premier niveau (même calque, même rang)."""
        ids = {id(o) for o in old}
        out = []
        for L in self.canvas.doc.layers:
            items = []
            for it in L.items:
                if id(it) in ids:
                    rep = new_by_old.get(id(it), [])
                    items.extend(rep)
                    out.extend(rep)
                else:
                    items.append(it)
            L.items = items
        return out

    def combine_items(self) -> None:
        if self._ctrl_on('combine'):                     # TypeEdit : Ctrl + Combiner groupe
            self.group()
            return
        from ..core import combine as C
        sel = list(self.canvas.selection)
        if len(sel) < 2:
            return
        sh = C.combine(sel)
        if sh is None:
            return
        self.push_undo()
        out = self._replace_in_layers(sel, {id(sel[0]): [sh]})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def uncombine_items(self) -> None:
        if self._ctrl_on('uncombine'):                   # TypeEdit : Ctrl + Décombiner dégroupe
            self.ungroup()
            return
        from ..core import combine as C
        sel = list(self.canvas.selection)
        rep = {id(it): C.uncombine(it) for it in sel}
        if not sel or all(len(v) <= 1 for v in rep.values()):
            return
        self.push_undo()
        out = self._replace_in_layers(sel, rep)
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def explode_step(self) -> str:
        """S : un niveau de moins à chaque appui — les groupes de la sélection
        dégroupés ; sinon chaque forme à plusieurs contours extérieurs séparée
        en pièces (extérieur et ses trous) ; sinon chaque contour seul. Rend
        l'étape faite ('groupes', 'pieces', 'contours' ou '')."""
        from ..core import combine as C
        sel = list(self.canvas.selection)
        if any(isinstance(s, Group) for s in sel):
            self.ungroup()
            others = [s for s in sel if not isinstance(s, Group)]
            if others:
                self.canvas.select(list(self.canvas.selection) + others)
            self.statusBar().showMessage(tr('Groupes dégroupés (S : niveau suivant)'), 4000)
            return 'groupes'
        shapes = [s for s in sel if isinstance(s, Shape) and len(s.path.contours) > 1]
        if not shapes:
            return ''
        pieces = {}
        for s in shapes:
            parts = C.combine_nested([s])
            if len(parts) > 1:
                pieces[id(s)] = parts
        if pieces:
            step, rep = 'pieces', pieces
        else:
            step, rep = 'contours', {id(s): C.uncombine(s) for s in shapes}
        self.push_undo()
        out = self._replace_in_layers(shapes, rep) + [s for s in sel if id(s) not in rep]
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('Formes séparées en pièces (extérieur et trous) — S : chaque contour seul')
                                     if step == 'pieces' else tr('Contours séparés'), 4000)
        return step

    def combine_nested_items(self) -> None:
        from ..core import combine as C
        sel = list(self.canvas.selection)
        if not sel:
            return
        shapes = C.combine_nested(sel)
        if not shapes:
            return
        self.push_undo()
        out = self._replace_in_layers(sel, {id(sel[0]): shapes})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} forme(s) : contours extérieurs avec leurs trous').format(len(shapes)), 5000)

    def distribute_items(self, kind: str) -> None:
        from ..core import combine as C
        sel = list(self.canvas.selection)
        if len(sel) < 3:
            QMessageBox.information(self, tr('Répartir'), tr('Sélectionnez au moins trois objets.'))
            return
        axis = 'x' if kind in ('h', 'hc') else 'y'
        mode = 'centers' if kind in ('hc', 'vc') else 'gaps'
        moved = C.distribute(sel, axis, mode)
        self.push_undo()
        out = self._replace_in_layers(sel, {id(a): [b] for a, b in zip(sel, moved)})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def space_items(self, kind: str) -> None:
        """Espacement imposé entre les objets (le premier reste en place)."""
        from dataclasses import dataclass
        from ..core import combine as C
        from .dialogs import ParamsDialog
        sel = list(self.canvas.selection)
        if len(sel) < 2:
            QMessageBox.information(self, tr('Espacer'), tr('Sélectionnez au moins deux objets.'))
            return

        @dataclass
        class Spec:
            gap: float = float(self.settings.value('espacer/ecart', 2.0))
        dlg = ParamsDialog(self, tr('Espacer'), Spec(), {'gap': tr('Écart entre les objets (mm)')})
        if not dlg.exec():
            return
        gap = dlg.result_params().gap
        self.settings.setValue('espacer/ecart', gap)
        self._apply_moved(sel, C.space_fixed(sel, 'x' if kind == 'h' else 'y', gap))

    def same_size_items(self, which: str) -> None:
        """Largeur, hauteur ou taille de l'objet sélectionné en premier, comme TypeEdit."""
        from ..core import combine as C
        sel = list(self.canvas.selection)
        if len(sel) < 2:
            QMessageBox.information(self, tr('Même taille'), tr('Sélectionnez au moins deux objets, la référence en premier.'))
            return
        self._apply_moved(sel, C.same_size(sel, which, 0, keep_ratio=bool(self.settings.value('meme_taille/proportions', False)
                                                                              in (True, 'true'))))

    def _apply_moved(self, sel, moved) -> None:
        self.push_undo()
        out = self._replace_in_layers(sel, {id(a): [b] for a, b in zip(sel, moved)})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    # --- braille, photo -------------------------------------------------------------
    def _replace_keep_corner(self, old: Group, new: Group) -> None:
        """Remplace un objet par sa version recalculée, coin haut gauche gardé."""
        ob, nb = old.bbox(), new.bbox()
        new = new.transformed(Affine.translation(ob[0] - nb[0], ob[3] - nb[3]))
        self.push_undo()
        out = self._replace_in_layers([old], {id(old): [new]})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def _place_centered(self, g: Group) -> None:
        bb = g.bbox()
        cx, cy = self._view_center()
        self._add_items([g.transformed(Affine.translation(cx - (bb[0] + bb[2]) / 2, cy - (bb[1] + bb[3]) / 2))])

    def _place_curve(self, path) -> Shape:
        """Le tracé sur l'outil courant, au centre de la vue."""
        s = Shape(path=path, tool=self.canvas.current_tool_index)
        self._place_centered(s)
        return self.canvas.selection[0]

    def equation_curve(self, params: dict | None = None, exec_dialog: bool = True):
        """Courbe tirée de formules ; `params` : kind, first, second, start, end (essais). Rend la forme, ou la fenêtre
        si `exec_dialog` est faux."""
        from ..core import equation as EQ
        from .curves_dialog import EquationDialog
        if params is not None:
            return self._place_curve(EQ.equation_path(params['kind'], params['first'], params.get('second', ''),
                                                      params['start'], params['end']))
        dlg = EquationDialog(self, self.settings.value('cad/equation', None))
        if not exec_dialog:
            return dlg
        if not dlg.exec():
            return None
        self.settings.setValue('cad/equation', dlg.values())
        return self._place_curve(dlg.result)

    def guilloche_dialog(self, spec=None, exec_dialog: bool = True):
        """Motif de guilloché ; `spec` : GuillocheSpec (essais). Rend la forme, ou la fenêtre si `exec_dialog` est faux."""
        from ..core import equation as EQ
        from .curves_dialog import GuillocheDialog
        if spec is not None:
            return self._place_curve(EQ.guilloche(spec))
        dlg = GuillocheDialog(self, self.settings.value('cad/guilloche', None))
        if not exec_dialog:
            return dlg
        if not dlg.exec():
            return None
        self.settings.setValue('cad/guilloche', dlg.values())
        return self._place_curve(dlg.result)

    def new_braille(self) -> None:
        from ..core import braille as BR
        from .dialogs import BrailleDialog
        dlg = BrailleDialog(self)
        if dlg.exec():
            self._place_centered(BR.build(dlg.result_spec(), self.canvas.current_tool_index))

    def edit_braille(self, g: Group) -> None:
        from ..core import braille as BR
        from .dialogs import BrailleDialog
        dlg = BrailleDialog(self, BR.BrailleSpec.from_dict(g.extra['braille']))
        if dlg.exec():
            self._replace_keep_corner(g, BR.build(dlg.result_spec(), g.tool))

    def _halftone_from(self, spec, tool: int):
        from ..core import halftone as HT
        from .dialogs import load_gray
        from .progress import run
        return run(self, tr('Photo en points'), HT.build, load_gray(spec.source), spec, tool)

    #: vectorisation en arcs : écart permis aux courbes (mm)
    ARC_TOL = 0.02

    TRACE_LABELS = {'threshold': 'Seuil (0 à 1, négatif = automatique)', 'invert': 'Encre claire sur fond sombre',
                    'speckle': 'Taches ignorées (aire en pixels)', 'tolerance': 'Écart de simplification (pixels)',
                    'corner_angle': 'Angle des coins (°)', 'smooth': 'Courbes entre les coins',
                    'centerline': 'Trait central (gravure en un passage)',
                    'min_length': 'Trait central : barbules ignorées (pixels)',
                    'arcs': 'En arcs et segments (au lieu de courbes de Bézier)',
                    'segment': 'Longueur des segments (mm, 0 = automatique)',
                    'curvature': 'Courbure continue (lissage C∞)',
                    'smoothing': 'Force du lissage (pixels)',
                    'colors': 'Couleurs cherchées (1 : noir et blanc)',
                    'keep_background': 'Couleurs : tracer aussi le fond'}

    def trace_image(self) -> None:
        """Vectorise l'image sélectionnée (contours posés dessus) ou un
        fichier image (largeur demandée, centré dans la vue)."""
        from dataclasses import make_dataclass
        from PySide6.QtGui import QImage
        from ..core import trace as TR
        from ..core.document import Image
        from ..core.geom import Path
        from .canvas import dib_to_qimage
        from .dialogs import ParamsDialog, qimage_gray, qimage_rgb
        sel = [it for it in self.canvas.selection if isinstance(it, Image)]
        s = self.settings
        spec = TR.TraceSpec(threshold=float(s.value('vectorisation/seuil', -1.0)),
                            speckle=float(s.value('vectorisation/taches', 4.0)),
                            tolerance=float(s.value('vectorisation/ecart', 0.8)),
                            corner_angle=float(s.value('vectorisation/coins', 60.0)),
                            smooth=s.value('vectorisation/lissage', 'true') in (True, 'true'),
                            centerline=s.value('vectorisation/central', 'false') in (True, 'true'),
                            min_length=float(s.value('vectorisation/barbules', 3.0)),
                            arcs=s.value('vectorisation/arcs', 'false') in (True, 'true'),
                            segment=float(s.value('vectorisation/segment', 0.0)),
                            curvature=s.value('vectorisation/courbure', 'false') in (True, 'true'),
                            smoothing=float(s.value('vectorisation/lissage_force', 2.0)),
                            colors=int(s.value('vectorisation/couleurs', 1)),
                            keep_background=s.value('vectorisation/fond', 'false') in (True, 'true'))
        labels = {k: tr(v) for k, v in self.TRACE_LABELS.items()}
        if sel:
            im = sel[0]
            q = dib_to_qimage(im.data) if im.fmt == 'dib' else QImage.fromData(im.data)
            if q is None or q.isNull():
                QMessageBox.warning(self, tr('Vectoriser'), tr('Image illisible.'))
                return
            params = spec
        else:
            path, _ = QFileDialog.getOpenFileName(self, tr('Vectoriser'), self._last_dir('image'),
                                                  tr('Images (*.png *.jpg *.jpeg *.bmp *.gif *.tif *.tiff)'))
            if not path:
                return
            self._remember_dir('image', path)
            from ..io import raster
            try:
                q, _orig, _note = raster.load_image(path)  # grandes images comprises (limite de Qt levée)
            except ValueError as ex:
                QMessageBox.warning(self, tr('Vectoriser'), str(ex))
                return
            P = make_dataclass('P', [(k, type(getattr(spec, k))) for k in self.TRACE_LABELS] + [('width', float)])
            params = P(*[getattr(spec, k) for k in self.TRACE_LABELS], float(s.value('vectorisation/largeur', 50.0)))
            labels['width'] = tr('Largeur du dessin (mm)')
        dlg = ParamsDialog(self, tr('Vectoriser'), params, labels)
        if not dlg.exec():
            return
        r = dlg.result_params()
        spec = TR.TraceSpec(**{k: getattr(r, k) for k in self.TRACE_LABELS})
        for key, v in (('seuil', spec.threshold), ('taches', spec.speckle), ('ecart', spec.tolerance),
                       ('coins', spec.corner_angle), ('lissage', spec.smooth),
                       ('central', spec.centerline), ('barbules', spec.min_length), ('arcs', spec.arcs),
                       ('segment', spec.segment), ('courbure', spec.curvature),
                       ('lissage_force', spec.smoothing), ('couleurs', spec.colors),
                       ('fond', spec.keep_background)):
            s.setValue(f'vectorisation/{key}', v)
        from .progress import Cancelled, run
        multi = spec.colors > 1 and not spec.centerline
        try:
            if multi:
                rgb, real = qimage_rgb(q, max_side=2500)
                size = rgb.shape[:2]
            else:
                gray = qimage_gray(q, max_side=2500)
                size = gray.shape
            if spec.segment > 0:                          # mm → pixels de l'image analysée
                import math
                mm_w = math.hypot(sel[0].matrix.a, sel[0].matrix.b) if sel else max(0.1, r.width)
                spec.segment = spec.segment * size[1] / max(mm_w, 1e-9)
            if multi:
                layers = run(self, tr('Vectorisation'), TR.trace_colors, rgb, spec, real)
                contours = [c for _col, cs in layers for c in cs]
            else:
                contours = run(self, tr('Vectorisation'), TR.trace_centerline if spec.centerline else TR.trace, gray, spec)
        except Cancelled:
            return
        except ValueError as ex:
            QMessageBox.warning(self, tr('Vectoriser'), str(ex))
            return
        if not contours:
            QMessageBox.information(self, tr('Vectoriser'), tr('Aucun contour trouvé (essayer un autre seuil).'))
            return
        H, W = size
        if sel:
            m = sel[0].matrix @ Affine(1 / W, 0, 0, 1 / H, 0, 0)
            tool = sel[0].tool
        else:
            width = max(0.1, r.width)
            s.setValue('vectorisation/largeur', width)
            height = width * H / W
            cx, cy = self._view_center()
            m = Affine(width / W, 0, 0, -height / H, cx - width / 2, cy + height / 2)
            tool = self.canvas.current_tool_index
        def placed(cs):
            p = Path([c.transformed(m) for c in cs])
            if spec.arcs:                                 # arcs de cercle et droites, à 0,02 mm près
                from ..core.biarc import to_arcs
                p = to_arcs(p, self.ARC_TOL)
            return p
        if multi:
            self._add_traced_colors([(col, placed(cs)) for col, cs in layers])
            self.statusBar().showMessage(tr('{0} contour(s) tracé(s) en {1} couleur(s)').format(len(contours), len(layers)),
                                         6000)
            return
        shape = Shape(path=placed(contours), tool=tool, name=tr('Vectorisation'))
        self._add_items([shape])
        self.statusBar().showMessage(tr('{0} contour(s) tracé(s)').format(len(contours)), 6000)

    def _add_traced_colors(self, layers: list) -> Group:
        """Une forme remplie par couleur, sur l'outil de cette couleur (repris, ou ajouté au dessin), en un groupe."""
        doc = self.canvas.doc
        self.push_undo(tr('Vectoriser'))
        shapes = [Shape(path=p, tool=k, filled=True, name=col) for k, (col, p) in enumerate(layers)]
        doc.adopt_tool_colors(shapes, {k: col for k, (col, _p) in enumerate(layers)})
        g = Group(children=shapes, name=tr('Vectorisation'), tool=shapes[0].tool)
        doc.add(g)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()
        return g

    def new_halftone(self) -> None:
        from .dialogs import HalftoneDialog
        dlg = HalftoneDialog(self)
        if not dlg.exec():
            return
        from .progress import Cancelled
        try:
            g = self._halftone_from(dlg.result_spec(), self.canvas.current_tool_index)
        except Cancelled:
            return
        except Exception as ex:
            QMessageBox.critical(self, tr('Photo (trame)'), str(ex))
            return
        self._place_centered(g)

    def edit_halftone(self, g: Group) -> None:
        from ..core import halftone as HT
        from .dialogs import HalftoneDialog
        dlg = HalftoneDialog(self, HT.HalftoneSpec.from_dict(g.extra['halftone']))
        if not dlg.exec():
            return
        from .progress import Cancelled
        try:
            new = self._halftone_from(dlg.result_spec(), g.tool)
        except Cancelled:
            return
        except Exception as ex:
            QMessageBox.critical(self, tr('Photo (trame)'), str(ex))
            return
        self._replace_keep_corner(g, new)

    # --- ordre, gel, masquage --------------------------------------------------------
    def reorder(self, kind: str) -> None:
        """Ordre dans le calque de chaque objet sélectionné (l'ordre de la
        liste est celui du dessin et de l'usinage)."""
        sel = {id(s) for s in self.canvas.selection}
        if not sel:
            return
        self.push_undo()
        for L in self.canvas.doc.layers:
            items = L.items
            picked = [it for it in items if id(it) in sel]
            if not picked:
                continue
            rest = [it for it in items if id(it) not in sel]
            if kind == 'front':
                L.items = rest + picked
            elif kind == 'back':
                L.items = picked + rest
            else:
                items = list(items)
                rng = range(len(items) - 2, -1, -1) if kind == 'forward' else range(1, len(items))
                for i in rng:
                    j = i + 1 if kind == 'forward' else i - 1
                    if id(items[i]) in sel and id(items[j]) not in sel:
                        items[i], items[j] = items[j], items[i]
                L.items = items
        self.canvas.invalidate()
        self._on_doc_changed()

    def _set_flag(self, items, attr: str, value: bool) -> None:
        for it in items:
            setattr(it, attr, value)

    def freeze_selection(self) -> None:
        """Geler / dégeler (TypeEdit) : la sélection se gèle, les objets gelés désignés au clic se dégèlent."""
        sel, thawed = list(self.canvas.selection), self.canvas.frozen_selected()
        if not sel and not thawed:
            return
        self.push_undo()
        self._set_flag(sel, 'locked', True)
        self._set_flag(thawed, 'locked', False)
        self.canvas.select(thawed)
        self.canvas.invalidate()
        self._on_doc_changed()
        if sel:
            self.statusBar().showMessage(tr('{0} objet(s) gelé(s)').format(len(sel)), 4000)
        else:
            self.statusBar().showMessage(tr('{0} objet(s) dégelé(s)').format(len(thawed)), 4000)

    def unfreeze_all(self) -> None:
        items = [it for L in self.canvas.doc.layers for it in L.items if it.locked]
        if not items:
            return
        self.push_undo()
        self._set_flag(items, 'locked', False)
        self.canvas.select(items)
        self._on_doc_changed()

    def hide_selection(self) -> None:
        sel = list(self.canvas.selection)
        if not sel:
            return
        self.push_undo()
        self._set_flag(sel, 'visible', False)
        self.canvas.select([])
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} objet(s) masqué(s)').format(len(sel)), 4000)

    def compare_dialog(self):
        """Comparer le dessin affiché à un autre onglet ou à un fichier lu du
        disque ; rend la comparaison (None si abandon)."""
        from PySide6.QtWidgets import QInputDialog
        others = [i for i in range(len(self.docs)) if i != self.doc_index]
        disk = tr('Fichier sur le disque…')
        choice = disk
        if others:
            names = [self.docs[i].name() for i in others] + [disk]
            choice, ok = QInputDialog.getItem(self, tr('Comparer'), tr('Comparer le dessin affiché à :'),
                                              names, 0, False)
            if not ok:
                return None
        if choice != disk:
            i = others[[self.docs[j].name() for j in others].index(choice)]
            return self.compare_with(self.docs[i].doc, self.docs[i].name())
        path, _f = QFileDialog.getOpenFileName(self, tr('Comparer à'), self._last_dir('ouvrir'),
                                               registry.filter_string())
        if not path:
            return None
        from .progress import Cancelled, run
        try:
            other = run(self, tr('Lecture de {0}').format(pathlib.Path(path).name), registry.open_document, path)
            self._after_read(other, path)
        except Cancelled:
            return None
        except Exception as ex:
            QMessageBox.critical(self, tr('Ouverture impossible'), f'{pathlib.Path(path).name}\n\n{ex}')
            return None
        return self.compare_with(other, pathlib.Path(path).name)

    def compare_with(self, other, name: str = ''):
        """Comparaison du dessin affiché avec le document `other`, montrée en
        couleurs sur le canevas ; la première zone est montrée."""
        from ..core import compare as CM
        res = CM.compare(self.canvas.doc, other, name)
        res.doc = self.canvas.doc
        self.canvas.compare = res
        self.canvas._cmp_q = {}
        for k in ('compare_next', 'compare_prev', 'compare_close'):
            self.A[k].setEnabled(bool(res.regions) or k == 'compare_close')
        if res.regions:
            self.compare_step(1)
        else:
            self.canvas.update()
        msg = tr('Comparaison avec {0} : {1} ajouté(s) (vert), {2} enlevé(s) (rouge), {3} modifié(s) (orange), '
                 '{4} identique(s)').format(name, len(res.added), len(res.removed), len(res.changed), res.common)
        if not res.differences():
            msg = tr('Comparaison avec {0} : aucune différence ({1} objet(s))').format(name, res.common)
        self.statusBar().showMessage(msg, 15000)
        return res

    def compare_step(self, d: int):
        """Zone de différences suivante (1) ou précédente (-1) : cadrée."""
        res = self.canvas.compare
        if res is None or res.doc is not self.canvas.doc:
            return None
        box = res.step(d)
        if box is None:
            return None
        x0, y0, x1, y1 = box
        pad = max(0.25 * max(x1 - x0, y1 - y0), 2.0)
        self.canvas.fit((x0 - pad, y0 - pad, x1 + pad, y1 + pad))
        self.statusBar().showMessage(tr('Différences : zone {0} sur {1}').format(res.at + 1, len(res.regions)), 6000)
        return box

    def compare_close(self) -> bool:
        if self.canvas.compare is None:
            return False
        self.canvas.compare = None
        self.canvas._cmp_q = {}
        for k in ('compare_next', 'compare_prev', 'compare_close'):
            self.A[k].setEnabled(False)
        self.canvas.update()
        return True

    ISOLATED = 'isole'

    def isolate(self) -> int:
        """Isoler : les objets visibles hors sélection sont masqués et marqués
        (Fin d'isolement les réaffiche, sans toucher aux objets masqués avant)."""
        sel = {id(it) for it in self.canvas.selection}
        if not sel:
            self.statusBar().showMessage(tr('Sélectionnez les objets à isoler.'), 5000)
            return 0
        others = [it for L in self.canvas.doc.layers for it in L.items if it.visible and id(it) not in sel]
        if not others:
            return 0
        self.push_undo()
        for it in others:
            it.visible = False
            it.extra[self.ISOLATED] = True
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} objet(s) masqué(s) le temps de l\'isolement').format(len(others)), 5000)
        return len(others)

    def unisolate(self) -> int:
        items = [it for L in self.canvas.doc.layers for it in L.items if it.extra.get(self.ISOLATED)]
        if not items:
            return 0
        self.push_undo()
        for it in items:
            it.visible = True
            it.extra.pop(self.ISOLATED, None)
        self.canvas.invalidate()
        self._on_doc_changed()
        return len(items)

    def show_all(self) -> None:
        items = [it for L in self.canvas.doc.layers for it in L.items if not it.visible]
        if not items:
            return
        self.push_undo()
        self._set_flag(items, 'visible', True)
        self.canvas.select(items)
        self.canvas.invalidate()
        self._on_doc_changed()

    # --- rogner ---------------------------------------------------------------------------
    @staticmethod
    def _closed_path(item):
        """Le tracé d'un objet fait seulement de contours fermés (forme, forme combinée, groupe), sinon None."""
        leaves = list(_leaves([item]))
        if not leaves or not all(isinstance(s, Shape) and s.path.contours and all(c.closed for c in s.path.contours)
                                 for s in leaves):
            return None
        return geom.Path([c for s in leaves for c in s.path.contours])

    def _frame_in(self, sel: list) -> tuple:
        """(cadre, objets) : le cadre est sélectionné en premier (TypeEdit) ; si le premier n'est pas fermé, c'est le dernier."""
        if len(sel) >= 2:
            if self._closed_path(sel[0]) is not None:
                return sel[0], sel[1:]
            if self._closed_path(sel[-1]) is not None:
                return sel[-1], sel[:-1]
        return None, sel

    def _cut_options(self, keep_inside: bool) -> tuple | None:
        """Ctrl sur Rogner ou Poinçonner (TypeEdit) : (type, garder le cadre) ; sans Ctrl, le type standard, cadre gardé."""
        if not self._ctrl_held():
            return 'standard', True
        from dataclasses import dataclass

        from .dialogs import ParamsDialog
        key = 'rogner' if keep_inside else 'poinconner'
        st = self.settings

        @dataclass
        class P:
            mode: str = str(st.value(f'{key}/type', 'standard'))
            keep: bool = st.value(f'{key}/garder', 'true') in (True, 'true')
        if keep_inside:
            title = tr('Type de rognage')
            modes = [('standard', tr('Recadrage standard')), ('strict', tr('Supprimer les éléments touchant le cadre')),
                     ('touching', tr('Conserver les éléments touchant le cadre'))]
        else:
            title = tr('Type de perforage')
            modes = [('standard', tr('Perforage standard')), ('strict', tr('Supprimer les éléments touchant le cadre')),
                     ('touching', tr('Conserver les éléments touchant le cadre'))]
        dlg = ParamsDialog(self, title, P(), {'mode': tr('Type'), 'keep': tr('Conserver le cadre')}, choices={'mode': modes})
        if not dlg.exec():
            return None
        p = dlg.result_params()
        st.setValue(f'{key}/type', p.mode)
        st.setValue(f'{key}/garder', bool(p.keep))
        return p.mode, bool(p.keep)

    def clip_items(self) -> None:
        """Rogner : le cadre est l'objet fermé sélectionné en premier, ou en dernier (sa forme exacte, pas sa boîte), sinon
        la plaque. Traits coupés sans ajouter de bord, surfaces (remplies, textes) intersectées. Ctrl : le type de rognage."""
        from ..core import clip as CL
        doc = self.canvas.doc
        sel = list(self.canvas.selection)
        frame, targets = self._frame_in(sel)
        if frame is not None:
            options = self._cut_options(True)
            if options is None:
                return None
            return self._region_cut(targets, frame, keep_inside=True, mode=options[0], keep_frame=options[1])
        if doc.plate is not None:
            pl = doc.plate
            box = (pl.x, pl.y, pl.x + pl.width, pl.y + pl.height)
            targets = sel or [it for L in doc.layers if L.visible and not L.locked for it in L.items]
        else:
            QMessageBox.information(self, tr('Rogner'), tr('Il faut une plaque, ou un cadre fermé sélectionné en dernier.'))
            return
        changed = removed = 0

        def cut(it):
            nonlocal changed, removed
            b = it.bbox()
            if b and box[0] <= b[0] and box[1] <= b[1] and b[2] <= box[2] and b[3] <= box[3]:
                return it                                    # entièrement dedans
            if b and (b[2] < box[0] or b[0] > box[2] or b[3] < box[1] or b[1] > box[3]):
                removed += 1
                return None                                  # entièrement dehors
            if isinstance(it, Group):
                ch = [x for x in (cut(c) for c in it.children) if x is not None]
                if not ch:
                    return None
                g = copy.copy(it)
                g.children = ch
                return g
            if isinstance(it, Shape):
                p = CL.clip_regions(it.path, box) if it.filled else CL.clip_strokes(it.path, box)
                changed += 1
                if not p.contours:
                    return None
                s = copy.copy(it)
                s.path = p
                return s
            if isinstance(it, Text) and it.outline:
                changed += 1
                p = CL.clip_regions(it.outline, box)
                return Shape(path=p, filled=True, tool=it.tool) if p.contours else None
            return it                                        # images : laissées telles quelles
        rep = {}
        for it in targets:
            r = cut(it)
            rep[id(it)] = [r] if r is not None else []
        if not changed and not removed:
            self.statusBar().showMessage(tr('Rien ne dépasse.'), 4000)
            return
        self.push_undo()
        out = self._replace_in_layers(targets, rep)
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        msg = tr('{0} objet(s) rogné(s), {1} retiré(s)').format(changed, removed)
        if len(sel) >= 2:                                # plusieurs objets, aucun fermé : ce n'est peut-être pas ce qu'on voulait
            msg = tr('Pas de cadre fermé dans la sélection : rogné à la plaque.') + ' ' + msg
        self.statusBar().showMessage(msg, 8000)

    def _double_line_params(self):
        from dataclasses import dataclass
        from .dialogs import ParamsDialog
        s = self.settings

        @dataclass
        class Spec:
            width: float = float(s.value('trait_double/largeur', 1.0))
            ends: str = str(s.value('trait_double/bouts', 'open'))
        spec = Spec()
        if spec.ends not in ('open', 'butt', 'round'):
            spec.ends = 'open'
        dlg = ParamsDialog(self, tr('Trait double'), spec, {'width': tr('Écartement (mm)'), 'ends': tr('Bouts')},
                           choices={'ends': [('open', tr('Ouverts (deux traits)')), ('butt', tr('Fermés (droits)')),
                                             ('round', tr('Fermés (ronds)'))]})
        if not dlg.exec():
            return None
        spec = dlg.result_params()
        spec.width = max(1e-3, abs(spec.width))
        s.setValue('trait_double/largeur', spec.width)
        s.setValue('trait_double/bouts', spec.ends)
        return spec

    def double_line_dialog(self) -> None:
        from ..core import parallel
        if not self._selected_shapes():
            QMessageBox.information(self, tr('Trait double'), tr('Sélectionnez au moins un objet.'))
            return
        spec = self._double_line_params()
        if spec is not None:
            self._fit_selection(tr('Trait double'), lambda p: parallel.double_line(p, spec.width, spec.ends))

    def dash_dialog(self) -> list | None:
        """Pointillés : les traits sélectionnés en tirets d'un type de trait."""
        from .dash_dialog import DashDialog
        if not self._selected_shapes():
            QMessageBox.information(self, tr('Pointillés'), tr('Sélectionnez au moins un objet.'))
            return None
        dlg = DashDialog(self, self.settings)
        if not dlg.exec():
            return None
        return self.dash_selection(**dlg.values())

    def dash_selection(self, pattern, scale: float = 1.0, fit: bool = True, dot: float = 0.0,
                       keep: bool = False) -> list:
        """Formes sélectionnées en tirets (`core.linetypes`), à leur place ;
        `keep` : les traits d'origine restent. Annulable."""
        from ..core import linetypes as LT
        out = []
        for s in self._selected_shapes():
            path = LT.dash_path(s.path, pattern, scale, fit, dot)
            if not path.contours:
                continue
            c = s.clone()
            c.path = path
            c.filled = False                                 # des traits ouverts : plus de remplissage
            out.append(c)
        if not out:
            return []
        self._replace_selection(out, keep=keep)
        self.statusBar().showMessage(tr('Pointillés : {0} tiret(s) ou point(s)').format(
            sum(len(c.path.contours) for c in out)), 8000)
        return out

    def explode_items(self) -> None:
        """Décomposer : un trait par segment."""
        from ..core import combine as C
        shapes = self._selected_shapes()
        if not shapes:
            QMessageBox.information(self, tr('Décomposer'), tr('Sélectionnez au moins un objet.'))
            return
        rep = {}
        for s in shapes:
            parts = []
            for p in C.explode(s.path):
                c = copy.copy(s)
                c.path = p
                c.filled = False
                parts.append(c)
            rep[id(s)] = parts
        self.push_undo()
        out = self._replace_in_layers(shapes, rep)
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} trait(s)').format(len(out)), 5000)

    def remove_contours_dialog(self) -> None:
        from dataclasses import dataclass
        from ..core import combine as C
        from .dialogs import ParamsDialog
        if not self._selected_shapes():
            QMessageBox.information(self, tr('Supprimer des contours'), tr('Sélectionnez au moins un objet.'))
            return
        s = self.settings

        @dataclass
        class Spec:
            mode: str = str(s.value('contours/mode', 'holes'))
            min_size: float = float(s.value('contours/taille', 1.0))
        spec = Spec()
        if spec.mode not in ('holes', 'outer', 'small'):
            spec.mode = 'holes'
        dlg = ParamsDialog(self, tr('Supprimer des contours'), spec,
                           {'mode': tr('Retirer'), 'min_size': tr('Taille minimale gardée (mm)')},
                           choices={'mode': [('holes', tr('Les trous')), ('outer', tr('Les contours extérieurs')),
                                             ('small', tr('Les contours plus petits que la taille'))]})
        if not dlg.exec():
            return
        v = dlg.result_params()
        s.setValue('contours/mode', v.mode)
        s.setValue('contours/taille', v.min_size)
        self._fit_selection(tr('Supprimer des contours'), lambda p: C.remove_contours(p, v.mode, max(0.0, v.min_size)))

    def blend_dialog(self) -> None:
        """Raccordement de deux traits ouverts sélectionnés."""
        from dataclasses import dataclass
        from ..core import blend
        from .dialogs import ParamsDialog
        sel = [s for s in self.canvas.selection if isinstance(s, Shape)]
        if len(sel) != 2 or len(self.canvas.selection) != 2 \
                or any(len(s.path.contours) != 1 or s.path.contours[0].closed for s in sel):
            QMessageBox.information(self, tr('Raccordement'), tr('Sélectionnez deux traits ouverts (un contour chacun).'))
            return

        @dataclass
        class Spec:
            radius: float = float(self.settings.value('raccordement/rayon', 2.0))
        dlg = ParamsDialog(self, tr('Raccordement'), Spec(), {'radius': tr('Rayon (mm, 0 = coin vif)')})
        if not dlg.exec():
            return
        r = max(0.0, dlg.result_params().radius)
        self.settings.setValue('raccordement/rayon', r)
        res = blend.blend_paths(sel[0].path, sel[1].path, r)
        if res is None:
            QMessageBox.information(self, tr('Raccordement'), tr('Ces deux traits ne peuvent pas être raccordés avec ce rayon.'))
            return
        new = copy.copy(sel[0])
        new.path = res
        self.push_undo()
        out = self._replace_in_layers(sel, {id(sel[0]): [new], id(sel[1]): []})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def blend_curve_dialog(self, params: dict | None = None) -> list:
        """Raccord en courbe (core.blend.bridge) : un ou deux traits ouverts
        sélectionnés (un contour chacun) ; joints en un seul tracé (fermé
        pour un trait seul) ou courbe à part. Annulable ; rend les objets."""
        from ..core import blend
        sel = [s for s in self.canvas.selection if isinstance(s, Shape)]
        if not 1 <= len(sel) <= 2 or len(self.canvas.selection) != len(sel) \
                or any(len(s.path.contours) != 1 or s.path.contours[0].closed for s in sel):
            QMessageBox.information(self, tr('Raccord en courbe'),
                                    tr('Sélectionnez un ou deux traits ouverts (un contour chacun).'))
            return []
        p = self._ask('raccord_courbe', tr('Raccord en courbe'),
                      [('smooth', bool, False, tr('Lisse (courbure nulle aux bouts) plutôt que tangent')),
                       ('join', bool, True, tr('Joindre en un seul tracé'))], params=params)
        if p is None:
            return []
        got = blend.bridge(sel[0].path.contours[0], sel[1].path.contours[0] if len(sel) == 2 else None,
                           bool(p['smooth']))
        if got is None:
            QMessageBox.information(self, tr('Raccord en courbe'),
                                    tr('Pas de raccord : les bouts se touchent déjà (Joindre) ou le trait est droit.'))
            return []
        curve, joined = got
        if not p['join']:
            new = Shape(path=geom.Path([curve]), tool=sel[0].tool)
            self._add_items([new])
            return [new]
        new = copy.copy(sel[0])
        new.path = geom.Path([joined])
        self.push_undo()
        out = self._replace_in_layers(sel, {id(sel[0]): [new], **({id(sel[1]): []} if len(sel) == 2 else {})})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        return out

    def _selected_dims(self, kinds) -> list:
        from ..core import dims
        return [(g, d) for g in self.canvas.selection if (d := dims.dim_of(g)) is not None and d.kind in kinds]

    def dim_inspect(self, params: dict | None = None) -> int:
        """Cote d'inspection (comme DIMINSPECT) sur les cotes sélectionnées :
        forme du cadre (aucune : retirée), libellé, taux. Annulable ; rend le
        nombre de cotes changées."""
        from ..core import dims
        sel = self._selected_dims(dims.INSPECTED)
        if not sel:
            QMessageBox.information(self, tr('Cote d\'inspection'),
                                    tr('Sélectionnez des cotes linéaires, angulaires ou radiales.'))
            return 0
        p = self._ask('inspection', tr('Cote d\'inspection'),
                      [('inspect', str, 'ronde', tr('Cadre')),
                       ('inspect_label', str, '', tr('Libellé (à gauche de la valeur)')),
                       ('inspect_rate', str, '100%', tr('Taux d\'inspection (à droite, ex. 100%)'))],
                      choices={'inspect': [(k, tr(v)) for k, v in dims.INSPECT.items()]}, params=params)
        if p is None:
            return 0
        self.push_undo()
        for g, d in sel:
            d.style.inspect = p['inspect'] if p['inspect'] in dims.INSPECT else ''
            d.style.inspect_label = str(p['inspect_label']) if d.style.inspect else ''
            d.style.inspect_rate = str(p['inspect_rate']) if d.style.inspect else ''
            dims.rebuild(g, d)
        self.canvas.invalidate()
        self._on_doc_changed()
        return len(sel)

    def dim_jog_line(self, params: dict | None = None) -> int:
        """Ressaut de cote (comme DIMJOGLINE) sur les cotes linéaires
        sélectionnées, à une position en % de la longueur (0 : retiré).
        Annulable ; rend le nombre de cotes changées."""
        from ..core import dims
        sel = self._selected_dims(dims.LINEAR)
        if not sel:
            QMessageBox.information(self, tr('Ressaut de cote'), tr('Sélectionnez des cotes linéaires.'))
            return 0
        p = self._ask('ressaut_cote', tr('Ressaut de cote'),
                      [('position', float, 25.0, tr('Position sur la ligne (% de la longueur, 0 : retirer)'))],
                      params=params)
        if p is None:
            return 0
        k = float(p['position']) / 100.0
        self.push_undo()
        for g, d in sel:
            (x1, y1), (x2, y2) = d.points[0], d.points[1]
            d.points = [d.points[0], d.points[1]] + ([(x1 + (x2 - x1) * k, y1 + (y2 - y1) * k)] if 0 < k < 1 else [])
            dims.rebuild(g, d)
        self.canvas.invalidate()
        self._on_doc_changed()
        return len(sel)

    def dim_space(self, params: dict | None = None) -> int:
        """Espacer les cotes (comme DIMSPACE) : cotes linéaires parallèles de
        la sélection à intervalle régulier à partir de la plus proche de
        l'objet coté (0 : alignées sur elle). Annulable ; rend le nombre de
        cotes déplacées."""
        from ..core import dims
        sel = self._selected_dims(dims.LINEAR)
        if len(sel) < 2:
            QMessageBox.information(self, tr('Espacer les cotes'),
                                    tr('Sélectionnez au moins deux cotes linéaires parallèles.'))
            return 0
        h = max(d.style.text_height for _g, d in sel)
        p = self._ask('espacer_cotes', tr('Espacer les cotes'),
                      [('spacing', float, round(2.0 * h, 3), tr('Intervalle entre les lignes de cote (mm, 0 : alignées)'))],
                      params=params)
        if p is None:
            return 0
        before = [d.offset for _g, d in sel]
        n = dims.space([d for _g, d in sel], max(0.0, float(p['spacing'])))
        if not n:
            self.statusBar().showMessage(tr('Aucune cote parallèle à espacer.'), 5000)
            return 0
        self.push_undo()
        for (g, d), o in zip(sel, before):
            if d.offset != o:
                dims.rebuild(g, d)
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} cote(s) espacée(s).').format(n), 5000)
        return n

    @staticmethod
    def _is_gdt(item) -> bool:
        from ..core import gdt
        return gdt.spec_of(item) is not None

    def gdt_frame(self, g: Group | None = None, params: dict | None = None):
        """Cadre de tolérancement (core.gdt) : caractéristique, tolérance
        (diamètre, valeur, condition de matière), trois références et
        identificateur ; posé au centre de la vue, ou le cadre `g` recalculé
        (un cadre de plusieurs lignes, lu d'un DXF, se modifie par sa chaîne).
        Annulable ; rend le groupe."""
        from ..core import gdt
        old = gdt.spec_of(g) if g is not None else None
        if g is not None and old is None:
            return None
        st = self.canvas.dim_style_fn() if getattr(self.canvas, 'dim_style_fn', None) else None
        h0 = float(old['height']) if old else float(getattr(st, 'text_height', 3.5) or 3.5)
        title = tr('Cadre de tolérancement')
        if old is not None and gdt.compose_fields(gdt.fields_of(old['text'])) != old['text']:
            if params is None:
                self.settings.setValue('cad/gdt_chaine', {'text': old['text'], 'height': h0})
            p = self._ask('gdt_chaine', title, [('text', str, old['text'], tr('Chaîne du cadre (codes DXF)')),
                                               ('height', float, h0, tr('Hauteur du texte (mm)'))], params=params)
            if p is None:
                return None
            text = str(p['text'])
        else:
            spec = [('symbol', str, 'flatness', tr('Caractéristique')),
                    ('diameter', bool, False, tr('Zone cylindrique (Ø)')),
                    ('value', str, '0.05', tr('Tolérance')),
                    ('material', str, '', tr('Condition de matière')),
                    ('datum1', str, '', tr('Référence primaire (ex. A ou A(M))')),
                    ('datum2', str, '', tr('Référence secondaire')),
                    ('datum3', str, '', tr('Référence tertiaire')),
                    ('datum_id', str, '', tr('Identificateur de référence (ligne sous le cadre)')),
                    ('height', float, h0, tr('Hauteur du texte (mm)'))]
            choices = {'symbol': [(k, tr(gdt.LABELS[k])) for k in gdt.CHARACTERISTICS],
                       'material': [('', tr('Aucune')), ('M', tr('Maximum de matière (M)')),
                                    ('L', tr('Minimum de matière (L)')), ('S', tr('Indépendante (S)'))]}
            if old is not None and params is None:
                self.settings.setValue('cad/gdt', {**gdt.fields_of(old['text']), 'height': h0})
            p = self._ask('gdt', title, spec, choices=choices, params=params)
            if p is None:
                return None
            text = gdt.compose_fields(p)
        h = float(p['height'])
        if not text or not h > 0:
            return None
        if old is not None:
            self.push_undo()
            gdt.rebuild(g, {**old, 'text': text, 'height': h,
                            'gap': old['gap'] * h / old['height'] if old.get('gap') is not None else None})
            self.canvas.invalidate()
            self._on_doc_changed()
            return g
        font = getattr(st, 'font', '') or 'Arial'
        new = gdt.group({'text': text, 'insert': [0.0, 0.0], 'rotation': 0.0, 'height': h, 'gap': None,
                         'font': font})
        bb = new.bbox()
        cx, cy = self._view_center()
        new = new.transformed(geom.Affine.translation(cx - (bb[0] + bb[2]) / 2, cy - (bb[1] + bb[3]) / 2))
        self._add_items([new])
        self.canvas.select([new])
        return new

    def purge(self) -> dict:
        """Purger (core.purge), annulable ; rend les nombres retirés."""
        import copy
        from ..core import purge as PG
        probe = copy.deepcopy(self.canvas.doc)
        counts = PG.purge(probe)
        if not any(counts.values()):
            self.statusBar().showMessage(tr('Rien à purger.'), 5000)
            return counts
        self.push_undo()
        PG.purge(self.canvas.doc)
        self.canvas.selection = []
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('Purgé : {0} objet(s), {1} groupe(s), {2} calque(s)').format(
            counts['objets'], counts['groupes'], counts['calques']), 6000)
        return counts

    FRAME_DIMS_TEMPLATES = 'cotes_auto/modeles'

    def frame_dims_templates(self) -> dict:
        """Modèles de réglages des cotes automatiques : nom → réglages."""
        v = self.settings.value(self.FRAME_DIMS_TEMPLATES, {})
        return dict(v) if isinstance(v, dict) else {}

    def smart_dims(self, params: dict | None = None, *, exec_dialog: bool = True):
        """Maj+C : cote choisie → ses réglages ; objets choisis → cotes
        automatiques ; rien → outil Cote (deux points, Tab : type suivant)."""
        from ..core import dims as D
        sel = list(self.canvas.selection)
        g = next((it for it in sel if D.dim_of(it) is not None), None)
        if g is not None:
            return self.edit_dim(g, exec_dialog=exec_dialog)
        if sel:
            return self.frame_dims(params)
        self.set_tool('dim')
        self.statusBar().showMessage(tr('Cote : cliquez les deux points, puis la position de la ligne — Tab : '
                                        'autre type de cote'), 8000)
        return None

    def frame_dims(self, params: dict | None = None) -> list:
        """Cotes automatiques des objets choisis (largeur, hauteur, et
        diamètres des cercles), réglages gardés ; un modèle choisi impose ses
        réglages, « Enregistrer comme modèle » en crée un."""
        from dataclasses import asdict
        from ..core import dims as D
        from ..core.holes import circle_of
        from . import dim_dialog as DD
        items = [it for it in self.canvas.selection if D.dim_of(it) is None]
        if not items:
            self.statusBar().showMessage(tr('Sélectionnez le cadre (ou les objets) à coter.'), 5000)
            return []
        templates = self.frame_dims_templates()
        base = D.FrameDims()
        spec = [('template', str, '', tr('Modèle')),
                ('width', bool, base.width, tr('Largeur')), ('height', bool, base.height, tr('Hauteur')),
                ('h_side', str, base.h_side, tr('Largeur placée')), ('v_side', str, base.v_side, tr('Hauteur placée')),
                ('gap', float, base.gap, tr('Écart au cadre (mm)')),
                ('each', bool, base.each, tr('Chaque objet coté à part (sinon l\'ensemble)')),
                ('circles', bool, base.circles, tr('Diamètre des cercles')),
                ('save_as', str, '', tr('Enregistrer ces réglages comme modèle (nom)'))]
        choices = {'template': [('', tr('(les réglages ci-dessous)'))] + [(k, k) for k in sorted(templates)],
                   'h_side': [('dessous', tr('Dessous')), ('dessus', tr('Dessus'))],
                   'v_side': [('gauche', tr('À gauche')), ('droite', tr('À droite'))]}
        p = self._ask('cotes_auto', tr('Cotes automatiques'), spec, choices=choices, params=params)
        if p is None:
            return []
        if p.get('template') and p['template'] in templates:
            p = dict(p, **templates[p['template']])
        fd = D.FrameDims(**{k: p[k] for k in asdict(base) if k in p})
        name = str(p.get('save_as') or '').strip()
        if name:
            templates[name] = asdict(fd)
            self.settings.setValue(self.FRAME_DIMS_TEMPLATES, templates)
            if params is None:
                last = self.settings.value('cad/cotes_auto', {})
                if isinstance(last, dict):                    # le nom ne reste pas pour la fois suivante
                    self.settings.setValue('cad/cotes_auto', dict(last, save_as='', template=name))
        style = DD.default_style(self.settings, self.canvas.dim_text)
        boxes = [it.bbox() for it in items] if fd.each else [self.canvas.selection_bbox()]
        dims = [d for b in boxes if b for d in D.frame_dims(b, fd, style)]
        if fd.circles:
            st = D.DimStyle(**{**asdict(style), 'diameter': True})
            for it in _leaves(items):
                c = circle_of(it)
                if c is not None:
                    cx, cy, r = c[0], c[1], c[2]
                    dims.append(D.Dim('radiale', [(cx, cy), (cx + r * 0.7071, cy + r * 0.7071)], 4.0, st))
        if not dims:
            self.statusBar().showMessage(tr('Rien à coter.'), 5000)
            return []
        groups = [D.group(d, tool=self.canvas.current_tool_index) for d in dims]
        self._add_items(groups)
        return groups

    def quick_dims(self, params: dict | None = None) -> list:
        """Cotation rapide (core.dims.quick) des objets choisis ; groupes de
        cotes ajoutés (annulable)."""
        from ..core import dims as D
        from ..core.holes import circle_of
        from . import dim_dialog as DD
        items = list(_leaves(self.canvas.selection))
        if not items:
            self.statusBar().showMessage(tr('Sélectionnez les objets à coter.'), 5000)
            return []
        p = self._ask('quick_dims', tr('Cotation rapide'),
                      [('mode', str, 'chaine', tr('Cotes')), ('gap', float, 8.0, tr('Écart à l\'objet (mm)'))],
                      choices={'mode': [('chaine', tr('En chaîne')), ('base', tr('Depuis une ligne de base'))]},
                      params=params)
        if p is None:
            return []
        pts = []
        for it in items:
            c = circle_of(it)
            if c is not None:
                pts.append((c[0], c[1]))
                continue
            b = it.bbox()
            if b:
                pts += [(b[0], b[1]), (b[2], b[3])]
        bb = self.canvas.selection_bbox()
        if not pts or not bb:
            return []
        style = DD.default_style(self.settings, self.canvas.dim_text)
        dims = D.quick(pts, bb, style, p['mode'], float(p['gap']))
        if not dims:
            self.statusBar().showMessage(tr('Rien à coter.'), 5000)
            return []
        groups = [D.group(d, tool=self.canvas.current_tool_index) for d in dims]
        self._add_items(groups)
        return groups

    def overkill(self) -> float:
        """Nettoyer les superpositions (core.overkill) : les formes droites
        choisies, par outil, remplacées par leurs traits fusionnés ; rend la
        longueur retirée (mm)."""
        from ..core import overkill as OK
        shapes = [s for s in self.canvas.selection if isinstance(s, Shape) and OK.straight_only(s.path)]
        if not shapes:
            self.statusBar().showMessage(tr('Sélectionnez des formes faites de traits droits.'), 5000)
            return 0.0
        by_tool: dict = {}
        for s in shapes:
            by_tool.setdefault(s.tool, []).append(s)
        new, removed = [], 0.0
        for tool, group in by_tool.items():
            path, r = OK.overkill([s.path for s in group])
            removed += r
            if path.contours:
                new.append(Shape(path=path, tool=tool))
        if removed <= 1e-6:
            self.statusBar().showMessage(tr('Aucune superposition.'), 5000)
            return 0.0
        keep = [it for it in self.canvas.selection if it not in shapes]
        self.canvas.selection = shapes
        self._replace_selection(new)
        if keep:
            self.canvas.select(new + keep)
        self.statusBar().showMessage(tr('{0} mm de traits superposés retirés').format(f'{removed:.2f}'), 6000)
        return removed

    def remove_loops_dialog(self, params: dict | None = None) -> None:
        from dataclasses import dataclass
        from ..core import parallel
        from ..core.geom import Path as _P
        from .dialogs import ParamsDialog
        if not self._selected_shapes():
            QMessageBox.information(self, tr('Gomme à boucles'), tr('Sélectionnez au moins un objet.'))
            return

        @dataclass
        class Spec:
            max_len: float = float(self.settings.value('boucles/longueur', 0.0))
            by: str = str(self.settings.value('boucles/critere', 'longueur') or 'longueur')
            separate: bool = self.settings.value('boucles/separer', 'false') in (True, 'true')
        # TypeEdit : les derniers réglages, sans fenêtre ; Ctrl ou premier usage : la fenêtre
        if params is None and (self._ctrl_on('remove_loops') or not self.settings.contains('boucles/longueur')):
            dlg = ParamsDialog(self, tr('Gomme à boucles'), Spec(),
                               {'max_len': tr('Taille maximale d\'une boucle (mm, 0 = toutes)'),
                                'by': tr('Taille mesurée'),
                                'separate': tr('Séparer les boucles du contour (sinon les supprimer)')},
                               choices={'by': [('longueur', tr('Longueur de la boucle')),
                                               ('encombrement', tr('Encombrement (diagonale de la boîte)'))]})
            if not dlg.exec():
                return
            spec = dlg.result_params()
        else:
            spec = Spec(**(params or {}))
        L = max(0.0, spec.max_len)
        self.settings.setValue('boucles/longueur', L)
        self.settings.setValue('boucles/critere', spec.by)
        self.settings.setValue('boucles/separer', bool(spec.separate))
        lim = L if L > 0 else float('inf')

        def work(p):
            out = []
            for c in p.contours:
                loops = [] if spec.separate else None
                out.append(parallel.remove_loops(c, lim, spec.by, loops))
                out += loops or []
            return _P(out)
        self._fit_selection(tr('Gomme à boucles'), work)

    def punch_items(self) -> None:
        """Poinçonner : la forme fermée sélectionnée en premier (ou, si le premier n'est pas fermé, en dernier) troue les
        autres objets sélectionnés ; elle reste en place. Ctrl : le type de perforage."""
        frame, targets = self._frame_in(list(self.canvas.selection))
        if frame is None:
            QMessageBox.information(self, tr('Poinçonner'),
                                    tr('Sélectionnez la forme fermée qui troue, puis les objets à trouer.'))
            return
        options = self._cut_options(False)
        if options is not None:
            self._region_cut(targets, frame, keep_inside=False, mode=options[0], keep_frame=options[1])

    def _region_cut(self, targets, frame, *, keep_inside: bool, mode: str = 'standard', keep_frame: bool = True) -> None:
        """Coupe des objets par une forme fermée quelconque : traits coupés exactement à son bord, surfaces (remplies, textes)
        par booléen. `mode` : 'standard' ; 'strict' retire ce qui touche le cadre ; 'touching' le garde entier."""
        from ..core import punch as PU
        region = self._closed_path(frame)
        changed = removed = 0

        def side(contour) -> str:
            r = PU.cut(geom.Path([contour]), region, False, keep_inside)
            return 'kept' if r is None else 'other' if not r.contours else 'touch'

        def whole(it):
            """Sans couper : un trait se juge contour par contour, une surface ou un texte d'un seul bloc."""
            nonlocal changed, removed
            allowed = ('kept',) if mode == 'strict' else ('kept', 'touch')
            if isinstance(it, Shape) and not it.filled:
                kept = [c for c in it.path.contours if side(c) in allowed]
                if len(kept) == len(it.path.contours):
                    return it
                if not kept:
                    removed += 1
                    return None
                changed += 1
                s = copy.copy(it)
                s.path = geom.Path(kept)
                return s
            path = it.path if isinstance(it, Shape) else it.outline if isinstance(it, Text) else None
            if not path:
                return it
            sides = {side(c) for c in path.contours}
            if sides == {'other'} or (mode == 'strict' and sides != {'kept'}):
                removed += 1
                return None
            return it

        def cut(it):
            nonlocal changed, removed
            if isinstance(it, Group):
                ch = [x for x in (cut(c) for c in it.children) if x is not None]
                if not ch:
                    return None
                g = copy.copy(it)
                g.children = ch
                return g
            if mode != 'standard':
                return whole(it)
            if isinstance(it, Shape):
                p = PU.cut(it.path, region, it.filled, keep_inside)
                if p is None:
                    return it
                if not p.contours:
                    removed += 1
                    return None
                changed += 1
                s = copy.copy(it)
                s.path = p
                return s
            if isinstance(it, Text) and it.outline:
                p = PU.cut(it.outline, region, True, keep_inside)
                if p is None:
                    return it
                if not p.contours:
                    removed += 1
                    return None
                changed += 1
                return Shape(path=p, filled=True, tool=it.tool)
            return it                                        # images : laissées telles quelles
        from ..core import progress as P
        from .progress import Cancelled, run

        def work():
            out = {}
            for i, it in enumerate(targets):
                P.step(i, len(targets), 'Objet {0} sur {1}')
                r = cut(it)
                out[id(it)] = [r] if r is not None else []
            return out
        try:
            rep = run(self, tr('Rogner') if keep_inside else tr('Poinçonner'), work)
        except Cancelled:
            return
        if not changed and not removed and keep_frame:
            self.statusBar().showMessage(tr('Rien ne dépasse.') if keep_inside else tr('Rien à poinçonner.'), 4000)
            return
        self.push_undo()
        rep[id(frame)] = [frame] if keep_frame else []
        out = self._replace_in_layers(list(targets) + [frame], rep)
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        msg = tr('{0} objet(s) rogné(s), {1} retiré(s)') if keep_inside else tr('{0} objet(s) poinçonné(s), {1} retiré(s)')
        self.statusBar().showMessage(msg.format(changed, removed), 6000)

    # --- arcs et segments -------------------------------------------------------------
    def arcs_dialog(self) -> None:
        from dataclasses import dataclass
        from ..core import biarc
        from .dialogs import ParamsDialog
        if not self.canvas.selection:
            QMessageBox.information(self, tr('Arcs et segments'), tr('Sélectionnez au moins un objet.'))
            return

        @dataclass
        class ArcSpec:
            tolerance: float = float(self.settings.value('arcs/tolerance', 0.01))
        dlg = ParamsDialog(self, tr('Arcs et segments'), ArcSpec(), {'tolerance': tr('Écart maximal (mm)')})
        if not dlg.exec():
            return
        tol = max(1e-4, dlg.result_params().tolerance)
        self.settings.setValue('arcs/tolerance', tol)
        from ..core import progress as P
        from .progress import Cancelled, run
        shapes = self._selected_shapes()

        def work():
            out = []
            for i, s in enumerate(shapes):
                P.step(i, len(shapes), 'Objet {0} sur {1}')
                c = copy.copy(s)
                c.path = biarc.to_arcs(s.path, tol)
                out.append(c)
            return out
        try:
            before = sum(biarc.stats(s.path)['autres'] for s in shapes)
            new = run(self, tr('Arcs et segments'), work)
        except Cancelled:
            return
        st = {'droites': 0, 'arcs': 0, 'autres': 0}
        for s in new:
            for k, v in biarc.stats(s.path).items():
                st[k] += v
        self._replace_selection(new)
        self.statusBar().showMessage(tr('{0} courbe(s) remplacée(s) : {1} arc(s), {2} droite(s)').format(
            before, st['arcs'], st['droites']), 8000)

    APPROX_LABELS = {'tolerance': 'Écart maximal (mm)', 'corner': 'Angle vif au-delà de (°)',
                     'curves': 'Ré-ajuster aussi les courbes existantes'}
    SEGMENT_LABELS = {'tolerance': 'Écart maximal (mm)', 'max_len': 'Longueur maximale d\'un segment (mm, 0 = libre)',
                      'lines_too': 'Découper aussi les droites'}

    def _fit_params(self, kind: str):
        """Réglages d'approximation ('approx') ou de segmentation ('segment')."""
        from dataclasses import dataclass
        from .dialogs import ParamsDialog
        s = self.settings
        if kind == 'approx':
            @dataclass
            class Spec:
                tolerance: float = float(s.value('approximation/ecart', 0.01))
                corner: float = float(s.value('approximation/angle', 35.0))
                curves: bool = s.value('approximation/courbes', 'true') in (True, 'true')
            labels, title = self.APPROX_LABELS, tr('Approximation')
        else:
            @dataclass
            class Spec:
                tolerance: float = float(s.value('segmentation/ecart', 0.01))
                max_len: float = float(s.value('segmentation/longueur', 0.0))
                lines_too: bool = s.value('segmentation/droites', 'false') in (True, 'true')
            labels, title = self.SEGMENT_LABELS, tr('Segmentation')
        dlg = ParamsDialog(self, title, Spec(), {k: tr(v) for k, v in labels.items()})
        if not dlg.exec():
            return None
        spec = dlg.result_params()
        spec.tolerance = max(1e-4, spec.tolerance)
        if kind == 'approx':
            for k, v in (('ecart', spec.tolerance), ('angle', spec.corner), ('courbes', spec.curves)):
                s.setValue(f'approximation/{k}', v)
        else:
            spec.max_len = max(0.0, spec.max_len)
            for k, v in (('ecart', spec.tolerance), ('longueur', spec.max_len), ('droites', spec.lines_too)):
                s.setValue(f'segmentation/{k}', v)
        return spec

    def _fit_selection(self, title: str, fn) -> None:
        shapes = self._selected_shapes()
        if not shapes:
            QMessageBox.information(self, title, tr('Sélectionnez au moins un objet.'))
            return
        from ..core import progress as P
        from .progress import Cancelled, run

        def work():
            out = []
            for i, s in enumerate(shapes):
                P.step(i, len(shapes), 'Objet {0} sur {1}')
                c = copy.copy(s)
                c.path = fn(s.path)
                out.append(c)
            return out
        before = sum(s.path.segment_count() for s in shapes)
        try:
            new = run(self, title, work)
        except Cancelled:
            return
        self._replace_selection(new)
        self.statusBar().showMessage(tr('{0} : {1} segment(s) → {2}').format(
            title, before, sum(s.path.segment_count() for s in new)), 8000)

    def approximate_dialog(self) -> None:
        from ..core import fitcurve
