    HOLE_LABELS = {'diameter': 'Diamètre (mm)', 'depth': 'Profondeur (mm)'}

    def _hole_dialog(self, spec, title: str, keep: bool | None = None):
        """Diamètre et profondeur ; `keep` : case « garder le diamètre des
        cercles » (conversion). Rend (spec, keep) ou None."""
        from dataclasses import make_dataclass
        from .dialogs import ParamsDialog
        labels = {k: tr(v) for k, v in self.HOLE_LABELS.items()}
        if keep is not None:
            P = make_dataclass('P', [('diameter', float), ('depth', float), ('keep', bool)])
            params = P(spec.diameter, spec.depth, keep)
            labels['keep'] = tr('Garder le diamètre des cercles')
        else:
            params = spec
        dlg = ParamsDialog(self, title, params, labels)
        if not dlg.exec():
            return None
        r = dlg.result_params()
        from ..core.holes import HoleSpec
        out = HoleSpec(diameter=max(0.001, r.diameter), depth=max(0.0, r.depth))
        return out, getattr(r, 'keep', False)

    def new_holes(self) -> None:
        """Cercles sélectionnés → trous ; sans cercle, un trou au centre de la vue."""
        from ..core import holes as HO
        sel = list(self.canvas.selection)
        circles = [it for it in sel if HO.circle_of(it) is not None]
        if circles:
            first = HO.spec_of(circles[0])
            res = self._hole_dialog(HO.HoleSpec(first.diameter, first.depth),
                                    tr('Changer {0} cercle(s) en trous').format(len(circles)), keep=True)
            if res is None:
                return
            spec, keep = res
            new = HO.convert(circles, spec, keep_diameter=keep)
            self.push_undo()
            out = self._replace_in_layers(circles, {k: [v] for k, v in new.items()})
            self.canvas.invalidate()
            self.canvas.select(out)
            self._on_doc_changed()
            return
        res = self._hole_dialog(HO.HoleSpec(), tr('Trou de perçage'))
        if res is None:
            return
        self._add_items([HO.make(self._view_center(), res[0], self.canvas.current_tool_index)])

    def edit_holes(self, items=None) -> None:
        """Diamètre et profondeur des trous sélectionnés (centres gardés)."""
        from ..core import holes as HO
        holes = [it for it in (items or self.canvas.selection) if HO.is_hole(it)]
        if not holes:
            return
        res = self._hole_dialog(HO.spec_of(holes[0]), tr('Trous ({0})').format(len(holes)))
        if res is None:
            return
        self.push_undo()
        out = self._replace_in_layers(holes, {id(h): [HO.updated(h, res[0])] for h in holes})
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()

    def _multicopy_spec(self):
        """Les derniers réglages de la multicopie."""
        from ..core import multicopy as MC
        s = self.settings

        def yes(key, default='false'):
            return s.value(f'multicopie/{key}', default) in (True, 'true')
        spec = MC.MultiSpec(margin=float(s.value('multicopie/marge', 3.0)), gap_x=float(s.value('multicopie/ecart_x', 2.0)),
                            gap_y=float(s.value('multicopie/ecart_y', 2.0)), total=int(s.value('multicopie/total', 0)),
                            planes=int(s.value('multicopie/plans', 0)), start=str(s.value('multicopie/depart', 'haut_gauche')),
                            place=str(s.value('multicopie/position', 'centre')), from_selection=yes('selection'),
                            optimised=yes('optimise'), turn_back=yes('retour'), quarter_turn=yes('rotation'),
                            ignore_first=yes('ignorer'), keep_original=yes('conserver'), limit_to_rows=yes('limiter', 'true'),
                            cuts=str(s.value('multicopie/decoupe', 'aucune')), cut_tool=int(s.value('multicopie/couleur', 0)),
                            tick=float(s.value('multicopie/trait', 3.0)))
        spec.start = spec.start if spec.start in MC.STARTS else MC.STARTS[0]
        spec.place = spec.place if spec.place in MC.PLACES else 'centre'
        spec.cuts = spec.cuts if spec.cuts in MC.CUTS else 'aucune'
        return spec

    def _remember_multicopy(self, spec) -> None:
        for k, v in (('marge', spec.margin), ('ecart_x', spec.gap_x), ('ecart_y', spec.gap_y), ('total', spec.total),
                     ('plans', spec.planes), ('depart', spec.start), ('position', spec.place),
                     ('selection', spec.from_selection), ('optimise', spec.optimised), ('retour', spec.turn_back),
                     ('rotation', spec.quarter_turn), ('ignorer', spec.ignore_first), ('conserver', spec.keep_original),
                     ('limiter', spec.limit_to_rows), ('decoupe', spec.cuts), ('couleur', spec.cut_tool), ('trait', spec.tick)):
            self.settings.setValue(f'multicopie/{k}', v)

    def fill_plate(self, spec=None):
        """Multicopie de la sélection (sans sélection : du plan actif), sur la plaque. `spec` : réglages donnés d'avance
        (essais). Rend le résultat ; None si rien n'est fait."""
        from ..core import multicopy as MC
        from ..core import variables as V
        from ..core.geom import bbox_union
        doc = self.canvas.doc
        title = tr('Multicopie')
        items = list(self.canvas.selection) or [it for it in doc.active_layer.items if it.visible and not it.locked]
        pl = doc.plate
        if not items or pl is None:
            QMessageBox.information(self, title, tr('Il faut une plaque et au moins un objet sélectionné.'))
            return None
        box = (pl.x, pl.y, pl.x + pl.width, pl.y + pl.height)
        table = V.table_of(doc)
        rows = len(table.rows) if table.rows and V.uses_variables(items) else 0
        if spec is None:
            from .multicopy_dialog import MulticopyDialog
            tools = [(i, f'{i + 1} — {t.name}') for i, t in enumerate(doc.tools)]
            dlg = MulticopyDialog(self, bbox_union(it.bbox() for it in items), box, self._multicopy_spec(), tools, rows)
            if not dlg.exec():
                return None
            spec = dlg.result_spec()
            self._remember_multicopy(spec)
        dress = None
        if rows:
            blank = {name: '' for name in table.names}

            def dress(copies, n):
                values = table.row(n) if n < rows else blank
                for c in copies:
                    V.fill_values(c, values)
                return n < rows
        res = MC.build(items, box, spec, MC.wanted(spec, rows), dress)
        if not res.planes:
            QMessageBox.information(self, title, tr('Aucun exemplaire ne tient sur la plaque.'))
            return res
        self.push_undo(title)
        home = doc.layer_of(items[0]) or doc.active_layer
        if not spec.keep_original:
            gone = {id(it) for it in (items[1:] if spec.ignore_first else items)}
            for L in doc.layers:
                L.items = [it for it in L.items if id(it) not in gone]
        used = {L.name for L in doc.layers}
        tool = min(max(spec.cut_tool, 0), max(len(doc.tools) - 1, 0))
        made = []
        for k, (copies, lines) in enumerate(zip(res.planes, res.cuts)):
            layer = home
            if k or spec.keep_original:
                layer = Layer(name=self._nest_layer_name(used), tool=home.tool)
                doc.layers.append(layer)
            layer.items.extend(copies)
            if lines is not None and lines.contours:
                layer.items.append(Shape(path=lines, tool=tool, name=tr('Lignes de découpe')))
            made += copies
        self.canvas.invalidate()
        self.canvas.select(made)
        self._on_doc_changed()
        lay = res.layout
        msg = tr('{0} exemplaire(s) : {1} × {2}{3}').format(res.count, lay.cols, lay.rows, tr(' (tournés)') if lay.turned else '')
        if lay.plates > 1:
            msg += ' — ' + tr('{0} plans').format(lay.plates)
        self.statusBar().showMessage(msg, 6000)
        return res

    def marquetry_dialog(self, exec_dialog: bool = True, spec=None):
        """Marqueterie (TypeEdit) : formes femelles et mâles de la sélection,
        chacune sur un plan neuf ; prédéfini : leurs opérations d'usinage."""
        from ..core import marquetry as MQ
        sel = list(self.canvas.selection)
        if not sel:
            QMessageBox.information(self, tr('Marqueterie'), tr('Sélectionnez des courbes fermées ou des textes.'))
            return None
        s = self.settings
        if spec is None:
            spec = MQ.MarquetrySpec()
            for f in ('corner_radius', 'female_offset', 'male_offset'):
                setattr(spec, f, float(s.value(f'marqueterie/{f}', getattr(spec, f))))
            for f in ('female_mirror', 'male_mirror', 'nest'):
                setattr(spec, f, s.value(f'marqueterie/{f}', getattr(spec, f)) in (True, 'true'))
            spec.preset = str(s.value('marqueterie/preset', spec.preset))
        n = len(self.canvas.doc.tools)
        spec.female_tool, spec.male_tool = min(spec.female_tool, n - 1), min(spec.male_tool, n - 1)
        if exec_dialog:
            from .dialogs import ParamsDialog
            tools = [(i, f'{i + 1} — {t.name}') for i, t in enumerate(self.canvas.doc.tools)]
            dlg = ParamsDialog(self, tr('Marqueterie'), spec, {
                'corner_radius': tr('Angles arrondis : rayon (mm, 0 = vifs)'),
                'female_offset': tr('Forme femelle : décalage (mm, > 0 plus grande)'),
                'female_mirror': tr('Forme femelle : miroir autour de l\'axe X'),
                'female_tool': tr('Forme femelle : couleur'),
                'male_offset': tr('Forme mâle : décalage (mm, < 0 plus petite)'),
                'male_mirror': tr('Forme mâle : miroir autour de l\'axe X'),
                'male_tool': tr('Forme mâle : couleur'),
                'nest': tr('Imbriquer les formes mâles sur la plaque'),
                'preset': tr('Prédéfini d\'usinage')},
                choices={'preset': [(k, tr(v[0])) for k, v in MQ.PRESETS.items()], 'female_tool': tools,
                         'male_tool': tools})
            if not dlg.exec():
                return None
            spec = dlg.result_params()
            for f in ('corner_radius', 'female_offset', 'male_offset', 'female_mirror', 'male_mirror', 'nest',
                      'preset'):
                s.setValue(f'marqueterie/{f}', getattr(spec, f))
        return self.apply_marquetry(sel, spec)

    def apply_marquetry(self, sel: list, spec):
        """Ajoute les plans de la marqueterie (et ses opérations) ; rend
        (femelles, mâles, opérations), None s'il n'y a aucun contour fermé."""
        from ..cam import inlay, model
        from ..core import marquetry as MQ
        doc = self.canvas.doc
        female, male = MQ.forms(sel, spec)
        if not female:
            QMessageBox.information(self, tr('Marqueterie'), tr('Aucun contour fermé dans la sélection.'))
            return None
        if spec.nest and male and doc.plate is not None:
            from ..core import nesting as N
            res = N.nest(male, doc.plate, N.NestSpec(margin=float(self.settings.value('imbrication/marge', 3.0)),
                                                     gap=float(self.settings.value('imbrication/ecart', 2.0))))
            male = res.items() + list(res.unplaced)
        setup = model.setup_of(doc)
        ops = inlay.operations(spec, female, male, setup, doc.plate.thickness if doc.plate else 0.0)
        self.push_undo(tr('Marqueterie'), with_cam=bool(ops))
        doc.layers.append(Layer(name=MQ.FEMALE_LAYER, items=female))
        doc.layers.append(Layer(name=MQ.MALE_LAYER, items=male))
        if ops:
            setup.operations += ops
            model.store(doc, setup)
            if hasattr(self, 'cam_panel'):
                self.cam_panel.refresh()
        self.canvas.invalidate()
        self._on_doc_changed()
        self.statusBar().showMessage(tr('Marqueterie : {0} formes femelles, {1} mâles, {2} opérations').format(
            len(female), len(male), len(ops)), 5000)
        return female, male, ops

    def nesting_dialog(self) -> None:
        from ..core import nesting as N
        from .dialogs import ParamsDialog
        sel = list(self.canvas.selection)
        pl = self.canvas.doc.plate
        if not sel or pl is None:
            QMessageBox.information(self, tr('Imbriquer'),
                                    tr('Il faut une plaque et au moins un objet sélectionné.'))
            return
        s = self.settings
        spec = N.NestSpec(margin=float(s.value('imbrication/marge', 3.0)),
                          gap=float(s.value('imbrication/ecart', 2.0)),
                          allow_rotate=s.value('imbrication/rotation', 'true') in (True, 'true'),
                          copies=int(s.value('imbrication/copies', 1)),
                          shape=s.value('imbrication/forme', 'false') in (True, 'true'),
                          angle_step=float(s.value('imbrication/pas_angle', 90.0)),
                          angles=str(s.value('imbrication/angles', '') or ''),
                          in_holes=s.value('imbrication/trous', 'false') in (True, 'true'),
                          allow_mirror=s.value('imbrication/miroir', 'false') in (True, 'true'),
                          precision=float(s.value('imbrication/precision', 0.5)), **self._nest_trials())
        dlg = ParamsDialog(self, tr('Imbriquer'), spec, {
            'margin': tr('Marge au bord de la plaque (mm)'), 'gap': tr('Écart entre objets (mm)'),
            'allow_rotate': tr('Quart de tour permis'),
            'copies': tr('Exemplaires de chaque objet (0 : remplir la plaque)'),
            'shape': tr('Selon la vraie forme des objets (sinon : leurs rectangles)'),
            'angle_step': tr('Forme : pas de rotation (°, 90 : quarts de tour)'),
            'angles': tr('Forme : angles permis (°, ex. 0;90;180 ; vide : d’après le pas)'),
            'in_holes': tr('Forme : ranger aussi dans les trous des autres'),
            'allow_mirror': tr('Forme : retournement permis (miroir)'),
            'precision': tr('Forme : précision (mm ; plus fin : plus serré, plus long)'),
            'tries': tr('Optimiseur : nombre d’essais (1 : un seul rangement)'),
            'both_ways': tr('Optimiseur : essayer les deux directions'),
            'max_seconds': tr('Optimiseur : durée maximale (s)'),
            'min_gain': tr('Optimiseur : s’arrêter à ce gain de remplissage (%, 0 : faire tous les essais)')})
        if not dlg.exec():
            return
        spec = dlg.result_params()
        self._remember_nest_trials(spec)
        for k, v in (('marge', spec.margin), ('ecart', spec.gap), ('rotation', spec.allow_rotate),
                     ('copies', spec.copies), ('forme', spec.shape), ('pas_angle', spec.angle_step),
                     ('angles', spec.angles), ('trous', spec.in_holes), ('miroir', spec.allow_mirror),
                     ('precision', spec.precision)):
            s.setValue(f'imbrication/{k}', v)
        self.apply_nesting(sel, spec)

    def _nest_spec(self):
        from ..core import nesting as N
        s = self.settings
        spec = N.NestSpec(margin=float(s.value('imbrication/marge', 3.0)),
                          gap=float(s.value('imbrication/ecart', 2.0)),
                          allow_rotate=s.value('imbrication/rotation', 'true') in (True, 'true'),
                          copies=int(s.value('imbrication/copies', 1)),
                          shape=s.value('imbrication/forme', 'false') in (True, 'true'),
                          angle_step=float(s.value('imbrication/pas_angle', 90.0)),
                          angles=str(s.value('imbrication/angles', '') or ''),
                          in_holes=s.value('imbrication/trous', 'false') in (True, 'true'),
                          allow_mirror=s.value('imbrication/miroir', 'false') in (True, 'true'),
                          precision=float(s.value('imbrication/precision', 0.5)),
                          corner=str(s.value('imbrication/coin', N.CORNERS[0])),
                          vertical=s.value('imbrication/vertical', 'false') in (True, 'true'), **self._nest_trials())
        if spec.corner not in N.CORNERS:
            spec.corner = N.CORNERS[0]
        return spec

    def _nest_trials(self) -> dict:
        """Les réglages de l'optimiseur d'imbrication."""
        s = self.settings
        return {'tries': int(s.value('imbrication/essais', 1)),
                'both_ways': s.value('imbrication/deux_sens', 'false') in (True, 'true'),
                'max_seconds': float(s.value('imbrication/duree', 30.0)),
                'min_gain': float(s.value('imbrication/gain', 0.0))}

    def _remember_nest_trials(self, spec) -> None:
        for k, v in (('essais', spec.tries), ('deux_sens', spec.both_ways), ('duree', spec.max_seconds),
                     ('gain', spec.min_gain)):
            self.settings.setValue(f'imbrication/{k}', v)

    def copy_nest(self, params: dict | None = None):
        """Copie imbriquée : `params` comme `CopyNestDialog.result_params`. Rend le résultat de l'imbrication."""
        sel = list(self.canvas.selection)
        title = tr('Copie imbriquée')
        if not sel or self.canvas.doc.plate is None:
            QMessageBox.information(self, title, tr('Il faut une plaque et au moins un objet sélectionné.'))
            return None
        s = self.settings
        if params is None:
            from .copy_nest_dialog import CopyNestDialog
            dlg = CopyNestDialog(self, sel, self._nest_spec(), per_plane=s.value('imbrication/plans', 'true') in (True, 'true'),
                                 count=int(s.value('imbrication/exemplaires', 2)))
            if not dlg.exec():
                return None
            params = dlg.result_params()
        spec = params['spec']
        for k, v in (('marge', spec.margin), ('ecart', spec.gap), ('rotation', spec.allow_rotate), ('forme', spec.shape),
                     ('pas_angle', spec.angle_step), ('angles', spec.angles), ('trous', spec.in_holes),
                     ('miroir', spec.allow_mirror), ('precision', spec.precision), ('coin', spec.corner), ('vertical', spec.vertical), ('plans', params.get('per_plane', True))):
            s.setValue(f'imbrication/{k}', v)
        self._remember_nest_trials(spec)
        if params.get('same'):
            s.setValue('imbrication/exemplaires', int(params.get('count', 1)))
        return self.apply_nesting(sel, spec, per_plane=bool(params.get('per_plane', True)), names=params.get('names'))

    def copy_into_shape(self, params: dict | None = None):
        """Des copies des objets (qui restent où ils sont) dans la dernière forme sélectionnée. Rend le résultat."""
        from ..core import nesting as N
        from ..core import pathops
        from ..core.hatch import closed_path
        from .progress import Cancelled, run
        title = tr('Copier dans une forme')
        sel = list(self.canvas.selection)
        target = sel[-1] if sel else None
        region = closed_path([target]) if isinstance(target, (Shape, Text, Group)) else None
        if len(sel) < 2 or region is None or not region.contours or pathops.area(pathops.normalize(region)) <= 0:
            QMessageBox.information(self, title, tr('Sélectionnez les objets puis, en dernier, la forme fermée à remplir.'))
            return None
        objs = sel[:-1]
        params = self._ask('copy_into', title, [
            ('count', int, 0, tr('Exemplaires de chaque objet (0 : autant qu’il en tient)')),
            ('margin', float, 1.0, tr('Marge au bord de la forme (mm)')),
            ('gap', float, 1.0, tr('Écart entre objets (mm)')),
            ('allow_rotate', bool, True, tr('Rotation permise')),
            ('angle_step', float, 90.0, tr('Pas de rotation (°, 90 : quarts de tour)')),
            ('in_holes', bool, False, tr('Ranger aussi dans les trous des autres')),
            ('allow_mirror', bool, False, tr('Retournement permis (miroir)')),
            ('precision', float, 0.5, tr('Précision (mm ; plus fin : plus serré, plus long)'))], params=params)
        if params is None:
            return None
        count = int(params['count'])
        spec = N.NestSpec(margin=max(0.0, float(params['margin'])), gap=max(0.0, float(params['gap'])),
                          allow_rotate=bool(params['allow_rotate']), angle_step=float(params['angle_step']),
                          in_holes=bool(params['in_holes']), allow_mirror=bool(params['allow_mirror']),
                          precision=float(params['precision']), shape=True, region=region,
                          copies=0 if count <= 0 else 1, counts=None if count <= 0 else [count] * len(objs))
        try:
            res = run(self, title, N.nest, objs, self.canvas.doc.plate, spec)
        except Cancelled:
            return None
        if not res.placed:
            QMessageBox.information(self, title, tr('Aucun objet ne tient dans cette forme.'))
            return res
        self.push_undo()
        new = [it.clone().transformed(m) for it, m in res.placed]
        layer = self.canvas.doc.layer_of(target) or self.canvas.doc.active_layer
        layer.items.extend(new)
        self.canvas.invalidate()
        self.canvas.select(new)
        self._on_doc_changed()
        msg = tr('{0} exemplaire(s) dans la forme — occupation {1} %').format(len(new), round(res.usage * 100))
        missing = count * len(objs) - len(new) if count > 0 else 0
        if missing > 0:
            msg += ' — ' + tr('{0} n’ont pas trouvé place').format(missing)
        elif count <= 0 and res.unplaced:
            msg += ' — ' + tr('{0} objet(s) trop grand(s) pour cette forme').format(len(res.unplaced))
        self.statusBar().showMessage(msg, 10000)
        return res

    def nest_into_contour(self, params: dict | None = None):
        """Range les objets (ils se déplacent) dans le premier sélectionné : contour fermé, groupe ou combinaison.
        Ce qui n'y tient pas reste où il est. Rend le résultat."""
        from ..core import nesting as N
        from ..core.nest_report import remember
        from .progress import Cancelled, run
        title = tr('Imbriquer dans un contour')
        sel = list(self.canvas.selection)
        zones = N.contours_of(sel[0]) if len(sel) >= 2 and isinstance(sel[0], (Shape, Text, Group)) else []
        if not zones:
            QMessageBox.information(self, title, tr('Sélectionnez d’abord le contour fermé englobant, puis les objets à y ranger.'))
            return None
        objs = sel[1:]
        params = self._ask('nest_into', title, [
            ('margin', float, 1.0, tr('Marge au bord du contour (mm)')),
            ('gap', float, 1.0, tr('Écart entre objets (mm)')),
            ('allow_rotate', bool, True, tr('Rotation permise')),
            ('angle_step', float, 90.0, tr('Pas de rotation (°, 90 : quarts de tour)')),
            ('in_holes', bool, False, tr('Ranger aussi dans les trous des autres')),
            ('allow_mirror', bool, False, tr('Retournement permis (miroir)')),
            ('precision', float, 0.5, tr('Précision (mm ; plus fin : plus serré, plus long)'))], params=params)
        if params is None:
            return None
        spec = N.NestSpec(margin=max(0.0, float(params['margin'])), gap=max(0.0, float(params['gap'])), shape=True,
                          allow_rotate=bool(params['allow_rotate']), angle_step=float(params['angle_step']),
                          in_holes=bool(params['in_holes']), allow_mirror=bool(params['allow_mirror']),
                          precision=float(params['precision']))
        try:
            res = run(self, title, N.nest_into, objs, zones, spec)
        except Cancelled:
            return None
        if not res.placed:
            QMessageBox.information(self, title, tr('Aucun objet ne tient dans ce contour.'))
            return res
        self.push_undo(title)
        doc = self.canvas.doc
        placed = self._replace_in_layers([it for it, _m in res.placed], {id(it): [it.transformed(m)] for it, m in res.placed})
        remember(doc, spec, res)
        self.canvas.invalidate()
        self.canvas.select(placed)
        self._on_doc_changed()
        msg = tr('{0} objet(s) rangé(s) dans {1} contour(s) — occupation {2} %').format(
            len(placed), res.plates, round(res.usage * 100))
        if res.unplaced:
            msg += ' — ' + tr('{0} sans place, resté(s) où ils étaient').format(len(res.unplaced))
        self.statusBar().showMessage(msg, 10000)
        return res

    def plate_remnant(self, params: dict | None = None):
        """Le restant de la plaque, compte tenu de la sélection (sinon du plan actif), sur un plan à lui. Rend la forme."""
        from ..core import remnant as RE
        title = tr('Restant de plaque')
        doc = self.canvas.doc
        items = list(self.canvas.selection) or list(doc.active_layer.items)
        if doc.plate is None:
            QMessageBox.information(self, title, tr('Il faut une plaque.'))
            return None
        params = self._ask('plate_remnant', title, [
            ('mode', str, 'standard', tr('Forme du restant')),
            ('gap', float, 2.0, tr('Écart gardé autour des objets (mm)')),
            ('min_area', float, 100.0, tr('Surface minimale (mm²)')),
            ('min_side', float, 20.0, tr('Largeur minimale (mm) : ce qui est plus étroit ne compte pas')),
            ('to_library', bool, False, tr('Garder aussi dans la bibliothèque'))],
            choices={'mode': [('simple', tr('Simple : le plus grand rectangle libre')),
                              ('standard', tr('Standard : autour des rectangles des objets')),
                              ('optimise', tr('Optimisé : autour de la vraie forme des objets'))]}, params=params)
        if params is None:
            return None
        spec = RE.RemnantSpec(mode=str(params['mode']), gap=float(params['gap']), min_area=float(params['min_area']),
                              min_side=float(params['min_side']))
        try:
            got = RE.remnant(doc.plate, items, spec)
        except RE.NoRemnant:
            QMessageBox.information(self, title, tr('Aucun restant ne répond à ces critères : baissez la surface ou '
                                                    'la largeur minimales, ou l’écart.'))
            return None
        self.push_undo(title)
        used = {L.name for L in doc.layers}
        name, n = title, 1
        while name in used:
            n += 1
            name = f'{title} {n}'
        tool = (doc.active_layer.tool + 1) % max(1, len(doc.tools))
        shape = Shape(path=got.path, tool=tool)
        layer = Layer(name=name, tool=tool, items=[shape])
        doc.layers.append(layer)
        self.canvas.invalidate()
        self.canvas.select([shape])
        self._on_doc_changed()
        msg = tr('Restant de plaque : {0} mm², {1} % de la plaque').format(round(got.area), round(got.share * 100))
        if got.others:
            msg += ' — ' + tr('{0} autre(s) partie(s) laissée(s) de côté').format(got.others)
        if params.get('to_library'):
            path = self._remnant_to_library(shape)
            msg += ' — ' + (tr('gardé dans la bibliothèque : {0}').format(path.name) if path is not None
                            else tr('impossible de l’écrire dans la bibliothèque'))
        self.statusBar().showMessage(msg, 10000)
        return shape

    def scrap_lines(self, params: dict | None = None):
        """Lignes de découpe de la matière restante, sur le plan des objets. Rend la forme des lignes."""
        from ..core import remnant as RE
        title = tr('Découper la matière restante')
        doc = self.canvas.doc
        items = list(self.canvas.selection) or list(doc.active_layer.items)
        if doc.plate is None:
            QMessageBox.information(self, title, tr('Il faut une plaque.'))
            return None
        tools = [(i, f'{i + 1} — {t.name}') for i, t in enumerate(doc.tools)]
        params = self._ask('scrap_lines', title, [
            ('step_x', float, 10.0, tr('Espacement en X (mm, 0 : pas de lignes verticales)')),
            ('step_y', float, 10.0, tr('Espacement en Y (mm, 0 : pas de lignes horizontales)')),
            ('gap', float, 1.0, tr('Écart gardé autour des objets (mm)')),
            ('tool', int, 0, tr('Couleur'))], choices={'tool': tools}, params=params)
        if params is None:
            return None
        path = RE.scrap_lines(doc.plate, items, float(params['step_x']), float(params['step_y']), max(0.0, float(params['gap'])))
        if not path.contours:
            QMessageBox.information(self, title, tr('Aucune ligne : donnez un espacement, ou il ne reste rien à découper.'))
            return None
        self.push_undo(title)
        tool = min(max(int(params['tool']), 0), max(len(doc.tools) - 1, 0))
        shape = Shape(path=path, tool=tool, name=tr('Lignes de découpe'))
        layer = (doc.layer_of(items[0]) if items else None) or doc.active_layer
        layer.items.append(shape)
        self.canvas.invalidate()
        self.canvas.select([shape])
        self._on_doc_changed()
        self.statusBar().showMessage(tr('{0} ligne(s) de découpe').format(len(path.contours)), 6000)
        return shape

    def _remnant_to_library(self, shape):
        """Symbole PlateNNNN.smb du dossier des restants, comme TypeEdit. Rend le chemin ; None si l'écriture échoue."""
        from ..io import smb
        from .symbols import library_root
        folder = library_root() / 'Restants de plaque'
        try:
            folder.mkdir(parents=True, exist_ok=True)
            n = 1
            while (folder / f'Plate{n:04d}.smb').exists():
                n += 1
            path = folder / f'Plate{n:04d}.smb'
            smb.write([shape], path, tools=self.canvas.doc.tool_colors([shape]))
        except OSError:
            return None
        return path

    def nest_report(self, path: str | None = None, params: dict | None = None, open_it: bool = True) -> str | None:
        """Le rapport d'imbrication en PDF. Rend son chemin."""
        from .nest_report import write_pdf
        title = tr('Rapport d’imbrication')
        doc = self.canvas.doc
        if not any(L.visible and L.items for L in doc.layers):
            QMessageBox.information(self, title, tr('Aucun plan rempli.'))
            return None
        params = self._ask('nest_report', title, [
            ('comment', str, '', tr('Commentaires')),
            ('with_image', bool, False, tr('Ajouter une image'))], params=params)
        if params is None:
            return None
        image = params.get('image', '')
        if params.get('with_image') and not image:
            image, _ = QFileDialog.getOpenFileName(self, title, self._last_dir('image'), tr('Images (*.bmp *.jpg *.jpeg *.png)'))
        if path is None:
            src = doc.source_path
            start = (os.path.splitext(src)[0] + ' - imbrication.pdf') if src else self._last_dir('rapport')
            path, _ = QFileDialog.getSaveFileName(self, title, start, tr('PDF (*.pdf)'))
            if not path:
                return None
            if not path.lower().endswith('.pdf'):
                path += '.pdf'
            self._remember_dir('rapport', path)
        kept = doc.extra.get('imbrication') or {}
        name = os.path.basename(doc.source_path) if doc.source_path else tr('Dessin sans nom')
        try:
            write_pdf(path, doc, name, float(kept.get('gap', 0.0)), str(params.get('comment', '')), image)
        except OSError as ex:
            QMessageBox.warning(self, title, tr('Impossible d’écrire le rapport : {0}').format(ex))
            return None
        self.statusBar().showMessage(tr('Rapport d’imbrication : {0}').format(path), 8000)
        if open_it:
            from PySide6.QtCore import QUrl
            from PySide6.QtGui import QDesktopServices
            QDesktopServices.openUrl(QUrl.fromLocalFile(path))
        return path

    def _nest_layer_name(self, used: set) -> str:
        """Le prochain nom de plan libre."""
        n = len(self.canvas.doc.layers) + 1
        while True:
            name = tr('Plan {0}').format(n)
            if name not in used:
                used.add(name)
                return name
            n += 1

    def apply_nesting(self, sel: list, spec, per_plane: bool = False, names: dict | None = None) -> object:
        from ..core import nesting as N
        from .progress import Cancelled, run
        try:
            res = run(self, tr('Imbriquer'), N.nest, sel, self.canvas.doc.plate, spec)
        except Cancelled:
            return None
        if not res.placed:
            QMessageBox.information(self, tr('Imbriquer'), tr('Aucun objet ne tient sur la plaque.'))
            return res
        self.push_undo()
        for it in sel:
            if names and id(it) in names:
                it.name = names[id(it)]
        seen: set[int] = set()
        new_by_old: dict[int, list] = {}
        planes: dict[int, list] = {}
        pitch = self.canvas.doc.plate.width + N.PLATE_GAP
        for (it, m), k in zip(res.placed, res.sheets):
            first = id(it) not in seen
            seen.add(id(it))
            if per_plane and k:                          # sur le plan de cette plaque, à la place de la plaque
                planes.setdefault(k, []).append((it if first else it.clone()).transformed(Affine.translation(-k * pitch, 0.0) @ m))
            else:
                new_by_old.setdefault(id(it), []).append((it if first else it.clone()).transformed(m))
        out = self._replace_in_layers([it for it in sel if id(it) in seen], new_by_old)
        doc = self.canvas.doc
        used = {L.name for L in doc.layers}
        for k in sorted(planes):
            doc.layers.append(Layer(name=self._nest_layer_name(used), items=planes[k]))
            out = out + planes[k]
        from ..core.nest_report import remember
        remember(doc, spec, res)
        self.canvas.invalidate()
        self.canvas.select(out)
        self._on_doc_changed()
        msg = tr('{0} objet(s) rangé(s) sur {1} plaque(s)').format(len(res.placed), res.plates)
        if res.usage:
            msg += ' — ' + tr('occupation {0} %').format(round(res.usage * 100))
        if res.mirrored:
            msg += ' — ' + tr('{0} retourné(s)').format(res.mirrored)
        if res.unplaced:
            msg += ' — ' + tr('{0} trop grand(s) pour la plaque').format(len(res.unplaced))
        if res.best:
            way = tr('verticale') if res.best['vertical'] else tr('horizontale')
            msg += ' — ' + tr('{0} essai(s), meilleure direction : {1}').format(res.best['tries'], way)
        self.statusBar().showMessage(msg, 8000)
        return res

    # --- symboles ----------------------------------------------------------------
    def save_as_symbol(self) -> None:
        items = list(self.canvas.selection) or list(self.canvas.doc.iter_items(visible_only=True))
        if not items:
            QMessageBox.information(self, tr('Créer un symbole'), tr('Rien à enregistrer.'))
            return
        folder = self.symbols.current_folder()
        exts = self.symbol_formats()
        start = str(folder / f'symbole{exts[0]}') if folder else self._last_dir('symbole')
        kinds = {'.smb': tr('Symbole TypeEdit (*.smb)'), '.dxf': tr('Dessin DXF (*.dxf)'),
                 '.vdz': tr('Dessin VectorDrive (*.vdz)')}
        path, _ = QFileDialog.getSaveFileName(self, tr('Créer un symbole'), start, kinds[exts[0]])
        if not path:
            return
        if not path.lower().endswith(exts[0]):
            path += exts[0]
        try:
            written = self._write_symbol(items, path)
        except Exception as ex:
            QMessageBox.critical(self, tr('Créer un symbole'), str(ex))
            return
        self._remember_dir('symbole', path)
        self.symbols.show_folder(pathlib.Path(path).parent)
        self.statusBar().showMessage(tr('Symbole enregistré : {0}').format(', '.join(str(f) for f in written))
                                     + self._symbol_note(items, written), 8000)

    def symbol_formats(self) -> list:
        """Extensions des symboles créés (réglage `symboles/format`) : SMB, DXF, les deux, ou VDZ."""
        from .options import value
        return {'smb': ['.smb'], 'dxf': ['.dxf'], 'smb+dxf': ['.smb', '.dxf'], 'vdz': ['.vdz']}.get(
            str(value(self.settings, 'symboles/format')), ['.smb'])

    def _write_symbol(self, items, path) -> list:
        """Le symbole écrit à `path`, son extension remplacée par celle de chaque format du réglage ; rend les
        fichiers écrits. SMB : textes TypeEdit modifiables selon le réglage, couleurs gardées ; DXF, VDZ : l'export
        de la sélection."""
        from ..io import smb
        out = []
        for ext in self.symbol_formats():
            f = pathlib.Path(path).with_suffix(ext)
            if ext == '.smb':
                smb.write(items, str(f), live_texts=self.symbol_live_texts(),
                          tools=self.canvas.doc.tool_colors(items))
            else:
                from .export_dialog import export_items
                export_items(self, items, str(f), {'plaque': False}, selection=True)
            out.append(f)
        return out

    def _symbol_note(self, items, written) -> str:
        """La note sur les textes d'un symbole SMB écrit sans textes TypeEdit modifiables."""
        if any(f.suffix == '.smb' for f in written) and not self.symbol_live_texts() \
                and any(isinstance(lf, Text) for lf in _leaves(items)):
            return tr(' (textes enregistrés en courbes)')
        return ''

    def symbol_live_texts(self) -> bool:
        """Les symboles créés gardent-ils leurs textes en textes TypeEdit modifiables (réglage) ?"""
        from .options import value
        return bool(value(self.settings, 'symboles/textes_vivants'))

    @staticmethod
    def _symbol_name(items) -> str:
        """Nom proposé pour un symbole : la première ligne de son premier texte, sinon « symbole »."""
        for lf in _leaves(items):
            if isinstance(lf, Text):
                line = str(getattr(lf, 'text', '') or '').strip().splitlines()
                if line and line[0].strip():
                    return line[0].strip()[:40]
        return tr('symbole')

    def add_selection_to_library(self, folder=None, name: str | None = None, *, fallback: bool = True):
        """Bibliothèque › Ajouter la sélection : la sélection du dessin enregistrée en symbole dans `folder` (le dossier
        affiché) ; seul le nom est demandé, un nom pris devient « nom (2) »… Sans dossier (favoris, récents) : la
        fenêtre Enregistrer sous. Le fichier ajouté est choisi dans la liste. Rend son chemin (None : rien).
        `fallback` : sans `folder`, le dossier visé par le panneau ancré (faux : un panneau qui n'en vise aucun)."""
        import re
        from PySide6.QtWidgets import QInputDialog
        items = list(self.canvas.selection)
        if not items:
            self.statusBar().showMessage(tr('Sélectionnez d’abord ce qu’il faut ajouter à la bibliothèque'), 6000)
            return None
        folder = pathlib.Path(folder) if folder else (self.symbols.target_folder() if fallback else None)
        if folder is None or not folder.is_dir():
            self.save_as_symbol()
            return None
        if name is None:
            name, ok = QInputDialog.getText(self, tr('Ajouter à la bibliothèque'),
                                            tr('Nom du symbole, dans « {0} » :').format(folder.name or str(folder)),
                                            text=self._symbol_name(items))
            if not ok:
                return None
        stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]', '_', str(name or '')).strip().rstrip('. ')
        if not stem:
            self.statusBar().showMessage(tr('Nom de symbole vide : rien d’ajouté'), 6000)
            return None
        exts = self.symbol_formats()
        path, k = folder / f'{stem}{exts[0]}', 2
        while any(path.with_suffix(e).exists() for e in exts):      # un nom libre dans chaque format écrit
            path, k = folder / f'{stem} ({k}){exts[0]}', k + 1
        try:
            written = self._write_symbol(items, path)
        except Exception as ex:
            QMessageBox.critical(self, tr('Ajouter à la bibliothèque'), str(ex))
            return None
        panels = [self.symbols] + [w.panel for w in [getattr(self, '_library_window', None)] if w is not None]
        for p in panels:
            if p is self.symbols or getattr(p, '_folder', None) == folder:
                p.show_folder(folder)
                p.select_file(path)
        msg = tr('Ajouté à la bibliothèque : {0}').format(', '.join(f.name for f in written))
        self.statusBar().showMessage(msg + self._symbol_note(items, written), 8000)
        return path

    # --- codes-barres, nettoyage ----------------------------------------------
    def new_barcode(self) -> None:
        from ..core import codes
        from .dialogs import BarcodeDialog
        last = self.settings.value('codes/dernier', None)
        spec = codes.BarcodeSpec.from_dict(last) if isinstance(last, dict) else codes.BarcodeSpec()
        spec.text = ''
        dlg = BarcodeDialog(self, spec)
        if not dlg.exec():
            return
        spec = dlg.result_spec()
        self.settings.setValue('codes/dernier', {k: v for k, v in spec.__dict__.items() if k != 'text'})
        g = codes.build(spec, self.canvas.current_tool_index)
        bb = g.bbox()
        cx, cy = self._view_center()
        g = g.transformed(Affine.translation(cx - (bb[0] + bb[2]) / 2, cy - (bb[1] + bb[3]) / 2))
        self.push_undo()
        self.canvas.doc.add(g)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()

    def galbe_dialog(self, spec=None):
        """Galbe (TypeArt) : relief bombé des formes fermées sélectionnées
        (trous compris), posé en image de hauteurs (blanc au plus haut) à
        usiner en Relief avec la profondeur du galbe ; rend l'image."""
        from dataclasses import asdict
        from ..cam import strategies as S
        from ..core import galbe as GB
        from ..core.document import Image
        from .dialogs import ParamsDialog
        sel = list(_leaves(self.canvas.selection))
        onto = next((it for it in sel if isinstance(it, Image) and 'galbe' in it.extra), None)
        items = [it for it in sel if not isinstance(it, Image)]
        # galbe asymétrique (TypeEdit : Ctrl + Galbe) : une courbe ouverte choisie avec
        # les formes fermées sert de profil (abscisse : distance au bord, ordonnée : hauteur)
        profile_pts = None
        for it in list(items):
            g = S.item_geometry(it)
            if g is not None and g.contours and not any(c.closed for c in g.contours):
                profile_pts = [q for c in g.contours for q in c.flatten(0.01)]
                items.remove(it)
                break
        if not items:
            self.statusBar().showMessage(tr('Sélectionnez des formes fermées.'), 4000)
            return None
        if spec is None:
            last = self.settings.value('galbe/dernier', None)
            spec = GB.GalbeSpec.from_dict(last) if isinstance(last, dict) else GB.GalbeSpec()
            labels = {
                'z_max': tr('Z max. (mm)'), 'z_min': tr('Z min. (mm)'), 'distance': tr('Distance max. (mm)'),
                'start_angle': tr('Angle de départ (°, 90 : vertical)'),
                'end_angle': tr('Angle d\'arrivée (°, 0 : sommet plat)'),
                'resolution': tr('Pas de la carte (mm)'), 'margin': tr('Fond autour (mm)'),
                'compression': tr('Compression')}
            if profile_pts:                              # profil dessiné : il donne la montée
                for k in ('distance', 'start_angle', 'end_angle', 'z_max'):
                    labels.pop(k)
            if onto is not None:                         # un galbe existant est choisi : il se combine
                labels.update(mode=tr('Combinaison avec le galbe existant'),
                              limit=tr('Seulement sur le galbe existant'))
            spec.profile_pts = None
            dlg = ParamsDialog(self, tr('Galbe'), spec, labels,
                               choices={'mode': [(k, tr(v)) for k, v in GB.MODES],
                                        'compression': [(k, tr(v)) for k, v in GB.COMPRESSIONS]})
            if not dlg.exec():
                return None
            spec = dlg.result_params()
            self.settings.setValue('galbe/dernier', {k: v for k, v in asdict(spec).items() if k != 'profile_pts'})
        if profile_pts:
            spec.profile_pts = profile_pts
        reg = S.region([g for it in items if (g := S.item_geometry(it))], 0.01)
        from .progress import Cancelled, run
        try:
            img = run(self, tr('Galbe'), GB.build_image, reg, spec, self.canvas.current_tool_index, onto)
        except Cancelled:
            return None
        if img is None:
            self.statusBar().showMessage(tr('Galbe : aucun contour fermé dans la sélection.'), 5000)
            return None
        if onto is not None:
            self._replace_item(onto, img, tr('Galbe'))
        else:
            self._add_items([img])
        self.statusBar().showMessage(tr('Galbe posé : à usiner en Relief, profondeur {0} mm').format(
            f'{img.extra["galbe"]["relief_depth"]:g}'), 8000)
        return img

    # --- TypeArt : dôme, extrudé, révolution, facette ---------------------------------------------
    def typeart_mode(self) -> tuple[str, bool]:
        """Mode de combinaison des reliefs (TypeArt) et « limiter »."""
        from ..core.galbe import MODES
        m = str(self.settings.value('typeart/mode', 'ajouter') or 'ajouter')
        return (m if m in dict(MODES) else 'ajouter'), self.settings.value('typeart/limiter', False) in (True, 'true')

    def relief_merge(self):
        """Combiner des reliefs (TypeEdit) : le premier choisi reçoit les
        autres selon le mode de combinaison ; ils sont remplacés par le résultat."""
        from ..core import relief_ops as R
        from ..core.document import Image
        sel = [it for it in _leaves(self.canvas.selection) if isinstance(it, Image) and 'galbe' in it.extra]
        if len(sel) < 2:
            self.statusBar().showMessage(tr('Sélectionnez au moins deux reliefs (le courant d\'abord).'), 6000)
            return None
        mode, limit = self.typeart_mode()
        img = R.merge_reliefs(sel, mode, limit)
        if img is None:
            self.statusBar().showMessage(tr('Relief illisible (tourné ou étiré ?).'), 6000)
            return None
        self.push_undo()
        ids = {id(s) for s in sel}
        first = True
        for L in self.canvas.doc.layers:
            out = []
            for it in L.items:
                if id(it) in ids:
                    if first:
                        out.append(img)
                        first = False
                    continue
                out.append(it)
            L.items = out
        self.canvas.invalidate()
        self.canvas.select([img])
        self._on_doc_changed()
        return img

    def relief_wrap(self, params: dict | None = None):
        """Enroule le second relief choisi sur le premier ; le résultat remplace le premier."""
        from ..core import galbe as GB, relief_wrap as RW
        from ..core.document import Image
        title = tr('Enrouler sur un relief')
        onto, markers, _others = self._typeart_selection()
        sel = [it for it in _leaves(self.canvas.selection) if isinstance(it, Image) and 'galbe' in it.extra]
        if len(sel) != 2 or onto is None:
            self.statusBar().showMessage(tr('Sélectionnez deux reliefs : le support, puis celui à enrouler.'), 6000)
            return None
        base, motif = sel
        got = GB.decode(base)
        if got is None or GB.decode(motif) is None:
            self.statusBar().showMessage(tr('Ces reliefs ne se relisent pas : ils doivent être posés droits.'), 6000)
            return None
        v = self._ask('relief_wrap', title,
                      [('kind', str, 'parallele', tr('Enroulement')), ('anchor', str, 'centre', tr('Point de départ')),
                       ('mode', str, 'ajouter', tr('Résultat')), ('copies_x', bool, False, tr('Répéter en X, dans le galbe du support')),
                       ('copies_y', bool, False, tr('Répéter en Y, dans le galbe du support')),
                       ('keep', bool, False, tr('Garder le relief d’origine')),
                       ('resolution', float, round(got[3], 4), tr('Pas du résultat (mm)'))],
                      choices={'kind': [(k, tr(t)) for k, t in RW.KINDS], 'anchor': [(k, tr(t)) for k, t in RW.ANCHORS],
                               'mode': [(k, tr(t)) for k, t in RW.MODES]}, params=params)
        if v is None:
            return None
        keep = bool(v.get('keep'))
        spec = RW.WrapSpec(**{k: v[k] for k in ('kind', 'anchor', 'mode', 'copies_x', 'copies_y', 'resolution')})
        from .progress import Cancelled, run
        try:
            img = run(self, title, RW.wrap, base, motif, spec, markers)
        except Cancelled:
            return None
        except ValueError:
            self.statusBar().showMessage(tr('Sélectionnez aussi deux marqueurs : celui du support, puis celui du relief à enrouler.'), 6000)
            return None
        if img is None:
            return None
        self.push_undo(title)
        for L in self.canvas.doc.layers:
            L.items = [img if it is base else it for it in L.items if keep or it is not motif]
        self.canvas.invalidate()
        self.canvas.select([img])
        self._on_doc_changed()
        return img

    def relief_place(self, mode: str | None = None):
        """Poser (TypeArt) : le second relief choisi posé sur le premier ;
        les deux remplacés par le résultat."""
        from ..core import relief_ops as R
        from ..core.document import Image
        sel = [it for it in _leaves(self.canvas.selection) if isinstance(it, Image) and 'galbe' in it.extra]
        if len(sel) != 2:
            self.statusBar().showMessage(tr('Sélectionnez deux reliefs : le dessous, puis celui à poser.'), 6000)
            return None
        if mode is None:
            from PySide6.QtWidgets import QInputDialog
            labels = [tr(v) for _k, v in R.PLACE_MODES]
            last = str(self.settings.value('relief/poser', 'base_zmax'))
            cur = next((i for i, (k, _v) in enumerate(R.PLACE_MODES) if k == last), 1)
            text, ok = QInputDialog.getItem(self, tr('Poser'), tr('Poser le relief'), labels, cur, False)
            if not ok:
                return None
            mode = R.PLACE_MODES[labels.index(text)][0]
            self.settings.setValue('relief/poser', mode)
        img = R.place(sel[0], sel[1], mode)
        if img is None:
            self.statusBar().showMessage(tr('Relief illisible ou vide.'), 6000)
            return None
        self.push_undo()
        for L in self.canvas.doc.layers:
            L.items = [img if it is sel[0] else it for it in L.items if it is not sel[1]]
        self.canvas.invalidate()
        self.canvas.select([img])
        self._on_doc_changed()
        return img

    def set_typeart_mode(self, mode: str) -> None:
        self.settings.setValue('typeart/mode', mode)
        self._check_quietly(f'typeart_mode_{mode}', True)

    def set_typeart_limit(self, on: bool) -> None:
        self.settings.setValue('typeart/limiter', bool(on))
        self._check_quietly('typeart_mode_limit', bool(on))

    def _typeart_sync(self) -> None:
        mode, lim = self.typeart_mode()
        self._check_quietly(f'typeart_mode_{mode}', True)
        self._check_quietly('typeart_mode_limit', lim)

    # --- volumes 3D ----------------------------------------------------------------------
    def _solid_centers(self) -> list:
        """Où poser une primitive : les marqueurs choisis, sinon le centre de
        chaque objet choisi, sinon le centre de la plaque, sinon l'origine."""
        if self._hist_centers is not None:                 # un recalcul : là où elle a été posée
            return [tuple(c) for c in self._hist_centers]
        _onto, markers, others = self._typeart_selection()
        if markers:
            return markers
        cs = [((b[0] + b[2]) / 2, (b[1] + b[3]) / 2) for it in others if (b := it.bbox())]
        if cs:
            return cs
        pl = self.canvas.doc.plate
        return [(pl.x + pl.width / 2, pl.y + pl.height / 2)] if pl is not None else [(0.0, 0.0)]

    def _solids_ready(self) -> bool:
        from ..core import solids as SO
        if not SO.available():
            QMessageBox.warning(self, tr('Volumes 3D'), tr('Le module manifold3d manque : volumes 3D indisponibles.'))
            return False
        return True

    def _put_solids(self, solids: list, replace: list = ()) -> list:
        """Volumes ajoutés au dessin (calque actif, outil du calque), à la
        place des objets `replace` s'il y en a ; annulable. Rend les formes."""
        from ..core import solids as SO
        tool = self.canvas.current_tool_index
        new = [SO.make_shape(s, tool) for s in solids]
        if not new:
            return []
        if replace:
            self.canvas.selection = list(replace)
            self._replace_selection(new)
        else:
            self._add_items(new)
        if self.view_mode() == '3d' and self.panel3d is not None:
            self.panel3d.stale = True
            self._refresh3d.start()
        return new

    def solid_primitive(self, kind: str, params: dict | None = None) -> list:
        """Pavé, coin, cylindre, cône, sphère, pyramide ou tore, posé sur les
        marqueurs choisis (ou au centre des objets choisis, de la plaque)."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        spec = {'box': [('dx', float, 20.0, tr('Longueur X (mm)')), ('dy', float, 20.0, tr('Largeur Y (mm)')),
                        ('dz', float, 10.0, tr('Hauteur Z (mm, négatif : vers le bas)')),
                        ('z0', float, 0.0, tr('Z de la base (mm)'))],
                'cylinder': [('r', float, 10.0, tr('Rayon (mm)')), ('h', float, 10.0, tr('Hauteur (mm)')),
                             ('z0', float, 0.0, tr('Z de la base (mm)'))],
                'cone': [('r', float, 10.0, tr('Rayon de la base (mm)')),
                         ('r_top', float, 0.0, tr('Rayon du dessus (mm, 0 : pointe)')),
                         ('h', float, 10.0, tr('Hauteur (mm)')), ('z0', float, 0.0, tr('Z de la base (mm)'))],
                'sphere': [('r', float, 10.0, tr('Rayon (mm)')),
                           ('z', float, 10.0, tr('Z du centre (mm ; égal au rayon : posée sur le plan)'))],
                'pyramid': [('sides', int, 4, tr('Nombre de côtés')),
                            ('r', float, 10.0, tr('Rayon de la base (mm, cercle passant par les sommets)')),
                            ('r_top', float, 0.0, tr('Rayon du dessus (mm, 0 : pointe)')),
                            ('h', float, 10.0, tr('Hauteur (mm)')), ('z0', float, 0.0, tr('Z de la base (mm)'))],
                'torus': [('R', float, 20.0, tr('Rayon de l\'anneau (mm, jusqu\'au centre du tube)')),
                          ('r', float, 5.0, tr('Rayon du tube (mm)')),
                          ('z', float, 5.0, tr('Z du centre (mm ; égal au rayon du tube : posé sur le plan)'))]}
        spec['wedge'] = spec['box']
        title = {'box': tr('Pavé'), 'wedge': tr('Coin'), 'cylinder': tr('Cylindre'), 'cone': tr('Cône'),
                 'sphere': tr('Sphère'), 'pyramid': tr('Pyramide'), 'torus': tr('Tore')}[kind]
        p = self._ask(f'solide_{kind}', title, spec[kind], params=params)
        if p is None:
            return []
        out = []
        try:
            for cx, cy in self._solid_centers():
                if kind in ('box', 'wedge'):
                    fn = SO.box if kind == 'box' else SO.wedge
                    s = fn(cx - p['dx'] / 2, cy - p['dy'] / 2, p['z0'], p['dx'], p['dy'], p['dz'])
                elif kind == 'cylinder':
                    s = SO.cylinder(cx, cy, p['z0'], p['r'], p['h'])
                elif kind == 'cone':
                    s = SO.cone(cx, cy, p['z0'], p['r'], p['h'], p['r_top'])
                elif kind == 'sphere':
                    s = SO.sphere(cx, cy, p['z'], p['r'])
                elif kind == 'pyramid':
                    s = SO.pyramid(cx, cy, p['z0'], int(p['sides']), p['r'], p['h'], p['r_top'])
                else:
                    s = SO.torus(cx, cy, p['z'], p['R'], p['r'])
                s.name = title
                out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out)

    def solid_to_relief(self, params: dict | None = None):
        """Volumes choisis → relief (le dessus de la matière à chaque pas),
        posé à côté d'eux ; rend l'image du relief."""
        from ..core import galbe as GB
        from ..core import solids as SO
        vols = [s for it in _leaves(self.canvas.selection) if (s := SO.of_item(it)) is not None]
        if not vols:
            self.statusBar().showMessage(tr('Sélectionnez des volumes.'), 5000)
            return None
        p = self._ask('solide_relief', tr('Volume en relief'),
                      [('resolution', float, 0.1, tr('Pas de la carte (mm)')),
                       ('margin', float, 1.0, tr('Fond autour (mm)'))], params=params)
        if p is None:
            return None
        from .progress import Cancelled, run
        try:
            H, x0, y1, res = run(self, tr('Volume en relief'), SO.heights, vols, float(p['resolution']),
                                 float(p['margin']))
        except Cancelled:
            return None
        spec = GB.GalbeSpec(resolution=res, margin=float(p['margin']))
        img = GB.encode(H, x0, y1, res, spec, self.canvas.current_tool_index, tr('Volume en relief'))
        return self._typeart_put(img, None, tr('Volume en relief'))

    def relief_to_solid(self, params: dict | None = None) -> list:
        """Reliefs choisis → volumes (dessus aux hauteurs du relief, socle
        dessous) ; les reliefs restent."""
        from ..core import galbe as GB
        from ..core import solids as SO
        from ..core.document import Image
        if not self._solids_ready():
            return []
        imgs = [it for it in _leaves(self.canvas.selection) if isinstance(it, Image) and 'galbe' in it.extra]
        if not imgs:
            self.statusBar().showMessage(tr('Sélectionnez des reliefs.'), 5000)
            return []
        p = self._ask('relief_volume', tr('Relief en volume'),
                      [('floor', float, 2.0, tr('Socle sous le point le plus bas (mm)')),
                       ('max_cells', int, 250_000, tr('Points du relief au plus (allège le volume)'))], params=params)
        if p is None:
            return []
        out = []
        for img in imgs:
            got = GB.decode(img)
            if got is None:
                continue
            H, x0, y1, res = got
            try:
                out.append(SO.from_heightmap(H, x0, y1, res, float(p['floor']), int(p['max_cells']),
                                             img.name or tr('Relief')))
            except SO.SolidError as ex:
                self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
        return self._put_solids(out)

    def solid_import(self, path: str | None = None) -> list:
        """Un STL ajouté au dessin comme volume (maillage fermé exigé)."""
        from ..core import solids as SO
        from ..io import mesh3d
        if not self._solids_ready():
            return []
        if path is None:
            path, _ = QFileDialog.getOpenFileName(self, tr('Importer un volume'), self._last_dir('modele3d'),
                                                  tr('STL (*.stl)'))
            if not path:
                return []
            self._remember_dir('modele3d', path)
        try:
            s = SO.from_triangles(mesh3d.read_stl(path), pathlib.Path(path).stem)
        except (OSError, ValueError) as ex:
            QMessageBox.warning(self, tr('Importer un volume'), tr('{0} : maillage illisible ou non fermé ({1})')
                                .format(pathlib.Path(path).name, ex))
            return []
        return self._put_solids([s])

    def _selected_solids(self) -> list:
        """[(forme, volume)] des volumes choisis (au premier niveau)."""
        from ..core import solids as SO
        return [(it, s) for it in self.canvas.selection if (s := SO.of_item(it)) is not None]

    def _swap_solids(self, mapping: list, extra_items: list = ()) -> list:
        """Chaque forme de `mapping` [(forme, [volumes])] remplacée, à sa
        place, par ses volumes (aucun : supprimée) ; `extra_items` ajoutés au
        calque actif. Annulable ; rend les nouvelles formes."""
        from ..core import solids as SO
        self.push_undo()
        repl = {}
        for it, sols in mapping:
            news = [SO.with_solid(it, sols[0])] if sols else []
            for s in sols[1:]:
                sh = SO.make_shape(s, it.tool)
                sh.name = it.name
                news.append(sh)
            repl[id(it)] = news
        new_all = []
        for L in self.canvas.doc.layers:
            items = []
            for it in L.items:
                if id(it) in repl:
                    items += repl[id(it)]
                    new_all += repl[id(it)]
                else:
                    items.append(it)
            L.items = items
        for it in extra_items:
            self.canvas.doc.add(it)
        new_all += list(extra_items)
        self.canvas.invalidate()
        self.canvas.select(new_all)
        self._on_doc_changed()
        if self.view_mode() == '3d' and self.panel3d is not None:
            self.panel3d.stale = True
            self._refresh3d.start()
        return new_all

    def _need_solids(self) -> list:
        pairs = self._selected_solids()
        if not pairs:
            self.statusBar().showMessage(tr('Sélectionnez des volumes.'), 5000)
        return pairs

    def solid_move_z(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_z', tr('Déplacer en Z'), [('dz', float, 5.0, tr('Déplacement en Z (mm)'))],
                      params=params) if pairs else None
        if p is None:
            return []
        m = SO.translation(0, 0, float(p['dz']))
        return self._swap_solids([(it, [s.transformed(m)]) for it, s in pairs])

    def solid_align3d(self, params: dict | None = None) -> list:
        """Aligner (SolidCraft : solid.align, ici sur les encombrements) : les
        volumes choisis sur le premier choisi, qui ne bouge pas."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if len(pairs) < 2:
            self.statusBar().showMessage(tr('Sélectionnez d\'abord le volume de référence, puis les autres.'), 5000)
            return []
        side = [('none', tr('Ne pas bouger')), ('min', tr('Côtés mini alignés')), ('centre', tr('Centres alignés')),
                ('max', tr('Côtés maxi alignés')), ('after', tr('Contre le côté maxi')),
                ('before', tr('Contre le côté mini'))]
        p = self._ask('solide_aligner', tr('Aligner'),
                      [('x', str, 'centre', tr('En X')), ('y', str, 'centre', tr('En Y')), ('z', str, 'after', tr('En Z')),
                       ('gap', float, 0.0, tr('Jeu contre la référence (mm)'))],
                      choices={'x': side, 'y': side,
                               'z': [('none', tr('Ne pas bouger')), ('min', tr('Dessous alignés')),
                                     ('centre', tr('Centres alignés')), ('max', tr('Dessus alignés')),
                                     ('after', tr('Posés sur la référence')), ('before', tr('Sous la référence'))]},
                      params=params)
        if p is None:
            return []
        ref = pairs[0][1].bounds()
        out = []
        for it, s in pairs[1:]:
            d = SO.align_offset(s.bounds(), ref, (p['x'], p['y'], p['z']), float(p['gap']))
            out.append((it, [s.transformed(SO.translation(*d))]))
        return self._swap_solids(out)

    def solid_rotate3d(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_rotation', tr('Rotation 3D'),
                      [('axis', str, 'x', tr('Axe')), ('angle', float, 90.0, tr('Angle (°, sens direct)')),
                       ('together', bool, False, tr('Autour du centre de l\'ensemble (sinon de chacun)'))],
                      choices={'axis': [('x', 'X'), ('y', 'Y'), ('z', 'Z')]}, params=params) if pairs else None
        if p is None:
            return []

        def center(bs):
            return ((min(b[0] for b in bs) + max(b[3] for b in bs)) / 2, (min(b[1] for b in bs) + max(b[4] for b in bs)) / 2,
                    (min(b[2] for b in bs) + max(b[5] for b in bs)) / 2)
        common = center([s.bounds() for _it, s in pairs])
        out = []
        for it, s in pairs:
            m = SO.rotation(p['axis'], float(p['angle']), common if p['together'] else center([s.bounds()]))
            out.append((it, [s.transformed(m)]))
        return self._swap_solids(out)

    def solid_permute(self, keep: bool | None = None) -> list:
        """Les volumes choisis, X Y Z devenant Z X Y. Avec Maj (`keep`), l'original reste et le résultat se pose à côté."""
        from PySide6.QtWidgets import QApplication
        from ..core import solids as SO
        pairs = self._need_solids()
        if not pairs:
            return []
        if keep is None:
            keep = bool(QApplication.keyboardModifiers() & Qt.KeyboardModifier.ShiftModifier)
        out = []
        for it, s in pairs:
            b = s.bounds()
            shift = (b[3] - b[0] + b[5] - b[2]) / 2 + 5.0 if keep else 0.0     # l'ancienne largeur et la nouvelle (Z)
            new = s.transformed(SO.permutation(b, shift))
            out.append((it, [s, new] if keep else [new]))
        return self._swap_solids(out)

    def solid_scale3d(self, params: dict | None = None) -> list:
        """Échelle 3D (SCALE, d'après SolidCraft) des volumes choisis : un
        facteur, ou un par axe, autour du centre de leur dessous, de leur
        centre ou de l'origine, chacun ou l'ensemble."""
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_echelle', tr('Échelle 3D'),
                      [('factor', float, 1.0, tr('Facteur (tous les axes)')),
                       ('per_axis', bool, False, tr('Un facteur par axe')),
                       ('fx', float, 1.0, tr('Facteur en X')),
                       ('fy', float, 1.0, tr('Facteur en Y')),
                       ('fz', float, 1.0, tr('Facteur en Z')),
                       ('origin', str, 'dessous', tr('Point fixe')),
                       ('together', bool, False, tr('Pour l\'ensemble (sinon pour chacun)'))],
                      choices={'origin': [('dessous', tr('Centre du dessous')), ('centre', tr('Centre')),
                                          ('origine', tr('Origine du dessin'))]}, params=params) if pairs else None
        if p is None:
            return []
        f = ((float(p['fx']), float(p['fy']), float(p['fz'])) if p['per_axis'] else (float(p['factor']),) * 3)

        def fixed(bs):
            if p['origin'] == 'origine':
                return (0.0, 0.0, 0.0)
            x0, y0, z0 = (min(b[k] for b in bs) for k in range(3))
            x1, y1, z1 = (max(b[k] for b in bs) for k in range(3, 6))
            return ((x0 + x1) / 2, (y0 + y1) / 2, z0 if p['origin'] == 'dessous' else (z0 + z1) / 2)
        common = fixed([s.bounds() for _it, s in pairs])
        try:
            out = [(it, [s.transformed(SO.scaling(*f, common if p['together'] else fixed([s.bounds()])))])
                   for it, s in pairs]
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        return self._swap_solids(out)

    def solid_mirror_z(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_symetrie', tr('Symétrie en Z'),
                      [('z', float, 0.0, tr('Z du plan de symétrie (mm)')),
                       ('copy', bool, False, tr('Garder l\'original (copie retournée)'))], params=params) if pairs else None
        if p is None:
            return []
        m = SO.mirror_z(float(p['z']))
        return self._swap_solids([(it, ([s] if p['copy'] else []) + [s.transformed(m)]) for it, s in pairs])

    def solid_slice(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_coupe', tr('Couper'),
                      [('plane', str, 'z', tr('Plan de coupe')), ('value', float, 5.0, tr('Position du plan (mm)')),
                       ('keep', str, 'deux', tr('Garder'))],
                      choices={'plane': [('z', tr('Horizontal (Z =)')), ('x', tr('Vertical (X =)')),
                                         ('y', tr('Vertical (Y =)')),
                                         ('trait', tr('Vertical, par le trait choisi avec les volumes'))],
                               'keep': [('deux', tr('Les deux côtés')), ('plus', tr('Au-dessus / du côté + (à droite du trait)')),
                                        ('moins', tr('Au-dessous / du côté − (à gauche du trait)'))]},
                      params=params) if pairs else None
        if p is None:
            return []
        if p['plane'] == 'trait':                       # SolidCraft : plan d'une ligne d'esquisse
            ends = self._chosen_trait()
            if ends is None:
                QMessageBox.information(self, tr('Couper'), tr('Choisissez aussi un trait du dessin (le premier '
                                                               'segment d\'une forme 2D) : le plan vertical passe '
                                                               'par lui.'))
                return []
            n, value = SO.line_plane(*ends)
        else:
            n, value = {'x': (1, 0, 0), 'y': (0, 1, 0), 'z': (0, 0, 1)}[p['plane']], float(p['value'])
        out = []
        for it, s in pairs:
            a, b = SO.split(s, n, value)
            keep = [x for x, side in ((a, 'plus'), (b, 'moins')) if x is not None and p['keep'] in (side, 'deux')]
            out.append((it, keep))
        return self._swap_solids(out)

    def _chosen_trait(self):
        """Extrémités du premier segment de la première forme 2D choisie (pas
        un volume), ou None."""
        import math
        from ..core import solids as SO
        for it in self.canvas.selection:
            if isinstance(it, Shape) and SO.of_item(it) is None:
                for c in it.path.contours:
                    for seg in c.segments:
                        if math.dist(seg.start, seg.end) > 1e-9:
                            return seg.start, seg.end
        return None

    def solid_section(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_section', tr('Section'), [('z', float, 1.0, tr('Hauteur de la section (Z, mm)'))],
                      params=params) if pairs else None
        if p is None:
            return []
        shapes = []
        for it, s in pairs:
            path = SO.section(s, float(p['z']))
            if path.contours:
                shapes.append(Shape(path=path, tool=it.tool, name=tr('Section Z {0}').format(f'{p["z"]:g}')))
        if not shapes:
            self.statusBar().showMessage(tr('Le plan ne traverse aucun volume choisi.'), 5000)
            return []
        self._add_items(shapes)
        return shapes

    def solid_flatshot(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        from ..core.geom import Affine
        pairs = self._need_solids()
        p = self._ask('solide_vue', tr('Vue à plat'), [('view', str, 'face', tr('Vue')),
                                                       ('gap', float, 10.0, tr('Écart à droite des volumes (mm)'))],
                      choices={'view': [('dessus', tr('Dessus')), ('face', tr('Face')), ('cote', tr('Côté'))]},
                      params=params) if pairs else None
        if p is None:
            return []
        x1 = max(s.bounds()[3] for _it, s in pairs)
        y0 = min(s.bounds()[1] for _it, s in pairs)
        paths = [SO.flatshot(s, p['view']) for _it, s in pairs]
        bbs = [q.bbox() for q in paths if q.contours]
        if not bbs:
            return []
        dx = x1 + float(p['gap']) - min(b[0] for b in bbs)
        dy = y0 - min(b[1] for b in bbs)
        m = Affine.translation(dx, dy)
        label = {'dessus': tr('Dessus'), 'face': tr('Face'), 'cote': tr('Côté')}[p['view']]
        shapes = [Shape(path=q.transformed(m), tool=it.tool, name=label) for (it, _s), q in zip(pairs, paths)
                  if q.contours]
        self._add_items(shapes)
        return shapes

    def solid_interfere(self, params: dict | None = None) -> list:
        """Interférence : volume commun de chaque paire de volumes choisis ;
        `add` : ces volumes communs ajoutés au dessin."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if len(pairs) < 2:
            self.statusBar().showMessage(tr('Sélectionnez au moins deux volumes.'), 5000)
            return []
        found = SO.interference([s for _it, s in pairs])
        if not found:
            self.statusBar().showMessage(tr('Aucune interférence entre les volumes choisis.'), 6000)
            return []
        lines = [f'{pairs[i][0].name or i + 1} × {pairs[j][0].name or j + 1} : {c.volume():.3f} mm³' for i, j, c in found]
        p = self._ask('solide_interference', tr('Interférence'),
                      [('add', bool, True, tr('Ajouter les volumes communs au dessin'))], params=params)
        if p is None:
            return []
        self.statusBar().showMessage(tr('{0} interférence(s) : {1}').format(len(found), ' ; '.join(lines)), 12000)
        return self._put_solids([c for _i, _j, c in found]) if p['add'] else []

    def solid_clearance(self, params: dict | None = None) -> dict | None:
        """Jeu entre volumes (SolidCraft : inspect.clearance) : chevauchements,
        contacts, paires plus proches que le jeu, plus proche voisin de
        chaque volume ; un compte rendu (non modal)."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if len(pairs) < 2:
            self.statusBar().showMessage(tr('Sélectionnez au moins deux volumes.'), 5000)
            return None
        p = self._ask('solide_jeu', tr('Jeu entre volumes'),
                      [('gap', float, 1.0, tr('Jeu minimal (mm) : signaler les volumes plus proches')),
                       ('min_volume', float, 0.01, tr('Chevauchement compté au-delà de (mm³ ; en deçà : contact)'))],
                      params=params)
        if p is None:
            return None
        r = SO.clearance([s for _it, s in pairs], float(p['gap']), float(p['min_volume']))
        name = [it.name or tr('Volume {0}').format(k + 1) for k, (it, _s) in enumerate(pairs)]
        lines = []
        if r['overlaps']:
            lines.append(tr('Chevauchements :'))
            lines += [f'  {name[i]} × {name[j]} : {v:.3f} mm³' for i, j, v in r['overlaps']]
        if r['contacts']:
            lines.append(tr('Contacts :'))
            lines += [f'  {name[i]} × {name[j]}' for i, j in r['contacts']]
        if r['near']:
            lines.append(tr('Plus proches que {0} mm :').format(f'{float(p["gap"]):g}'))
            lines += [tr('  {0} × {1} : {2:.3f} mm, vers X {3:.2f}  Y {4:.2f}  Z {5:.2f}').format(
                name[i], name[j], d, *((a + b) / 2 for a, b in zip(pa, pb))) for i, j, d, pa, pb in r['near']]
        if not lines:
            lines.append(tr('Aucun chevauchement, aucun contact, aucune paire plus proche que {0} mm.').format(
                f'{float(p["gap"]):g}'))
        lines.append(tr('Plus proche voisin :'))
        lines += [f'  {name[k]} → {name[nb[0]]} : {nb[1]:.3f} mm' for k, nb in enumerate(r['nearest']) if nb]
        r['text'] = '\n'.join(lines)
        if params is None:
            box = QMessageBox(QMessageBox.Icon.Information, tr('Jeu entre volumes'), r['text'],
                              QMessageBox.StandardButton.Ok, self)
            box.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            box.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
            box.open()
        return r

    def solid_compare(self, params: dict | None = None) -> dict | None:
        """Comparer deux volumes (SolidCraft : inspect.compare) : le premier
        choisi est A, le second B ; compte rendu non modal ; `add` : les
        régions ajoutées au dessin (rouge : matière de A seulement, vert : de
        B seulement)."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if len(pairs) != 2:
            self.statusBar().showMessage(tr('Sélectionnez deux volumes : la version A puis la version B.'), 5000)
            return None
        p = self._ask('solide_comparer', tr('Comparer deux volumes'),
                      [('tolerance', float, 0.01, tr('Tolérance (mm) : les surfaces plus proches s\'accordent')),
                       ('spacing', float, 0.5, tr('Espacement des points mesurés (mm)')),
                       ('add', bool, False, tr('Ajouter les régions différentes au dessin (rouge : A seul, vert : '
                                               'B seul)'))], params=params)
        if p is None:
            return None
        tol = max(1e-6, float(p['tolerance']))
        (ia, a), (ib, b) = pairs
        from PySide6.QtWidgets import QApplication
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            r = SO.compare(a, b, tol, max(0.01, float(p['spacing'])))
        finally:
            QApplication.restoreOverrideCursor()
        na, nb = ia.name or 'A', ib.name or 'B'
        lines = [tr('A : {0} — {1:.3f} mm³, {2:.3f} mm²').format(na, r['a']['volume'], r['a']['area']),
                 tr('B : {0} — {1:.3f} mm³, {2:.3f} mm²').format(nb, r['b']['volume'], r['b']['area']),
                 tr('Différence de volume B − A : {0:+.3f} mm³').format(r['difference']),
                 tr('Écart de A à B : plus grand {0:.4f} mm (X {1:.2f}  Y {2:.2f}  Z {3:.2f}), moyen {4:.4f} mm').format(
                     r['a_to_b']['max'], *r['a_to_b']['at'], r['a_to_b']['mean']),
                 tr('Écart de B à A : plus grand {0:.4f} mm (X {1:.2f}  Y {2:.2f}  Z {3:.2f}), moyen {4:.4f} mm').format(
                     r['b_to_a']['max'], *r['b_to_a']['at'], r['b_to_a']['mean'])]
        if r['identical']:
            lines.append(tr('Identiques à {0:g} mm près (plus grand écart {1:.4f} mm).').format(tol, r['max']))
        else:
            ra = [g for g in r['regions'] if g['side'] == 'a']
            rb = [g for g in r['regions'] if g['side'] == 'b']
            lines.append(tr('{0} région(s) différente(s) de plus de {1:g} mm : {2} de matière de A seulement '
                            '({3:.3f} mm³), {4} de B seulement ({5:.3f} mm³)').format(
                len(r['regions']), tol, len(ra), sum(g['volume'] for g in ra), len(rb), sum(g['volume'] for g in rb)))
            lines += [tr('  {0} seul : {1:.3f} mm³, écart {2:.3f} mm, vers X {3:.2f}  Y {4:.2f}  Z {5:.2f}').format(
                'A' if g['side'] == 'a' else 'B', g['volume'], g['max_deviation'], *g['center'])
                for g in r['regions'][:20]]
        r['text'] = '\n'.join(lines)
        if params is None:
            box = QMessageBox(QMessageBox.Icon.Information, tr('Comparer deux volumes'), r['text'],
                              QMessageBox.StandardButton.Ok, self)
            box.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            box.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
            box.open()
        if p['add'] and r['regions']:
            pieces = []
            for g in r['regions']:
                g['solid'].name = tr('{0} seul').format(na if g['side'] == 'a' else nb)
                pieces.append(g['solid'])
            r['items'] = self._put_solids(pieces)
        return r

    def solid_array_z(self, params: dict | None = None) -> list:
        """Réseau en Z : `count` exemplaires de chaque volume choisi (lui
        compris), décalés de `step` en hauteur et tournés de `angle` autour
        de l'axe vertical de son centre, de l'un à l'autre."""
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_reseau_z', tr('Réseau en Z'),
                      [('count', int, 3, tr('Nombre d\'exemplaires (l\'original compris)')),
                       ('step', float, 10.0, tr('Pas en hauteur (mm)')),
                       ('angle', float, 0.0, tr('Rotation de l\'un à l\'autre (°)'))], params=params) if pairs else None
        if p is None or int(p['count']) < 2:
            return []
        out = []
        for it, s in pairs:
            b = s.bounds()
            c = ((b[0] + b[3]) / 2, (b[1] + b[4]) / 2, 0.0)
            copies = [s]
            for k in range(1, int(p['count'])):
                m = SO.translation(0, 0, k * float(p['step'])) @ SO.rotation('z', k * float(p['angle']), c)
                copies.append(s.transformed(m))
            out.append((it, copies))
        return self._swap_solids(out)

    def solid_separate(self) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        out = [(it, SO.components(s)) for it, s in pairs]
        if all(len(c) <= 1 for _it, c in out):
            if pairs:
                self.statusBar().showMessage(tr('Chaque volume choisi est d\'un seul tenant.'), 5000)
            return []
        return self._swap_solids(out)

    def solid_analysis(self, params: dict | None = None) -> list:
        """Analyse de surface de la pièce 3D (volumes du dessin ou fichier
        STEP), d'après SolidCraft : dépouille des faces vers une direction de
        démoulage, ou faces atteintes le long d'une direction ; la vue 3D en
        couleurs, les parts de la surface dans la barre d'état. Rend ces
        parts (0..1)."""
        p = self._ask('solide_analyse', tr('Analyse de surface'),
                      [('mode', str, 'depouille', tr('Analyse')),
                       ('direction', str, 'z+', tr('Direction')),
                       ('angle', float, 1.0, tr('Dépouille minimale (°)'))],
                      choices={'mode': [('depouille', tr('Dépouille : vert au moins l\'angle, jaune moins, rouge à '
                                                         'l\'opposé')),
                                        ('acces', tr('Accessibilité : vert atteinte, rouge cachée')),
                                        ('aucune', tr('Aucune : couleurs de la pièce'))],
                               'direction': [(k, k[0].upper() + ('+' if k[1] == '+' else '−'))
                                             for k in ('z+', 'z-', 'x+', 'x-', 'y+', 'y-')]}, params=params)
        if p is None:
            return []
        self.set_view_mode('3d')
        panel = self.panel3d
        panel.show_part()
        kind = None if p['mode'] == 'aucune' else p['mode']
        if kind and panel.view.model is None:
            self.statusBar().showMessage(tr('Aucune pièce 3D à analyser (volumes du dessin ou fichier STEP).'), 6000)
            return []
        shares = panel.set_analysis(kind, p['direction'], float(p['angle']))
        pc = [f'{100 * v:.1f}' for v in shares]
        if kind == 'depouille':
            panel._say(tr('Dépouille d\'au moins {0}° : {1} % ; moins : {2} % ; à l\'opposé : {3} %').format(
                f'{abs(float(p["angle"])):g}', *pc))
        elif kind == 'acces':
            panel._say(tr('Atteinte : {0} % ; cachée : {1} %').format(*pc))
        else:
            panel._say(tr('Analyse de surface retirée'))
        return shares

    def solid_cells(self, params: dict | None = None) -> list:
        """Cellules (BOUNDARY FILL, d'après SolidCraft) des volumes choisis :
        morceaux, vides enfermés ou les deux, ajoutés (volumes gardés) ou à
        la place des volumes."""
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_cellules', tr('Cellules'),
                      [('mode', str, 'cavites', tr('Cellules')),
                       ('keep', bool, True, tr('Garder les volumes choisis'))],
                      choices={'mode': [('cavites', tr('Vides enfermés')), ('morceaux', tr('Morceaux')),
                                        ('tous', tr('Morceaux et vides'))]}, params=params) if pairs else None
        if p is None:
            return []
        try:
            cells = SO.boundary_cells([s for _it, s in pairs], p['mode'] != 'cavites', p['mode'] != 'morceaux')
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        for c in cells:
            c.name = tr(c.name)
        if p['keep']:
            new = self._put_solids(cells)
        else:
            new = self._swap_solids([(pairs[0][0], cells)] + [(it, []) for it, _s in pairs[1:]])
        self.statusBar().showMessage(tr('{0} cellule(s), {1} mm³ en tout').format(
            len(cells), f'{sum(c.volume() for c in cells):.1f}'), 8000)
        return new

    def solid_sweep(self, params: dict | None = None) -> list:
        """Balayage (SWEEP) : le premier objet choisi est le chemin, les
        formes fermées suivantes les profils."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        sel = [it for it in self.canvas.selection if isinstance(it, Shape) and not SO.is_solid(it)
               and it.path.contours]
        if len(sel) < 2:
            self.statusBar().showMessage(tr('Choisissez le chemin, puis un ou plusieurs profils fermés.'), 6000)
            return []
        path_item, profiles = sel[0], [it for it in sel[1:] if any(c.closed for c in it.path.contours)]
        if not profiles:
            self.statusBar().showMessage(tr('Choisissez le chemin, puis un ou plusieurs profils fermés.'), 6000)
            return []
        p = self._ask('solide_balayage', tr('Balayage 3D'),
                      [('z', float, 0.0, tr('Hauteur du chemin (Z, mm)')),
                       ('twist', float, 0.0, tr('Torsion le long du chemin (°)')),
                       ('scale_end', float, 1.0, tr('Échelle du profil à l\'arrivée (1 : la même)')),
                       ('delete', bool, True, tr('Remplacer les profils par les volumes'))], params=params)
        if p is None:
            return []
        out = []
        try:
            for prof in profiles:
                s = SO.sweep(path_item.path.contours[0], prof.path, float(p['z']), float(p['twist']),
                             float(p['scale_end']))
                s.name = prof.name or tr('Balayage')
                out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out, profiles if p['delete'] else ())

    def solid_loft(self, params: dict | None = None) -> list:
        """Lissage entre sections (LOFT) : les contours fermés choisis, dans
        l'ordre du choix, posés de bas en haut à `step` mm l'un de l'autre
        (ou aux hauteurs `heights` : « 0 ; 12 ; 30 »)."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        secs = [it for it in self.canvas.selection if isinstance(it, Shape) and not SO.is_solid(it)
                and any(c.closed for c in it.path.contours)]
        if len(secs) < 2:
            self.statusBar().showMessage(tr('Choisissez au moins deux contours fermés, de bas en haut.'), 6000)
            return []
        p = self._ask('solide_lissage', tr('Lissage 3D'),
                      [('step', float, 10.0, tr('Écart en hauteur entre deux sections (mm)')),
                       ('heights', str, '', tr('Ou hauteurs des sections (mm, séparées par ;)')),
                       ('smooth', bool, True, tr('Passage arrondi (sinon réglé)')),
                       ('delete', bool, True, tr('Remplacer les sections par le volume'))], params=params)
        if p is None:
            return []
        zs = [i * float(p['step']) for i in range(len(secs))]
        txt = str(p.get('heights') or '').replace(',', '.').strip()
        if txt:
            try:
                got = [float(v) for v in txt.replace(' ', '').split(';') if v]
            except ValueError:
                got = []
            if len(got) != len(secs):
                self.statusBar().showMessage(tr('Il faut une hauteur par section ({0}).').format(len(secs)), 6000)
                return []
            zs = got
        try:
            s = SO.loft([next(c for c in it.path.contours if c.closed) for it in secs], zs, bool(p['smooth']))
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        s.name = tr('Lissage')
        return self._put_solids([s], secs if p['delete'] else ())

    def solid_polysolid(self, params: dict | None = None) -> list:
        """Mur (POLYSOLID) le long de chaque trait choisi."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        lines = [it for it in _leaves(self.canvas.selection) if isinstance(it, Shape) and not SO.is_solid(it)
                 and it.path.contours]
        if not lines:
            self.statusBar().showMessage(tr('Sélectionnez des traits.'), 5000)
            return []
        p = self._ask('solide_mur', tr('Mur'),
                      [('width', float, 5.0, tr('Largeur (mm)')), ('height', float, 20.0, tr('Hauteur (mm)')),
                       ('justify', str, 'centre', tr('Position par rapport au trait')),
                       ('z', float, 0.0, tr('Z de la base (mm)')),
                       ('delete', bool, False, tr('Remplacer les traits par les murs'))],
                      choices={'justify': [('gauche', tr('À gauche')), ('centre', tr('Au milieu')),
                                           ('droite', tr('À droite'))]}, params=params)
        if p is None:
            return []
        out = []
        try:
            for it in lines:
                for c in it.path.contours:
                    s = SO.polysolid(c, float(p['width']), float(p['height']), p['justify'], float(p['z']))
                    s.name = tr('Mur')
                    out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out, lines if p['delete'] else ())

    def _solid_each(self, title: str, fn, pairs: list) -> list:
        """`fn(volume)` appliqué à chaque volume choisi (barre de progression),
        résultats à leur place."""
        from ..core import solids as SO
        from .progress import Cancelled, run
        out = []
        try:
            for it, s in pairs:
                out.append((it, [run(self, title, fn, s)]))
        except Cancelled:
            return []
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        return self._swap_solids(out)

    def solid_shell(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_coque', tr('Coque'),
                      [('thickness', float, 2.0, tr('Épaisseur des parois (mm)')),
                       ('direction', str, 'inside', tr('Parois')),
                       ('open_top', bool, False, tr('Ouverte par le dessus')),
                       ('open_bottom', bool, False, tr('Ouverte par le dessous')),
                       ('open_xmin', bool, False, tr('Ouverte côté X−')),
                       ('open_xmax', bool, False, tr('Ouverte côté X+')),
                       ('open_ymin', bool, False, tr('Ouverte côté Y−')),
                       ('open_ymax', bool, False, tr('Ouverte côté Y+'))],
                      choices={'direction': [('inside', tr('Dedans (l\'encombrement ne change pas)')),
                                             ('outside', tr('Dehors (le volume devient le vide)')),
                                             ('both', tr('Des deux côtés (moitié de l\'épaisseur)'))]},
                      params=params) if pairs else None
        if p is None:
            return []
        sides = [k for k, key in (('-z', 'open_bottom'), ('-x', 'open_xmin'), ('+x', 'open_xmax'),
                                  ('-y', 'open_ymin'), ('+y', 'open_ymax')) if p[key]]
        return self._solid_each(tr('Coque'), lambda s: SO.shell(s, float(p['thickness']), bool(p['open_top']),
                                                                open_sides=sides, direction=p['direction']), pairs)

    def solid_round(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_arrondi', tr('Arrondir les arêtes'),
                      [('radius', float, 1.0, tr('Rayon (mm)')),
                       ('concave', bool, False, tr('Arrondir aussi les arêtes rentrantes'))],
                      params=params) if pairs else None
        if p is None:
            return []
        return self._solid_each(tr('Arrondir les arêtes'),
                                lambda s: SO.round_edges(s, float(p['radius']), bool(p['concave'])), pairs)

    def solid_edges(self, params: dict | None = None) -> list:
        """Congés et chanfreins sur les arêtes qu'on clique (core.edge_blend)."""
        from ..core import edge_blend as EB
        pairs = self._need_solids()
        if not pairs:
            return []
        if len(pairs) > 1:
            self.statusBar().showMessage(tr('Choisissez un seul volume : les arêtes se cliquent sur lui.'), 6000)
            return []
        if params is None:
            params = self._edges_dialog(pairs[0][1])
            if params is None:
                return []
        title = tr('Congés et chanfreins')
        p = self._ask('solide_aretes', title,
                      [('radius', float, 2.0, tr('Rayon ou distance (mm)')),
                       ('kind', str, 'fillet', tr('Forme')),
                       ('radius_end', float, 0.0, tr('À l’autre bout (mm)'))],
                      choices={'kind': [('fillet', tr('Congé')), ('chamfer', tr('Chanfrein'))]}, params=params)
        return self._solid_each(title, lambda s: EB.apply(s, p), pairs)

    def _edges_dialog(self, solid):
        """La fenêtre des arêtes ; une étape reprise la retrouve avec ses arêtes. None : abandon."""
        from ..core import history3d as HI
        from .edges3d_dialog import EdgesDialog
        prefill = self._hist_prefill
        if self._replaying and prefill is None:
            raise HI.HistoryError(tr('Cette étape ne garde pas ses réglages.'))
        last = prefill if prefill is not None else self.settings.value('cad/solide_aretes', None)
        dlg = EdgesDialog(self, solid, last if isinstance(last, dict) else None)
        if not dlg.exec():
            if prefill is not None:
                raise HI.HistoryCancelled()
            return None
        out = dlg.values()
        if prefill is None:                              # les réglages retenus, pas les arêtes : elles sont à ce volume
            self.settings.setValue('cad/solide_aretes', {k: out[k] for k in ('kind', 'radius', 'radius_end')})
        return out

    def _faces_dialog(self, make, solid, key: str, keep: tuple) -> dict | None:
        """Une fenêtre où l'on clique des faces : son résultat, ou None. Une étape d'historique rouverte y
        retrouve ses réglages et ses faces ; sinon les derniers réglages, pas les faces : elles sont à ce volume."""
        from ..core import history3d as HI
        prefill = self._hist_prefill
        if self._replaying and prefill is None:
            raise HI.HistoryError(tr('Cette étape ne garde pas ses réglages.'))
        last = prefill if prefill is not None else self.settings.value(key, None)
        dlg = make(self, solid, last if isinstance(last, dict) else None)
        if not dlg.exec():
            if prefill is not None:
                raise HI.HistoryCancelled()
            return None
        out = dlg.values()
        if prefill is None:
            self.settings.setValue(key, {k: out[k] for k in keep})
        return out

    def _one_solid_for_faces(self) -> list:
        pairs = self._need_solids()
        if len(pairs) > 1:
            self.statusBar().showMessage(tr('Choisissez un seul volume : les faces se cliquent sur lui.'), 6000)
            return []
        return pairs

    def solid_delete_faces(self, params: dict | None = None) -> list:
        """Supprimer les faces qu'on clique (core.face_delete)."""
        from ..core import face_delete as FD
        pairs = self._one_solid_for_faces()
        if not pairs:
            return []
        if params is None:
            from .draft3d_dialog import DeleteFacesDialog
            params = self._faces_dialog(DeleteFacesDialog, pairs[0][1], 'cad/solide_suppr_faces', ())
            if params is None:
                return []
        title = tr('Supprimer des faces')
        p = self._ask('solide_suppr_faces', title, [], params=params)
        return self._solid_each(title, lambda s: FD.apply(s, p), pairs)

    def solid_move_faces(self, params: dict | None = None) -> list:
        """Déplacer les faces qu'on clique (core.face_move)."""
        from ..core import face_move as FM
        pairs = self._one_solid_for_faces()
        if not pairs:
            return []
        if params is None:
            from .draft3d_dialog import MoveFacesDialog
            params = self._faces_dialog(MoveFacesDialog, pairs[0][1], 'cad/solide_faces', ('mode', 'distance', 'dx', 'dy', 'dz'))
            if params is None:
                return []
        title = tr('Déplacer des faces')
        p = self._ask('solide_faces', title,
                      [('distance', float, 1.0, tr('Distance (mm)')),
                       ('dx', float, 0.0, 'X (mm)'), ('dy', float, 0.0, 'Y (mm)'), ('dz', float, 0.0, 'Z (mm)')],
                      params=params)
        return self._solid_each(title, lambda s: FM.apply(s, p), pairs)

    def solid_draft(self, params: dict | None = None) -> list:
        """Dépouille des faces qu'on clique (core.draft3d)."""
        from ..core import draft3d as DR
        pairs = self._one_solid_for_faces()
        if not pairs:
            return []
        if params is None:
            from .draft3d_dialog import DraftDialog
            params = self._faces_dialog(DraftDialog, pairs[0][1], 'cad/solide_depouille', ('angle', 'pull'))
            if params is None:
                return []
        title = tr('Dépouille')
        p = self._ask('solide_depouille', title,
                      [('angle', float, 3.0, tr('Angle (°)')),
                       ('pull', str, 'z+', tr('Démoulage')),
                       ('neutral', float, 0.0, tr('Plan neutre (mm)'))],
                      params=params)
        return self._solid_each(title, lambda s: DR.apply(s, p), pairs)

    def solid_offset(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_decalage', tr('Décaler le volume'),
                      [('distance', float, 1.0, tr('Distance (mm, négatif : aminci)'))], params=params) if pairs else None
        if p is None:
            return []
        return self._solid_each(tr('Décaler le volume'), lambda s: SO.offset(s, float(p['distance'])), pairs)

    def solid_smooth(self, params: dict | None = None) -> list:
        from ..core import solids as SO
        pairs = self._need_solids()
        p = self._ask('solide_lisser', tr('Lisser le maillage'),
                      [('steps', int, 2, tr('Subdivisions de chaque arête')),
                       ('sharp', float, 52.5, tr('Arêtes gardées vives au-delà de (°)'))], params=params) if pairs else None
        if p is None:
            return []
        return self._solid_each(tr('Lisser le maillage'), lambda s: SO.smooth(s, int(p['steps']), float(p['sharp'])),
                                pairs)

    def solid_presspull(self, params: dict | None = None) -> list:
        """Tirer / pousser : un volume et des formes fermées choisis."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        regions = self._solid_profiles()
        if len(pairs) != 1 or not regions:
            self.statusBar().showMessage(tr('Choisissez un volume et des formes fermées posées sur lui.'), 6000)
            return []
        p = self._ask('solide_tirer', tr('Tirer / pousser'),
                      [('height', float, 2.0, tr('Hauteur (mm ; positif : tirer, négatif : pousser)')),
                       ('top', bool, True, tr('Depuis le dessus du volume (sinon depuis Z de départ)')),
                       ('z0', float, 0.0, tr('Z de départ (mm)'))], params=params)
        if p is None:
            return []
        it, s = pairs[0]
        z0 = None if p['top'] else float(p['z0'])
        try:
            for r in regions:
                s = SO.presspull(s, r.path, float(p['height']), z0)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        out = self._swap_solids([(it, [s])] + [(r, []) for r in regions])
        return out

    def _solid_spots(self) -> list:
        """[(x, y, diamètre ou None)] : les marqueurs choisis, puis le centre
        et le diamètre des cercles choisis (pas les volumes) ; à défaut les
        points de _solid_centers."""
        from ..core import solids as SO
        from ..core.shapes import fit_circle
        _onto, markers, others = self._typeart_selection()
        spots = [(x, y, None) for x, y in markers]
        for it in others:
            if isinstance(it, Shape) and not SO.is_solid(it):
                for c in it.path.contours:
                    f = fit_circle(c, 0.02) if c.closed else None
                    if f:
                        spots.append((f[0][0], f[0][1], 2.0 * f[1]))
        return spots or [(x, y, None) for x, y in self._solid_centers()]

    def solid_coil(self, params: dict | None = None) -> list:
        """Ressort (COIL, d'après SolidCraft) sur les marqueurs ou les cercles
        choisis (diamètre du cercle), sinon au centre des objets choisis ou de
        la plaque."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        p = self._ask('solide_ressort', tr('Ressort'),
                      [('diameter', float, 20.0, tr('Diamètre (mm ; un cercle choisi donne le sien)')),
                       ('position', str, 'centre', tr('Diamètre pris')),
                       ('section', str, 'ronde', tr('Section')),
                       ('size', float, 2.0, tr('Taille de la section (mm : diamètre ou côté)')),
                       ('pitch', float, 5.0, tr('Pas (mm, montée par tour)')),
                       ('turns', float, 6.0, tr('Nombre de tours')),
                       ('start', float, 0.0, tr('Départ (°, depuis l\'axe X)')),
                       ('left', bool, False, tr('Enroulé à gauche')),
                       ('z0', float, 0.0, tr('Z du dessous (mm)'))],
                      choices={'position': [('centre', tr('Au milieu de la section')),
                                            ('dedans', tr('Hors tout (section dedans)')),
                                            ('dehors', tr('Intérieur (section dehors)'))],
                               'section': [('ronde', tr('Ronde')), ('carree', tr('Carrée'))]}, params=params)
        if p is None:
            return []
        pos = {'dedans': -1, 'dehors': 1}.get(p['position'], 0)
        out = []
        try:
            for x, y, dia in self._solid_spots():
                s = SO.coil(x, y, float(p['z0']), dia or float(p['diameter']), float(p['pitch']), float(p['turns']),
                            float(p['size']), p['section'] == 'carree', pos, float(p['start']), bool(p['left']))
                s.name = tr('Ressort')
                out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out)

    def solid_thread(self, params: dict | None = None) -> list:
        """Filetage ISO modélisé (d'après SolidCraft) : tige filetée sur les
        marqueurs ou les cercles choisis, ou taraudage du volume choisi à ces
        endroits. Désignation vide : d'après le diamètre du cercle (celui de
        la tige, ou du perçage pour un taraudage)."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        p = self._ask('solide_filetage', tr('Filetage'),
                      [('mode', str, 'tige', tr('Filetage')),
                       ('designation', str, 'M8', tr('Désignation (M8, M8x1 ; vide : d\'après le cercle choisi — '
                                                    'diamètre de la tige, ou du perçage pour un taraudage)')),
                       ('length', float, 20.0, tr('Longueur de la tige ou profondeur filetée (mm)')),
                       ('through', bool, False, tr('Taraudage débouchant')),
                       ('left', bool, False, tr('Filet à gauche')),
                       ('chamfer', bool, True, tr('Bouts de la tige chanfreinés')),
                       ('z0', float, 0.0, tr('Z du dessous de la tige (mm)'))],
                      choices={'mode': [('tige', tr('Tige filetée')),
                                        ('taraudage', tr('Taraudage du volume choisi'))]}, params=params)
        if p is None:
            return []
        internal = p['mode'] == 'taraudage'
        pairs = self._selected_solids() if internal else []
        if internal and len(pairs) != 1:
            self.statusBar().showMessage(tr('Choisissez un volume (et des marqueurs ou des cercles où le tarauder).'),
                                         6000)
            return []
        try:
            jobs = []
            for x, y, dia in self._solid_spots():
                des = str(p['designation']).strip()
                if not des:
                    m = SO.metric_for(dia, internal) if dia else None
                    if m is None:
                        raise SO.SolidError(tr('désignation vide : choisissez des cercles de la taille voulue ou '
                                               'donnez-la (M8…)'))
                    des = SO.format_metric(*m)
                jobs.append((x, y, des))
            if internal:
                it, s = pairs[0]
                for x, y, des in jobs:
                    s = SO.tapped_hole(s, x, y, des, float(p['length']), bool(p['through']), left=bool(p['left']))
                return self._swap_solids([(it, [s])])
            out = []
            for x, y, des in jobs:
                s = SO.threaded_rod(x, y, float(p['z0']), float(p['length']), des, bool(p['left']),
                                    bool(p['chamfer']))
                s.name = tr('Tige filetée') + ' ' + des
                out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out)

    def solid_hole(self, params: dict | None = None) -> list:
        """Perçages 3D (d'après SolidCraft) dans le volume choisi, sur les
        marqueurs ou les cercles choisis (diamètre du cercle). Annulable."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if len(pairs) != 1:
            self.statusBar().showMessage(tr('Choisissez un volume (et des marqueurs ou des cercles où le percer).'),
                                         6000)
            return []
        p = self._ask('solide_percage', tr('Perçage 3D'),
                      [('kind', str, 'simple', tr('Perçage')),
                       ('diameter', float, 6.6, tr('Diamètre (mm ; un cercle choisi donne le sien)')),
                       ('through', bool, False, tr('Débouchant')),
                       ('depth', float, 10.0, tr('Profondeur (mm)')),
                       ('point', bool, True, tr('Pointe de foret au fond')),
                       ('tip_angle', float, 118.0, tr('Angle de la pointe (°)')),
                       ('cb_diameter', float, 0.0, tr('Lamage : diamètre (mm ; 0 : 1,8 × le trou)')),
                       ('cb_depth', float, 0.0, tr('Lamage : profondeur (mm ; 0 : le diamètre du trou)')),
                       ('cs_diameter', float, 0.0, tr('Fraisure : diamètre (mm ; 0 : 2 × le trou)')),
                       ('cs_angle', float, 90.0, tr('Fraisure : angle (°)'))],
                      choices={'kind': [(k, tr(v)) for k, v in SO.HOLES.items()]}, params=params)
        if p is None:
            return []
        it, s = pairs[0]
        try:
            for x, y, dia in self._solid_spots():
                s = SO.hole(s, x, y, dia or float(p['diameter']), None if p['through'] else float(p['depth']),
                            p['kind'], bool(p['point']), float(p['tip_angle']), float(p['cb_diameter']),
                            float(p['cb_depth']), float(p['cs_diameter']), float(p['cs_angle']))
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        return self._swap_solids([(it, [s])])

    def solid_pipe(self, params: dict | None = None) -> list:
        """Tube (PIPE, d'après SolidCraft) le long de chaque trait choisi."""
        from ..core import solids as SO
        if not self._solids_ready():
            return []
        lines = [it for it in _leaves(self.canvas.selection) if isinstance(it, Shape) and not SO.is_solid(it)
                 and it.path.contours]
        if not lines:
            self.statusBar().showMessage(tr('Sélectionnez des traits.'), 5000)
            return []
        p = self._ask('solide_tube', tr('Tube'),
                      [('diameter', float, 10.0, tr('Diamètre extérieur (mm)')),
                       ('wall', float, 0.0, tr('Paroi (mm ; 0 : plein)')),
                       ('on_plane', bool, True, tr('Posé sur le plan (sinon l\'axe à Z)')),
                       ('z', float, 0.0, tr('Z de l\'axe (mm)')),
                       ('delete', bool, False, tr('Remplacer les traits par les tubes'))], params=params)
        if p is None:
            return []
        out = []
        try:
            for it in lines:
                for c in it.path.contours:
                    if c.segments:
                        s = SO.pipe(c, float(p['diameter']), float(p['wall']),
                                    None if p['on_plane'] else float(p['z']))
                        s.name = tr('Tube')
                        out.append(s)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Volume impossible : {0}').format(ex), 6000)
            return []
        return self._put_solids(out, lines if p['delete'] else ())

