    def solid_lip(self, params: dict | None = None) -> list:
        """Lèvre ou rainure (LIP, GROOVE, d'après SolidCraft) le long du bord
        des volumes coqués choisis, sur leur dessus."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        if not pairs:
            self.statusBar().showMessage(tr('Choisissez des volumes coqués ouverts (Coque, dessus ouvert).'), 6000)
