    def _plastic_put(self, make, separate: bool, z: float) -> list:
        """Pièces plastiques `make(x, y, z0, join)` aux marqueurs choisis :
        posées sur le dessus de la matière du volume choisi et réunies à lui
        (sauf `separate`), sans volume posées à Z."""
        from ..core import solids as SO
        pairs = self._selected_solids()
        _onto, markers, _others = self._typeart_selection()
        try:
            if not pairs:
                return self._put_solids([make(x, y, z, False) for x, y in markers])
            it, s = pairs[0]
            tools = []
            for x, y in markers:
                top = SO.top_at(s, x, y)
                if top is None:
                    raise SO.SolidError('pas de matière sous un marqueur')
                tools.append(make(x, y, top, not separate))
            if separate:
                return self._put_solids(tools)
            u = SO.boolean('union', [s] + tools)
        except SO.SolidError as ex:
            self.statusBar().showMessage(tr('Opération impossible : {0}').format(ex), 6000)
            return []
        u.name, u.color = s.name, s.color
        return self._swap_solids([(it, [u])])

    def _plastic_ready(self) -> bool:
        _onto, markers, _others = self._typeart_selection()
        if markers and len(self._selected_solids()) <= 1:
            return True
        self.statusBar().showMessage(tr('Choisissez des marqueurs, et au plus un volume où poser les pièces.'), 6000)
        return False

    def solid_snap_fit(self, params: dict | None = None) -> list:
        """Clips à crochet (SNAP FIT, d'après SolidCraft) aux marqueurs
        choisis, sur le volume choisi ou à part."""
        from ..core import solids as SO
        if not self._plastic_ready():
            return []
        p = self._ask('solide_clip', tr('Clip'),
                      [('length', float, 12.0, tr('Bras : longueur (mm)')),
                       ('thickness', float, 1.5, tr('Bras : épaisseur (mm)')),
                       ('width', float, 6.0, tr('Bras : largeur (mm)')),
                       ('catch_depth', float, 1.0, tr('Crochet : saillie (mm)')),
                       ('catch_length', float, 3.0, tr('Crochet : hauteur (mm)')),
                       ('angle', float, 0.0, tr('Crochet : direction (°)')),
                       ('base_height', float, 0.0, tr('Pied sous le dessus (mm)')),
                       ('z', float, 0.0, tr('Z sans volume choisi (mm)')),
                       ('separate', bool, False, tr('Volumes à part'))], params=params)
        if p is None:
            return []
        dims = [float(p[k]) for k in ('length', 'thickness', 'width', 'catch_depth', 'catch_length')]
        return self._plastic_put(lambda x, y, z0, join: SO.snap_fit(
            x, y, z0, *dims, angle=float(p['angle']), base_height=float(p['base_height']), join=join),
            bool(p['separate']), float(p['z']))

    def solid_rest(self, params: dict | None = None) -> list:
        """Appuis (REST, d'après SolidCraft) aux marqueurs choisis, sur le
        volume choisi ou à part."""
        from ..core import solids as SO
        if not self._plastic_ready():
            return []
        p = self._ask('solide_appui', tr('Appui'),
                      [('shape', str, 'rond', tr('Forme')),
                       ('width', float, 6.0, tr('Diamètre ou largeur (mm)')),
                       ('length', float, 10.0, tr('Rectangle : longueur (mm)')),
                       ('angle', float, 0.0, tr('Rectangle : direction de la longueur (°)')),
                       ('height', float, 1.0, tr('Hauteur (mm)')),
                       ('draft', float, 0.0, tr('Dépouille (°)')),
                       ('thickness', float, 0.0, tr('Paroi (mm ; 0 : plein)')),
                       ('z', float, 0.0, tr('Z sans volume choisi (mm)')),
                       ('separate', bool, False, tr('Volumes à part'))],
                      choices={'shape': [('rond', tr('Rond')), ('rectangle', tr('Rectangle'))]}, params=params)
        if p is None:
            return []
        ln = float(p['length']) if p['shape'] == 'rectangle' else 0.0
        return self._plastic_put(lambda x, y, z0, join: SO.rest(
            x, y, z0, float(p['width']), float(p['height']), ln, float(p['angle']), float(p['draft']),
            float(p['thickness']), join=join), bool(p['separate']), float(p['z']))

    def solid_wrap_emboss(self, params: dict | None = None) -> list:
        """Relief ou gravure enroulé sur un cylindre (EMBOSS, d'après
        SolidCraft) : le volume choisi et des formes fermées ou des textes."""
        from ..cam import strategies as S
        from ..core import solids as SO
