    MOUSE_WHEEL = (('zoom', 'Zoom avant / arrière'), ('defilement', 'Défilement (Ctrl : zoom, Maj : horizontal)'))
    MOUSE_RIGHT = (('aucun', 'Rien (glisser : déplacer la vue)'), ('zoom', 'Zoom avant'),
                   ('annuler', 'Défaire la dernière action'), ('poser', 'Poser l\'outil courant (comme Espace)'),
                   ('geler', 'Geler la sélection'))

    def apply_mouse_settings(self) -> None:
        st = self.settings
        w = str(st.value('souris/molette', 'zoom') or 'zoom')
        r = str(st.value('souris/bouton_droit', 'aucun') or 'aucun')
        self.canvas.wheel_mode = w if w in dict(self.MOUSE_WHEEL) else 'zoom'
        self.canvas.right_click = r if r in dict(self.MOUSE_RIGHT) else 'aucun'
        self.canvas.wheel_invert = st.value('souris/molette_inverse', False) in (True, 'true')

    def mouse_settings(self, params: dict | None = None) -> dict | None:
        """Utilisation de la souris (TypeEdit F5) : molette, clic droit (glisser
        avec le bouton droit ou la molette déplace toujours la vue ; double-clic
        sur la molette : tout voir)."""
        p = self._ask('souris', tr('Utilisation de la souris'),
                      [('wheel', str, self.canvas.wheel_mode, tr('Molette')),
                       ('invert', bool, self.canvas.wheel_invert,
                        tr('Inverser le zoom de la molette (vers soi : rapprocher)')),
                       ('right', str, self.canvas.right_click, tr('Clic droit (sans glisser)'))],
                      choices={'wheel': [(k, tr(v)) for k, v in self.MOUSE_WHEEL],
                               'right': [(k, tr(v)) for k, v in self.MOUSE_RIGHT]}, params=params)
        if p is None:
            return None
        self.settings.setValue('souris/molette', p['wheel'])
        self.settings.setValue('souris/molette_inverse', bool(p.get('invert', False)))
        self.settings.setValue('souris/bouton_droit', p['right'])
        self.apply_mouse_settings()
        return p

    def _on_right_click(self, what: str) -> None:
        if what == 'annuler':
            self.undo()
        elif what == 'geler' and (self.canvas.selection or self.canvas.frozen_selected()):
            self.freeze_selection()
        elif what == 'poser':
            from PySide6.QtCore import QEvent
            from PySide6.QtGui import QKeyEvent
            from PySide6.QtWidgets import QApplication
            key = QKeyEvent(QEvent.Type.KeyPress, Qt.Key.Key_Space, Qt.KeyboardModifier.NoModifier)
            QApplication.sendEvent(self.canvas, key)

    def _ask_angle(self) -> float | None:
        """Angle voulu (rotation par référence), degrés depuis l'horizontale."""
        from PySide6.QtWidgets import QInputDialog
        v, ok = QInputDialog.getDouble(self, tr('Rotation par référence'), tr('Angle voulu (°, 0 : horizontal)'),
                                       0.0, -360.0, 360.0, 3)
        return v if ok else None

    def _ask_length(self, ref: float) -> float | None:
        """Nouvelle longueur (échelle par référence) ; None : abandon."""
        from PySide6.QtWidgets import QInputDialog
        v, ok = QInputDialog.getDouble(self, tr('Échelle par référence'),
                                       tr('Longueur de référence : {0} mm — nouvelle longueur (mm)').format(f'{ref:.4g}'),
                                       ref, 1e-6, 1e6, 4)
        return v if ok else None

    def leader_text(self) -> str | None:
        """Texte d'un repère (outil Cote, type Repère) ; None : abandon."""
        from PySide6.QtWidgets import QInputDialog
        last = str(self.settings.value('cotes/repere', '') or '')
        text, ok = QInputDialog.getText(self, tr('Repère'), tr('Texte du repère'), text=last)
        if not ok or not text.strip():
            return None
        self.settings.setValue('cotes/repere', text)
        return text

    def sculpt_params(self) -> dict:
        from ..core.sculpt import BRUSHES, MIRRORS
        st = self.settings
        brush = str(st.value('sculpt/pinceau', 'ajouter') or 'ajouter')
        mirror = str(st.value('sculpt/miroir', 'aucun') or 'aucun')
        try:
            radius = float(st.value('sculpt/rayon', 2.0))
            strength = float(st.value('sculpt/force', 0.1))
            axes = int(st.value('sculpt/axes', 4))
        except (TypeError, ValueError):
            radius, strength, axes = 2.0, 0.1, 4
        from ..core.sculpt import MASKS
        mask = str(st.value('sculpt/masque', 'dedans') or 'dedans')
        return {'brush': brush if brush in dict(BRUSHES) else 'ajouter', 'radius': radius, 'strength': strength,
                'mirror': mirror if mirror in dict(MIRRORS) else 'aucun', 'mirror_axes': max(2, min(10, axes)),
                'mask': mask if mask in dict(MASKS) else 'dedans'}

    def sculpt_dialog(self, params: dict | None = None) -> dict | None:
        """Pinceau de SculptArt : type, rayon, force (gardés)."""
        from ..core.sculpt import BRUSHES, MASKS, MIRRORS
        cur = self.sculpt_params()
        p = self._ask('sculpt', tr('Pinceau'), [('brush', str, cur['brush'], tr('Pinceau')),
                                                ('radius', float, cur['radius'], tr('Rayon (mm)')),
                                                ('strength', float, cur['strength'], tr('Force (mm par touche)')),
                                                ('mirror', str, cur['mirror'], tr('Miroir (autour du centre du relief)')),
                                                ('mirror_axes', int, cur['mirror_axes'], tr('Multi-axe : nombre d\'axes (2 à 10)')),
                                                ('mask', str, cur['mask'], tr('Masque (formes fermées choisies avec le relief)'))],
                      choices={'brush': [(k, tr(v)) for k, v in BRUSHES],
                               'mirror': [(k, tr(v)) for k, v in MIRRORS],
                               'mask': [(k, tr(v)) for k, v in MASKS]}, params=params)
        if p is None:
            return None
        self.settings.setValue('sculpt/miroir', p.get('mirror', 'aucun'))
        self.settings.setValue('sculpt/axes', int(p.get('mirror_axes', 4)))
        self.settings.setValue('sculpt/masque', p.get('mask', 'dedans'))
        self.settings.setValue('sculpt/pinceau', p['brush'])
        self.settings.setValue('sculpt/rayon', float(p['radius']))
        self.settings.setValue('sculpt/force', float(p['strength']))
        self.canvas.sculpt_params = self.sculpt_params()
        if self.canvas.tool != 'sculpt':
            self.set_tool('sculpt')
        return self.canvas.sculpt_params

    def _relief_swap(self, old, new) -> bool:
        """Relief retouché au pinceau mis à la place de l'ancien (l'annulation
        a été posée au début du coup de pinceau)."""
        L = self.canvas.doc.layer_of(old)
        if L is None:
            return False
        L.items[next(i for i, it in enumerate(L.items) if it is old)] = new
        self.canvas.invalidate()
        self.canvas.selection = [new if it is old else it for it in self.canvas.selection]
        self.modified = True
        self.canvas.update()
        return True

    def _replace_item(self, old, new, label: str) -> bool:
        """`new` à la place de `old` dans son calque (un pas d'annulation)."""
        L = self.canvas.doc.layer_of(old)
        if L is None:
            return False
        self.push_undo(label)
        L.items[next(i for i, it in enumerate(L.items) if it is old)] = new
        self.canvas.invalidate()
        self.canvas.select([new])
        self._on_doc_changed()
        return True

    def galbe_smooth(self, passes: int | None = None):
        """Lissage d'un galbe (TypeArt) : moyenne répétée, sur tout le galbe ou
        dans les formes fermées sélectionnées avec lui ; rend la nouvelle image."""
        from dataclasses import dataclass
        from ..cam import strategies as S
        from ..core import galbe as GB
        from ..core.document import Image
        sel = list(_leaves(self.canvas.selection))
        img = next((it for it in sel if isinstance(it, Image) and 'galbe' in it.extra), None)
        if img is None:
            self.statusBar().showMessage(tr('Sélectionnez un galbe (et, au besoin, la zone à lisser).'), 5000)
            return None
        if passes is None:
            from .dialogs import ParamsDialog

            @dataclass
            class Spec:
                passes: int = int(self.settings.value('galbe/passes', 3))
            dlg = ParamsDialog(self, tr('Lissage'), Spec(), {'passes': tr('Nombre de passes')})
            if not dlg.exec():
                return None
            passes = max(1, int(dlg.result_params().passes))
            self.settings.setValue('galbe/passes', passes)
        zone = [it for it in sel if not isinstance(it, Image)]
        reg = S.region([g for it in zone if (g := S.item_geometry(it))], 0.01) if zone else None
        new = GB.smooth(img, passes, reg if reg is not None and not reg.is_empty else None)
        if new is None or not self._replace_item(img, new, tr('Lissage')):
            return None
        return new

    def code_plate(self, data: str | None = None):
        """Plaque codée (TauDrive) : sur les cadres sélectionnés, le code dans le
        plus grand (le plus grand symbole qui tienne, centré), son texte
        lisible dans le suivant ; rend le groupe."""
        from PySide6.QtWidgets import QInputDialog
        from ..core import codeplate as CP
        code_f, text_f = CP.frames_of(list(self.canvas.selection))
        if not code_f:
            if data is None:                             # à la souris, rien de sélectionné : depuis un préréglage
                return self.code_plate_preset()
            self.statusBar().showMessage(tr('Sélectionnez le cadre du code, et celui du texte'), 5000)
            return None
        if data is None:
            data, ok = QInputDialog.getText(self, tr('Plaque codée'), tr('Donnée du code :'),
                                            text=str(self.settings.value('plaque/donnee', '')))
            if not ok:
                return None
        data = data.strip()
        if not data:
            return None
        spec = CP.PlateSpec(data=data, kind=str(self.settings.value('plaque/code', 'datamatrix')),
                            font=str(self.settings.value('plaque/police', 'Arial')), code_frame=code_f, text_frame=text_f)
        try:
            g = CP.build(spec, self.canvas.current_tool_index)
        except ValueError:
            QMessageBox.warning(self, tr('Plaque codée'), tr('Donnée impossible à coder dans ce cadre.'))
            return None
        self.settings.setValue('plaque/donnee', data)
        self.push_undo(tr('Plaque codée'))
        self.canvas.doc.add(g)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()
        return g

    #: préréglages de plaque codée de l'utilisateur (JSON)
    PLATE_PRESETS_KEY = 'plaque/prereglages'

    def plate_presets(self) -> list:
        """Préréglages de plaque codée : ceux de l'utilisateur (qui remplacent
        un livré du même nom), puis les livrés."""
        import json
        from ..core import codeplate as CP
        try:
            raw = json.loads(str(self.settings.value(self.PLATE_PRESETS_KEY, '[]') or '[]'))
        except ValueError:
            raw = []
        mine = [CP.Preset.from_dict(d) for d in raw if isinstance(d, dict) and d.get('name')]
        names = {p.name for p in mine}
        return mine + [p for p in CP.FACTORY if p.name not in names]

    def save_plate_preset(self, preset) -> None:
        import dataclasses
        import json
        from ..core import codeplate as CP
        mine = [p for p in self.plate_presets() if p not in CP.FACTORY and p.name != preset.name] + [preset]
        self.settings.setValue(self.PLATE_PRESETS_KEY, json.dumps([dataclasses.asdict(p) for p in mine],
                                                                  ensure_ascii=False))

    def code_plate_preset(self, name: str | None = None, data: str | None = None, at=None, exec_dialog: bool = True):
        """Plaque codée depuis un préréglage : la plaque type entière (cadres,
        code, texte) posée au centre de la plaque (ou en `at`) ; cadres
        sélectionnés : « Enregistrer… » en fait un préréglage. Rend le groupe."""
        from PySide6.QtWidgets import (QComboBox, QDialog, QDialogButtonBox, QFormLayout, QInputDialog, QLineEdit,
                                       QPushButton)
        from ..core import codeplate as CP
        presets = self.plate_presets()
        if exec_dialog:
            dlg = QDialog(self)
            dlg.setWindowTitle(tr('Plaque codée depuis un préréglage'))
            form = QFormLayout(dlg)
            box = QComboBox()
            for p in presets:
                box.addItem(p.name, p.name)
            form.addRow(tr('Préréglage'), box)
            edit = QLineEdit(str(self.settings.value('plaque/donnee', '')))
            form.addRow(tr('Donnée du code'), edit)
            save = QPushButton(tr('Enregistrer les cadres sélectionnés comme préréglage…'))
            save.setEnabled(len(self.canvas.selection) >= 1)

            def do_save():
                code_f, text_f = CP.frames_of(list(self.canvas.selection))
                if not code_f:
                    return
                n, ok = QInputDialog.getText(dlg, tr('Préréglage de plaque codée'), tr('Nom'))
                if ok and n.strip():
                    p = CP.preset_from_frames(n.strip(), code_f, text_f,
                                              str(self.settings.value('plaque/code', 'datamatrix')),
                                              str(self.settings.value('plaque/police', 'Arial')))
                    self.save_plate_preset(p)
                    box.addItem(p.name, p.name)
                    box.setCurrentIndex(box.count() - 1)
            save.clicked.connect(lambda _=False: do_save())
            form.addRow(save)
            bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
            bb.accepted.connect(dlg.accept)
            bb.rejected.connect(dlg.reject)
            form.addRow(bb)
            if not dlg.exec():
                return None
            name, data = box.currentData(), edit.text()
        preset = next((p for p in self.plate_presets() if p.name == name), presets[0] if presets else None)
        data = (data or '').strip()
        if preset is None or not data:
            return None
        if at is None:
            plate = self.canvas.doc.plate
            at = (plate.x + plate.width / 2, plate.y + plate.height / 2) if plate is not None else (0.0, 0.0)
        try:
            g = CP.build_from_preset(preset, data, at[0], at[1], self.canvas.current_tool_index)
        except ValueError:
            QMessageBox.warning(self, tr('Plaque codée'), tr('Donnée impossible à coder dans ce cadre.'))
            return None
        self.settings.setValue('plaque/donnee', data)
        self.push_undo(tr('Plaque codée'))
        self.canvas.doc.add(g)
        self.canvas.invalidate()
        self.canvas.select([g])
        self._on_doc_changed()
        return g

    def edit_code_plate(self, g: Group, data: str | None = None):
        """Nouvelle donnée d'une plaque codée : code et texte refaits ensemble,
        là où la plaque a été déplacée ; rend le nouveau groupe."""
        from PySide6.QtWidgets import QInputDialog
        from ..core import codeplate as CP
        if data is None:
            data, ok = QInputDialog.getText(self, tr('Plaque codée'), tr('Donnée du code :'),
                                            text=str(g.extra['codeplate'].get('data', '')))
            if not ok:
                return None
        try:
            new = CP.rebuild(g, data.strip())
        except ValueError:
            QMessageBox.warning(self, tr('Plaque codée'), tr('Donnée impossible à coder dans ce cadre.'))
            return None
        doc = self.canvas.doc
        L = doc.layer_of(g)
        if L is None:
            return None
        self.push_undo(tr('Plaque codée'))
        L.items[next(i for i, it in enumerate(L.items) if it is g)] = new
        self.canvas.invalidate()
        self.canvas.select([new])
        self._on_doc_changed()
        return new

    def edit_barcode(self, g: Group) -> None:
        """Re-édition : même coin bas gauche, même calque, même outil."""
        from ..core import codes
        from .dialogs import BarcodeDialog
        dlg = BarcodeDialog(self, codes.BarcodeSpec.from_dict(g.extra['barcode']))
        if not dlg.exec():
            return
        old_bb = g.bbox()
        new = codes.build(dlg.result_spec(), g.tool)
        nb = new.bbox()
        new = new.transformed(Affine.translation(old_bb[0] - nb[0], old_bb[1] - nb[1]))
        self.push_undo()
        doc = self.canvas.doc
        L = doc.layer_of(g)
        if L is None:
            self._undo.pop()
            return
        L.items[next(i for i, it in enumerate(L.items) if it is g)] = new
        self.canvas.invalidate()
        self.canvas.select([new])
        self._on_doc_changed()

    def dedupe_dialog(self) -> None:
        """Supprimer les superposés (raccourci à) : tout de suite, avec les derniers réglages ; Ctrl+clic ou premier
        usage : la fenêtre."""
        from PySide6.QtWidgets import QCheckBox as _CB
        from .dialogs import _buttons, _spin
        tol = float(self.settings.value('nettoyage/tolerance', 0.01))
        across = self.settings.value('nettoyage/entre_calques', False) in (True, 'true')
        if self._ctrl_held() or not self.settings.contains('nettoyage/entre_calques'):
            dlg = QDialog(self)
            dlg.setWindowTitle(tr('Supprimer les superposés'))
            form = QFormLayout(dlg)
            sel = self.canvas.selection
            form.addRow(QLabel(tr('Sur la sélection.') if sel
                               else tr('Sur tout le dessin (calques visibles et non verrouillés).')))
            w_tol = _spin(tol, 0.0001, 10)
            form.addRow(tr('Tolérance'), w_tol)
            w_across = _CB(tr('Comparer aussi entre calques (un même dessin sur deux outils est souvent voulu)'))
            w_across.setChecked(across)
            form.addRow(w_across)
            form.addRow(QLabel(tr('Raccourci : à, avec ces réglages ; Ctrl+clic pour revenir à cette fenêtre.')))
            _buttons(dlg, form)
            self.last_dedupe_dialog = (w_tol, w_across)
            if not dlg.exec():
                return
            tol, across = w_tol.value(), w_across.isChecked()
            self.settings.setValue('nettoyage/tolerance', tol)
            self.settings.setValue('nettoyage/entre_calques', across)
        n = self.remove_duplicates(tol, across=across)
        self.statusBar().showMessage(tr('{0} contour(s) superposé(s) supprimé(s).').format(n), 6000)

    def chain_dialog(self) -> None:
        """Raccorder, comme l'autoconnexion de TypeEdit : les derniers réglages, sans fenêtre ; Ctrl+clic ou premier
        usage : la fenêtre."""
        from PySide6.QtWidgets import QCheckBox as _QCheckBox
        from .dialogs import _buttons, _spin
        tol = float(self.settings.value('raccord/tolerance', 0.01))
        link = float(self.settings.value('raccord/liaison', 0.0))
        apart = self.settings.value('raccord/separement', False) in (True, 'true')
        if self._ctrl_held() or not self.settings.contains('raccord/liaison'):
            dlg = QDialog(self)
            dlg.setWindowTitle(tr('Raccorder'))
            form = QFormLayout(dlg)
            form.addRow(QLabel(tr('Sur la sélection.') if self.canvas.selection
                               else tr('Sur tout le dessin (calques visibles et non verrouillés).')))
            w_tol = _spin(tol, 0.0001, 10)
            w_link = _spin(link, 0.0, 1000)
            w_apart = _QCheckBox(tr('Séparément : fermer chaque contour sur lui-même, sans le relier aux autres'))
            w_apart.setChecked(apart)
            w_tol.setToolTip(tr('En dessous, les deux points sont fusionnés : la forme bouge un peu'))
            w_link.setToolTip(tr('En dessous, les deux points sont reliés par un segment : la forme ne bouge pas'))
            form.addRow(tr('Distance de fusion de points (mm)'), w_tol)
            form.addRow(tr('Distance de liaison de points (mm)'), w_link)
            form.addRow(w_apart)
            _buttons(dlg, form)
            self.last_chain_dialog = (w_tol, w_link, w_apart)
            if not dlg.exec():
                return
            tol, link, apart = w_tol.value(), w_link.value(), w_apart.isChecked()
            self.settings.setValue('raccord/tolerance', tol)
            self.settings.setValue('raccord/liaison', link)
            self.settings.setValue('raccord/separement', apart)
        joins, closings = self.chain_contours(tol, link, apart)
        self.statusBar().showMessage(tr('{0} raccord(s), {1} contour(s) fermé(s)').format(joins, closings), 6000)

    def chain_contours(self, tol: float = 0.01, link: float = 0.0, separately: bool = False) -> tuple[int, int]:
        """Raccorde, calque par calque, les contours ouverts des formes de
        premier niveau (sélection, sinon tout le dessin visible). Une forme
        par chaîne ; les contours fermés restent dans leur forme. Voir
        `chain.chain_layers` pour `link` et `separately`."""
        from ..core import chain as CH
        sel = {id(s) for s in self.canvas.selection}
        snapshot = self._snapshot()
        total_j, total_c, new_sel = CH.chain_layers(self.canvas.doc.layers, tol, sel or None, link, separately)
        if total_j or total_c:
            self._undo.append(snapshot)
            self._redo.clear()
            self.canvas.invalidate()
            self.canvas.select(new_sel if sel else [])
            self._on_doc_changed()
        return total_j, total_c

    def remove_duplicates(self, tol: float = 0.01, *, across: bool = False) -> int:
        from ..core import cleanup
        doc = self.canvas.doc
        sel = {id(s) for s in self.canvas.selection}
        layers = [L for L in doc.layers if L.visible and not L.locked]
        targets = {id(L): [it for it in L.items if (not sel or id(it) in sel)] for L in layers}
        snapshot = self._snapshot()
        total = 0
        groups = [layers] if across else [[L] for L in layers]
        for group in groups:
            items = [it for L in group for it in targets[id(L)]]
            if not items:
                continue
            res, n = cleanup.dedupe(items, tol)
            if not n:
                continue
            total += n
            repl = {id(a): b for a, b in zip(items, res)}
            for L in group:
                L.items = [repl.get(id(it), it) for it in L.items if repl.get(id(it), it) is not None]
        if total:
            self._undo.append(snapshot)
            self._redo.clear()
            self.canvas.selection = []
            self.canvas.invalidate()
            self._on_selection()
            self._on_doc_changed()
        return total

    def reverse_contours(self) -> None:
        from ..core import cleanup
        sel = self.canvas.selection
        if not sel:
            return
        self.push_undo()

        def rev(it):
            import copy as _copy
            if isinstance(it, Group):
                g = _copy.copy(it)
                g.children = [rev(c) for c in it.children]
                return g
            if isinstance(it, Shape):
                s = _copy.copy(it)
                s.path = cleanup.reverse(it.path)
                return s
            return it
        ids = {id(s) for s in sel}
        new_sel = []
        for L in self.canvas.doc.layers:
            for i, it in enumerate(L.items):
                if id(it) in ids:
                    L.items[i] = rev(it)
                    new_sel.append(L.items[i])
        self.canvas.invalidate()
        self.canvas.select(new_sel)
        if not self.A['direction'].isChecked():
            self.A['direction'].setChecked(True)
        self._on_doc_changed()

    def edit_plate(self) -> None:
        dlg = PlateDialog(self.canvas.doc.plate, self, settings=self.settings, drawing_bbox=self.canvas.doc.bbox(),
                          part_note=self.adjust_part_note())
        if dlg.exec():
            self.apply_plate(dlg.plate(), dlg.adjust_matrix())
            z = dlg.plate().zero_point(dlg.zero.currentData() or '')
            if z is not None:
                self.canvas.set_origin(*z)

    def new_table(self, params: dict | None = None):
        """Tableau : un groupe (traits + textes vivants), coin haut-gauche au
        haut-gauche de la plaque (marges comprises), sinon en (0, 0)."""
        from ..core import table as TB
        from ..core import text as TX
        from ..core.document import Group, Text
        from ..core.geom import Affine
        p = self._ask('table', tr('Tableau'),
                      [('content', str, 'Désignation;Valeur\\nTension;230 V', tr('Contenu (une ligne par rangée, « ; » entre cellules, \\n : rangée suivante)')),
                       ('widths', str, '', tr('Largeurs des colonnes (mm, ex. « 30 50 » ; vide : égales)')),
                       ('width', float, 80.0, tr('Largeur totale (colonnes égales) (mm)')),
                       ('row_height', float, 8.0, tr('Hauteur des rangées (mm)')),
                       ('text_height', float, 3.5, tr('Hauteur du texte (mm)')),
                       ('padding', float, 1.5, tr('Marge dans la cellule (mm)')),
                       ('align', str, 'left', tr('Alignement')), ('frame', bool, True, tr('Cadre')),
                       ('inner', bool, True, tr('Traits intérieurs')), ('font', str, 'Arial', tr('Police'))],
                      choices={'align': [(k, tr(v)) for k, v in TB.ALIGNS]}, params=params)
        if p is None:
            return None
        spec = TB.TableSpec(**p)
        pl = self.canvas.doc.plate
        if pl is not None:
            ux0, _uy0, _ux1, uy1 = pl.usable()
            origin = (ux0 + (0 if pl.has_margins() else 2.0), uy1 - (0 if pl.has_margins() else 2.0))
        else:
            origin = (0.0, 0.0)
        lines, cells = TB.build(spec, origin)
        if not cells and not lines.contours:
            self.statusBar().showMessage(tr('Tableau vide.'), 5000)
            return None
        tool = self.canvas.current_tool_index
        children = [Shape(path=lines, tool=tool)] if lines.contours else []
        for txt, x, y, al, length in cells:
            t = Text(text=txt, font=spec.font, size=spec.text_height, matrix=Affine.translation(x, y), align=al,
                     tool=tool)
            t.extra['max_length'] = {'length': length, 'by': 'line'}
            t.outline = TX.outline_for(t)
            children.append(t)
        g = Group(children=children, name=tr('Tableau'))
        self._add_items([g])
        return g

    def plate_text(self, params: dict | None = None) -> list:
        """Mise en page du texte (TypeEdit) : n textes « Ligne k » centrés,
        répartis sur la plaque, à remplacer par le vrai texte."""
        from ..core import platetext as PT
        from ..core.document import Text
        from ..core.geom import Affine
        pl = self.canvas.doc.plate
        if pl is None:
            self.statusBar().showMessage(tr('Définissez d\'abord la plaque.'), 5000)
            return []
        p = self._ask('plate_text', tr('Mise en page du texte'),
                      [('lines', int, 3, tr('Nombre de lignes')), ('volume', float, 55.0, tr('Volume du texte (% de la hauteur)')),
                       ('margin_factor', float, 1.0, tr('Marges du haut et du bas (× interligne)')),
                       ('offset', float, 0.0, tr('Décalage des marges (%) : le texte remonte')),
                       ('h_margin', float, 6.0, tr('Marges gauche et droite (% de la largeur)')),
                       ('weights', str, '', tr('Hauteurs relatives des lignes (ex. « 2 1 1 », vide : égales)')),
                       ('font', str, 'Arial', tr('Police'))], params=params)
        if p is None:
            return []
        spec = PT.PlateTextSpec(**{k: p[k] for k in ('lines', 'volume', 'margin_factor', 'offset', 'h_margin',
                                                       'weights', 'font')})
        texts = []
        for k, (xc, yb, h, length) in enumerate(PT.layout(pl, spec), 1):
            t = Text(text=tr('Ligne {0}').format(k), font=spec.font, size=h, matrix=Affine.translation(xc, yb),
                     align='center', tool=self.canvas.current_tool_index)
            t.extra['max_length'] = {'length': length, 'by': 'line'}
            texts.append(t)
        from ..core import text as TX
        for t in texts:
            t.outline = TX.outline_for(t)
        self._add_items(texts)
        return texts

    def adjust_part_note(self) -> str | None:
        """Ce qu'« Ajuster la composition » fait au dessin posé sur la pièce
        3D — elle ne change pas de taille et, sauf centrée sur la plaque, ne
        suit pas son centre —, ou None (pas de pièce 3D)."""
        from ..core import placement3d as P3
        from ..io import model3d
        doc = self.canvas.doc
        if model3d.source_of(doc) is None:
            return None
        p = P3.of(doc)
        if p.mode in self.FOLLOWS_PLATE:
            return tr('La pièce 3D suit la plaque (position « {0} ») mais ne change pas de taille : le dessin ajusté '
                      'ne tombera plus forcément au même endroit sur elle.').format(tr(P3.MODES.get(p.mode, p.mode)))
        return tr('La pièce 3D ne suit pas l\'ajustement (position « {0} ») : le dessin se décalera d\'elle — '
                  'la replacer ensuite (Placer la pièce 3D) si le dessin doit rester dessus.').format(
            tr(P3.MODES.get(p.mode, p.mode)))

    #: positions de la pièce 3D tirées de la plaque (core.placement3d.resolve)
    FOLLOWS_PLATE = ('centre', 'coin')

    @staticmethod
    def _part_view(it) -> bool:
        """Objet de la vue de la pièce 3D (lecture du STEP) : il suit la
        pièce, pas la composition."""
        return isinstance(it, Shape) and bool(it.extra.get('step'))

    @classmethod
    def _without_view(cls, items) -> list:
        """`items` sans les objets de la vue de la pièce 3D, groupes compris
        (un groupe qui n'avait qu'elle disparaît)."""
        out = []
        for it in items:
            if isinstance(it, Group) and it.children:
                kids = cls._without_view(it.children)
                if len(kids) != len(it.children):
                    if not kids:
                        continue
                    it = copy.copy(it)
                    it.children = kids
                elif any(a is not b for a, b in zip(kids, it.children)):
                    it = copy.copy(it)
                    it.children = kids
                out.append(it)
            elif not cls._part_view(it):
                out.append(it)
        return out

    @classmethod
    def _moved(cls, it, m, view: bool):
        """`it` transformé par `m` pour ses seuls objets de la vue de la
        pièce 3D (`view`), ou pour les seuls autres — dans les groupes aussi
        (contours STEP groupés, groupe mêlé au dessin)."""
        marks = {cls._part_view(x) for x in _leaves([it])}
        if marks == {view}:
            return it.transformed(m)
        if view not in marks:
            return it
        c = copy.copy(it)                                  # groupe mêlé : chacun selon ce qu'il est
        c.children = [cls._moved(ch, m, view) for ch in it.children]
        return c

    def _part_follows_plate(self):
        """Pièce 3D centrée sur la plaque (ou dans son coin) recalée sur la
        plaque du document : son décalage, et les objets de sa vue STEP
        déplacés d'autant — les mêmes objets (une opération qui les désigne
        les garde ; face et rotation inchangées : pas de relecture). Rend
        (Δx, Δy), ou None si elle n'a pas bougé."""
        import dataclasses
        from ..core import placement3d as P3
        from ..io import model3d
        from .progress import Cancelled, run
        doc = self.canvas.doc
        src, cur, plate = model3d.source_of(doc), P3.of(doc), doc.plate
        if src is None or plate is None:
            return None
        try:
            m = run(self, tr('Placer la pièce 3D'), model3d.load, src, P3.Placement(cur.face, cur.rot))
        except Cancelled:                                  # 4. dit : sa prise du dessin reste l'ancienne
            self.statusBar().showMessage(tr('Lecture de la pièce 3D annulée : elle est restée à sa place d\'avant '
                                            'la plaque — la replacer (Placer la pièce 3D).'), 15000)
            return None
        except Exception as e:                             # noqa: BLE001 — pièce illisible : laissée où elle était
            self.statusBar().showMessage(tr('Pièce 3D illisible, laissée où elle était : {0}').format(e), 15000)
            return None
        new = P3.resolve(dataclasses.replace(cur), m.bounds(), (plate.x, plate.y, plate.width, plate.height))
        ddx, ddy = new.dx - cur.dx, new.dy - cur.dy
        if abs(ddx) < 1e-9 and abs(ddy) < 1e-9:
            return None
        move = Affine.translation(ddx, ddy)
        for L in doc.layers:
            L.items = [self._moved(it, move, True) for it in L.items]
        doc.extra[P3.KEY] = P3.to_dict(new)
        return ddx, ddy

    def apply_plate(self, plate, adjust=None) -> None:
        """Nouvelle plaque (annulable) ; `adjust` : transformation de la
        composition (Ajuster la composition). Une pièce 3D centrée sur la
        plaque (ou dans son coin) la suit : sa prise du dessin aussi, pas
        seulement les prises retournées."""
        from ..core import placement3d as P3
        from ..core import surface2d
        from ..io import model3d
        doc = self.canvas.doc
        old = doc.plate
        follows = model3d.source_of(doc) is not None and P3.of(doc).mode in self.FOLLOWS_PLATE
        self.push_undo(keys=(P3.KEY,) if follows else ())
        if adjust is not None:
            for L in self.canvas.doc.layers:
                if surface2d.of_layer(L) is None:          # une surface posée suit la pièce, pas la composition ;
                    L.items = [self._moved(it, adjust, False) if follows else it.transformed(adjust)   # sa vue
                               for it in L.items]          # aussi quand elle suit la plaque
            self.canvas.selection = []
            self.canvas.invalidate()
            note = self.adjust_part_note()
            if note:                                       # le dessin ajusté et la pièce 3D se sont séparés
                self.statusBar().showMessage(note, 15000)
        self.canvas.doc.plate = plate
        box = lambda p: (p.x, p.y, p.width, p.height) if p is not None else None     # noqa: E731
        moved = self._part_follows_plate() if follows and box(old) != box(plate) else None
        if moved is not None:                              # sa vue STEP déplacée, ses surfaces suivies
            surface2d.follow(doc)
            self.canvas.selection = []
            self.canvas.invalidate()
            if self.panel3d is not None:
                self.panel3d.stale = True
                self._refresh_3d_if_visible()
            if adjust is None:
                mode = tr(P3.MODES.get(P3.of(doc).mode, P3.of(doc).mode))
                if old is not None and (old.width, old.height) == (plate.width, plate.height):
                    msg = tr('La pièce 3D a suivi la plaque (position « {0} ») ; le dessin, lui, n\'a pas bougé — '
                             '« Ajuster la composition à la nouvelle taille » le fait suivre.').format(mode)
                else:
                    msg = tr('La pièce 3D a suivi la plaque (position « {0} ») : décalée de {1} mm en X et {2} mm '
                             'en Y ; le dessin, lui, n\'a pas bougé — le déplacer d\'autant s\'il doit rester sur '
                             'elle.').format(mode, f'{moved[0]:+.2f}', f'{moved[1]:+.2f}')
                self.statusBar().showMessage(msg, 15000)
        elif surface2d.follow(self.canvas.doc):            # pièce centrée sur la plaque : ses surfaces la suivent
            self.canvas.invalidate()
        self.canvas.update()
        self._on_doc_changed()
